# ===== S1. 기하와 가지치기 (§1.1) =====

ORIGIN_POINT_ID = "__origin__"
DESTINATION_POINT_ID = "__destination__"
_SNAP_EDGE_IDS: MappingProxyType = MappingProxyType(
    {ORIGIN_POINT_ID: "__snap_origin__", DESTINATION_POINT_ID: "__snap_destination__"}
)
_POINT_NAMES: MappingProxyType = MappingProxyType({ORIGIN_POINT_ID: "찍은 출발점", DESTINATION_POINT_ID: "찍은 목적지"})
_POINT_SOURCE = "지도에서 찍은 점"
# 찍은 점을 붙일 수 있는 지상 노드(§1.10.1). 승강장과 역 안 노드에는 붙이지 않는다.
_GROUND_TYPES = frozenset(
    {NodeType.PLACE, NodeType.INTERSECTION, NodeType.WAYPOINT, NodeType.BUS_STOP, NodeType.STATION_EXIT, NodeType.BIKE_STATION}
)
# 타원 밖이어도 남기는 승하차·역 안 노드(§1.1).
_TRANSFER_KEEP_TYPES = frozenset({NodeType.BUS_STOP, NodeType.SUBWAY_PLATFORM, NodeType.STATION_HALL})


def haversine_m(a: tuple[float, float], b: tuple[float, float], radius_m: float) -> float:
    """(위도, 경도) 두 점 사이의 대원 거리(m), §1.1 의 Haversine 공식."""
    phi1, phi2 = math.radians(a[0]), math.radians(b[0])
    half_dphi = (phi2 - phi1) / 2.0
    half_dlam = math.radians(b[1] - a[1]) / 2.0
    h = math.sin(half_dphi) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(half_dlam) ** 2
    return 2.0 * radius_m * math.asin(math.sqrt(min(1.0, h)))


def _latlon(node: Node) -> tuple[float, float]:
    return (node.lat, node.lon)


def _node_index(scenario: Scenario) -> dict[str, Node]:
    """노드와 대여소를 ID 로 찾는 표."""
    index: dict[str, Node] = {node.id: node for node in scenario.nodes}
    index.update({station.id: station for station in scenario.bike_stations})
    return index


def edge_length_m(edge: Edge, node_index: dict[str, Node], config: EngineConfig) -> float:
    """엣지 길이(m). `distance_m` 이 있으면 그 값, 없으면 끝점과 `via` 좌표를 이은 꺾은선의 Haversine 합이다."""
    if edge.distance_m is not None:
        return float(edge.distance_m)
    points = [_latlon(node_index[edge.source]), *edge.via, _latlon(node_index[edge.target])]
    return sum(haversine_m(a, b, config.earth_radius_m) for a, b in zip(points, points[1:]))


def _nearest_ground(scenario: Scenario, lat: float, lon: float, config: EngineConfig) -> tuple[float, str] | None:
    """찍은 좌표에서 가장 가까운 지상 노드(거리가 같으면 ID 순)와 그 거리(§1.10.1)."""
    best: tuple[float, str] | None = None
    index = _node_index(scenario)
    for node_id in sorted(index):
        node = index[node_id]
        if node.node_type not in _GROUND_TYPES:
            continue
        distance = haversine_m((lat, lon), _latlon(node), config.earth_radius_m)
        if best is None or distance < best[0]:
            best = (distance, node_id)
    return best


def snap_point(scenario: Scenario, lat: float, lon: float, node_id: str, config: EngineConfig) -> tuple[Scenario, float] | None:
    """찍은 좌표에 POINT 노드를 만들고 가장 가까운 지상 노드에 SNAP 엣지로 잇는다(§1.10.1).

    거리가 같으면 ID 가 앞선 노드에 붙인다. 직선거리가 `snap_max_m` 보다 길거나 붙일 노드가 없으면 None 이다.
    """
    if node_id not in _SNAP_EDGE_IDS:
        raise ValueError(f"붙이는 점의 ID 는 {ORIGIN_POINT_ID} 나 {DESTINATION_POINT_ID} 여야 합니다: {node_id}")
    index = _node_index(scenario)
    edge_id = _SNAP_EDGE_IDS[node_id]
    if node_id in index or any(edge.id == edge_id for edge in scenario.edges):
        raise ValueError(f"시나리오에 이미 {node_id} 노드나 {edge_id} 엣지가 있습니다")
    best = _nearest_ground(scenario, lat, lon, config)
    if best is None or best[0] > config.snap_max_m:
        return None
    distance, target = best
    point = Node(
        id=node_id, name=_POINT_NAMES[node_id], node_type=NodeType.POINT, lat=lat, lon=lon, verified=True, source=_POINT_SOURCE
    )
    source_id, target_id = (node_id, target) if node_id == ORIGIN_POINT_ID else (target, node_id)
    edge = Edge(
        id=edge_id,
        source=source_id,
        target=target_id,
        modes=(Mode.WALK,),
        kind=EdgeKind.SNAP,
        distance_m=distance if distance > 0 else None,
        bidirectional=True,
    )
    snapped = scenario.model_copy(update={"nodes": scenario.nodes + (point,), "edges": scenario.edges + (edge,)})
    return snapped, distance


def ellipse_axes(d_sd_m: float, gamma: float) -> tuple[float, float]:
    """타원의 장반축 $a = \\gamma d / 2$ 와 단반축 $b = (d/2)\\sqrt{\\gamma^2 - 1}$ (§1.1)."""
    return gamma * d_sd_m / 2.0, d_sd_m / 2.0 * math.sqrt(max(0.0, gamma * gamma - 1.0))


def ellipse_polygon(
    s: tuple[float, float], d: tuple[float, float], gamma: float, radius_m: float, n_vertices: int
) -> tuple[tuple[float, float], ...]:
    """지도 표시용 타원 다각형의 (위도, 경도) 꼭짓점들. 중점 둘레의 국소 평면 근사(§1.1)."""
    d_sd = haversine_m(s, d, radius_m)
    a, b = ellipse_axes(d_sd, gamma)
    lat_c, lon_c = (s[0] + d[0]) / 2.0, (s[1] + d[1]) / 2.0
    m_per_deg_lat = radius_m * math.pi / 180.0
    m_per_deg_lon = m_per_deg_lat * math.cos(math.radians(lat_c))
    angle = math.atan2((d[0] - s[0]) * m_per_deg_lat, (d[1] - s[1]) * m_per_deg_lon)
    cos_a, sin_a = math.cos(angle), math.sin(angle)
    points = []
    for k in range(n_vertices):
        t = 2.0 * math.pi * k / n_vertices
        x, y = a * math.cos(t), b * math.sin(t)
        east, north = x * cos_a - y * sin_a, x * sin_a + y * cos_a
        points.append((lat_c + north / m_per_deg_lat, lon_c + east / m_per_deg_lon))
    return tuple(points)


def prune_by_ellipse(
    scenario: Scenario, s_node_id: str, d_node_id: str, config: EngineConfig
) -> tuple[PruningSummary, tuple[PruningRecord, ...], frozenset[str]]:
    """타원 부등식 $d(S,X) + d(X,D) \\le \\gamma\\, d(S,D)$ 로 남길 노드를 정한다(§1.1).

    부등식은 허용 오차 없이 비교한다. S, D 는 늘 남기고, 타원 밖의 승하차·역 안 노드는 환승용으로 남긴다.
    기록은 합이 작은 순서(같으면 ID 순)이고, 셋째 값은 남긴 노드 ID 집합이다. 엣지는 그래프를 만들 때 고른다.
    """
    index = _node_index(scenario)
    radius = config.earth_radius_m
    s, d = _latlon(index[s_node_id]), _latlon(index[d_node_id])
    d_sd = haversine_m(s, d, radius)
    threshold = config.gamma * d_sd
    records: list[PruningRecord] = []
    kept: set[str] = set()
    for node_id in sorted(index):
        point = _latlon(index[node_id])
        d_s = haversine_m(s, point, radius)
        d_d = haversine_m(point, d, radius)
        total = d_s + d_d
        inside = total <= threshold or node_id in (s_node_id, d_node_id)
        transfer = not inside and index[node_id].node_type in _TRANSFER_KEEP_TYPES
        if inside or transfer:
            kept.add(node_id)
        records.append(
            PruningRecord(
                node_id=node_id, d_s_m=d_s, d_d_m=d_d, sum_m=total, threshold_m=threshold, kept=inside or transfer, kept_for_transfer=transfer
            )
        )
    records.sort(key=lambda record: (record.sum_m, record.node_id))
    a, b = ellipse_axes(d_sd, config.gamma)
    summary = PruningSummary(
        d_sd_m=d_sd,
        threshold_m=threshold,
        a_m=a,
        b_m=b,
        kept_count=len(kept),
        total_count=len(index),
        polygon=ellipse_polygon(s, d, config.gamma, radius, config.ellipse_vertices),
    )
    return summary, tuple(records), frozenset(kept)


# ===== S2. 신호 (§1.2, §1.9) =====


def is_open_signal(phase: SignalPhase) -> bool:
    """개방 고정 신호인가(§1.2 의 표). 감응 신호는 실시간 상태를 알아도 표본으로 다룬다(§1.6)."""
    return phase.realtime_open and not phase.actuated and phase.offset_s is not None


def _wrap(value: float, cycle: float) -> float:
    """[0, cycle) 로 접는다. 아주 작은 음수가 cycle 로 올림되는 부동소수 경우를 0 으로 둔다."""
    wrapped = value % cycle
    return 0.0 if wrapped >= cycle else wrapped


def offset_from_observation(phase: SignalPhase, state: SignalState | str, remaining_s: float, t_obs_s: float) -> float | None:
    """관측(상태, 남은 시간 r, 관측 시각)에서 오프셋 $\\theta$ 를 역산한다(§1.2 (0)). 불일치면 None."""
    kind = SignalState(state)
    green, red, cycle = phase.green_s, phase.red_s, phase.cycle_s
    if remaining_s < 0:
        return None
    if kind == SignalState.GREEN:
        if remaining_s > green:
            return None
        tau_obs = green - remaining_s
    elif kind == SignalState.RED:
        if remaining_s > red:
            return None
        tau_obs = cycle - remaining_s
    else:
        return None
    return _wrap(tau_obs - t_obs_s, cycle)


def deterministic_wait(phase: SignalPhase, t_arr_s: float) -> SignalEvent:
    """개방 고정 신호의 결정적 대기 $W_{det}$ (§1.2 (1)). 위상이 녹색 시간과 같으면 적색이다."""
    if phase.offset_s is None:
        raise ValueError(f"신호 {phase.id}: 오프셋을 모르는 신호는 결정적 대기를 계산할 수 없습니다")
    cycle = phase.cycle_s
    tau = _wrap(phase.offset_s + t_arr_s, cycle)
    green = tau < phase.green_s
    return SignalEvent(
        signal_id=phase.id,
        t_arr_s=t_arr_s,
        tau_s=tau,
        state=SignalState.GREEN if green else SignalState.RED,
        wait_s=0.0 if green else cycle - tau,
        var_s2=0.0,
        source=phase.source,
        actuated=phase.actuated,
    )


def _red_samples(phase: SignalPhase) -> list[float]:
    """감응 신호의 주기마다 적색 시간 $\\rho_i = \\max(0, c_i - T_{green})$ (§1.2 (3))."""
    return [max(0.0, cycle - phase.green_s) for cycle in phase.gap_samples_s]


def stochastic_wait(phase: SignalPhase) -> tuple[float, float]:
    """위상을 모르는 신호의 대기 기댓값과 분산(§1.2 (2), (3)). 감응 신호는 주기 길이로 가중한다."""
    if phase.actuated:
        total = sum(phase.gap_samples_s)
        reds = _red_samples(phase)
        mean = sum(red * red / 2.0 for red in reds) / total
        second = sum(red**3 / 3.0 for red in reds) / total
        return mean, max(0.0, second - mean * mean)
    green, red, cycle = phase.green_s, phase.red_s, phase.cycle_s
    return red * red / (2.0 * cycle), red**3 * (4.0 * green + red) / (12.0 * cycle * cycle)


def worst_wait(phase: SignalPhase) -> float:
    """가장 긴 대기(신호 회피 규칙 WORST, §1.2): 고정 신호는 $T_{red}$, 감응 신호는 $\\max_i \\rho_i$."""
    if phase.actuated:
        return max(_red_samples(phase))
    return phase.red_s


def signal_event(phase: SignalPhase, t_arr_s: float, rule: WaitRule | str) -> SignalEvent:
    """대기 규칙(§1.10.3 의 표)에 따른 신호 이벤트. 개방 신호는 결정적 대기, 표본 신호는 규칙의 상수 대기다."""
    kind = WaitRule(rule)
    if is_open_signal(phase):
        event = deterministic_wait(phase, t_arr_s)
        return event.model_copy(update={"wait_s": 0.0}) if kind == WaitRule.NONE else event
    if kind == WaitRule.NONE:
        wait, var = 0.0, 0.0
    elif kind == WaitRule.WORST:
        wait, var = worst_wait(phase), 0.0
    else:
        wait, var = stochastic_wait(phase)
    return SignalEvent(
        signal_id=phase.id,
        t_arr_s=t_arr_s,
        tau_s=None,
        state=SignalState.STOCHASTIC,
        wait_s=wait,
        var_s2=var,
        source=phase.source,
        actuated=phase.actuated,
    )


# --- 신호 학습의 순수 함수 (§1.9). 관측은 (그날 0시부터의 초, 상태, 남은 초) 튜플이다. ---


@dataclass(frozen=True)
class SignalDaySamples:
    """신호 하나, 하루 하나의 학습 표본(§1.9 의 1 ~ 4). 표본 사전의 키는 시간대 번호(시)다."""

    green_starts: tuple[float, ...]
    green_ends: tuple[float, ...]
    outages: tuple[tuple[float, float], ...]
    dropped_gaps: int  # 관측 공백과 겹쳐 버린 녹색 시작 간격 수
    gaps_by_slot: dict[int, tuple[float, ...]]
    greens_by_slot: dict[int, tuple[float, ...]]


@dataclass(frozen=True)
class SignalSlotFit:
    """요일 종류 하나, 시간대 하나의 학습 결과(§1.9 의 5 ~ 8)."""

    slot: int
    learned: bool
    cycle_s: float | None
    green_s: float | None
    red_s: float | None
    iqr_s: float | None
    actuated: bool
    gap_samples_s: tuple[float, ...]  # 감응 신호면 정렬한 주기 표본 전부, 아니면 빈 튜플
    n_gaps: int
    n_greens: int
    merged_slots: tuple[int, ...]


def switch_events(observations: Iterable[tuple[float, SignalState | str, float | None]]) -> tuple[list[float], list[float]]:
    """관측마다 다음 전환 시각 $s = t_{obs} + r$. 적색이면 녹색 시작, 녹색이면 녹색 끝 후보다(정렬해 돌려준다)."""
    starts: list[float] = []
    ends: list[float] = []
    for t_obs, state, remaining in observations:
        if remaining is None:
            continue
        moment = float(t_obs) + float(remaining)
        kind = SignalState(state)
        if kind == SignalState.RED:
            starts.append(moment)
        elif kind == SignalState.GREEN:
            ends.append(moment)
    return sorted(starts), sorted(ends)


def group_switches(times: Iterable[float], group_s: float) -> list[float]:
    """정렬한 전환 후보를 묶음의 첫 값과의 차이가 `group_s` 이하인 것끼리 모아 묶음마다 중앙값을 낸다(§1.9 의 1)."""
    groups: list[list[float]] = []
    for value in sorted(times):
        if groups and value - groups[-1][0] <= group_s:
            groups[-1].append(value)
        else:
            groups.append([value])
    return [statistics.median(group) for group in groups]


def observation_outages(obs_times: Iterable[float], poll_s: float, factor: float) -> list[tuple[float, float]]:
    """이웃한 두 관측의 간격이 factor × 조회 주기를 넘는 구간 (a, b) 들(§1.9 의 2)."""
    ordered = sorted(float(t) for t in obs_times)
    limit = factor * poll_s
    return [(a, b) for a, b in zip(ordered, ordered[1:]) if b - a > limit]


def signal_day_samples(
    observations: Iterable[tuple[float, SignalState | str, float | None]], poll_s: float, config: EngineConfig
) -> SignalDaySamples:
    """하루치 관측에서 녹색 시작·끝, 관측 공백, 시간대별 주기 표본과 녹색 시간 표본을 만든다(§1.9 의 1 ~ 4)."""
    rows = list(observations)
    raw_starts, raw_ends = switch_events(rows)
    starts = group_switches(raw_starts, config.signal_group_s)
    ends = group_switches(raw_ends, config.signal_group_s)
    outages = observation_outages((row[0] for row in rows), poll_s, config.signal_outage_factor)
    gaps: dict[int, list[float]] = {}
    greens: dict[int, list[float]] = {}
    dropped = 0
    for start, following in zip(starts, starts[1:]):
        slot = int(math.floor(start / config.signal_slot_s))
        if any(a < following and b > start for a, b in outages):
            dropped += 1
        else:
            gaps.setdefault(slot, []).append(following - start)
        end = next((value for value in ends if start < value < following), None)
        if end is not None:
            greens.setdefault(slot, []).append(end - start)
    return SignalDaySamples(
        green_starts=tuple(starts),
        green_ends=tuple(ends),
        outages=tuple(outages),
        dropped_gaps=dropped,
        gaps_by_slot={slot: tuple(values) for slot, values in sorted(gaps.items())},
        greens_by_slot={slot: tuple(values) for slot, values in sorted(greens.items())},
    )


def fit_signal_slots(day_samples: Iterable[SignalDaySamples], config: EngineConfig) -> dict[int, SignalSlotFit]:
    """같은 요일 종류의 날들을 모아 시간대마다 주기와 녹색 시간을 정한다(§1.9 의 5 ~ 8).

    주기 표본이 모자란 시간대는 거리 1, 2, … 의 이웃 시간대(h − d 와 h + d)를 관측된 범위 안에서 함께 더한 뒤 다시 센다.
    """
    gaps_by_slot: dict[int, list[float]] = {}
    greens_by_slot: dict[int, list[float]] = {}
    for day in day_samples:
        for slot, values in day.gaps_by_slot.items():
            gaps_by_slot.setdefault(slot, []).extend(values)
        for slot, values in day.greens_by_slot.items():
            greens_by_slot.setdefault(slot, []).extend(values)
    slots = sorted(set(gaps_by_slot) | set(greens_by_slot))
    fits: dict[int, SignalSlotFit] = {}
    if not slots:
        return fits
    first, last = slots[0], slots[-1]
    for slot in slots:
        gaps = list(gaps_by_slot.get(slot, ()))
        greens = list(greens_by_slot.get(slot, ()))
        used = [slot]
        distance = 1
        while len(gaps) < config.signal_min_gaps and (slot - distance >= first or slot + distance <= last):
            for other in (slot - distance, slot + distance):
                if other in gaps_by_slot or other in greens_by_slot:
                    gaps.extend(gaps_by_slot.get(other, ()))
                    greens.extend(greens_by_slot.get(other, ()))
                    used.append(other)
            distance += 1
        merged = tuple(sorted(used))
        if len(gaps) < config.signal_min_gaps or not greens:
            fits[slot] = SignalSlotFit(slot, False, None, None, None, None, False, (), len(gaps), len(greens), merged)
            continue
        cycle = statistics.median(gaps)
        green = statistics.median(greens)
        if len(gaps) >= 2:
            quartiles = statistics.quantiles(gaps, n=4, method="inclusive")
            iqr = quartiles[2] - quartiles[0]
        else:
            iqr = 0.0
        actuated = iqr > config.actuated_iqr_s
        fits[slot] = SignalSlotFit(
            slot=slot,
            learned=True,
            cycle_s=cycle,
            green_s=green,
            red_s=max(0.0, cycle - green),
            iqr_s=iqr,
            actuated=actuated,
            gap_samples_s=tuple(sorted(gaps)) if actuated else (),
            n_gaps=len(gaps),
            n_greens=len(greens),
            merged_slots=merged,
        )
    return fits


# ===== S3. 확률 순수 함수 (§1.4, §1.8.1, §1.3) =====


class StepKind(enum.StrEnum):
    """프로필 단계의 종류(§1.4.2)."""

    TRAVEL = "TRAVEL"
    FIXED = "FIXED"
    SIGNAL = "SIGNAL"
    BIKE_GATE = "BIKE_GATE"
    BOARD = "BOARD"


@dataclass(frozen=True)
class ProfileStep:
    """프로필의 한 단계. TRAVEL 은 거리와 수단, FIXED 는 초, SIGNAL 은 신호 ID, BIKE_GATE 와 BOARD 는 구간·탑승 번호다."""

    kind: StepKind
    distance_m: float = 0.0
    mode: Mode = Mode.WALK
    seconds: float = 0.0
    signal_id: str = ""
    index: int = -1


def travel_step(distance_m: float, mode: Mode = Mode.WALK) -> ProfileStep:
    return ProfileStep(StepKind.TRAVEL, distance_m=float(distance_m), mode=Mode(mode))


def fixed_step(seconds: float) -> ProfileStep:
    return ProfileStep(StepKind.FIXED, seconds=float(seconds))


def signal_step(signal_id: str) -> ProfileStep:
    return ProfileStep(StepKind.SIGNAL, signal_id=signal_id)


def compact_steps(steps: Iterable[ProfileStep]) -> tuple[ProfileStep, ...]:
    """이어진 같은 수단의 TRAVEL 을 길이를 더해 하나로 합친다(§1.4.2 의 만들기 규칙)."""
    merged: list[ProfileStep] = []
    for step in steps:
        if (
            merged
            and step.kind == StepKind.TRAVEL
            and merged[-1].kind == StepKind.TRAVEL
            and merged[-1].mode == step.mode
        ):
            merged[-1] = travel_step(merged[-1].distance_m + step.distance_m, step.mode)
        else:
            merged.append(step)
    return tuple(merged)


def radical_inverse_int(n: int, base: int) -> tuple[int, int]:
    """근역 $\\phi_b(n)$ 의 정수 쌍 (rev, denom) (§1.4.4)."""
    rev, denom = 0, 1
    while n > 0:
        n, digit = divmod(n, base)
        rev = rev * base + digit
        denom *= base
    return rev, denom


@functools.lru_cache(maxsize=64)
def halton_column(base: int, n_points: int) -> np.ndarray:
    """점 번호 n = 1 … N 의 $\\phi_b(n)$ = rev / denom (정수로 정확히 구한 뒤 한 번 나눈다, §1.4.4). 읽기 전용 배열."""
    rest = np.arange(1, n_points + 1, dtype=np.int64)
    rev = np.zeros(n_points, dtype=np.int64)
    denom = np.ones(n_points, dtype=np.int64)
    while np.any(rest > 0):
        active = rest > 0
        digit = rest % base
        rev = np.where(active, rev * base + digit, rev)
        denom = np.where(active, denom * base, denom)
        rest = rest // base
    column = rev / denom
    column.flags.writeable = False
    return column


@functools.lru_cache(maxsize=16)
def halton_m(n_points: int, k_move: float) -> np.ndarray:
    """차원 0 의 속도 배수 $m_n = 1 + k_{move}\\,\\Phi^{-1}(\\phi_2(n))$ ($k_{move} = 0$ 이면 1). 읽기 전용 배열."""
    if k_move == 0:
        values = np.ones(n_points)
    else:
        inverse = statistics.NormalDist().inv_cdf
        values = 1.0 + k_move * np.array([inverse(float(u)) for u in halton_column(HALTON_PRIMES[0], n_points)])
    values.flags.writeable = False
    return values


_ERFC = np.vectorize(math.erfc, otypes=[float])


def upper_normal_tail(z: Any) -> np.ndarray:
    """$\\bar\\Phi(z) = \\tfrac12 \\operatorname{erfc}(z/\\sqrt2)$ 을 원소마다 계산한다($+\\infty$ 는 0)."""
    return 0.5 * _ERFC(np.asarray(z, dtype=float) / math.sqrt(2.0))


def bisect_threshold(predicate: Callable[[np.ndarray], Any], n: int, config: EngineConfig) -> np.ndarray:
    """점마다 사건이 참이 되는 가장 작은 m (§1.4.3). $m_{max}$ 에서도 거짓이면 $+\\infty$ 다.

    `predicate` 는 길이 n 의 m 배열을 받아 점마다 참·거짓 배열을 돌려준다. 점마다 lo, hi 배열로 `bisect_iters` 번 반복한다.
    """
    hi = np.full(n, config.m_max)
    lo = np.full(n, config.m_min)
    reachable = np.asarray(predicate(hi.copy()), dtype=bool)
    for _ in range(config.bisect_iters):
        mid = (lo + hi) / 2.0
        ok = np.asarray(predicate(mid), dtype=bool)
        hi = np.where(ok, mid, hi)
        lo = np.where(ok, lo, mid)
    return np.where(reachable, hi, np.inf)


def p_bike(n0: int, rate_per_hour: float | None, elapsed_s: float) -> float:
    """잔존 확률 $\\Pr[\\text{Poisson}(\\lambda (g + a)) < n_0]$ (§1.8.1). 항은 곱으로 이어 더한다."""
    if n0 <= 0:
        return 0.0
    if rate_per_hour is None or rate_per_hour == 0:
        return 1.0
    mean = rate_per_hour / 3600.0 * max(0.0, elapsed_s)
    term = math.exp(-mean)
    total = term
    for j in range(1, n0):
        term *= mean / j
        total += term
    return min(1.0, total)


def grade_of(p_star: float, config: EngineConfig) -> Grade:
    """등급(§1.4.5 (3)): $P^{*} \\ge p_{safe}$ 면 SAFE, $p_{ghost}$ 이상이면 RISKY, 아니면 GHOST."""
    if p_star >= config.p_safe:
        return Grade.SAFE
    if p_star >= config.p_ghost:
        return Grade.RISKY
    return Grade.GHOST


def weighted_quantile(values: Sequence[float] | np.ndarray, weights: Sequence[float] | np.ndarray, q: float) -> float | None:
    """가중 분위수(§1.4.5 (4)). 안정 정렬 후 같은 값의 무게를 묶어 누적하고 `cum >= q * total * (1 - 1e-12)` 인 첫 값.

    끝까지 만족하지 않으면 가장 큰 값, 값이 없으면 None 이다. 모든 점을 numpy 배열로 한꺼번에 다룬다.
    """
    points = np.asarray(values, dtype=float)
    if points.size == 0:
        return None
    point_weights = np.asarray(weights, dtype=float)
    order = np.argsort(points, kind="stable")
    sorted_values = points[order]
    starts = np.flatnonzero(np.concatenate(([True], sorted_values[1:] != sorted_values[:-1])))
    cumulative = np.cumsum(np.add.reduceat(point_weights[order], starts))
    target = q * float(np.sum(point_weights)) * (1.0 - 1e-12)
    hits = np.flatnonzero(cumulative >= target)
    return float(sorted_values[starts[hits[0]]] if hits.size else sorted_values[-1])


def margin_histogram(
    margins: Sequence[float] | np.ndarray, weights: Sequence[float] | np.ndarray | None, buffer_s: float, bin_s: float
) -> MarginHistogram:
    """여유 시간 막대그래프(§1.4.7). 칸 경계는 $t_{buf} + j h$ 이고 범위는 유한한 값의 0.005 · 0.995 분위수로 정한다.

    `weights` 가 None 이면 유한한 점마다 같은 무게다. 칸과 성공 질량은 점의 개수로 센다. 점은 경계와 직접 비교해 칸에 넣는다.
    """
    values = np.asarray(margins, dtype=float)
    n_points = int(values.size)
    finite_mask = np.isfinite(values)
    finite = values[finite_mask]
    n_infinite = n_points - int(finite.size)
    success = int(np.count_nonzero(finite >= buffer_s))
    mass = success / n_points if n_points else 0.0
    if finite.size == 0:
        return MarginHistogram(
            bin_width_s=bin_s, bins=(), n_points=n_points, n_under=0, n_over=0, n_infinite=n_infinite, success_mass=mass
        )
    point_weights = np.ones(finite.size) if weights is None else np.asarray(weights, dtype=float)[finite_mask]
    q_lo = weighted_quantile(finite, point_weights, 0.005)
    q_hi = weighted_quantile(finite, point_weights, 0.995)
    j_lo = math.floor((q_lo - buffer_s) / bin_s)
    j_hi = math.floor((q_hi - buffer_s) / bin_s)
    edges = buffer_s + np.arange(j_lo, j_hi + 2, dtype=float) * bin_s
    n_bins = j_hi - j_lo + 1
    inside = finite[(finite >= edges[0]) & (finite < edges[-1])]
    counts = np.bincount(np.searchsorted(edges, inside, side="right") - 1, minlength=n_bins)
    return MarginHistogram(
        bin_width_s=bin_s,
        bins=tuple((float(edges[i]), int(counts[i])) for i in range(n_bins)),
        n_points=n_points,
        n_under=int(np.count_nonzero(finite < edges[0])),
        n_over=int(np.count_nonzero(finite >= edges[-1])),
        n_infinite=n_infinite,
        success_mass=mass,
    )


def bike_plan_time_s(walk_to_m: float, ride_m: float, walk_from_m: float, signal_wait_s: float, config: EngineConfig) -> float:
    """따릉이 구간의 계획 소요시간 $T_{pm}$ (§1.3): 도보, 잠금 해제, 주행, 신호 대기 합, 반납, 도보."""
    return (
        walk_to_m / config.v_walk_mps
        + config.t_unlock_s
        + ride_m / config.v_pm_mps
        + signal_wait_s
        + config.t_dock_s
        + walk_from_m / config.v_walk_mps
    )


def _bike_multiplier(m: Any, config: EngineConfig) -> Any:
    """$m_{pm} = 1 + (k_{pm}/k_{move})(m - 1)$, $k_{move} = 0$ 이면 1 (§1.4.1)."""
    if config.k_move == 0:
        return np.ones_like(m) if isinstance(m, np.ndarray) else 1.0
    return 1.0 + (config.k_pm / config.k_move) * (m - 1.0)


def propagate_steps(
    steps: Iterable[ProfileStep],
    t0_s: float,
    signals: dict[str, SignalPhase],
    config: EngineConfig,
    rule: WaitRule | str = WaitRule.EXPECTED,
    m: float = 1.0,
) -> tuple[float, tuple[SignalEvent, ...]]:
    """단계를 차례로 지나며 신호마다 대기 규칙의 대기를 더한 끝 시각과 신호 이벤트(§1.2 의 순차 전파).

    i 번째 신호의 도착 시각은 시작 시각 + 그 지점까지의 이동시간 + 앞선 신호들의 대기 합이다.
    """
    m_pm = _bike_multiplier(m, config)
    t = float(t0_s)
    events: list[SignalEvent] = []
    for step in steps:
        if step.kind == StepKind.TRAVEL:
            speed = m * config.v_walk_mps if step.mode == Mode.WALK else m_pm * config.v_pm_mps
            t += step.distance_m / speed
        elif step.kind == StepKind.FIXED:
            t += step.seconds
        elif step.kind == StepKind.SIGNAL:
            event = signal_event(signals[step.signal_id], t, rule)
            events.append(event)
            t += event.wait_s
        else:
            raise ValueError(f"propagate_steps 는 {step.kind} 단계를 다루지 않습니다")
    return t, tuple(events)


def assign_halton_dims(
    signal_ids: Iterable[str], signals: dict[str, SignalPhase], config: EngineConfig
) -> tuple[dict[str, int], tuple[str, ...]]:
    """표본 신호에 처음 나오는 순서대로 준난수 차원 1, 2, … 를 준다(§1.4.4). 차원 0 은 속도 배수다.

    개방 고정 신호는 차원을 받지 않고, 같은 신호는 한 번만 센다. `max_halton_dims` 를 넘친 신호는 둘째 값이다.
    """
    dims: dict[str, int] = {}
    capped: list[str] = []
    for signal_id in signal_ids:
        if signal_id in dims or signal_id in capped or is_open_signal(signals[signal_id]):
            continue
        if len(dims) + 1 < config.max_halton_dims:
            dims[signal_id] = len(dims) + 1
        else:
            capped.append(signal_id)
    return dims, tuple(capped)


def sample_signal_phase(phase: SignalPhase, u: Any) -> tuple[np.ndarray, np.ndarray]:
    """표본점 u 에서 신호의 (위상 $\\theta$, 주기 C) 배열(§1.4.4).

    미개방 고정 신호는 $\\theta = u C$. 감응 신호는 주기 표본을 이어 붙인 시간축에서 $x = u \\sum c_i$ 가 든 칸의 주기와 그 칸 안 위치다.
    """
    points = np.asarray(u, dtype=float)
    if phase.actuated:
        cycles = np.asarray(sorted(phase.gap_samples_s), dtype=float)
        cumulative = np.cumsum(cycles)
        x = points * cumulative[-1]
        index = np.minimum(np.searchsorted(cumulative, x, side="right"), len(cycles) - 1)
        before = np.where(index > 0, cumulative[np.maximum(index - 1, 0)], 0.0)
        return x - before, cycles[index]
    cycle = phase.cycle_s
    return points * cycle, np.full(points.shape, cycle)


def signal_draws(dims: dict[str, int], signals: dict[str, SignalPhase], n_points: int) -> dict[str, tuple[np.ndarray, np.ndarray]]:
    """차원을 받은 표본 신호마다 점 n = 1 … N 의 (θ, C). 차원 k 의 밑은 `HALTON_PRIMES[k]` 다."""
    return {
        signal_id: sample_signal_phase(signals[signal_id], halton_column(HALTON_PRIMES[dim], n_points))
        for signal_id, dim in sorted(dims.items(), key=lambda item: item[1])
    }


def _wait_points(phase: SignalPhase, draw: tuple[np.ndarray, np.ndarray] | None, t: np.ndarray) -> np.ndarray:
    """점마다 신호 대기 $W_k(t)$ (§1.4.2). 차원을 넘겨 표본이 없는 신호는 상수 $E[W]$ 다."""
    if is_open_signal(phase):
        cycle = phase.cycle_s
        tau = np.mod(phase.offset_s + t, cycle)
        return np.where(tau < phase.green_s, 0.0, cycle - tau)
    if draw is None:
        return np.full(t.shape, stochastic_wait(phase)[0])
    theta, cycle = draw
    tau = np.mod(theta + t, cycle)
    return np.where(tau < phase.green_s, 0.0, cycle - tau)


def _point_speeds(m: np.ndarray, config: EngineConfig, m_pm: Any = None) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """점마다 (걷는 속도, 주행 속도, 가지 못하는 점). $m \\le m_{min}$ 이거나 $m_{pm} \\le m_{min}$ 인 점은 배수 1 로 계산하고 표시만 한다(§1.4.1).
    `m_pm` 을 주면 모형의 주행 배수 대신 그 값을 쓴다(추적 평가의 유형, §4.13.4)."""
    bike = _bike_multiplier(m, config) if m_pm is None else np.broadcast_to(np.asarray(m_pm, dtype=float), np.shape(m)).astype(float)
    dead = (m <= config.m_min) | (bike <= config.m_min)
    return np.where(dead, 1.0, m) * config.v_walk_mps, np.where(dead, 1.0, bike) * config.v_pm_mps, dead


def _advance_steps(
    steps: Iterable[ProfileStep],
    t: np.ndarray,
    walk_speed: np.ndarray,
    bike_speed: np.ndarray,
    draws: dict[str, tuple[np.ndarray, np.ndarray]],
    signals: dict[str, SignalPhase],
) -> np.ndarray:
    """점마다 TRAVEL, FIXED, SIGNAL 단계를 차례로 지난 시각(§1.4.2). 표본이 없는 표본 신호는 $E[W]$ 를 기다린다."""
    for step in steps:
        if step.kind == StepKind.TRAVEL:
            t = t + step.distance_m / (walk_speed if step.mode == Mode.WALK else bike_speed)
        elif step.kind == StepKind.FIXED:
            t = t + step.seconds
        elif step.kind == StepKind.SIGNAL:
            t = t + _wait_points(signals[step.signal_id], draws.get(step.signal_id), t)
        else:
            raise ValueError(f"이동시간 계산은 {step.kind} 단계를 다루지 않습니다(TRAVEL, FIXED, SIGNAL 만)")
    return t


def move_times(
    steps: Iterable[ProfileStep],
    m: Any,
    draws: dict[str, tuple[np.ndarray, np.ndarray]],
    signals: dict[str, SignalPhase],
    config: EngineConfig,
    t0_s: float = 0.0,
) -> np.ndarray:
    """점마다 TRAVEL, FIXED, SIGNAL 단계를 지나 끝에 닿는 시각(§1.4.2). $m \\le m_{min}$ 이거나 $m_{pm} \\le m_{min}$ 이면 $+\\infty$."""
    multipliers = np.asarray(m, dtype=float)
    walk_speed, bike_speed, dead = _point_speeds(multipliers, config)
    t = _advance_steps(steps, np.full(multipliers.shape, float(t0_s)), walk_speed, bike_speed, draws, signals)
    return np.where(dead, np.inf, t)


@dataclass(frozen=True)
class EventProbability:
    """이동이 마감 이하에 끝나는 사건의 확률과 계산 방법(§1.4.3)."""

    probability: float
    method: ProbMethod
    n_points: int
    dims: dict[str, int]
    capped: tuple[str, ...]
    thresholds: np.ndarray = field(repr=False)
    warnings: tuple[WarningCode, ...] = ()

    @property
    def n_dims(self) -> int:
        """준난수 차원 수(차원 0 의 속도 배수를 포함한다)."""
        return 1 + len(self.dims)


def arrival_probability(
    steps: Iterable[ProfileStep], deadline_s: float, signals: dict[str, SignalPhase], config: EngineConfig
) -> EventProbability:
    """$t = 0$ 에 시작한 이동이 `deadline_s` 이하에 끝날 확률(§1.4.3). 승차 사건이면 마감은 $dep - t_{buf}$ 다.

    표본 신호가 없으면 EXACT (점 하나), 있으면 QMC (`n_qmc` 점), $k_{move} = 0$ 이면 DEGENERATE ($m = 1$ 에서 참인 비율).
    """
    profile = tuple(steps)
    order = [step.signal_id for step in profile if step.kind == StepKind.SIGNAL]
    dims, capped = assign_halton_dims(order, signals, config)
    n = config.n_qmc if dims else 1
    draws = signal_draws(dims, signals, n)

    def predicate(m: np.ndarray) -> np.ndarray:
        return move_times(profile, m, draws, signals, config) <= deadline_s

    if config.k_move == 0:
        hit = predicate(np.ones(n))
        thresholds = np.where(hit, 1.0, np.inf)
        probability = float(np.mean(hit))
        method = ProbMethod.DEGENERATE
    else:
        thresholds = bisect_threshold(predicate, n, config)
        probability = float(np.mean(upper_normal_tail((thresholds - 1.0) / config.k_move)))
        method = ProbMethod.QMC if dims else ProbMethod.EXACT
    return EventProbability(
        probability=probability,
        method=method,
        n_points=n,
        dims=dims,
        capped=capped,
        thresholds=thresholds,
        warnings=(WarningCode.QMC_DIMENSIONS_CAPPED,) if capped else (),
    )


# ===== S4. 요금과 효용 (§1.5, §1.11.1) =====

_CLIMATE_CARD_BUS_TYPES = frozenset(
    {BusRouteType.TRUNK, BusRouteType.BRANCH, BusRouteType.CIRCULAR, BusRouteType.NIGHT, BusRouteType.VILLAGE}
)
_CEIL_GUARD = 1e-9  # 거리 추가요금의 올림 전에 빼는 값(§1.5 (3))


class FareRide(NamedTuple):
    """요금 계산용 탑승 하나(§1.5 (1)). 시각은 $t = 0$ 기준 초, 거리는 m."""

    mode: TravelMode
    route_type: BusRouteType | None
    route_id: str
    board_s: float | None  # 차량 안 출발의 탑승 1 은 None
    alight_s: float
    distance_m: float
    in_station: bool = False  # 앞 지하철 탑승과 개찰구 안에서 갈아탐


@dataclass
class _FareUnit:
    """역 안 환승을 합친 뒤의 탑승 하나."""

    rides: list[FareRide]
    indexes: list[int]
    distance_m: float

    @property
    def first(self) -> FareRide:
        return self.rides[0]

    @property
    def last(self) -> FareRide:
        return self.rides[-1]

    @property
    def subway(self) -> bool:
        return self.first.mode == TravelMode.SUBWAY


def _clock_hhmm(seconds: float) -> str:
    total = int(round(seconds)) % int(SECONDS_PER_DAY)
    return f"{total // 3600:02d}:{total % 3600 // 60:02d}"


def transfer_window_for(board_clock_s: float, config: EngineConfig) -> float:
    """다음 승차의 시계 시각으로 환승 인정 시간을 정한다(§1.5 (2)). 밤 시간대면 `transfer_window_night_s`."""
    clock = board_clock_s % SECONDS_PER_DAY
    start, end = config.transfer_night_from_s, config.transfer_night_to_s
    night = (clock >= start or clock < end) if start > end else (start <= clock < end)
    return config.transfer_window_night_s if night else config.transfer_window_s


def _base_fare(ride: FareRide, config: EngineConfig) -> int:
    if ride.mode == TravelMode.SUBWAY:
        return config.fare_subway_krw
    return config.fare_bus_by_type_krw[BusRouteType(ride.route_type)]


def _guarded_units(excess_m: float, unit_km: float) -> int:
    """$\\lceil \\max(0, x) / \\text{단위} - 10^{-9} \\rceil$ (부동소수 오차로 한 단계가 더 붙지 않게)."""
    if excess_m <= 0:
        return 0
    return max(0, math.ceil(excess_m / (unit_km * 1000.0) - _CEIL_GUARD))


def _distance_extra(units: list[_FareUnit], distance_m: float, config: EngineConfig) -> int:
    """묶음의 거리 추가요금(§1.5 (3))."""
    free_m = config.fare_free_distance_km * 1000.0
    if len(units) == 1 and not units[0].subway:
        return 0
    if len(units) == 1:
        long_m = config.fare_long_km * 1000.0
        steps = _guarded_units(min(distance_m, long_m) - free_m, config.fare_step_km) + _guarded_units(
            distance_m - long_m, config.fare_long_step_km
        )
    else:
        steps = _guarded_units(distance_m - free_m, config.fare_step_km)
    return steps * config.fare_step_krw


def _break_reason(unit: _FareUnit, chain: list[_FareUnit], clock_s: float, config: EngineConfig) -> str | None:
    """다음 탑승이 앞 묶음에 들지 못하는 이유. 표의 위쪽 조건이 먼저다(§1.5 (2))."""
    previous = chain[-1]
    board = unit.first.board_s
    if board is not None and board - previous.last.alight_s > transfer_window_for(clock_s + board, config):
        return "WINDOW"
    if len(chain) >= config.max_rides_per_chain:
        return "MAX_RIDES"
    if not unit.subway and not previous.subway and unit.first.route_id == previous.last.route_id:
        return "SAME_LINE"
    if unit.subway and previous.subway:
        return "SUBWAY_OUTSIDE"
    return None


def fare_breakdown(fare_rides: Iterable[Any], used_bike: bool, clock_s: float, config: EngineConfig) -> FareBreakdown:
    """여정의 요금(§1.5). `fare_rides` 는 탑승마다 `FareRide` (또는 같은 순서의 튜플), `clock_s` 는 $c_0$ 이다.

    역 안 환승인 지하철 두 탑승은 하나로 합치고, 환승 묶음마다 가장 비싼 기본요금과 거리 추가요금을 더한다.
    기후동행카드가 적용되면 대중교통 비용만 0원이고 묶음의 요금은 내역에 그대로 남는다.
    """
    rides = [ride if isinstance(ride, FareRide) else FareRide(*ride) for ride in fare_rides]
    units: list[_FareUnit] = []
    for number, ride in enumerate(rides, start=1):
        if units and ride.in_station and ride.mode == TravelMode.SUBWAY and units[-1].subway:
            units[-1].rides.append(ride)
            units[-1].indexes.append(number)
            units[-1].distance_m += ride.distance_m
        else:
            units.append(_FareUnit([ride], [number], float(ride.distance_m)))
    grouped: list[tuple[list[_FareUnit], str | None]] = []
    for unit in units:
        reason = _break_reason(unit, grouped[-1][0], clock_s, config) if grouped else None
        if grouped and reason is None:
            grouped[-1][0].append(unit)
        else:
            grouped.append(([unit], reason))
    chains = []
    for chain_units, reason in grouped:
        distance = sum(unit.distance_m for unit in chain_units)
        chains.append(
            FareChain(
                ride_indexes=tuple(index for unit in chain_units for index in unit.indexes),
                base_krw=max(_base_fare(ride, config) for unit in chain_units for ride in unit.rides),
                distance_m=distance,
                distance_extra_krw=_distance_extra(chain_units, distance, config),
                break_reason=reason,
            )
        )
    transit = sum(chain.base_krw + chain.distance_extra_krw for chain in chains)
    eligible = all(
        ride.mode == TravelMode.SUBWAY or BusRouteType(ride.route_type) in _CLIMATE_CARD_BUS_TYPES for ride in rides
    )
    applied = bool(config.climate_card and rides and eligible)
    bike = config.bike_pass_krw if used_bike else 0
    discount = config.bike_mileage_discount_krw if used_bike and config.bike_mileage else 0
    charged = 0 if applied else transit
    return FareBreakdown(
        chains=tuple(chains),
        transit_krw=charged,
        bike_krw=bike,
        mileage_discount_krw=discount,
        climate_card_applied=applied,
        total_krw=charged + bike - discount,
    )


def fare_warnings(breakdown: FareBreakdown, config: EngineConfig) -> tuple[WarningCode, ...]:
    """요금 내역의 경고(§1.5): 인정 시간을 넘겨 새 묶음이 생김, 기후동행카드를 켰지만 적용하지 못함."""
    codes: list[WarningCode] = []
    if any(chain.break_reason == "WINDOW" for chain in breakdown.chains):
        codes.append(WarningCode.TRANSFER_WINDOW_EXCEEDED)
    if config.climate_card and breakdown.chains and not breakdown.climate_card_applied:
        codes.append(WarningCode.CLIMATE_CARD_NOT_APPLICABLE)
    return tuple(codes)


def fare_notes(config: EngineConfig) -> tuple[str, ...]:
    """요금 안내 문구(§1.5, §1.6). `FARE_NOTES` 의 자리 표시를 설정값으로 채운다(§0.4)."""
    fares = config.fare_bus_by_type_krw
    values: dict[str, Any] = {
        "fare_subway_krw": config.fare_subway_krw,
        "fare_bus_trunk_krw": fares[BusRouteType.TRUNK],
        "fare_bus_branch_krw": fares[BusRouteType.BRANCH],
        "fare_bus_circular_krw": fares[BusRouteType.CIRCULAR],
        "fare_bus_wide_area_krw": fares[BusRouteType.WIDE_AREA],
        "fare_bus_night_krw": fares[BusRouteType.NIGHT],
        "fare_bus_village_krw": fares[BusRouteType.VILLAGE],
        "fare_free_distance_km": config.fare_free_distance_km,
        "fare_step_km": config.fare_step_km,
        "fare_step_krw": config.fare_step_krw,
        "fare_long_km": config.fare_long_km,
        "fare_long_step_km": config.fare_long_step_km,
        "max_rides_per_chain": config.max_rides_per_chain,
        "max_transfers": config.max_rides_per_chain - 1,
        "bike_pass_krw": config.bike_pass_krw,
        "bike_mileage_discount_krw": config.bike_mileage_discount_krw,
        "transfer_window_min": config.transfer_window_s / 60.0,
        "transfer_window_night_min": config.transfer_window_night_s / 60.0,
        "night_from_hhmm": _clock_hhmm(config.transfer_night_from_s),
        "night_to_hhmm": _clock_hhmm(config.transfer_night_to_s),
    }
    missing = [name for name in FARE_NOTE_FIELDS if name not in values]
    if missing:
        raise ValueError(f"요금 안내의 자리 표시를 채울 값이 없습니다: {', '.join(missing)}")
    return tuple(note.format(**values) for note in FARE_NOTES)


def utility_terms(
    mean_s: float, cost_krw: float, p_star: float, t_max_s: float, cost_max_krw: float, weights: tuple[float, float, float]
) -> UtilityTerms:
    """종합 점수 $J = w_t \\bar T / T_{max} + w_c \\text{Cost} / \\text{Cost}_{max} + w_r (1 - P^{*})$ (§1.11.1).

    가중치는 합이 1 이 되게 정규화하고, 최댓값이 0 인 항은 0 이다.
    """
    total_weight = sum(weights)
    w_t, w_c, w_r = (weight / total_weight for weight in weights)
    time_term = w_t * mean_s / t_max_s if t_max_s > 0 else 0.0
    cost_term = w_c * cost_krw / cost_max_krw if cost_max_krw > 0 else 0.0
    risk_term = w_r * (1.0 - p_star)
    return UtilityTerms(
        time_term=time_term,
        cost_term=cost_term,
        risk_term=risk_term,
        total=time_term + cost_term + risk_term,
        t_max_s=t_max_s,
        cost_max_krw=cost_max_krw,
        weights=(w_t, w_c, w_r),
    )


# ===== S5. 차량 시각과 탐색 (§1.7, §1.10, §1.11.3) =====

# 걷기 라벨의 부모 가운데 차량에서 내려 생긴 종류. 가상 차량의 승차 라벨에서 같은 노선에서 내린 라벨을 뺄 때 쓴다(§1.11.3).
_RIDE_PARENT_TAGS = ("RIDE", "VORIGIN")


def _json_key(value: Any) -> str:
    """구조 키와 대표 묶기 키의 JSON 형식(공백 없음, 한글 그대로, §1.10.5)."""
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"))


@dataclass(frozen=True, eq=False)
class TripSet:
    """한 노선(버스 노선 또는 지하철 정차 패턴)의 차량 시각(§1.7). 차량은 추월 없는 순서(앞 차량이 먼저)다.

    `dep`, `arr` 는 (차량, 순번) 배열이고 시각이 없으면 NaN 이다. 버스는 두 배열이 같다($\\text{dep} = \\text{arr} = \\tau$).
    `run_s` 는 버스면 구간 운행시간 $r_i$, 지하철이면 $\\pi_{arr}(i+1) - \\pi_{dep}(i)$ 이고 `run_sources` 는 버스만 있다.
    """

    route_id: str
    mode: TravelMode
    trip_ids: tuple[str, ...]
    dep: np.ndarray
    arr: np.ndarray
    sources: tuple[tuple[TimeSource | None, ...], ...]
    full: tuple[tuple[bool, ...], ...]
    last: tuple[bool, ...]
    run_s: tuple[float, ...]
    run_sources: tuple[RunTimeSource, ...]
    warnings: tuple[EngineWarning, ...]
    usable: bool
    n_known: int
    n_synthetic: int

    @property
    def n_trips(self) -> int:
        return len(self.trip_ids)

    @property
    def n_stops(self) -> int:
        return int(self.dep.shape[1])

    def row_of(self, trip_id: str) -> int | None:
        """차량 ID 의 행 번호. 없으면 None."""
        return self.trip_ids.index(trip_id) if trip_id in self.trip_ids else None

    def times(self, row: int, which: str = "dep") -> tuple[float | None, ...]:
        """차량 하나의 순번별 출발(`dep`) 또는 도착(`arr`) 시각. 없으면 None."""
        values = self.dep[row] if which == "dep" else self.arr[row]
        return tuple(None if math.isnan(value) else float(value) for value in values)


@dataclass
class _BusVehicle:
    """버스 차량 하나를 만드는 동안의 값(§1.7.1 의 4 ~ 7)."""

    vehicle_id: str
    times: list[float | None]
    sources: list[TimeSource | None]
    full: list[bool]
    first: int
    position: int
    last: bool


def _bus_run_times(
    line: BusLine, observed: dict[str, dict[int, float]], config: EngineConfig
) -> tuple[tuple[float, ...], tuple[RunTimeSource, ...]]:
    """구간 운행시간 $r_i$ 와 출처(§1.7.1 의 3). 두 순번에 함께 관측된 차량 가운데 뒤 순번이 가장 이른 차량(같으면 ID 순)."""
    runs: list[float] = []
    sources: list[RunTimeSource] = []
    for index in range(len(line.stop_ids) - 1):
        best: tuple[float, str] | None = None
        for vehicle in sorted(observed):
            times = observed[vehicle]
            if index in times and index + 1 in times and (best is None or times[index + 1] < best[0]):
                best = (times[index + 1], vehicle)
        if best is None:
            runs.append(line.segment_dist_m[index] / config.bus_design_speed_mps)
            sources.append(RunTimeSource.DESIGN)
        else:
            times = observed[best[1]]
            runs.append(max(0.0, times[index + 1] - times[index]))
            sources.append(RunTimeSource.PREDICTION)
    return tuple(runs), tuple(sources)


def _bus_position(first: int, sect_values: list[int]) -> int:
    """차량의 위치: 관측 항목의 `sect_ord` 가운데 가장 흔한 값(같으면 큰 값), 없으면 처음 관측 순번(§1.7.1 의 5)."""
    if not sect_values:
        return first
    counts = Counter(sect_values)
    return max(counts, key=lambda value: (counts[value], value))


def _vehicle_order(a: _BusVehicle, b: _BusVehicle) -> int:
    """앞 차량이 먼저 오게 하는 비교(§1.7.1 의 5): 위치가 큰 쪽, 같으면 처음 함께 시각이 있는 순번의 시각이 작은 쪽."""
    if a.position != b.position:
        return -1 if a.position > b.position else 1
    for time_a, time_b in zip(a.times, b.times):
        if time_a is not None and time_b is not None:
            return -1 if time_a < time_b else (1 if time_a > time_b else 0)
    return 0


def _stack(rows: list[list[float | None]], n_stops: int) -> np.ndarray:
    """시각 목록(없으면 None)을 (차량, 순번) 배열로 바꾼다. 없는 시각은 NaN."""
    if not rows:
        return np.zeros((0, n_stops), dtype=float)
    return np.array([[math.nan if value is None else value for value in row] for row in rows], dtype=float)


def build_bus_trips(line: BusLine, clock_s: float, config: EngineConfig) -> TripSet:
    """버스 예측에서 차량 시각을 만든다(§1.7.1). `clock_s` 는 기점 막차를 비교하는 기준 시계 시각 $c_0$ 다."""
    n = len(line.stop_ids)
    warnings: list[EngineWarning] = []
    observed: dict[str, dict[int, float]] = {}
    full_flags: dict[str, dict[int, bool]] = {}
    last_flags: dict[str, bool] = {}
    sect_values: dict[str, list[int]] = {}
    items = [(index, item) for index, row in enumerate(line.predictions) for item in row]
    ended = any(item.kind == PredictionKind.ENDED for _, item in items)
    any_last = any(item.is_last for _, item in items)
    for index, item in items:
        if item.kind != PredictionKind.NORMAL or item.eta_s is None:
            continue
        vehicle = item.vehicle_id
        times = observed.setdefault(vehicle, {})
        times[index] = min(times.get(index, math.inf), float(item.eta_s))
        flags = full_flags.setdefault(vehicle, {})
        flags[index] = flags.get(index, False) or item.is_full
        last_flags[vehicle] = last_flags.get(vehicle, False) or item.is_last
        if item.sect_ord is not None:
            sect_values.setdefault(vehicle, []).append(item.sect_ord)
    for vehicle, times in observed.items():
        running, fixed = -math.inf, 0
        for index in sorted(times):
            if times[index] < running:
                times[index] = running
                fixed += 1
            running = times[index]
        if fixed:
            warnings.append(
                EngineWarning(
                    code=WarningCode.PREDICTION_NOT_MONOTONE,
                    message=f"버스 {line.id} 차량 {vehicle}: 도착 예측이 순번을 따라 줄어 {fixed}개 순번을 앞 값으로 올렸습니다",
                    ref_ids=(line.id, vehicle),
                )
            )
    if line.prediction_age_s is not None and line.prediction_age_s > config.prediction_stale_s:
        warnings.append(
            EngineWarning(
                code=WarningCode.STALE_PREDICTION,
                message=f"버스 {line.id}: 예측을 관측한 지 {line.prediction_age_s:.0f}초가 지났습니다(기준 {config.prediction_stale_s:.0f}초)",
                ref_ids=(line.id,),
            )
        )
    run_s, run_sources = _bus_run_times(line, observed, config)
    if not observed:
        warnings.append(
            EngineWarning(
                code=WarningCode.NO_VEHICLE_TIMES,
                message=f"버스 {line.id}: 시각을 아는 차량이 없어 이번 질의에서 쓰지 않습니다",
                ref_ids=(line.id,),
            )
        )
        empty = _stack([], n)
        return TripSet(line.id, TravelMode.BUS, (), empty, empty.copy(), (), (), (), run_s, run_sources, tuple(warnings), False, 0, 0)
    vehicles: list[_BusVehicle] = []
    for vehicle, times in observed.items():
        first = min(times)
        tau: list[float | None] = [None] * n
        sources: list[TimeSource | None] = [None] * n
        for index in range(first, n):
            if index in times:
                tau[index], sources[index] = times[index], TimeSource.PREDICTED
            else:
                tau[index], sources[index] = tau[index - 1] + run_s[index - 1], TimeSource.EXTENDED
        running = -math.inf
        for index in range(first, n):
            running = max(running, tau[index])
            tau[index] = running
        vehicles.append(
            _BusVehicle(
                vehicle_id=vehicle,
                times=tau,
                sources=sources,
                full=[full_flags[vehicle].get(index, False) for index in range(n)],
                first=first,
                position=_bus_position(first, sect_values.get(vehicle, [])),
                last=last_flags.get(vehicle, False),
            )
        )
    ordered = sorted(vehicles, key=functools.cmp_to_key(_vehicle_order))
    for ahead, behind in zip(ordered, ordered[1:]):
        fixed = 0
        for index in range(n):
            mine, front = behind.times[index], ahead.times[index]
            if mine is not None and front is not None and mine < front:
                behind.times[index] = front
                fixed += 1
        if fixed:
            warnings.append(
                EngineWarning(
                    code=WarningCode.PREDICTION_OVERTAKE,
                    message=f"버스 {line.id} 차량 {behind.vehicle_id}: 앞 차량 {ahead.vehicle_id} 보다 이른 {fixed}개 순번을 앞 차량 시각으로 올렸습니다",
                    ref_ids=(line.id, behind.vehicle_id),
                )
            )
    known: list[_BusVehicle] = []
    for vehicle in ordered:
        known.append(vehicle)
        if vehicle.last:
            break
    ids = [f"{line.id}:{vehicle.vehicle_id}" for vehicle in known]
    rows = [list(vehicle.times) for vehicle in known]
    time_sources: list[tuple[TimeSource | None, ...]] = [tuple(vehicle.sources) for vehicle in known]
    fulls = [tuple(vehicle.full) for vehicle in known]
    lasts = [vehicle.last for vehicle in known]
    rear = known[-1]
    virtual: list[float] = [0.0] * n
    for index in range(rear.first, n):
        virtual[index] = rear.times[index]
    for index in range(rear.first - 1, -1, -1):
        virtual[index] = virtual[index + 1] - run_s[index]
    if ended or any_last:
        pass
    elif line.headway_s is None or line.headway_s <= 0:
        warnings.append(
            EngineWarning(code=WarningCode.NO_HEADWAY, message=f"버스 {line.id}: 배차 간격이 없어 뒤 차량을 잇지 않습니다", ref_ids=(line.id,))
        )
    else:
        k = 1
        while True:
            start = virtual[0] + k * line.headway_s
            if start > config.horizon_s:
                break
            if line.last_departure_clock_s is not None and clock_s + start > line.last_departure_clock_s:
                break
            ids.append(f"{line.id}:+{k}")
            rows.append([value + k * line.headway_s for value in virtual])
            time_sources.append(tuple([TimeSource.HEADWAY] * n))
            fulls.append(tuple([False] * n))
            lasts.append(False)
            k += 1
    times_array = _stack(rows, n)
    return TripSet(
        route_id=line.id,
        mode=TravelMode.BUS,
        trip_ids=tuple(ids),
        dep=times_array,
        arr=times_array.copy(),
        sources=tuple(time_sources),
        full=tuple(fulls),
        last=tuple(lasts),
        run_s=run_s,
        run_sources=run_sources,
        warnings=tuple(warnings),
        usable=True,
        n_known=len(known),
        n_synthetic=len(ids) - len(known),
    )


def _median_profile(dep: np.ndarray, arr: np.ndarray) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """지하철 운행 프로필: $\\pi_{dep}(i)$ = 중앙값($\\text{dep}_v(i) - \\text{dep}_v(0)$), $\\pi_{arr}$ 도 같은 기준(§1.11.3)."""
    base = dep[:, 0]
    n = dep.shape[1]
    pi_dep = tuple(float(statistics.median((dep[:, index] - base).tolist())) for index in range(n))
    pi_arr = tuple(float(statistics.median((arr[:, index] - base).tolist())) for index in range(n))
    return pi_dep, pi_arr


def pattern_trips(pattern: SubwayPattern, config: EngineConfig) -> TripSet:
    """정차 패턴의 열차를 차량 배열로 바꾸고 추월이 없는지 다시 확인한다(§1.7.2 의 6, 8).

    열차를 (첫 순번 출발, 열차 ID) 순으로 늘어놓고, 바로 앞 열차보다 이른 `dep`·`arr` 를 앞 열차 값으로 올린다.
    `config` 는 계약의 인자이고 지금 규칙에서는 쓰지 않는다(범위 거르기는 시나리오 준비가 한다, §1.7.2 의 4).
    """
    del config
    trips = sorted(pattern.trips, key=lambda trip: (trip.dep_s[0], trip.id))
    dep = np.array([trip.dep_s for trip in trips], dtype=float)
    arr = np.array([trip.arr_s for trip in trips], dtype=float)
    warnings: list[EngineWarning] = []
    for row in range(1, len(trips)):
        raised = (dep[row] < dep[row - 1]) | (arr[row] < arr[row - 1])
        if raised.any():
            dep[row] = np.maximum(dep[row], dep[row - 1])
            arr[row] = np.maximum(arr[row], arr[row - 1])
            warnings.append(
                EngineWarning(
                    code=WarningCode.TIMETABLE_OVERTAKE,
                    message=f"패턴 {pattern.id} 열차 {trips[row].id}: 앞 열차보다 이른 {int(raised.sum())}개 순번을 앞 열차 시각으로 올렸습니다",
                    ref_ids=(pattern.id, trips[row].id),
                )
            )
    pi_dep, pi_arr = _median_profile(dep, arr)
    n = dep.shape[1]
    return TripSet(
        route_id=pattern.id,
        mode=TravelMode.SUBWAY,
        trip_ids=tuple(trip.id for trip in trips),
        dep=dep,
        arr=arr,
        sources=tuple(tuple([TimeSource.TIMETABLE] * n) for _ in trips),
        full=tuple(tuple([False] * n) for _ in trips),
        last=tuple(False for _ in trips),
        run_s=tuple(pi_arr[index + 1] - pi_dep[index] for index in range(n - 1)),
        run_sources=(),
        warnings=tuple(warnings),
        usable=True,
        n_known=len(trips),
        n_synthetic=0,
    )


def run_profile(trip_set: TripSet) -> tuple[tuple[float, ...], tuple[float, ...]]:
    """노선의 운행 프로필 ($\\pi_{dep}$, $\\pi_{arr}$) (§1.11.3). 버스는 $\\pi(i+1) = \\pi(i) + r_i$ 이고 두 값이 같다."""
    if trip_set.mode == TravelMode.SUBWAY:
        return _median_profile(trip_set.dep, trip_set.arr)
    profile = [0.0]
    for run in trip_set.run_s:
        profile.append(profile[-1] + run)
    return tuple(profile), tuple(profile)


def line_times(trip_set: TripSet) -> LineTimes:
    """화면과 결과에 남기는 노선의 차량 요약(§3.3 `LineTimes`)."""
    return LineTimes(
        route_id=trip_set.route_id,
        mode=trip_set.mode,
        run_s=trip_set.run_s,
        run_source=trip_set.run_sources,
        trip_ids=trip_set.trip_ids,
        n_known=trip_set.n_known,
        n_synthetic=trip_set.n_synthetic,
        usable=trip_set.usable,
    )


def stop_vehicle_order(trip_set: TripSet, index: int) -> tuple[tuple[str, float, TimeSource | None], ...]:
    """순번 `index` 에서 본 차량 순서(§1.7.1): 시각이 0 이상인 차량을 (시각, 노선의 차량 순서) 순으로."""
    rows = [row for row in range(trip_set.n_trips) if not math.isnan(trip_set.dep[row, index]) and trip_set.dep[row, index] >= 0]
    rows.sort(key=lambda row: (float(trip_set.dep[row, index]), row))
    return tuple((trip_set.trip_ids[row], float(trip_set.dep[row, index]), trip_set.sources[row][index]) for row in rows)


@dataclass(frozen=True, eq=False)
class BoardIndex:
    """노선의 탈 수 있는 차량 배열(§1.7.3). 순번마다 출발 시각(오름차순)과 같은 순서의 차량 행 번호, (차량, 순번)마다 내릴 수 있는지와
    만차 상태(그 순번 이하에서 차량이 관측된 마지막 순번의 만차 표시, 관측된 순번이 없으면 거짓)."""

    route_id: str
    node_ids: tuple[str, ...]
    deps: tuple[np.ndarray, ...]
    rows: tuple[np.ndarray, ...]
    alight: np.ndarray
    full_state: np.ndarray

    def first_row(self, index: int, t: float) -> int | None:
        """순번 `index` 에서 출발이 `t` 이상인 첫 차량의 행 번호(`searchsorted` left). 없으면 None."""
        deps = self.deps[index]
        position = int(np.searchsorted(deps, t, side="left"))
        return int(self.rows[index][position]) if position < len(deps) else None


def full_state(trip_set: TripSet) -> np.ndarray:
    """(차량, 순번)마다 만차 상태(§1.7.3): 그 순번 이하에서 차량이 관측된(`PREDICTED`) 마지막 순번의 만차 표시.

    관측된 순번이 없으면(합성 차량, 지하철 열차) 거짓이다. 관측이 끝난 뒤의 순번은 앞 정류장에서 본 표시를 이어 쓴다.
    """
    state = np.zeros((trip_set.n_trips, trip_set.n_stops), dtype=bool)
    for row in range(trip_set.n_trips):
        current = False
        for index in range(trip_set.n_stops):
            if trip_set.sources[row][index] == TimeSource.PREDICTED:
                current = bool(trip_set.full[row][index])
            state[row, index] = current
    return state


def board_index(trip_set: TripSet, node_ids: Sequence[str], kept_ids: frozenset[str] | set[str], config: EngineConfig) -> BoardIndex:
    """탈 수 있는 차량의 출발 시각 배열과 내릴 수 있는 곳(§1.7.3).

    타려면 출발 시각이 있고, 노드가 가지치기에서 남았고, `SKIP` 이면 그 순번의 만차 상태가 거짓이어야 한다.
    내리려면 도착 시각이 있고 노드가 남았어야 한다(만차 정책과 상관없다).
    """
    skip_full = config.full_vehicle_policy == FullVehiclePolicy.SKIP
    state = full_state(trip_set)
    deps: list[np.ndarray] = []
    rows: list[np.ndarray] = []
    for index, node_id in enumerate(node_ids):
        chosen: list[int] = []
        if node_id in kept_ids:
            chosen = [
                row
                for row in range(trip_set.n_trips)
                if not math.isnan(trip_set.dep[row, index]) and not (skip_full and state[row, index])
            ]
        chosen.sort(key=lambda row: (float(trip_set.dep[row, index]), row))
        deps.append(np.array([trip_set.dep[row, index] for row in chosen], dtype=float))
        rows.append(np.array(chosen, dtype=int))
    kept_mask = np.array([node_id in kept_ids for node_id in node_ids], dtype=bool)
    alight = ~np.isnan(trip_set.arr) & kept_mask[np.newaxis, :]
    return BoardIndex(trip_set.route_id, tuple(node_ids), tuple(deps), tuple(rows), alight, state)


@dataclass(frozen=True, eq=False)
class RideVehicles:
    """한 탑승의 유효 차량열(§1.7.4 (3)). 위치마다 노선 ID, 그 노선 `TripSet` 의 행, 차량 ID, 승차 순번의 출발과 하차 순번의
    도착(둘 다 오름차순), 승차 순번의 시각 출처와 만차 상태, 막차 여부다. `lines` 는 묶음의 (노선 ID, 승차 순번, 하차 순번)이다.
    노선이 하나뿐이면 그 노선의 탈 수 있는 차량 배열(`BoardIndex`)과 같다."""

    lines: tuple[tuple[str, int, int], ...]
    route_ids: tuple[str, ...]
    rows: np.ndarray
    trip_ids: tuple[str, ...]
    deps: np.ndarray
    arrs: np.ndarray
    sources: tuple[TimeSource | None, ...]
    full: tuple[bool, ...]
    last: tuple[bool, ...]

    @property
    def size(self) -> int:
        return int(self.deps.size)

    def indices(self, route_id: str) -> tuple[int, int]:
        """묶음에서 그 노선의 (승차 순번, 하차 순번)."""
        for line_id, board, alight in self.lines:
            if line_id == route_id:
                return board, alight
        raise KeyError(f"노선 {route_id} 은 이 묶음에 없습니다")

    def first(self, t: float) -> int | None:
        """출발이 `t` 이상인 첫 위치(`searchsorted` left). 없으면 None."""
        position = int(np.searchsorted(self.deps, t, side="left"))
        return position if position < self.size else None

    def position_of(self, trip_id: str) -> int | None:
        """차량 ID 의 위치. 없으면 None."""
        return self.trip_ids.index(trip_id) if trip_id in self.trip_ids else None


class Hop(NamedTuple):
    """경로의 한 걸음: (출발 노드, 도착 노드, 길이 m, 신호 ID, 엣지 ID, 수단). 같은 두 노드 사이의 엣지는 따로 다룬다."""

    from_id: str
    to_id: str
    length_m: float
    signal_id: str | None
    edge_id: str
    mode: Mode


@dataclass(frozen=True, eq=False)
class Graph:
    """가지치기에서 남은 노드와 엣지의 걷기·주행 그래프(§1.10.1). 인접 목록은 (이웃 노드 ID, 엣지 ID) 순이다."""

    kept: frozenset[str]
    nodes: dict[str, Node]
    edges: dict[str, Edge]
    lengths: dict[str, float]
    signals: dict[str, SignalPhase]
    adjacency: dict[Mode, dict[str, tuple[Hop, ...]]]
    bike_stations: dict[str, BikeStation]
    expected_waits: dict[str, float]
    worst_waits: dict[str, float]

    @property
    def has_sampled_signal(self) -> bool:
        """남은 엣지에 위상을 모르는 신호(미개방 고정, 감응)가 하나라도 있나(§1.10.5 의 AVERSE 조건)."""
        return any(
            edge.signal_id is not None and not is_open_signal(self.signals[edge.signal_id]) for edge in self.edges.values()
        )

    def hop_wait(self, hop: Hop, t: float, rule: WaitRule) -> float:
        """엣지에 시각 t 에 들어설 때의 신호 대기 $w_e(t)$ (§1.10.3 의 표)."""
        if hop.signal_id is None or rule == WaitRule.NONE:
            return 0.0
        phase = self.signals[hop.signal_id]
        if is_open_signal(phase):
            cycle = phase.cycle_s
            tau = _wrap(phase.offset_s + t, cycle)
            return 0.0 if tau < phase.green_s else cycle - tau
        return self.worst_waits[hop.signal_id] if rule == WaitRule.WORST else self.expected_waits[hop.signal_id]


def build_graph(scenario: Scenario, kept_ids: frozenset[str] | set[str], config: EngineConfig) -> Graph:
    """남은 노드 사이의 엣지로 걷기(WALK)·주행(BIKE) 그래프를 만든다(§1.1, §1.10.1).

    엣지는 양 끝이 모두 남고, 신호가 있으면 그 교차로 노드도 남았을 때만 쓴다. 양방향 엣지는 양쪽으로 넣는다.
    """
    index = _node_index(scenario)
    signals = {phase.id: phase for phase in scenario.signals}
    kept = frozenset(kept_ids)
    edges: dict[str, Edge] = {}
    lengths: dict[str, float] = {}
    adjacency: dict[Mode, dict[str, list[Hop]]] = {Mode.WALK: {}, Mode.BIKE: {}}
    for edge in sorted(scenario.edges, key=lambda item: item.id):
        if edge.source not in kept or edge.target not in kept or edge.source == edge.target:
            continue
        if edge.signal_id is not None and signals[edge.signal_id].intersection_id not in kept:
            continue
        length = edge_length_m(edge, index, config)
        edges[edge.id] = edge
        lengths[edge.id] = length
        for mode in edge.modes:
            adjacency[mode].setdefault(edge.source, []).append(Hop(edge.source, edge.target, length, edge.signal_id, edge.id, mode))
            if edge.bidirectional:
                adjacency[mode].setdefault(edge.target, []).append(Hop(edge.target, edge.source, length, edge.signal_id, edge.id, mode))
    sorted_adjacency = {
        mode: {node: tuple(sorted(hops, key=lambda hop: (hop.to_id, hop.edge_id))) for node, hops in table.items()}
        for mode, table in adjacency.items()
    }
    used_signals = {edge.signal_id for edge in edges.values() if edge.signal_id is not None}
    sampled = [signal_id for signal_id in sorted(used_signals) if not is_open_signal(signals[signal_id])]
    return Graph(
        kept=kept,
        nodes={node_id: node for node_id, node in index.items() if node_id in kept},
        edges=edges,
        lengths=lengths,
        signals=signals,
        adjacency=sorted_adjacency,
        bike_stations={station.id: station for station in scenario.bike_stations if station.id in kept},
        expected_waits={signal_id: stochastic_wait(signals[signal_id])[0] for signal_id in sampled},
        worst_waits={signal_id: worst_wait(signals[signal_id]) for signal_id in sampled},
    )


def shortest_distance_path(graph: Graph, src: str, dst: str, mode: Mode | str = Mode.WALK) -> tuple[Hop, ...] | None:
    """최단거리 경로(§1.2 의 대체 보행, §1.11.3 의 기존 방식). 큐는 (거리, 노드 ID) 순, 라벨은 엄격히 작아질 때만 바꾼다.

    출발과 도착이 같으면 빈 경로, 닿지 못하면 None 이다.
    """
    if src == dst:
        return ()
    if src not in graph.kept or dst not in graph.kept:
        return None
    table = graph.adjacency[Mode(mode)]
    best = {src: 0.0}
    parent: dict[str, Hop] = {}
    heap: list[tuple[float, str]] = [(0.0, src)]
    while heap:
        distance, node = heapq.heappop(heap)
        if distance > best[node]:
            continue
        if node == dst:
            break
        for hop in table.get(node, ()):
            candidate = distance + hop.length_m
            if candidate < best.get(hop.to_id, math.inf):
                best[hop.to_id] = candidate
                parent[hop.to_id] = hop
                heapq.heappush(heap, (candidate, hop.to_id))
    if dst not in best:
        return None
    path: list[Hop] = []
    node = dst
    while node != src:
        hop = parent[node]
        path.append(hop)
        node = hop.from_id
    return tuple(reversed(path))


def _hop_points(hop: Hop, edge: Edge | None) -> list[tuple[float, float]]:
    """엣지의 중간 좌표를 지나는 방향으로(엣지를 거꾸로 지나면 뒤집는다)."""
    if edge is None or not edge.via:
        return []
    points = [tuple(point) for point in edge.via]
    return points if hop.from_id == edge.source else list(reversed(points))


def propagate(
    scenario: Scenario,
    hops: Sequence[Hop],
    t0_s: float,
    speed_mps: float,
    rule: WaitRule | str,
    *,
    graph: Graph | None = None,
    start_id: str | None = None,
) -> PathResult:
    """경로를 시각 `t0_s` 에서 출발해 차례로 지나간다(§1.2 의 순차 전파). 신호 대기는 엣지에 들어설 때 규칙대로 더한다.

    `graph` 를 주면 노드·엣지·신호 표를 다시 만들지 않는다. 빈 경로는 `start_id` 노드 하나의 결과다.
    """
    kind = WaitRule(rule)
    if graph is not None:
        nodes, edges, signals = graph.nodes, graph.edges, graph.signals
    else:
        nodes = _node_index(scenario)
        edges = {edge.id: edge for edge in scenario.edges}
        signals = {phase.id: phase for phase in scenario.signals}
    first = hops[0].from_id if hops else start_id
    if first is None:
        raise ValueError("빈 경로에는 start_id 가 필요합니다")
    node_ids = [first]
    polyline: list[tuple[float, float]] = [_latlon(nodes[first])]
    t = float(t0_s)
    travel = wait = distance = 0.0
    events: list[SignalEvent] = []
    for hop in hops:
        if hop.signal_id is not None:
            event = signal_event(signals[hop.signal_id], t, kind)
            events.append(event)
            t += event.wait_s
            wait += event.wait_s
        step = hop.length_m / speed_mps
        t += step
        travel += step
        distance += hop.length_m
        node_ids.append(hop.to_id)
        polyline.extend(_hop_points(hop, edges.get(hop.edge_id)))
        polyline.append(_latlon(nodes[hop.to_id]))
    return PathResult(
        node_ids=tuple(node_ids),
        edge_ids=tuple(hop.edge_id for hop in hops),
        polyline=tuple(polyline),
        distance_m=distance,
        t_start_s=float(t0_s),
        t_end_s=t,
        travel_s=travel,
        wait_s=wait,
        events=tuple(events),
    )


@dataclass
class Labels:
    """시간 의존 Dijkstra 의 결과: 노드별 도착 시각, 부모 걸음(출처면 None), 그 라벨이 시작한 출처 노드."""

    times: dict[str, float]
    parents: dict[str, Hop | None]
    roots: dict[str, str]

    def path_to(self, node_id: str) -> tuple[Hop, ...]:
        """출처에서 그 노드까지의 걸음."""
        path: list[Hop] = []
        node = node_id
        while self.parents[node] is not None:
            hop = self.parents[node]
            path.append(hop)
            node = hop.from_id
        return tuple(reversed(path))


def td_dijkstra(
    graph: Graph,
    sources: Iterable[tuple[str, float]],
    mode: Mode | str,
    speed_mps: float,
    rule: WaitRule | str,
    prune: Callable[[str, float], bool] | None = None,
) -> Labels:
    """다중 출발 시간 의존 Dijkstra (§1.10.3). 엣지를 나오는 시각은 $t + w_e(t) + \\ell_e / s$ 다.

    큐는 (시각, 노드 ID) 순으로 꺼내고, 꺼낸 시각이 라벨보다 크면 건너뛴다. 라벨은 엄격히 작아질 때만 바꾼다.
    `prune(노드, 시각)` 은 자기 라벨보다 엄격히 작은 후보에만 불리고, 참이면 그 라벨을 만들지 않는다(지배·목표 가지치기).
    거짓을 돌려주면 그 라벨이 바로 쓰인다.
    """
    kind = WaitRule(rule)
    table = graph.adjacency[Mode(mode)]
    times: dict[str, float] = {}
    parents: dict[str, Hop | None] = {}
    roots: dict[str, str] = {}
    for node, t in sorted(sources, key=lambda item: (item[1], item[0])):
        if t < times.get(node, math.inf):
            times[node], parents[node], roots[node] = float(t), None, node
    heap = [(t, node) for node, t in times.items()]
    heapq.heapify(heap)
    while heap:
        t, node = heapq.heappop(heap)
        if t > times[node]:
            continue
        for hop in table.get(node, ()):
            arrival = t + graph.hop_wait(hop, t, kind) + hop.length_m / speed_mps
            if arrival >= times.get(hop.to_id, math.inf):
                continue
            if prune is not None and prune(hop.to_id, arrival):
                continue
            times[hop.to_id], parents[hop.to_id], roots[hop.to_id] = arrival, hop, roots[node]
            heapq.heappush(heap, (arrival, hop.to_id))
    return Labels(times, parents, roots)


@dataclass(frozen=True, eq=False)
class RouteData:
    """탐색이 쓰는 노선 하나(버스 노선 또는 지하철 정차 패턴): 차량 배열, 탈 수 있는 차량, 운행 프로필."""

    route_id: str
    mode: TravelMode
    name: str  # 버스는 노선 번호, 지하철은 호선
    display_name: str  # Ride.route_name
    bus_type: BusRouteType | None
    node_ids: tuple[str, ...]
    segment_dist_m: tuple[float, ...]
    trips: TripSet
    board: BoardIndex
    pi_dep: tuple[float, ...]
    pi_arr: tuple[float, ...]
    direction: str = ""  # 지하철 정차 패턴의 방향(묶음의 요금 종류, §1.7.4). 버스는 ""

    @property
    def usable(self) -> bool:
        return self.trips.usable

    @property
    def short_label(self) -> str:
        """여정 이름의 탑승 부분(§1.10.5): 버스 "{번호}번", 지하철 "지하철 {호선}"."""
        return f"{self.name}번" if self.mode == TravelMode.BUS else f"지하철 {self.name}"


@dataclass(eq=False)
class SearchContext:
    """한 질의의 탐색 준비: 붙인 시나리오, 출발·목적지, 가지치기, 그래프, 노선(ID 순), 차량 안 출발의 탄 차량.

    `path_cache`, `plan_cache`, `vehicle_cache` (묶음마다 유효 차량열, §1.7.4)는 이 질의 안에서만 쓰는 함수 지역 캐시다(§3.6).
    """

    scenario: Scenario
    query: Query
    config: EngineConfig
    origin_id: str
    destination_id: str
    pruning: PruningSummary
    pruning_records: tuple[PruningRecord, ...]
    graph: Graph
    routes: dict[str, RouteData]
    boarding_nodes: frozenset[str]
    origin_route: str | None
    origin_row: int | None
    origin_index: int | None
    warnings: tuple[EngineWarning, ...]
    path_cache: dict[tuple[str, str, Mode], tuple[Hop, ...] | None] = field(default_factory=dict)
    plan_cache: dict[str, "Plan"] = field(default_factory=dict)
    vehicle_cache: dict[tuple[tuple[str, int | None, int], ...], RideVehicles] = field(default_factory=dict)

    @property
    def kept(self) -> frozenset[str]:
        return self.graph.kept

    @property
    def in_vehicle(self) -> bool:
        return self.origin_route is not None

    def shortest(self, src: str, dst: str, mode: Mode = Mode.WALK) -> tuple[Hop, ...] | None:
        """같은 (출발, 도착, 수단)의 최단거리 경로는 한 번만 구한다(§3.6)."""
        key = (src, dst, Mode(mode))
        if key not in self.path_cache:
            self.path_cache[key] = shortest_distance_path(self.graph, src, dst, mode)
        return self.path_cache[key]


def _snap_failure(scenario: Scenario, lat: float, lon: float, config: EngineConfig, role: str) -> EngineWarning:
    nearest = _nearest_ground(scenario, lat, lon, config)
    where = "붙일 지상 노드가 없습니다" if nearest is None else f"가장 가까운 노드 {nearest[1]} 까지 {nearest[0]:.2f} m"
    return EngineWarning(
        code=WarningCode.SNAP_FAILED,
        message=f"찍은 {role}을 보행망에 붙이지 못했습니다: {where}(한도 {config.snap_max_m:g} m)",
        ref_ids=() if nearest is None else (nearest[1],),
    )


def _subway_display_name(pattern: SubwayPattern, stations: dict[str, SubwayStation]) -> str:
    """지하철 탑승의 화면 이름 "{호선} {방향} {패턴 마지막 역 이름}행" (§3.3 `Ride`)."""
    last = stations.get(pattern.station_keys[-1])
    return f"{pattern.line} {pattern.direction} {last.name if last else pattern.station_keys[-1]}행"


def build_search_context(scenario: Scenario, query: Query, config: EngineConfig) -> tuple[SearchContext | None, EngineWarning | None]:
    """질의 하나의 탐색을 준비한다: 좌표 붙이기, 차량 시각, 가지치기, 그래프, 탈 수 있는 차량 배열(§1.10.1, §1.7).

    붙이기에 실패하면 (None, SNAP_FAILED 경고)다. 차량 안 출발의 노선·차량·순번이 시나리오와 맞지 않으면 ValueError.
    """
    origin = query.origin
    if origin.kind == OriginKind.AT_POINT:
        snapped = snap_point(scenario, origin.lat, origin.lon, ORIGIN_POINT_ID, config)
        if snapped is None:
            return None, _snap_failure(scenario, origin.lat, origin.lon, config, "출발점")
        scenario = snapped[0]
    if query.destination_node_id is None:
        snapped = snap_point(scenario, query.destination_lat, query.destination_lon, DESTINATION_POINT_ID, config)
        if snapped is None:
            return None, _snap_failure(scenario, query.destination_lat, query.destination_lon, config, "목적지")
        scenario = snapped[0]
        destination = DESTINATION_POINT_ID
    else:
        destination = query.destination_node_id
    warnings: list[EngineWarning] = []
    stations = {station.key: station for station in scenario.subway_stations}
    raw: list[tuple[str, TravelMode, str, str, BusRouteType | None, tuple[str, ...], tuple[float, ...], TripSet, str]] = []
    for line in scenario.bus_lines:
        trips = build_bus_trips(line, scenario.clock_s, config)
        warnings.extend(trips.warnings)
        raw.append((line.id, TravelMode.BUS, line.name, line.name, line.route_type, line.stop_ids, line.segment_dist_m, trips, ""))
    for pattern in scenario.subway_patterns:
        trips = pattern_trips(pattern, config)
        warnings.extend(trips.warnings)
        raw.append(
            (
                pattern.id,
                TravelMode.SUBWAY,
                pattern.line,
                _subway_display_name(pattern, stations),
                None,
                pattern.platform_ids,
                pattern.segment_dist_m,
                trips,
                pattern.direction,
            )
        )
    by_id = {item[0]: item for item in raw}
    origin_route = origin_row = origin_index = None
    if origin.kind == OriginKind.AT_NODE:
        origin_id = origin.node_id
    elif origin.kind == OriginKind.AT_POINT:
        origin_id = ORIGIN_POINT_ID
    else:
        route_id = origin.line_id if origin.kind == OriginKind.ON_BUS else origin.pattern_id
        if route_id not in by_id:
            raise ValueError(f"차량 안 출발의 노선·패턴 {route_id} 이 시나리오에 없습니다")
        trips = by_id[route_id][7]
        row = trips.row_of(origin.trip_id)
        if row is None:
            raise ValueError(f"차량 안 출발의 차량 {origin.trip_id} 이 노선 {route_id} 의 차량 목록에 없습니다")
        nodes = by_id[route_id][5]
        if origin.next_index is None or origin.next_index >= len(nodes):
            raise ValueError(f"차량 안 출발의 다음 순번 {origin.next_index} 이 노선 {route_id} 의 범위 밖입니다")
        origin_route, origin_row, origin_index = route_id, row, origin.next_index
        origin_id = nodes[origin.next_index]
    summary, records, kept = prune_by_ellipse(scenario, origin_id, destination, config)
    graph = build_graph(scenario, kept, config)
    routes: dict[str, RouteData] = {}
    for route_id, mode, name, display, bus_type, nodes, distances, trips, direction in sorted(raw, key=lambda item: item[0]):
        pi_dep, pi_arr = run_profile(trips)
        routes[route_id] = RouteData(
            route_id=route_id,
            mode=mode,
            name=name,
            display_name=display,
            bus_type=bus_type,
            node_ids=tuple(nodes),
            segment_dist_m=tuple(distances),
            trips=trips,
            board=board_index(trips, nodes, kept, config),
            pi_dep=pi_dep,
            pi_arr=pi_arr,
            direction=direction,
        )
    boarding = frozenset(node for route in routes.values() for node in route.node_ids)
    return (
        SearchContext(
            scenario=scenario,
            query=query,
            config=config,
            origin_id=origin_id,
            destination_id=destination,
            pruning=summary,
            pruning_records=records,
            graph=graph,
            routes=routes,
            boarding_nodes=boarding,
            origin_route=origin_route,
            origin_row=origin_row,
            origin_index=origin_index,
            warnings=tuple(warnings),
        ),
        None,
    )


@dataclass(frozen=True)
class RunConditions:
    """실행 조건 하나(§1.10.5 의 표): 수단, 속도 배수, 대기 규칙, 따릉이 상한, 승차 여유, 건너뛰었는지."""

    run: SearchRun
    skipped: bool
    skip_reason: str
    modes: tuple[TravelMode, ...]
    m: float
    rule: WaitRule
    bike_limit: int
    buffer_s: float

    @property
    def naive(self) -> bool:
        return self.run == SearchRun.NAIVE


def run_conditions(context: SearchContext, run: SearchRun, config: EngineConfig) -> RunConditions:
    """§1.10.5 의 실행표대로 조건을 정한다. 수단은 TravelMode 정의 순서로 적고, BIKE 가 없으면 따릉이 상한은 0 이다."""
    enabled = set(config.modes_enabled)
    m, rule, buffer_s, reason = 1.0, WaitRule.EXPECTED, config.safety_buffer_s, ""
    both = TravelMode.BUS in enabled and TravelMode.SUBWAY in enabled
    if run == SearchRun.FULL:
        modes, bikes = enabled, config.max_bike_legs
    elif run == SearchRun.NO_BIKE:
        modes, bikes = enabled - {TravelMode.BIKE}, 0
        if not (TravelMode.BIKE in enabled and config.max_bike_legs >= 1):
            reason = "따릉이가 꺼져 있거나 따릉이 상한이 0 이라 FULL 과 같습니다"
    elif run in (SearchRun.BUS_ONLY, SearchRun.SUBWAY_ONLY):
        modes, bikes = {TravelMode.BUS if run == SearchRun.BUS_ONLY else TravelMode.SUBWAY}, 0
        if not both:
            reason = "버스와 지하철이 함께 켜져 있지 않습니다"
    elif run == SearchRun.SLOW:
        modes, bikes, m = enabled, config.max_bike_legs, config.m_slow
        if not config.k_move > 0:
            reason = "걷는 속도의 개인차(k_move)가 0 이라 느린 사람 조건이 FULL 과 같습니다"
    elif run == SearchRun.AVERSE:
        modes, bikes, rule = enabled, config.max_bike_legs, WaitRule.WORST
        if not context.graph.has_sampled_signal:
            reason = "가지치기 뒤 그래프에 위상을 모르는 신호가 없습니다"
    else:
        modes, bikes, rule, buffer_s = enabled - {TravelMode.BIKE}, 0, WaitRule.NONE, 0.0
    if TravelMode.BIKE not in modes:
        bikes = 0
    return RunConditions(
        run=run,
        skipped=bool(reason),
        skip_reason=reason,
        modes=tuple(mode for mode in TravelMode if mode in modes),
        m=m,
        rule=rule,
        bike_limit=bikes,
        buffer_s=buffer_s,
    )


@dataclass(frozen=True)
class JourneyMove:
    """여정의 이동 하나. 따릉이가 없으면 `walk`, 있으면 ① `walk_in`, ③ `ride`, ⑤ `walk_out` 과 대여소·반납소다."""

    index: int
    from_id: str
    to_id: str
    walk: tuple[Hop, ...] | None
    pick_id: str | None = None
    drop_id: str | None = None
    walk_in: tuple[Hop, ...] = ()
    ride: tuple[Hop, ...] = ()
    walk_out: tuple[Hop, ...] = ()

    @property
    def has_bike(self) -> bool:
        return self.pick_id is not None

    @property
    def hops(self) -> tuple[Hop, ...]:
        """지나는 걸음 전체(따릉이 이동은 ① ③ ⑤ 를 이어 붙인 것)."""
        return self.walk_in + self.ride + self.walk_out if self.has_bike else (self.walk or ())

    @property
    def walk_distance_m(self) -> float:
        """걷는 거리(따릉이 구간은 ①⑤)."""
        legs = self.walk_in + self.walk_out if self.has_bike else (self.walk or ())
        return sum(hop.length_m for hop in legs)


@dataclass(frozen=True)
class JourneyRide:
    """여정의 탑승 하나: (노선 ID, 승차 순번, 하차 순번). 탐색에서 탄 차량은 참고로만 남긴다(가상 차량이면 None).

    `bundle` 은 묶음(§1.7.4)의 (노선 ID, 승차 순번, 하차 순번)을 노선 ID 순으로 둔 것이다. 노선이 하나뿐이면 이 탑승 하나다.
    """

    route_id: str
    board_index: int | None
    alight_index: int
    search_trip_id: str | None
    bundle: tuple[tuple[str, int | None, int], ...] = ()

    @property
    def lines(self) -> tuple[tuple[str, int | None, int], ...]:
        """묶음의 노선들. 묶음을 붙이지 않은 탑승은 이 탑승 하나다."""
        return self.bundle or ((self.route_id, self.board_index, self.alight_index),)

    @property
    def bundled(self) -> bool:
        """노선이 둘 이상인 묶음인지."""
        return len(self.bundle) > 1


@dataclass(frozen=True)
class Journey:
    """되짚은 여정(§1.10.4). 이동과 탑승이 번갈아 나오고, 구조 키와 여정 ID, 화면 이름, 찾은 실행을 가진다."""

    itinerary_id: str
    structure_key: str
    ride_key: str
    label: str
    in_vehicle: bool
    moves: tuple[JourneyMove, ...]
    rides: tuple[JourneyRide, ...]
    found_by: tuple[SearchRun, ...] = ()

    @property
    def walk_distance_m(self) -> float:
        return sum(move.walk_distance_m for move in self.moves)


@dataclass(eq=False)
class RunResult:
    """실행 하나의 결과(§1.10.3, §1.10.4): 조건, 라운드별 라벨, 탐색 기록, $D$ 의 파레토 라벨과 되짚은 여정.

    걷기 라벨은 {(노드, b, f): (시각, 부모)}, 주행 라벨은 {(노드, b): (시각, 부모, 빌린 대여소)} 이다.
    `d_labels` 는 (도착, 탑승 수, b, 라운드, f) 이고 (도착, 탑승 수, b) 순이다.
    """

    conditions: RunConditions
    walk: tuple[dict, ...]
    bike: tuple[dict, ...]
    rounds: tuple[SearchRoundTrace, ...]
    d_labels: tuple[tuple[float, int, int, int, int], ...]
    journeys: tuple[Journey, ...]

    @property
    def trace(self) -> SearchRunTrace:
        c = self.conditions
        return SearchRunTrace(
            run=c.run,
            skipped=c.skipped,
            skip_reason=c.skip_reason,
            modes=c.modes,
            m_run=c.m,
            wait_rule=c.rule,
            bike_limit=c.bike_limit,
            buffer_s=c.buffer_s,
            rounds=self.rounds,
            d_labels=tuple((t, rides, bikes) for t, rides, bikes, _k, _f in self.d_labels),
            itinerary_ids=tuple(journey.itinerary_id for journey in self.journeys),
        )


class _RoundSearch:
    """라운드 탐색 하나의 상태(§1.10.2, §1.10.3). 라운드마다 걷기·주행 라벨 표를 따로 두고, 상태마다 모든 라운드의 최솟값을 둔다."""

    def __init__(self, context: SearchContext, conditions: RunConditions, config: EngineConfig) -> None:
        self.context = context
        self.graph = context.graph
        self.conditions = conditions
        self.config = config
        self.rounds_max = config.max_rides
        self.bikes = conditions.bike_limit
        self.walk_speed = conditions.m * config.v_walk_mps
        self.bike_speed = _bike_multiplier(conditions.m, config) * config.v_pm_mps
        self.rule = conditions.rule
        self.walk: list[dict[tuple[str, int, int], tuple[float, tuple]]] = [{} for _ in range(self.rounds_max + 1)]
        self.bike: list[dict[tuple[str, int], tuple[float, tuple, str]]] = [{} for _ in range(self.rounds_max + 1)]
        self.best_walk: dict[tuple[str, int, int], float] = {}
        self.best_bike: dict[tuple[str, int], float] = {}
        self.best_d = [math.inf] * (self.bikes + 1)
        self.uses_bike = TravelMode.BIKE in conditions.modes and self.bikes > 0
        self.rounds: list[SearchRoundTrace] = []

    # --- 지배와 목표 가지치기 (§1.10.2) ---

    def _walk_ok(self, node: str, b: int, f: int, t: float) -> bool:
        if t >= min(self.best_d[: b + 1]):
            return False
        best = self.best_walk
        return not any(best.get((node, bb, ff), math.inf) <= t for bb in range(b + 1) for ff in range(f + 1))

    def _note_walk(self, node: str, b: int, f: int, t: float) -> None:
        self.best_walk[(node, b, f)] = t
        if node == self.context.destination_id and t < self.best_d[b]:
            self.best_d[b] = t

    def _set_walk(self, k: int, node: str, b: int, f: int, t: float, parent: tuple) -> bool:
        if not self._walk_ok(node, b, f, t):
            return False
        self.walk[k][(node, b, f)] = (t, parent)
        self._note_walk(node, b, f, t)
        return True

    def _bike_ok(self, node: str, b: int, t: float) -> bool:
        if t >= min(self.best_d[: b + 1]):
            return False
        return not any(self.best_bike.get((node, bb), math.inf) <= t for bb in range(1, b + 1))

    def _set_bike(self, k: int, node: str, b: int, t: float, parent: tuple, pick: str) -> bool:
        if not self._bike_ok(node, b, t):
            return False
        self.bike[k][(node, b)] = (t, parent, pick)
        self.best_bike[(node, b)] = t
        return True

    # --- 이동 단계 (§1.10.3 (나)) ---

    def _walk_dijkstra(self, k: int, b: int, f: int) -> None:
        labels = self.walk[k]
        sources = sorted((node, entry[0]) for (node, bb, ff), entry in labels.items() if bb == b and ff == f)
        if not sources:
            return

        def prune(node: str, t: float) -> bool:
            if not self._walk_ok(node, b, f, t):
                return True
            self._note_walk(node, b, f, t)
            return False

        result = td_dijkstra(self.graph, sources, Mode.WALK, self.walk_speed, self.rule, prune)
        for node, t in result.times.items():
            hop = result.parents[node]
            if hop is not None:
                labels[(node, b, f)] = (t, ("EDGE", hop))

    def _bike_phase(self, k: int, b: int) -> None:
        stations = self.graph.bike_stations
        config = self.config
        age = self.context.scenario.bike_obs_age_s
        rented: list[str] = []
        for (node, bb, ff), (t, _parent) in sorted(self.walk[k].items(), key=lambda item: item[0]):
            if bb != b or ff != 0 or node not in stations:
                continue
            station = stations[node]
            if station.bikes_available < 1:
                continue
            if p_bike(station.bikes_available, station.rental_rate_per_hour, age + t) < config.bike_pick_min_p:
                continue
            if self._set_bike(k, node, b + 1, t + config.t_unlock_s, ("PICK",), node):
                rented.append(node)
        if not rented:
            return
        layer = b + 1
        labels = self.bike[k]
        sources = [(node, labels[(node, layer)][0]) for node in rented]

        def prune(node: str, t: float) -> bool:
            if not self._bike_ok(node, layer, t):
                return True
            self.best_bike[(node, layer)] = t
            return False

        result = td_dijkstra(self.graph, sources, Mode.BIKE, self.bike_speed, self.rule, prune)
        for node, t in result.times.items():
            hop = result.parents[node]
            if hop is not None:
                labels[(node, layer)] = (t, ("EDGE", hop), result.roots[node])
        for (node, bb), (t, _parent, pick) in sorted(labels.items(), key=lambda item: item[0]):
            if bb == layer and node in stations and pick != node:
                self._set_walk(k, node, layer, 1, t + config.t_dock_s, ("DOCK",))

    def _move_phase(self, k: int) -> None:
        for b in range(self.bikes + 1):
            self._walk_dijkstra(k, b, 0)
            if b >= 1:
                self._walk_dijkstra(k, b, 1)
            if b < self.bikes and self.uses_bike:
                self._bike_phase(k, b)

    # --- 노선 훑기 (§1.10.3 (가), §1.11.3 (1)) ---

    def _board_label(self, k: int, node: str, b: int, lowest: int, exclude: str | None) -> tuple[float, tuple[int, int] | None]:
        """라운드 k' < k 의 걷기 라벨 (node, b, ·) 가운데 가장 이른 것(같으면 라운드가 작은 것, 그다음 f = 0)."""
        best_t, best_source = math.inf, None
        for kk in range(lowest, k):
            layer = self.walk[kk]
            for f in (0, 1):
                entry = layer.get((node, b, f))
                if entry is None:
                    continue
                parent = entry[1]
                if exclude is not None and parent[0] in _RIDE_PARENT_TAGS and parent[1] == exclude:
                    continue
                if entry[0] < best_t:
                    best_t, best_source = entry[0], (kk, f)
        return best_t, best_source

    def _scan(self, k: int, b: int, route: RouteData, marked: set[str]) -> None:
        nodes = route.node_ids
        board = route.board
        arrivals = route.trips.arr
        kept = self.context.kept
        start = next(index for index, node in enumerate(nodes) if node in marked)
        virtual = self.conditions.naive and self.config.naive_transfer_wait == NaiveTransferWait.ZERO and k >= 2
        lowest = 1 if virtual else 0
        exclude = route.route_id if virtual else None
        buffer_s = self.conditions.buffer_s
        current: int | None = None
        sigma = math.inf
        board_at: int | None = None
        board_source: tuple[int, int] | None = None
        for index in range(start, len(nodes)):
            node = nodes[index]
            if virtual:
                if sigma < math.inf and node in kept:
                    self._set_walk(k, node, b, 0, sigma + route.pi_arr[index], ("RIDE", route.route_id, None, board_at, index, board_source))
            elif current is not None and board.alight[current, index]:
                self._set_walk(
                    k, node, b, 0, float(arrivals[current, index]), ("RIDE", route.route_id, current, board_at, index, board_source)
                )
            t, source = self._board_label(k, node, b, lowest, exclude)
            if t == math.inf:
                continue
            deps = board.deps[index]
            if virtual:
                if len(deps) and deps[-1] >= t and t - route.pi_dep[index] < sigma:
                    sigma, board_at, board_source = t - route.pi_dep[index], index, source
            else:
                row = board.first_row(index, t + buffer_s)
                if row is not None and (current is None or row < current):
                    current, board_at, board_source = row, index, source

    # --- 라운드 (§1.10.3) ---

    def _trace(self, k: int, marked: int, scanned: int) -> SearchRoundTrace:
        best = min(self.best_d)
        return SearchRoundTrace(
            round=k, new_labels=len(self.walk[k]), marked_stops=marked, routes_scanned=scanned, best_d_s=None if best == math.inf else best
        )

    def run(self) -> None:
        context = self.context
        if not context.in_vehicle:
            self._set_walk(0, context.origin_id, 0, 0, 0.0, ("ORIGIN",))
            self._move_phase(0)
            self.rounds.append(self._trace(0, 0, 0))
            first_round = 1
        else:
            self.rounds.append(SearchRoundTrace(round=0, new_labels=0, marked_stops=0, routes_scanned=0, best_d_s=None))
            route = context.routes[context.origin_route]
            row = context.origin_row
            for index in range(context.origin_index, len(route.node_ids)):
                if route.board.alight[row, index]:
                    self._set_walk(
                        1, route.node_ids[index], 0, 0, float(route.trips.arr[row, index]), ("VORIGIN", route.route_id, row, index)
                    )
            self._move_phase(1)
            self.rounds.append(self._trace(1, 0, 1))
            first_round = 2
        for k in range(first_round, self.rounds_max + 1):
            marked: list[set[str]] = [set() for _ in range(self.bikes + 1)]
            for node, b, _f in self.walk[k - 1]:
                if node in context.boarding_nodes:
                    marked[b].add(node)
            union = set().union(*marked)
            if not union:
                break
            scanned = 0
            for b in range(self.bikes + 1):
                if not marked[b]:
                    continue
                for route in context.routes.values():
                    if not route.usable or route.mode not in self.conditions.modes:
                        continue
                    if not any(node in marked[b] for node in route.node_ids):
                        continue
                    self._scan(k, b, route, marked[b])
                    scanned += 1
            self._move_phase(k)
            self.rounds.append(self._trace(k, len(union), scanned))

    def d_candidates(self) -> list[tuple[float, int, int, int]]:
        """라운드와 층마다 $\\tau_k(D, b) = \\min_f \\tau_k^W(D, b, f)$ (같으면 f = 0): (시각, 라운드, b, f)."""
        found: list[tuple[float, int, int, int]] = []
        destination = self.context.destination_id
        for k, labels in enumerate(self.walk):
            for b in range(self.bikes + 1):
                zero, one = labels.get((destination, b, 0)), labels.get((destination, b, 1))
                if zero is None and one is None:
                    continue
                if one is None or (zero is not None and zero[0] <= one[0]):
                    found.append((zero[0], k, b, 0))
                else:
                    found.append((one[0], k, b, 1))
        return found


def _journey_label(context: SearchContext, rides: Sequence[JourneyRide], moves: Sequence[JourneyMove], in_vehicle: bool) -> str:
    """화면용 여정 이름(§1.10.5): 첫 이동의 따릉이, 탑승마다 노선 이름과 그 뒤 이동의 따릉이를 " → " 로 잇는다.

    지점 출발은 이동 0 이 첫 탑승 앞에 있으므로 탑승 l (0부터) 뒤의 이동은 moves[l + 1], 차량 안 출발은 moves[l] 이다.
    """
    parts: list[str] = []
    after = 0 if in_vehicle else 1
    if not in_vehicle and moves[0].has_bike:
        parts.append("따릉이")
    for number, ride in enumerate(rides):
        route = context.routes[ride.route_id]
        parts.append(_bundle_name(context, ride) if ride.bundled and route.mode == TravelMode.BUS else route.short_label)
        if moves[number + after].has_bike:
            parts.append("따릉이")
    return " → ".join(parts) if parts else "도보"


def _bundle_name(context: SearchContext, ride: JourneyRide) -> str:
    """묶음의 화면 이름(§3.3 `Ride.bundle_name`): 버스는 노선 이름을 노선 ID 순으로 "·" 로 이은 "143·146·345번",
    지하철은 "{호선} {방향} 먼저 오는 열차". 노선이 하나뿐인 탑승은 ""."""
    if not ride.bundled:
        return ""
    first = context.routes[ride.bundle[0][0]]
    if first.mode == TravelMode.BUS:
        return "·".join(context.routes[route_id].name for route_id, _board, _alight in ride.bundle) + "번"
    return f"{first.name} {first.direction} 먼저 오는 열차"


def _fare_class(route: RouteData, config: EngineConfig) -> tuple:
    """묶음의 요금 종류(§1.7.4 (1)): 버스는 노선 종류의 기본요금, 지하철은 (호선, 방향)."""
    if route.mode == TravelMode.BUS:
        return (TravelMode.BUS, config.fare_bus_by_type_krw[route.bus_type])
    return (TravelMode.SUBWAY, route.name, route.direction)


def _bundle_candidates(context: SearchContext, route_id: str, board: int | None, alight: int) -> dict[str, tuple[int | None, int]]:
    """탑승의 후보 노선 $C_r$ (§1.7.4 (1)): {노선 ID: (승차 순번, 하차 순번)}. 탑승 자신의 노선은 탐색이 찾은 순번이다.

    다른 노선은 수단과 요금 종류가 같고, 승차 노드에서 하차 노드로 가는 쌍 $i' < j'$ 가 있고(여럿이면 $j' - i'$, 그다음 $i'$ 가
    작은 쌍), 탐색이 쓰는 노선이며 그 쌍에서 타고 내릴 수 있는 차량이 있어야 한다. 차량 안 출발의 탑승 1 은 그 노선뿐이다.
    """
    out: dict[str, tuple[int | None, int]] = {route_id: (board, alight)}
    if board is None:
        return out
    route = context.routes[route_id]
    start, end = route.node_ids[board], route.node_ids[alight]
    kind = _fare_class(route, context.config)
    for other_id, other in context.routes.items():
        if other_id == route_id or not other.usable or other.mode != route.mode or _fare_class(other, context.config) != kind:
            continue
        pair: tuple[int, int] | None = None
        nodes = other.node_ids
        for i, node in enumerate(nodes):
            if node != start:
                continue
            for j in range(i + 1, len(nodes)):
                if nodes[j] == end and (pair is None or (j - i, i) < (pair[1] - pair[0], pair[0])):
                    pair = (i, j)
        if pair is None:
            continue
        rows = other.board.rows[pair[0]]
        if rows.size and bool(np.any(other.board.alight[rows, pair[1]])):
            out[other_id] = pair
    return out


def ride_bundles(
    context: SearchContext, rides: Sequence[tuple[str, int | None, int]]
) -> tuple[tuple[tuple[str, int | None, int], ...], ...]:
    """탑승마다 묶음(§1.7.4 (1), (2)). `rides` 는 되짚은 탑승마다 (노선 ID, 승차 순번 또는 None, 하차 순번)이다.

    묶음은 탑승의 노선과, 후보 노선 가운데 바로 앞 탑승의 후보에도 바로 뒤 탑승의 후보에도 들지 않는 노선이고, 노선 ID 순으로
    (노선 ID, 승차 순번, 하차 순번)을 둔다. 노선이 하나면 그 탑승 하나다.
    """
    candidates = [_bundle_candidates(context, route_id, board, alight) for route_id, board, alight in rides]
    out: list[tuple[tuple[str, int | None, int], ...]] = []
    for number, (route_id, _board, _alight) in enumerate(rides):
        near: set[str] = set()
        if number > 0:
            near |= set(candidates[number - 1])
        if number + 1 < len(rides):
            near |= set(candidates[number + 1])
        chosen = {line: pair for line, pair in candidates[number].items() if line == route_id or line not in near}
        out.append(tuple((line, chosen[line][0], chosen[line][1]) for line in sorted(chosen)))
    return tuple(out)


def ride_vehicles(context: SearchContext, bundle: Sequence[tuple[str, int | None, int]]) -> RideVehicles:
    """승차 순번이 있는 묶음의 유효 차량열(§1.7.4 (3)). 노선이 하나면 그 노선의 탈 수 있는 차량 배열 그대로다.

    여럿이면 노선마다 승차 순번에서 탈 수 있고 하차 순번에서 내릴 수 있는 차량을 모은 뒤, 다른 노선에 같거나 늦게 떠나 더 일찍
    닿는 차량이 있는 차량을 빼고 (출발, 도착, 노선 ID, 노선의 차량 순서) 순으로 둔다. 같은 묶음은 탐색 문맥에서 한 번만 만든다.
    """
    key = tuple((route_id, board, alight) for route_id, board, alight in bundle)
    cached = context.vehicle_cache.get(key)
    if cached is not None:
        return cached
    if not key or any(board is None for _route_id, board, _alight in key):
        raise ValueError("유효 차량열은 승차 순번이 있는 탑승에만 있습니다(차량 안 출발의 첫 탑승은 탄 차량뿐입니다)")
    items: list[tuple[float, float, str, int]] = []
    if len(key) == 1:
        route_id, board, alight = key[0]
        route = context.routes[route_id]
        rows = route.board.rows[board]
        items = [(float(dep), float(route.trips.arr[int(row), alight]), route_id, int(row)) for dep, row in zip(route.board.deps[board], rows)]
    else:
        pools: dict[str, tuple[np.ndarray, np.ndarray]] = {}
        for route_id, board, alight in key:
            route = context.routes[route_id]
            rows = route.board.rows[board]
            keep = route.board.alight[rows, alight] if rows.size else np.zeros(0, dtype=bool)
            for dep, row in zip(route.board.deps[board][keep], rows[keep]):
                items.append((float(dep), float(route.trips.arr[int(row), alight]), route_id, int(row)))
            mine = [item for item in items if item[2] == route_id]
            deps = np.array([item[0] for item in mine], dtype=float)
            arrs = np.array([item[1] for item in mine], dtype=float)
            # 출발 오름차순으로 둔 그 노선 차량의 "그 위치 이후 가장 이른 도착"
            suffix = np.minimum.accumulate(arrs[::-1])[::-1] if arrs.size else arrs
            pools[route_id] = (deps, suffix)

        def overtaken(item: tuple[float, float, str, int]) -> bool:
            for other_id, (deps, suffix) in pools.items():
                if other_id == item[2] or deps.size == 0:
                    continue
                position = int(np.searchsorted(deps, item[0], side="left"))
                if position < deps.size and suffix[position] < item[1]:
                    return True
            return False

        items = sorted(item for item in items if not overtaken(item))
    board_of = {route_id: int(board) for route_id, board, _alight in key}
    vehicles = RideVehicles(
        lines=tuple((route_id, int(board), int(alight)) for route_id, board, alight in key),
        route_ids=tuple(item[2] for item in items),
        rows=np.array([item[3] for item in items], dtype=int),
        trip_ids=tuple(context.routes[item[2]].trips.trip_ids[item[3]] for item in items),
        deps=np.array([item[0] for item in items], dtype=float),
        arrs=np.array([item[1] for item in items], dtype=float),
        sources=tuple(context.routes[item[2]].trips.sources[item[3]][board_of[item[2]]] for item in items),
        full=tuple(bool(context.routes[item[2]].board.full_state[item[3], board_of[item[2]]]) for item in items),
        last=tuple(bool(context.routes[item[2]].trips.last[item[3]]) for item in items),
    )
    context.vehicle_cache[key] = vehicles
    return vehicles


def _backtrack(context: SearchContext, walk: Sequence[dict], bike: Sequence[dict], k: int, b: int, f: int) -> Journey:
    """$D$ 의 라벨에서 부모를 거꾸로 따라가 여정을 만든다(§1.10.4)."""
    rides: list[tuple[str, int | None, int, int | None]] = []
    drafts: list[dict[str, Any]] = []
    walking: list[Hop] = []
    riding: list[Hop] = []
    draft: dict[str, Any] = {"pick": None, "drop": None, "ride": (), "walk_out": ()}

    def close() -> None:
        nonlocal draft, walking
        path = tuple(reversed(walking))
        draft["walk_in" if draft["pick"] is not None else "walk"] = path
        drafts.append(draft)
        draft = {"pick": None, "drop": None, "ride": (), "walk_out": ()}
        walking = []

    state: tuple = ("W", k, context.destination_id, b, f)
    while True:
        if state[0] == "W":
            _, kk, node, bb, ff = state
            _t, parent = walk[kk][(node, bb, ff)]
            tag = parent[0]
            if tag == "EDGE":
                hop = parent[1]
                walking.append(hop)
                state = ("W", kk, hop.from_id, bb, ff)
            elif tag == "DOCK":
                draft["walk_out"] = tuple(reversed(walking))
                walking = []
                draft["drop"] = node
                state = ("B", kk, node, bb)
            elif tag == "RIDE":
                _, route_id, row, board_at, alight_at, (board_round, board_f) = parent
                close()
                rides.append((route_id, board_at, alight_at, row))
                state = ("W", board_round, context.routes[route_id].node_ids[board_at], bb, board_f)
            elif tag == "VORIGIN":
                _, route_id, row, alight_at = parent
                close()
                rides.append((route_id, None, alight_at, row))
                break
            else:
                close()
                break
        else:
            _, kk, node, bb = state
            _t, parent, _pick = bike[kk][(node, bb)]
            if parent[0] == "EDGE":
                hop = parent[1]
                riding.append(hop)
                state = ("B", kk, hop.from_id, bb)
            else:
                draft["ride"] = tuple(reversed(riding))
                riding = []
                draft["pick"] = node
                state = ("W", kk, node, bb - 1, 0)
    rides.reverse()
    drafts.reverse()
    bundles = ride_bundles(context, [(route_id, board_at, alight_at) for route_id, board_at, alight_at, _row in rides])
    journey_rides = tuple(
        JourneyRide(
            route_id=route_id,
            board_index=board_at,
            alight_index=alight_at,
            search_trip_id=None if row is None else context.routes[route_id].trips.trip_ids[row],
            bundle=bundle,
        )
        for (route_id, board_at, alight_at, row), bundle in zip(rides, bundles)
    )
    in_vehicle = context.in_vehicle
    alights = [context.routes[ride.route_id].node_ids[ride.alight_index] for ride in journey_rides]
    boards = [context.routes[ride.route_id].node_ids[ride.board_index] for ride in journey_rides if ride.board_index is not None]
    starts = alights if in_vehicle else [context.origin_id] + alights
    ends = boards + [context.destination_id]
    moves = tuple(
        JourneyMove(
            index=number + (1 if in_vehicle else 0),
            from_id=start,
            to_id=end,
            walk=None if item["pick"] is not None else item["walk"],
            pick_id=item["pick"],
            drop_id=item["drop"],
            walk_in=item.get("walk_in", ()),
            ride=item["ride"],
            walk_out=item["walk_out"],
        )
        for number, (item, start, end) in enumerate(zip(drafts, starts, ends))
    )
    # 노선이 둘 이상인 묶음은 그 자리에 노선마다의 셋을 노선 ID 순으로 둔다(§1.10.5). 노선이 하나면 셋 그대로다.
    ride_part = [
        [list(line) for line in ride.bundle] if ride.bundled else [ride.route_id, ride.board_index, ride.alight_index]
        for ride in journey_rides
    ]
    bike_part = [[move.pick_id, move.drop_id] if move.has_bike else None for move in moves]
    path_part = [[hop.edge_id for hop in move.hops] for move in moves]
    key = _json_key([ride_part, bike_part, path_part])
    return Journey(
        itinerary_id="I" + hashlib.sha1(key.encode("utf-8")).hexdigest()[:10],
        structure_key=key,
        ride_key=_json_key([ride_part, bike_part]),
        label=_journey_label(context, journey_rides, moves, in_vehicle),
        in_vehicle=in_vehicle,
        moves=moves,
        rides=journey_rides,
    )


def search_run(context: SearchContext, run: SearchRun | str, config: EngineConfig) -> RunResult:
    """실행 조건 하나로 라운드 탐색을 한다(§1.10.3). $D$ 의 라벨은 파레토로 거르고 (도착, 탑승 수, b) 순으로 둔다(§1.10.4)."""
    conditions = run_conditions(context, SearchRun(run), config)
    if conditions.skipped:
        return RunResult(conditions, (), (), (), (), ())
    search = _RoundSearch(context, conditions, config)
    search.run()
    labelled = []
    for t, k, b, f in search.d_candidates():
        journey = _backtrack(context, search.walk, search.bike, k, b, f)
        labelled.append((t, len(journey.rides), b, k, f, journey))
    kept = []
    for item in labelled:
        dominated = False
        for other in labelled:
            if other is item:
                continue
            if other[0] <= item[0] and other[1] <= item[1] and other[2] <= item[2]:
                if other[:3] != item[:3] or other[3] < item[3]:
                    dominated = True
                    break
        if not dominated:
            kept.append(item)
    kept.sort(key=lambda item: (item[0], item[1], item[2]))
    return RunResult(
        conditions=conditions,
        walk=tuple(search.walk),
        bike=tuple(search.bike),
        rounds=tuple(search.rounds),
        d_labels=tuple((t, rides, b, k, f) for t, rides, b, k, f, _journey in kept),
        journeys=tuple(item[5] for item in kept),
    )


def extract_journeys(context: SearchContext, run_result: RunResult) -> tuple[Journey, ...]:
    """실행의 $D$ 파레토 라벨마다 부모를 거꾸로 따라가 여정을 만든다(§1.10.4). 라벨 순서 그대로다."""
    return tuple(_backtrack(context, run_result.walk, run_result.bike, k, b, f) for _t, _rides, b, k, f in run_result.d_labels)


def _reach(context: SearchContext, result: RunResult) -> tuple[tuple[str, int, float], ...]:
    """승하차 노드와 대여소마다 걷기 라벨이 처음 생긴 라운드와 그 라운드의 가장 이른 시각(§1.10.5 의 `reach`)."""
    targets = context.boarding_nodes | frozenset(context.graph.bike_stations)
    first: dict[str, tuple[int, float]] = {}
    for k, labels in enumerate(result.walk):
        earliest: dict[str, float] = {}
        for (node, _b, _f), (t, _parent) in labels.items():
            if node in targets and node not in first and t < earliest.get(node, math.inf):
                earliest[node] = t
        for node, t in earliest.items():
            first[node] = (k, t)
    return tuple((node, first[node][0], first[node][1]) for node in sorted(first))


def search_candidates(context: SearchContext, config: EngineConfig) -> tuple[tuple[Journey, ...], SearchSummary]:
    """§1.10.5 의 실행을 차례로 돌려 여정을 합치고, 계획 도착 순으로 `max_candidates` 개와 실행마다의 1위를 남긴다.

    남긴 여정은 여정 ID 순이다. 합친 여정의 `found_by` 는 실행표 순서다.
    """
    results = [search_run(context, run, config) for run in SearchRun]
    found: dict[str, Journey] = {}
    found_by: dict[str, list[SearchRun]] = {}
    run_best: list[str] = []
    total = 0
    for result in results:
        for journey in result.journeys:
            total += 1
            found.setdefault(journey.itinerary_id, journey)
            runs = found_by.setdefault(journey.itinerary_id, [])
            if result.conditions.run not in runs:
                runs.append(result.conditions.run)
        if result.journeys:
            run_best.append(result.journeys[0].itinerary_id)
    merged = {jid: dataclasses.replace(journey, found_by=tuple(found_by[jid])) for jid, journey in found.items()}

    def order(jid: str) -> tuple:
        plan = plan_schedule(merged[jid], context, config)
        arrival = math.inf if plan.arrival_s is None else plan.arrival_s
        return (arrival, len(merged[jid].rides), round(merged[jid].walk_distance_m, 6), jid)

    ranked = sorted(merged, key=order)
    keep = list(ranked[: config.max_candidates])
    for jid in run_best:
        if jid not in keep:
            keep.append(jid)
    kept_ids = sorted(keep)
    full = next(result for result in results if result.conditions.run == SearchRun.FULL)
    summary = SearchSummary(
        runs=tuple(result.trace for result in results),
        found_total=total,
        distinct=len(merged),
        kept=len(kept_ids),
        discarded_ids=tuple(sorted(set(merged) - set(kept_ids))),
        reach=_reach(context, full),
    )
    return tuple(merged[jid] for jid in kept_ids), summary


# ===== S6. 평가와 엔진 (§1.4, §1.10.6, §1.11, §4.6) =====
# 계획 시각(§1.10.6)은 4단계에서 먼저 만들었다. 후보 수 상한(§1.10.5)이 계획 도착으로 여정을 고르기 때문이다.

# 시간 막대 칸의 이름(§6.5 의 구간 이름과 같다). 탑승 칸은 노선 이름이다.
_LEG_LABELS: MappingProxyType = MappingProxyType(
    {
        LegKind.WALK: "걷기",
        LegKind.SIGNAL_WAIT: "신호 대기",
        LegKind.BIKE_UNLOCK: "대여",
        LegKind.BIKE: "따릉이",
        LegKind.BIKE_DOCK: "반납",
        LegKind.STOP_WAIT: "기다림",
    }
)


@dataclass(frozen=True)
class Plan:
    """§1.10.6 의 계획: $m = 1$, 표본 신호는 $E[W]$, 모든 $\\beta_b = 1$ 로 한 번 계산한 시각.

    `moves` 는 계획이 지난 이동(막차를 놓치면 그 앞까지), `rides` 는 모든 탑승(놓친 탑승과 그 뒤는 계획 값이 None),
    `legs` 는 빈틈없이 이어진 시간 막대, `pick_arrivals` 와 `p_bikes` 는 따릉이 구간마다 $a_b$ 와 $P_{bike}$ 다.
    `missed_ride` 는 막차를 놓친 탑승 번호(1부터), `walk_m` 은 여정의 걷는 거리(따릉이 구간의 ①⑤ 포함)다.
    """

    itinerary_id: str
    start_s: float
    moves: tuple[Move, ...]
    rides: tuple[Ride, ...]
    legs: tuple[Leg, ...]
    pick_arrivals: tuple[float, ...]
    p_bikes: tuple[float, ...]
    arrival_s: float | None
    missed_last: bool
    missed_ride: int | None
    walk_m: float


def _timed_path(
    context: SearchContext, hops: Sequence[Hop], t0_s: float, speed_mps: float, kind: LegKind, start_id: str, legs: list[Leg]
) -> PathResult:
    """경로를 계획 규칙(EXPECTED)으로 지나고 시간 막대 칸을 `legs` 에 더한다. 대기가 있는 신호에서 칸을 나눈다.

    시각은 `propagate` 와 같은 순서로 더하므로 칸의 끝이 경로의 끝 시각과 정확히 같다. 길이 0 인 칸은 만들지 않는다.
    """
    path = propagate(context.scenario, hops, t0_s, speed_mps, WaitRule.EXPECTED, graph=context.graph, start_id=start_id)
    label = _LEG_LABELS[kind]
    t = float(t0_s)
    leg_start, leg_from, distance = t, path.node_ids[0], 0.0
    events = iter(path.events)
    for hop in hops:
        if hop.signal_id is not None:
            event = next(events)
            if event.wait_s > 0:
                if t > leg_start:
                    legs.append(Leg(kind=kind, start_s=leg_start, end_s=t, distance_m=distance, from_id=leg_from, to_id=hop.from_id, label=label))
                legs.append(
                    Leg(
                        kind=LegKind.SIGNAL_WAIT,
                        start_s=t,
                        end_s=t + event.wait_s,
                        distance_m=0.0,
                        from_id=hop.from_id,
                        to_id=hop.from_id,
                        label=_LEG_LABELS[LegKind.SIGNAL_WAIT],
                    )
                )
                t += event.wait_s
                leg_start, leg_from, distance = t, hop.from_id, 0.0
        t += hop.length_m / speed_mps
        distance += hop.length_m
    if t > leg_start:
        legs.append(Leg(kind=kind, start_s=leg_start, end_s=t, distance_m=distance, from_id=leg_from, to_id=path.node_ids[-1], label=label))
    return path


def _plan_fallback(context: SearchContext, src: str, dst: str, t0_s: float) -> PathResult | None:
    """대체 보행(최단거리 경로)을 계획 규칙으로 `t0_s` 부터 지난 결과. 경로가 없으면 None."""
    hops = context.shortest(src, dst)
    if hops is None:
        return None
    return propagate(context.scenario, hops, t0_s, context.config.v_walk_mps, WaitRule.EXPECTED, graph=context.graph, start_id=src)


def _plan_move(
    context: SearchContext,
    move: JourneyMove,
    t0_s: float,
    config: EngineConfig,
    moves: list[Move],
    legs: list[Leg],
    picks: list[float],
    p_values: list[float],
) -> float:
    """이동 하나를 계획 시각으로 지나고 끝 시각을 돌려준다. 따릉이 구간은 ① 도보, 대여, ③ 주행, 반납, ⑤ 도보다(§1.3)."""
    if not move.has_bike:
        path = _timed_path(context, move.walk or (), t0_s, config.v_walk_mps, LegKind.WALK, move.from_id, legs)
        moves.append(
            Move(
                index=move.index,
                from_id=move.from_id,
                to_id=move.to_id,
                walk=path,
                bike=None,
                t_start_s=t0_s,
                t_end_s=path.t_end_s,
                distance_m=path.distance_m,
                walk_distance_m=path.distance_m,
            )
        )
        return path.t_end_s
    walk_in = _timed_path(context, move.walk_in, t0_s, config.v_walk_mps, LegKind.WALK, move.from_id, legs)
    arrival = walk_in.t_end_s
    unlocked = arrival + config.t_unlock_s
    if unlocked > arrival:
        legs.append(
            Leg(kind=LegKind.BIKE_UNLOCK, start_s=arrival, end_s=unlocked, distance_m=0.0, from_id=move.pick_id, to_id=move.pick_id, label=_LEG_LABELS[LegKind.BIKE_UNLOCK])
        )
    ride = _timed_path(context, move.ride, unlocked, config.v_pm_mps, LegKind.BIKE, move.pick_id, legs)
    docked = ride.t_end_s + config.t_dock_s
    if docked > ride.t_end_s:
        legs.append(
            Leg(kind=LegKind.BIKE_DOCK, start_s=ride.t_end_s, end_s=docked, distance_m=0.0, from_id=move.drop_id, to_id=move.drop_id, label=_LEG_LABELS[LegKind.BIKE_DOCK])
        )
    walk_out = _timed_path(context, move.walk_out, docked, config.v_walk_mps, LegKind.WALK, move.drop_id, legs)
    station = context.graph.bike_stations[move.pick_id]
    age = context.scenario.bike_obs_age_s
    probability = p_bike(station.bikes_available, station.rental_rate_per_hour, age + arrival)
    segment = BikeSegment(
        pick_id=move.pick_id,
        drop_id=move.drop_id,
        walk_in=walk_in,
        ride=ride,
        walk_out=walk_out,
        unlock_s=config.t_unlock_s,
        dock_s=config.t_dock_s,
        arrival_at_pick_s=arrival,
        obs_age_s=age,
        p_bike=probability,
        fallback=_plan_fallback(context, move.pick_id, move.to_id, arrival),
    )
    moves.append(
        Move(
            index=move.index,
            from_id=move.from_id,
            to_id=move.to_id,
            walk=None,
            bike=segment,
            t_start_s=t0_s,
            t_end_s=walk_out.t_end_s,
            distance_m=walk_in.distance_m + ride.distance_m + walk_out.distance_m,
            walk_distance_m=walk_in.distance_m + walk_out.distance_m,
        )
    )
    picks.append(arrival)
    p_values.append(probability)
    return walk_out.t_end_s


def _ride_record(
    context: SearchContext,
    journey: Journey,
    number: int,
    plan: tuple[str, float | None, float | None, float, float] | None,
    fallback: PathResult | None,
    line: tuple[str, int, int] | None = None,
) -> Ride:
    """탑승 하나의 결과 행. 노선 값(ID, 이름, 종류, 순번, 거리)은 `line` (계획 차량의 노선과 그 승차·하차 순번)이고, 계획 차량이
    없으면(막차 놓침, 계획이 닿지 못한 탑승, 차량 안 출발의 첫 탑승) 묶음의 첫 노선(노선 ID 순)이다(§1.7.4 (4)).
    거리는 노선의 구간 거리 합이고, 차량 안 출발의 첫 탑승은 이미 탄 거리 + $j_0$ 부터의 합이다(§1.5 (1))."""
    ride = journey.rides[number]
    route_id, board_index, alight_index = line if line is not None else ride.lines[0]
    route = context.routes[route_id]
    if board_index is None:
        distance = context.query.origin.prior_distance_m + sum(route.segment_dist_m[context.origin_index : alight_index])
        board_node = None
    else:
        distance = sum(route.segment_dist_m[board_index:alight_index])
        board_node = route.node_ids[board_index]
    trip_id, stop_arrival, dep, arr, wait = plan if plan is not None else (None, None, None, None, None)
    bundle = (
        tuple(
            BundleLine(route_id=line_id, route_name=context.routes[line_id].display_name, board_index=board, alight_index=alight)
            for line_id, board, alight in ride.bundle
        )
        if ride.bundled
        else ()
    )
    return Ride(
        index=number + 1,
        mode=route.mode,
        route_id=route.route_id,
        route_name=route.display_name,
        bus_type=route.bus_type,
        board_index=board_index,
        alight_index=alight_index,
        board_node_id=board_node,
        alight_node_id=route.node_ids[alight_index],
        distance_m=distance,
        plan_trip_id=trip_id,
        plan_stop_arrival_s=stop_arrival,
        plan_dep_s=dep,
        plan_arr_s=arr,
        plan_wait_s=wait,
        fallback=fallback,
        bundle=bundle,
        bundle_name=_bundle_name(context, ride),
    )


def plan_schedule(journey: Journey, context: SearchContext, config: EngineConfig) -> Plan:
    """여정의 계획 시각(§1.10.6). 걷기는 $v_{walk}$, 주행은 $v_{pm}$, 표본 신호는 $E[W]$, 개방 신호는 $W_{det}$ 이고,
    탑승은 정류장 도착 + $t_{buf}$ 뒤 유효 차량열(§1.7.4)의 첫 차량을 탄다(§1.4.2 의 BOARD). 그런 차량이 없으면 막차 놓침이고
    대체 보행으로 끝난다. 탑승의 노선 값과 시간 막대의 탑승 칸은 탄 차량의 노선이다.

    같은 여정의 계획은 이 질의 안에서 다시 계산하지 않는다(`context.plan_cache`).
    """
    cached = context.plan_cache.get(journey.itinerary_id)
    if cached is not None:
        return cached
    legs: list[Leg] = []
    moves: list[Move] = []
    picks: list[float] = []
    p_values: list[float] = []
    records: list[Ride | None] = [None] * len(journey.rides)
    missed_ride: int | None = None
    next_ride = 0
    if journey.in_vehicle:
        first = journey.rides[0]
        route = context.routes[first.route_id]
        t = float(route.trips.arr[context.origin_row, first.alight_index])
        records[0] = _ride_record(context, journey, 0, (route.trips.trip_ids[context.origin_row], None, None, t, 0.0), None)
        next_ride = 1
    else:
        t = 0.0
    start = t
    arrival: float | None = None
    for move in journey.moves:
        t = _plan_move(context, move, t, config, moves, legs, picks, p_values)
        if next_ride >= len(journey.rides):
            continue
        ride = journey.rides[next_ride]
        board_node = context.routes[ride.route_id].node_ids[ride.board_index]
        vehicles = ride_vehicles(context, ride.lines)
        position = vehicles.first(t + config.safety_buffer_s)
        if position is None:
            missed_ride = next_ride + 1
            hops = context.shortest(board_node, context.destination_id)
            fallback = None if hops is None else _timed_path(context, hops, t, config.v_walk_mps, LegKind.WALK, board_node, legs)
            records[next_ride] = _ride_record(context, journey, next_ride, None, fallback)
            arrival = None if fallback is None else fallback.t_end_s
            break
        line_id = vehicles.route_ids[position]
        route = context.routes[line_id]
        board_at, alight_at = vehicles.indices(line_id)
        dep = float(vehicles.deps[position])
        arr = float(vehicles.arrs[position])
        if dep > t:
            legs.append(
                Leg(kind=LegKind.STOP_WAIT, start_s=t, end_s=dep, distance_m=0.0, from_id=board_node, to_id=board_node, label=_LEG_LABELS[LegKind.STOP_WAIT])
            )
        alight_node = route.node_ids[alight_at]
        if arr > dep:
            legs.append(
                Leg(
                    kind=LegKind.BUS if route.mode == TravelMode.BUS else LegKind.SUBWAY,
                    start_s=dep,
                    end_s=arr,
                    distance_m=sum(route.segment_dist_m[board_at:alight_at]),
                    from_id=board_node,
                    to_id=alight_node,
                    label=route.short_label,
                )
            )
        records[next_ride] = _ride_record(
            context,
            journey,
            next_ride,
            (vehicles.trip_ids[position], t, dep, arr, dep - t),
            _plan_fallback(context, board_node, context.destination_id, t),
            (line_id, board_at, alight_at),
        )
        t = arr
        next_ride += 1
    else:
        arrival = t
    for number in range(len(journey.rides)):
        if records[number] is None:
            records[number] = _ride_record(context, journey, number, None, None)
    plan = Plan(
        itinerary_id=journey.itinerary_id,
        start_s=start,
        moves=tuple(moves),
        rides=tuple(records),
        legs=tuple(legs),
        pick_arrivals=tuple(picks),
        p_bikes=tuple(p_values),
        arrival_s=arrival,
        missed_last=missed_ride is not None,
        missed_ride=missed_ride,
        walk_m=journey.walk_distance_m,
    )
    context.plan_cache[journey.itinerary_id] = plan
    return plan


# --- S6 (5단계). 프로필과 실현 시각 (§1.4.2) ---

# 자전거가 없는데 이동의 도착점까지 걸을 길도 없을 때 남은 단계 대신 넣는 표시. 그 조합의 점은 더 가지 못한다($T = +\infty$).
_NO_PATH = ProfileStep(StepKind.FIXED, seconds=math.inf)
MISSED_LAST = "MISSED_LAST"  # 탄 차량 분포의 맨 뒤 항목(§1.4.5 (4))


def _prob(value: float) -> float:
    """확률 필드에 넣을 값. 부동소수 합의 오차로 [0, 1] 을 조금 벗어난 값을 접는다."""
    return min(1.0, max(0.0, float(value)))


def _hop_steps(hops: Sequence[Hop]) -> tuple[ProfileStep, ...]:
    """경로의 걸음을 단계로 바꾼다: 신호가 붙은 엣지는 SIGNAL 다음 TRAVEL, 아니면 TRAVEL. 같은 수단의 TRAVEL 은 합친다(§1.4.2)."""
    steps: list[ProfileStep] = []
    for hop in hops:
        if hop.signal_id is not None:
            steps.append(signal_step(hop.signal_id))
        steps.append(travel_step(hop.length_m, hop.mode))
    return compact_steps(steps)


def _journey_sequence(journey: Journey) -> list[tuple[str, int]]:
    """여정의 이동과 탑승 순서: ("move", 이동 번호) 와 ("ride", 탑승 번호), 번호는 0부터. 차량 안 출발은 탑승 0 이 맨 앞이다."""
    sequence: list[tuple[str, int]] = [("ride", 0)] if journey.in_vehicle else []
    for number, move in enumerate(journey.moves):
        sequence.append(("move", number))
        if move.index < len(journey.rides):
            sequence.append(("ride", move.index))
    return sequence


@dataclass(frozen=True, eq=False)
class Profile:
    """여정 하나의 프로필(§1.4.2). `steps` 는 모든 $\\beta_b = 1$ 인 본 프로필이고 BOARD 와 BIKE_GATE 의 번호는 1부터다.

    `segments` 는 따릉이 구간마다 (BIKE_GATE 의 위치, 그 구간의 남은 단계가 끝나는 위치)이고, 자전거가 없으면 그 사이를
    `bike_fallbacks` (대여소 → 이동의 도착점 최단거리 보행)로 바꾼다. `ride_fallbacks` 는 탑승마다 승차 노드 → $D$ 의
    대체 보행이다(차량 안 출발의 탑승 1 과 걸을 길이 없는 곳은 None). `dims`, `capped` 는 표본 신호의 Halton 차원과 넘친 신호다.
    """

    itinerary_id: str
    start_s: float
    steps: tuple[ProfileStep, ...]
    rides: tuple[JourneyRide, ...]
    origin_row: int | None
    segments: tuple[tuple[int, int], ...]
    ride_fallbacks: tuple[tuple[ProfileStep, ...] | None, ...]
    bike_fallbacks: tuple[tuple[ProfileStep, ...] | None, ...]
    dims: dict[str, int]
    capped: tuple[str, ...]

    @property
    def n_bikes(self) -> int:
        return len(self.segments)

    def steps_for(self, beta: Sequence[int]) -> tuple[ProfileStep, ...]:
        """따릉이 조합 β 의 단계. $\\beta_b = 0$ 인 구간은 BIKE_GATE 뒤의 남은 단계를 대체 보행으로 바꾼다(길이 없으면 `_NO_PATH`)."""
        if all(value == 1 for value in beta):
            return self.steps
        out: list[ProfileStep] = []
        cursor = 0
        for value, (gate, end), fallback in zip(beta, self.segments, self.bike_fallbacks):
            if value == 1:
                continue
            out.extend(self.steps[cursor : gate + 1])
            out.extend(fallback if fallback is not None else (_NO_PATH,))
            cursor = end
        out.extend(self.steps[cursor:])
        return tuple(out)


def build_profile(journey: Journey, context: SearchContext, config: EngineConfig) -> Profile:
    """여정을 프로필로 바꾼다(§1.4.2 의 만들기 규칙)와 표본 신호의 준난수 차원을 정한다(§1.4.4).

    차원은 본 프로필의 신호가 먼저이고, 그다음 여정의 이동과 탑승 순서로 대체 보행(따릉이 구간은 대여소 → 이동 도착점,
    탑승은 승차 노드 → $D$)의 신호를 센다. 차량 안 출발의 탑승 1 은 BOARD 도 대체 보행도 없다.
    """
    steps: list[ProfileStep] = []
    segments: list[tuple[int, int]] = []
    bike_fallbacks: list[tuple[ProfileStep, ...] | None] = []
    ride_fallbacks: list[tuple[ProfileStep, ...] | None] = [None] * len(journey.rides)
    fallback_signals: list[str] = []
    origin_row: int | None = None
    start = 0.0
    if journey.in_vehicle:
        first = journey.rides[0]
        origin_row = context.origin_row
        start = float(context.routes[first.route_id].trips.arr[origin_row, first.alight_index])

    def fallback(src: str, dst: str) -> tuple[ProfileStep, ...] | None:
        hops = context.shortest(src, dst)
        if hops is None:
            return None
        fallback_signals.extend(hop.signal_id for hop in hops if hop.signal_id is not None)
        return _hop_steps(hops)

    for kind, number in _journey_sequence(journey):
        if kind == "ride":
            ride = journey.rides[number]
            if ride.board_index is None:
                continue
            steps.append(ProfileStep(StepKind.BOARD, index=number + 1))
            ride_fallbacks[number] = fallback(context.routes[ride.route_id].node_ids[ride.board_index], context.destination_id)
            continue
        move = journey.moves[number]
        if not move.has_bike:
            steps.extend(_hop_steps(move.walk or ()))
            continue
        steps.extend(_hop_steps(move.walk_in))
        gate = len(steps)
        steps.append(ProfileStep(StepKind.BIKE_GATE, index=len(segments) + 1))
        steps.append(fixed_step(config.t_unlock_s))
        steps.extend(_hop_steps(move.ride))
        steps.append(fixed_step(config.t_dock_s))
        steps.extend(_hop_steps(move.walk_out))
        segments.append((gate, len(steps)))
        bike_fallbacks.append(fallback(move.pick_id, move.to_id))
    main_signals = [step.signal_id for step in steps if step.kind == StepKind.SIGNAL]
    dims, capped = assign_halton_dims(main_signals + fallback_signals, context.graph.signals, config)
    return Profile(
        itinerary_id=journey.itinerary_id,
        start_s=start,
        steps=tuple(steps),
        rides=journey.rides,
        origin_row=origin_row,
        segments=tuple(segments),
        ride_fallbacks=tuple(ride_fallbacks),
        bike_fallbacks=tuple(bike_fallbacks),
        dims=dims,
        capped=capped,
    )


@dataclass(frozen=True, eq=False)
class Realization:
    """점마다의 실현(§1.4.2): $D$ 도착(닿지 못하면 $+\\infty$), 탑승마다 정류장 도착(닿지 못하면 NaN)과 탄 차량의 유효 차량열
    위치(§1.7.4, 타지 못하면 −1. 차량 안 출발의 탑승 1 은 탄 차량의 행), 막차 놓침으로 끝났는지, 따릉이 구간마다 대체 보행
    (자전거 없음)인지."""

    arrival: np.ndarray
    stops: np.ndarray
    vehicles: np.ndarray
    missed: np.ndarray
    bike_fallback: tuple[bool, ...]


def _realize_points(
    profile: Profile,
    steps: Sequence[ProfileStep],
    m: Any,
    draws: dict[str, tuple[np.ndarray, np.ndarray]],
    context: SearchContext,
    beta: Sequence[int],
    upto: int | None = None,
    m_pm: Any = None,
) -> Realization:
    """단계를 한 번씩 지나며 모든 점을 numpy 배열로 함께 실현한다(§1.4.2, §1.4.3 의 계산 방법).

    BOARD 는 유효 차량열(§1.7.4)의 출발 배열에 `searchsorted(dep, t + t_buf, "left")` 를 쓴다. 차량이 없으면 막차 놓침이고
    승차 노드에서 $D$ 까지 대체 보행으로 끝난다(길이 없으면 $+\\infty$). $m \\le m_{min}$ 이거나 $m_{pm} \\le m_{min}$ 인 점은
    처음부터 가지 못한 점이라 어느 차량도 타지 않는다. `upto` 가 탑승 번호(0부터)면 그 탑승의 정류장 도착을 적고 멈춘다.
    """
    config = context.config
    signals = context.graph.signals
    multipliers = np.asarray(m, dtype=float)
    n = multipliers.size
    walk_speed, bike_speed, dead = _point_speeds(multipliers, config, m_pm)
    stops = np.full((len(profile.rides), n), np.nan)
    vehicles = np.full((len(profile.rides), n), -1, dtype=int)
    arrival = np.full(n, np.inf)
    missed = np.zeros(n, dtype=bool)
    alive = ~dead
    if profile.origin_row is not None:
        vehicles[0] = profile.origin_row
    t = np.full(n, float(profile.start_s))
    buffer = config.safety_buffer_s
    for step in steps:
        kind = step.kind
        if step is _NO_PATH:
            alive = np.zeros(n, dtype=bool)
            break
        if kind == StepKind.TRAVEL:
            t = t + step.distance_m / (walk_speed if step.mode == Mode.WALK else bike_speed)
        elif kind == StepKind.FIXED:
            t = t + step.seconds
        elif kind == StepKind.SIGNAL:
            t = t + _wait_points(signals[step.signal_id], draws.get(step.signal_id), t)
        elif kind == StepKind.BOARD:
            number = step.index - 1
            ride = profile.rides[number]
            stops[number] = np.where(alive, t, np.nan)
            if upto == number:
                break
            sequence = ride_vehicles(context, ride.lines)
            if sequence.size:
                position = np.searchsorted(sequence.deps, t + buffer, side="left")
                ok = alive & (position < sequence.size)
                taken = np.minimum(position, sequence.size - 1)
                vehicles[number] = np.where(ok, taken, -1)
            else:
                ok = np.zeros(n, dtype=bool)
            miss = alive & ~ok
            if miss.any():
                fallback = profile.ride_fallbacks[number]
                ends = (
                    np.full(n, np.inf)
                    if fallback is None
                    else _advance_steps(fallback, t, walk_speed, bike_speed, draws, signals)
                )
                arrival = np.where(miss, ends, arrival)
                missed = missed | miss
                alive = alive & ~miss
            if ok.any():
                t = np.where(ok, sequence.arrs[taken], t)
        elif kind != StepKind.BIKE_GATE:
            raise ValueError(f"프로필에 모르는 단계 {kind} 가 있습니다")
    arrival = np.where(alive, t, arrival)
    return Realization(
        arrival=arrival,
        stops=stops,
        vehicles=vehicles,
        missed=missed,
        bike_fallback=tuple(value == 0 for value in beta),
    )


def realize(
    profile: Profile,
    m: Any,
    omega: dict[str, tuple[np.ndarray, np.ndarray]],
    beta: Sequence[int],
    context: SearchContext,
    m_pm: Any = None,
) -> Realization:
    """속도 배수 배열 m, 표본 신호의 (θ, C) 배열 omega, 따릉이 조합 β 로 모든 점을 한꺼번에 실현한다(§1.4.2).

    omega 에 없는 표본 신호는 상수 $E[W]$ 를 기다린다(차원을 넘친 신호, §1.4.4). 개방 신호는 실제 위상을 쓴다.
    `m_pm` 을 주면 모형의 주행 배수 대신 그 값을 쓴다(추적 평가, §4.13.4).
    """
    return _realize_points(profile, profile.steps_for(beta), m, omega, context, tuple(beta), m_pm=m_pm)


# --- S6 (5단계). 여정 평가: 문턱값, 안내 차량, 차량 목록, 도착 분포 (§1.4.3, §1.4.5, §1.4.7) ---


@dataclass(frozen=True)
class _Guide:
    """탑승 하나의 안내 결과: 안내 차량의 유효 차량열 위치(차량이 없거나 차량 안 출발의 탑승 1 이면 None), 찾았는지,
    $Q_l(g_l)$, 조건부 확률, $m_{max}$ 로 탈 수 있는 첫 위치."""

    position: int | None
    found: bool
    q_joint: float
    conditional: float
    start: int


class _Evaluation:
    """여정 하나의 확률 평가 상태(§1.4.5). 문턱값은 (따릉이 조합, 탑승, 차량)마다 한 번만 이분법으로 구한다.

    탈 확률과 안내 차량은 표본 신호가 있으면 `n_qmc` 점, 없으면 점 하나로 계산한다(EXACT). 차량 여럿의 문턱값은
    점 배열을 이어 붙여 한 번의 이분법으로 구한다(결과는 차량마다 따로 구한 것과 같다). 차량은 탑승의 유효 차량열(§1.7.4)
    위치로 가리킨다.
    """

    def __init__(self, journey: Journey, plan: Plan, context: SearchContext, config: EngineConfig) -> None:
        self.journey = journey
        self.plan = plan
        self.context = context
        self.config = config
        self.profile = build_profile(journey, context, config)
        self.signals = context.graph.signals
        self.n_prob = config.n_qmc if self.profile.dims else 1
        self.draws = signal_draws(self.profile.dims, self.signals, config.n_qmc if self.profile.dims else 1)
        n_bikes = self.profile.n_bikes
        # 계획이 닿지 못한 따릉이 구간(앞에서 막차를 놓침)은 $a_b$ 가 없어 $P_{bike} = 0$ 으로 둔다.
        self.p_bikes = tuple(_prob(value) for value in plan.p_bikes) + (0.0,) * (n_bikes - len(plan.p_bikes))
        self.ones = (1,) * n_bikes
        self.combos: list[tuple[tuple[int, ...], float]] = []
        for beta in itertools.product((1, 0), repeat=n_bikes):
            weight = 1.0
            for value, probability in zip(beta, self.p_bikes):
                weight *= probability if value == 1 else 1.0 - probability
            self.combos.append((beta, weight))
        self._steps: dict[tuple[int, ...], tuple[ProfileStep, ...]] = {}
        self._tiled: dict[int, dict[str, tuple[np.ndarray, np.ndarray]]] = {}
        self._thresholds: dict[tuple[tuple[int, ...], int, int], np.ndarray] = {}

    def steps(self, beta: tuple[int, ...]) -> tuple[ProfileStep, ...]:
        if beta not in self._steps:
            self._steps[beta] = self.profile.steps_for(beta)
        return self._steps[beta]

    def _draws_for(self, count: int) -> dict[str, tuple[np.ndarray, np.ndarray]]:
        """차량 count 대의 점을 이어 붙인 배열에 맞춘 표본 신호 값."""
        if count == 1:
            return self.draws
        if count not in self._tiled:
            self._tiled[count] = {
                signal_id: (np.tile(theta, count), np.tile(cycle, count)) for signal_id, (theta, cycle) in self.draws.items()
            }
        return self._tiled[count]

    def vehicles(self, number: int) -> RideVehicles:
        """탑승 `number` (0부터)의 유효 차량열(§1.7.4). 차량 안 출발의 탑승 1 에는 없다."""
        return ride_vehicles(self.context, self.journey.rides[number].lines)

    def thresholds(self, beta: tuple[int, ...], number: int, positions: Iterable[int]) -> None:
        """탑승 사건 $E_l(v)$ 의 문턱값 $m^{*}$ 를 점마다 구해 둔다(§1.4.3). $v$ 는 유효 차량열의 위치다.
        $k_{move} = 0$ 이면 $m = 1$ 에서 참이면 1, 아니면 $+\\infty$."""
        missing = [
            position
            for position in dict.fromkeys(int(position) for position in positions)
            if (beta, number, position) not in self._thresholds
        ]
        if not missing:
            return
        sequence = self.vehicles(number)
        n = self.n_prob
        count = len(missing)
        steps = self.steps(beta)
        draws = self._draws_for(count)
        limits = np.repeat(sequence.deps[np.array(missing, dtype=int)], n)
        buffer = self.config.safety_buffer_s

        def event(m: np.ndarray) -> np.ndarray:
            stops = _realize_points(self.profile, steps, m, draws, self.context, beta, upto=number).stops[number]
            with np.errstate(invalid="ignore"):
                return stops + buffer <= limits

        if self.config.k_move == 0:
            values = np.where(event(np.ones(count * n)), 1.0, np.inf)
        else:
            values = bisect_threshold(event, count * n, self.config)
        for k, position in enumerate(missing):
            self._thresholds[(beta, number, position)] = values[k * n : (k + 1) * n]

    def threshold(self, beta: tuple[int, ...], number: int, position: int) -> np.ndarray:
        self.thresholds(beta, number, (position,))
        return self._thresholds[(beta, number, position)]

    def chance(self, thresholds: np.ndarray) -> float:
        """$\\Pr[m \\ge m^{*}]$ 의 점 평균. $k_{move} = 0$ 이면 $m = 1$ 에서 참인 비율이다(DEGENERATE)."""
        if self.config.k_move == 0:
            return float(np.mean(thresholds <= 1.0))
        return float(np.mean(upper_normal_tail((thresholds - 1.0) / self.config.k_move)))

    def p_catch(self, number: int, position: int) -> float:
        """$p_{catch,l}(v) = \\Pr[E_l(v)]$: 앞 탑승의 결과를 가리지 않고 따릉이 조합을 섞은 값(§1.4.5 (2)). $v$ 는 유효 차량열의 위치다."""
        total = 0.0
        for beta, weight in self.combos:
            if weight > 0:
                total += weight * self.chance(self.threshold(beta, number, position))
        return _prob(total)

    def first_position(self, number: int) -> int:
        """$m_{max}$ 로 실현했을 때(모든 $\\beta_b = 1$) 탈 수 있는 가장 이른 차량의 유효 차량열 위치. 점들 가운데 가장 이른 것이다."""
        deps = self.vehicles(number).deps
        real = _realize_points(
            self.profile, self.steps(self.ones), np.full(self.n_prob, self.config.m_max), self.draws, self.context, self.ones, upto=number
        )
        reached = real.stops[number][np.isfinite(real.stops[number])]
        if reached.size == 0 or deps.size == 0:
            return int(deps.size)
        return int(np.searchsorted(deps, reached + self.config.safety_buffer_s, side="left").min())

    def guide(self) -> list[_Guide]:
        """탑승 순서로 안내 차량을 정한다(§1.4.5 (2)): $Q_l(v) \\ge p_{ghost}$ 인 첫 차량, 없으면 마지막 차량(찾지 못함).

        $Q_l$ 은 앞 탑승 안내 차량들의 문턱값과의 최댓값으로 구한다. 차량 안 출발의 탑승 1 은 탄 차량이고 확률 1 이다.
        """
        config = self.config
        bound = np.full(self.n_prob, config.m_min)
        q_prev = 1.0
        guides: list[_Guide] = []
        for number, ride in enumerate(self.journey.rides):
            if ride.board_index is None:
                guides.append(_Guide(position=None, found=True, q_joint=1.0, conditional=1.0, start=0))
                continue
            size = self.vehicles(number).size
            start = self.first_position(number)
            guided: int | None = None
            found = False
            q = 0.0
            position, chunk = start, 2
            while position < size and not found:
                batch = list(range(position, min(position + chunk, size)))
                self.thresholds(self.ones, number, batch)
                for candidate in batch:
                    joint = np.maximum(bound, self._thresholds[(self.ones, number, candidate)])
                    value = self.chance(joint)
                    if value >= config.p_ghost:
                        guided, found, q, bound = candidate, True, value, joint
                        break
                position += len(batch)
                chunk *= 2
            if not found:
                if size:
                    guided = size - 1
                    bound = np.maximum(bound, self.threshold(self.ones, number, guided))
                    q = self.chance(bound)
                else:
                    bound = np.full(self.n_prob, np.inf)
            guides.append(
                _Guide(position=guided, found=found, q_joint=_prob(q), conditional=_prob(q / q_prev) if q_prev > 0 else 0.0, start=start)
            )
            q_prev = q
        return guides

    def listed_positions(self, number: int, guide: _Guide, naive_position: int | None) -> list[int]:
        """차량 목록(§1.4.5 (2))의 유효 차량열 위치: $m_{max}$ 로 탈 수 있는 첫 차량(기존 방식 차량이 더 이르면 그 차량)부터
        안내 차량의 다음 차량까지, 6대를 넘으면 끝에서부터 6대."""
        size = self.vehicles(number).size
        if size == 0:
            return []
        first = guide.start
        if naive_position is not None:
            first = min(first, naive_position)
        end = guide.position + 1 if guide.position is not None else size - 1
        end = min(end, size - 1)
        first = max(first, end - 5)
        return list(range(first, end + 1))

    def realizations(self) -> list[tuple[tuple[int, ...], float, Realization]]:
        """도착 분포의 Halton 점(차원 0 의 $m_n$, 표본 신호의 $\\omega_n$)으로 조합마다 실현한다(§1.4.5 (4)).

        무게가 0 인 조합은 빼되, 막대그래프가 쓰는 모든 $\\beta_b = 1$ 조합은 언제나 실현한다.
        """
        config = self.config
        m = halton_m(config.n_qmc, config.k_move)
        draws = self.draws if self.profile.dims else {}
        return [
            (beta, weight, _realize_points(self.profile, self.steps(beta), m, draws, self.context, beta))
            for beta, weight in self.combos
            if weight > 0 or beta == self.ones
        ]


def _ordinal(trips: TripSet, index: int, row: int) -> int:
    """그 정류장에서 몇 번째로 오는 차인지(§1.4.5 (2), §1.7.1): 차량 노선의 승차 순번에서 시각이 0 이상인 차량을
    (시각, 노선의 차량 순서) 순으로 센 번호."""
    column = trips.dep[:, index]
    target = column[row]
    rows = np.arange(trips.n_trips)
    with np.errstate(invalid="ignore"):
        valid = ~np.isnan(column) & (column >= 0)
        earlier = valid & ((column < target) | ((column == target) & (rows < row)))
    return 1 + int(np.count_nonzero(earlier))


def _vehicle_option(context: SearchContext, vehicles: RideVehicles, position: int, p_catch: float) -> VehicleOption:
    """차량 목록의 차량 하나(§1.4.5 (2)): 유효 차량열의 위치 `position` 의 차량. 몇 번째 차는 그 차량 노선의 승차 순번에서 센다."""
    route_id = vehicles.route_ids[position]
    board, _alight = vehicles.indices(route_id)
    return VehicleOption(
        trip_id=vehicles.trip_ids[position],
        route_id=route_id,
        ordinal=_ordinal(context.routes[route_id].trips, board, int(vehicles.rows[position])),
        dep_s=float(vehicles.deps[position]),
        alight_arr_s=float(vehicles.arrs[position]),
        time_source=vehicles.sources[position],
        is_full=vehicles.full[position],
        is_last=vehicles.last[position],
        p_catch=p_catch,
    )


def _trip_distribution(
    vehicles: RideVehicles, number: int, realized: Sequence[tuple[tuple[int, ...], float, Realization]], n_points: int
) -> tuple[tuple[str, float], ...]:
    """탑승 하나의 탄 차량 분포(§1.4.5 (4)): 유효 차량열 순으로 차량마다 무게, 맨 뒤에 MISSED_LAST. 무게 0 인 항목은 뺀다.

    MISSED_LAST 는 그 탑승에서 막차를 놓친 점, 앞에서 이미 끝난 점(막차 놓침, 자전거도 걸을 길도 없음), 처음부터 가지 못한 점이다.
    """
    masses: dict[int, float] = {}
    for _beta, weight, real in realized:
        if weight <= 0:
            continue
        values, counts = np.unique(real.vehicles[number], return_counts=True)
        for value, count in zip(values.tolist(), counts.tolist()):
            masses[value] = masses.get(value, 0.0) + weight * count / n_points
    entries = [(vehicles.trip_ids[position], _prob(mass)) for position, mass in sorted(masses.items()) if position >= 0 and mass > 0]
    missed = masses.get(-1, 0.0)
    if missed > 0:
        entries.append((MISSED_LAST, _prob(missed)))
    return tuple(entries)


def _histograms(
    evaluation: _Evaluation, guides: Sequence[_Guide], ones: Realization
) -> list[MarginHistogram | None]:
    """탑승마다 여유 $M = \\text{dep}_{g_l} - \\text{정류장 도착}$ 의 막대그래프(§1.4.7). 점은 모든 $\\beta_b = 1$ 조합에서
    앞 탑승들을 안내 차량이나 그보다 이른 차량으로 탄 점이다. 안내 차량이 없는 탑승부터는 None 이다."""
    config = evaluation.config
    selected = np.ones(ones.arrival.size, dtype=bool)
    out: list[MarginHistogram | None] = []
    stopped = False
    for number, (ride, guide) in enumerate(zip(evaluation.journey.rides, guides)):
        if ride.board_index is None:
            out.append(None)
            continue
        if stopped or guide.position is None:
            stopped = True
            out.append(None)
            continue
        deps = evaluation.vehicles(number).deps
        dep_g = float(deps[guide.position])
        margins = dep_g - ones.stops[number][selected]
        out.append(margin_histogram(margins, None, config.safety_buffer_s, config.hist_bin_s))
        taken = ones.vehicles[number]
        taken_dep = np.where(taken >= 0, deps[np.maximum(taken, 0)], np.inf)
        selected = selected & (taken >= 0) & (taken_dep <= dep_g)
    return out


# --- S6 (5단계). 기존 방식 시각과 유령 판정 (§1.11.3, §1.4.6) ---


@dataclass(frozen=True)
class NaiveTimeline:
    """기존 방식 시각 모형의 여정 하나(§1.11.3). 탑승마다 정류장 도착, 탄 차량(유효 차량열 위치와 차량 ID, 가상 차량이면 None.
    차량 안 출발의 탑승 1 은 위치 없이 탄 차량의 ID), 여유, 그리고 약속 도착(타야 할 곳에 그 시각 이후의 실제 차량이 없거나
    걸을 길이 없으면 None)."""

    wait: NaiveTransferWait
    stop_arrivals: tuple[float | None, ...]
    positions: tuple[int | None, ...]
    trip_ids: tuple[str | None, ...]
    margins: tuple[float | None, ...]
    promised_s: float | None


def _naive_leg_s(context: SearchContext, src: str, dst: str, mode: Mode, speed_mps: float) -> float | None:
    """최단거리 경로를 신호 대기 없이 지나는 시간. 길이 없으면 None."""
    hops = context.shortest(src, dst, mode)
    if hops is None:
        return None
    return sum(hop.length_m for hop in hops) / speed_mps


def _naive_move_s(context: SearchContext, move: JourneyMove, config: EngineConfig) -> float | None:
    """기존 방식의 이동 시간: 걷기는 최단거리를 $v_{walk}$ 로, 따릉이는 ①③⑤ 를 각각 최단거리로 가고 대여·반납 시간을 더한다."""
    if not move.has_bike:
        return _naive_leg_s(context, move.from_id, move.to_id, Mode.WALK, config.v_walk_mps)
    legs = (
        _naive_leg_s(context, move.from_id, move.pick_id, Mode.WALK, config.v_walk_mps),
        _naive_leg_s(context, move.pick_id, move.drop_id, Mode.BIKE, config.v_pm_mps),
        _naive_leg_s(context, move.drop_id, move.to_id, Mode.WALK, config.v_walk_mps),
    )
    if any(leg is None for leg in legs):
        return None
    return legs[0] + config.t_unlock_s + legs[1] + config.t_dock_s + legs[2]


def naive_timeline(journey: Journey, context: SearchContext, config: EngineConfig, wait: NaiveTransferWait | str) -> NaiveTimeline:
    """여정의 탑승 구조와 대여소를 그대로 두고 기존 방식 시각 모형으로 계산한다(§1.11.3 (2), (3)).

    첫 탑승(차량 안 출발이면 탄 차량)은 실제 차량을 승차 여유 0 으로 탄다. 둘째 탑승부터는 `REAL` 이면 같은 방식,
    `ZERO` 면 정류장에 닿자마자 떠나 $\\pi_{arr}(j) - \\pi_{dep}(i)$ 뒤에 내린다(그 시각 이후의 실제 차량이 있을 때만. 묶음이면
    노선마다의 값 가운데 가장 짧은 값). 실제 차량은 유효 차량열(§1.7.4)에서 고르고, 기존 방식 차량 $\\nu_l$ 은 `REAL` 로 부른
    결과의 차량이다.
    """
    mode = NaiveTransferWait(wait)
    count = len(journey.rides)
    stops: list[float | None] = [None] * count
    positions: list[int | None] = [None] * count
    ids: list[str | None] = [None] * count
    margins: list[float | None] = [None] * count
    first_real: int | None = 0
    t = 0.0
    if journey.in_vehicle:
        first = journey.rides[0]
        route = context.routes[first.route_id]
        ids[0] = route.trips.trip_ids[context.origin_row]
        t = float(route.trips.arr[context.origin_row, first.alight_index])
        first_real = None
    promised: float | None = None
    for kind, number in _journey_sequence(journey):
        if kind == "move":
            seconds = _naive_move_s(context, journey.moves[number], config)
            if seconds is None:
                break
            t += seconds
            continue
        ride = journey.rides[number]
        if ride.board_index is None:
            continue
        vehicles = ride_vehicles(context, ride.lines)
        position = vehicles.first(t)
        if position is None:
            break
        stops[number] = t
        if number == first_real or mode == NaiveTransferWait.REAL:
            positions[number] = position
            ids[number] = vehicles.trip_ids[position]
            margins[number] = float(vehicles.deps[position]) - t
            t = float(vehicles.arrs[position])
        else:
            margins[number] = 0.0
            t += min(context.routes[line_id].pi_arr[alight] - context.routes[line_id].pi_dep[board] for line_id, board, alight in vehicles.lines)
    else:
        promised = t
    return NaiveTimeline(
        wait=mode,
        stop_arrivals=tuple(stops),
        positions=tuple(positions),
        trip_ids=tuple(ids),
        margins=tuple(margins),
        promised_s=promised,
    )


# --- S6 (5단계). 요금 적용과 여정 평가 결과 (§1.5, §1.4.5) ---

_IN_STATION_KINDS = frozenset({EdgeKind.STATION_PASSAGE, EdgeKind.STAIRS})


def _itinerary_fare(journey: Journey, plan: Plan, context: SearchContext, config: EngineConfig) -> FareBreakdown:
    """계획(§1.10.6)이 탄 탑승으로 요금을 계산한다(§1.5). 막차를 놓친 탑승과 그 뒤는 넣지 않는다.

    이어진 두 지하철 탑승 사이의 이동이 따릉이 없이 역 안 엣지만 지나면(엣지가 없어도) 개찰구 안 환승이다.
    """
    moves = {move.index: move for move in journey.moves}
    fare_rides: list[FareRide] = []
    for number, ride in enumerate(plan.rides):
        if ride.plan_arr_s is None:
            break
        in_station = False
        if number > 0 and ride.mode == TravelMode.SUBWAY and plan.rides[number - 1].mode == TravelMode.SUBWAY:
            move = moves.get(number)
            in_station = (
                move is not None
                and not move.has_bike
                and all(context.graph.edges[hop.edge_id].kind in _IN_STATION_KINDS for hop in move.walk or ())
            )
        fare_rides.append(
            FareRide(
                mode=ride.mode,
                route_type=ride.bus_type,
                route_id=ride.route_id,
                board_s=ride.plan_dep_s,
                alight_s=ride.plan_arr_s,
                distance_m=ride.distance_m,
                in_station=in_station,
            )
        )
    used_bike = any(move.bike is not None for move in plan.moves)
    return fare_breakdown(fare_rides, used_bike, context.scenario.clock_s, config)


def assess_itinerary(journey: Journey, plan: Plan, context: SearchContext, config: EngineConfig) -> ItineraryResult:
    """후보 여정 하나를 평가한다(§1.4.5, §1.4.6, §1.11.3, §1.5): 탈 확률과 안내 차량, $P^{*}$ 와 등급, 도착 분포,
    탄 차량 분포, 여유 막대그래프, 기존 방식의 약속 도착과 기존 방식 차량, 유령 환승, 요금, 상태와 사유.

    순위에 쓰는 값(`rank`, `criterion_value`, `utility`, 대표 묶기)은 `rank_itineraries` 가 채운다.
    """
    evaluation = _Evaluation(journey, plan, context, config)
    profile = evaluation.profile
    guides = evaluation.guide()
    naive = naive_timeline(journey, context, config, NaiveTransferWait.REAL)
    promise = naive if config.naive_transfer_wait == NaiveTransferWait.REAL else naive_timeline(journey, context, config, config.naive_transfer_wait)
    realized = evaluation.realizations()
    ones = next(real for beta, _weight, real in realized if beta == evaluation.ones)
    n_points = config.n_qmc
    histograms = _histograms(evaluation, guides, ones)
    boardings: list[BoardingAssessment] = []
    for number, (ride, guide) in enumerate(zip(journey.rides, guides)):
        if ride.board_index is None:
            origin_trip = context.routes[ride.route_id].trips.trip_ids[context.origin_row]
            boardings.append(
                BoardingAssessment(
                    ride_index=number + 1,
                    guided_trip_id=origin_trip,
                    guided_found=True,
                    q_joint=1.0,
                    p_conditional=1.0,
                    vehicles=(),
                    trip_distribution=((origin_trip, 1.0),),
                    naive_trip_id=None,
                    naive_stop_arrival_s=None,
                    naive_margin_s=None,
                    p_catch_naive=None,
                    ghost=False,
                    histogram=None,
                )
            )
            continue
        vehicles = evaluation.vehicles(number)
        naive_position = naive.positions[number]
        listed = evaluation.listed_positions(number, guide, naive_position)
        wanted = listed + ([naive_position] if naive_position is not None else [])
        for beta, weight in evaluation.combos:
            if weight > 0:
                evaluation.thresholds(beta, number, wanted)
        p_naive = evaluation.p_catch(number, naive_position) if naive_position is not None else None
        boardings.append(
            BoardingAssessment(
                ride_index=number + 1,
                guided_trip_id=None if guide.position is None else vehicles.trip_ids[guide.position],
                guided_found=guide.found,
                q_joint=guide.q_joint,
                p_conditional=guide.conditional,
                vehicles=tuple(_vehicle_option(context, vehicles, position, evaluation.p_catch(number, position)) for position in listed),
                trip_distribution=_trip_distribution(vehicles, number, realized, n_points),
                naive_trip_id=naive.trip_ids[number],
                naive_stop_arrival_s=naive.stop_arrivals[number] if naive_position is not None else None,
                naive_margin_s=naive.margins[number] if naive_position is not None else None,
                p_catch_naive=p_naive,
                ghost=p_naive is not None and p_naive < config.p_ghost,
                histogram=histograms[number],
            )
        )
    q_last = guides[-1].q_joint if guides else 1.0
    p_star = _prob(math.prod(evaluation.p_bikes) * q_last)
    weighted = [(weight, real) for _beta, weight, real in realized if weight > 0]
    times = np.concatenate([real.arrival for _weight, real in weighted])
    weights = np.concatenate([np.full(real.arrival.size, weight / n_points) for weight, real in weighted])
    finite = np.isfinite(times)
    p_unreachable = _prob(float(np.sum(weights[~finite])))
    if finite.any():
        mean = float(np.sum(times[finite] * weights[finite]) / np.sum(weights[finite]))
        quantiles = tuple(weighted_quantile(times[finite], weights[finite], q) for q in (0.1, 0.5, 0.9))
    else:
        mean, quantiles = None, (None, None, None)
    deadline = context.query.deadline_s
    p_on_time = None if deadline is None else _prob(float(np.sum(weights[finite & (times <= deadline)])))
    if config.k_move == 0:
        method = ProbMethod.DEGENERATE
    else:
        method = ProbMethod.QMC if profile.dims else ProbMethod.EXACT
    arrival = ArrivalStats(
        mean_s=mean,
        p10_s=quantiles[0],
        p50_s=quantiles[1],
        p90_s=quantiles[2],
        p_on_time=p_on_time,
        p_unreachable=p_unreachable,
        method=method,
        n_points=n_points,
        n_sampled_signals=len(profile.dims),
        capped_signal_ids=profile.capped,
        bike_fallback_mass=tuple(
            _prob(sum(weight for beta, weight in evaluation.combos if beta[b] == 0)) for b in range(profile.n_bikes)
        ),
        missed_last_mass=_prob(sum(weight * float(np.mean(real.missed)) for weight, real in weighted)),
    )
    reasons: list[ReasonCode] = []
    if any(not guide.found for guide, ride in zip(guides, journey.rides) if ride.board_index is not None):
        reasons.append(ReasonCode.LAST_VEHICLE_RISK)
    if p_star < config.p_ghost:
        reasons.append(ReasonCode.LOW_PLAN_PROBABILITY)
    if p_unreachable > 0 and not finite.any():
        reasons.append(ReasonCode.UNREACHABLE)
    return ItineraryResult(
        itinerary_id=journey.itinerary_id,
        label=journey.label,
        found_by=journey.found_by,
        structure_key=journey.structure_key,
        ride_key=journey.ride_key,
        moves=plan.moves,
        rides=plan.rides,
        legs=plan.legs,
        plan_arrival_s=plan.arrival_s,
        plan_missed_last=plan.missed_last,
        boardings=tuple(boardings),
        p_bikes=evaluation.p_bikes,
        p_star=p_star,
        grade=grade_of(p_star, config),
        arrival=arrival,
        status=RouteStatus.GHOST_PRUNED if reasons else RouteStatus.RANKED,
        reasons=tuple(reasons),
        naive_promised_s=promise.promised_s,
        ghost_count=sum(1 for boarding in boardings if boarding.ghost),
        fare=_itinerary_fare(journey, plan, context, config),
        utility=None,
        criterion_value=None,
        walk_distance_m=plan.walk_m,
    )


# --- S6 (5단계). 순위, 대표, 비교 패널 (§1.11) ---


def rank_itineraries(
    results: Sequence[ItineraryResult], query: Query, config: EngineConfig
) -> tuple[tuple[ItineraryResult, ...], tuple[str, ...], tuple[str, ...], str | None]:
    """RANKED 여정의 순위(§1.11.1)와 대표 묶기(§1.11.2). (고친 결과(들어온 순서), 대표 순위, 걸러진 여정, 최선 여정)을 돌려준다.

    값은 소수 여섯째 자리에서 반올림해 비교하고, 같으면 $P^{*}$ 큰 쪽, 요금 싼 쪽, 탑승 적은 쪽, 걷는 거리 짧은 쪽, ID 순이다.
    `ON_TIME` 이 아니면 기준 값보다 먼저 `p_unreachable` (소수 여섯째 자리에서 반올림)이 작은 쪽을 앞에 둔다(EV13).
    `ON_TIME` 인데 마감이 없으면 `MEAN_ARRIVAL` 로 정렬한다(경고는 `run_engine` 이 남긴다).
    """
    criterion = config.rank_criterion
    if criterion == RankCriterion.ON_TIME and query.deadline_s is None:
        criterion = RankCriterion.MEAN_ARRIVAL
    ranked = [result for result in results if result.status == RouteStatus.RANKED]
    t_max = max((result.arrival.mean_s for result in ranked), default=0.0)
    cost_max = max((float(result.fare.total_krw) for result in ranked), default=0.0)
    values: dict[str, float] = {}
    utilities: dict[str, UtilityTerms] = {}
    for result in ranked:
        stats = result.arrival
        if criterion == RankCriterion.MEAN_ARRIVAL:
            values[result.itinerary_id] = stats.mean_s
        elif criterion == RankCriterion.P90_ARRIVAL:
            values[result.itinerary_id] = stats.p90_s
        elif criterion == RankCriterion.ON_TIME:
            values[result.itinerary_id] = stats.p_on_time
        else:
            terms = utility_terms(
                stats.mean_s, float(result.fare.total_krw), result.p_star, t_max, cost_max, (config.w_time, config.w_cost, config.w_risk)
            )
            utilities[result.itinerary_id] = terms
            values[result.itinerary_id] = terms.total
    sign = -1.0 if criterion == RankCriterion.ON_TIME else 1.0

    def key(result: ItineraryResult) -> tuple:
        unreachable = 0.0 if criterion == RankCriterion.ON_TIME else round(result.arrival.p_unreachable, 6)
        return (
            unreachable,
            sign * round(values[result.itinerary_id], 6),
            -round(result.p_star, 6),
            result.fare.total_krw,
            len(result.rides),
            round(result.walk_distance_m, 6),
            result.itinerary_id,
        )

    representative: dict[str, str] = {}
    variants: dict[str, list[str]] = {}
    ranking: list[str] = []
    for result in sorted(ranked, key=key):
        head = representative.setdefault(result.ride_key, result.itinerary_id)
        if head == result.itinerary_id:
            ranking.append(result.itinerary_id)
            variants[head] = []
        else:
            variants[head].append(result.itinerary_id)
    pruned = sorted(
        (result for result in results if result.status != RouteStatus.RANKED),
        key=lambda result: (result.arrival.mean_s is None, result.arrival.mean_s or 0.0, result.itinerary_id),
    )
    rank_of = {jid: number for number, jid in enumerate(ranking, start=1)}
    updated = []
    for result in results:
        jid = result.itinerary_id
        if result.status != RouteStatus.RANKED:
            update = {"rank": None, "representative_id": None, "variant_ids": (), "criterion_value": None, "utility": None}
        else:
            head = representative[result.ride_key]
            update = {
                "rank": rank_of.get(jid),
                "representative_id": None if head == jid else head,
                "variant_ids": tuple(variants[jid]) if head == jid else (),
                "criterion_value": values[jid],
                "utility": utilities.get(jid),
            }
        updated.append(result.model_copy(update=update))
    return tuple(updated), tuple(ranking), tuple(result.itinerary_id for result in pruned), ranking[0] if ranking else None


def comparison_panel(results: Sequence[ItineraryResult], best_id: str | None, naive_best_id: str | None) -> ComparisonPanel:
    """기존 방식 1위 여정과 이 앱의 최선 여정을 나란히 둔다(§1.11.3 (5)). 계산하지 못한 값은 None 이다."""
    by_id = {result.itinerary_id: result for result in results}
    naive = by_id.get(naive_best_id) if naive_best_id is not None else None
    best = by_id.get(best_id) if best_id is not None else None
    naive_mean = naive.arrival.mean_s if naive is not None else None
    best_mean = best.arrival.mean_s if best is not None else None
    promised = naive.naive_promised_s if naive is not None else None
    return ComparisonPanel(
        naive_best_id=naive_best_id,
        best_id=best_id,
        same=naive_best_id is not None and naive_best_id == best_id,
        naive_promised_s=promised,
        naive_mean_s=naive_mean,
        naive_p90_s=naive.arrival.p90_s if naive is not None else None,
        naive_p_star=naive.p_star if naive is not None else None,
        naive_status=naive.status if naive is not None else None,
        naive_reasons=naive.reasons if naive is not None else (),
        best_mean_s=best_mean,
        best_p90_s=best.arrival.p90_s if best is not None else None,
        late_vs_promise_s=naive_mean - promised if naive_mean is not None and promised is not None else None,
        saving_s=naive_mean - best_mean if naive_mean is not None and best_mean is not None else None,
        app_misled=naive is not None and naive.ghost_count > 0,
    )


# --- S6 (5단계). run_engine (§2) ---


def _station_statuses(context: SearchContext, config: EngineConfig) -> tuple[StationStatus, ...]:
    """타원 안에 남은 대여소마다 상태(§1.3). $a$ 는 출발 노드에서 걷기 그래프로 $m = 1$, `EXPECTED` 로 돌린 Dijkstra 의 도착이다.

    차량 안 출발이면 탄 차량에서 내릴 수 있는 정류장(승강장)들을 그 하차 시각과 함께 출처로 둔다.
    """
    if context.in_vehicle:
        route = context.routes[context.origin_route]
        row = context.origin_row
        sources = [
            (route.node_ids[index], float(route.trips.arr[row, index]))
            for index in range(context.origin_index, len(route.node_ids))
            if route.board.alight[row, index]
        ]
    else:
        sources = [(context.origin_id, 0.0)]
    labels = td_dijkstra(context.graph, sources, Mode.WALK, config.v_walk_mps, WaitRule.EXPECTED)
    age = context.scenario.bike_obs_age_s
    statuses: list[StationStatus] = []
    for station_id in sorted(context.graph.bike_stations):
        station = context.graph.bike_stations[station_id]
        bikes = station.bikes_available
        arrival = labels.times.get(station_id)
        if arrival is None:
            use = StationUse.NO_BIKE if bikes == 0 else StationUse.LOW_P_BIKE
            statuses.append(StationStatus(station_id=station_id, use=use, bikes_available=bikes, arrival_s=None, p_bike=None))
            continue
        probability = p_bike(bikes, station.rental_rate_per_hour, age + arrival)
        if bikes == 0:
            use = StationUse.NO_BIKE
        elif probability < config.bike_pick_min_p:
            use = StationUse.LOW_P_BIKE
        else:
            use = StationUse.AVAILABLE
        statuses.append(StationStatus(station_id=station_id, use=use, bikes_available=bikes, arrival_s=arrival, p_bike=probability))
    return tuple(statuses)


def _empty_summary() -> SearchSummary:
    return SearchSummary(runs=(), found_total=0, distinct=0, kept=0, discarded_ids=(), reach=())


def _source_warnings(sources: Sequence[ApiSourceStatus]) -> list[EngineWarning]:
    """시나리오 준비의 원천 상태를 경고로 옮긴다(§3.4): SKIPPED, FAILED 는 각각 LIVE_DATA_SKIPPED, LIVE_DATA_FAILED, 그리고 각 `issues`."""
    warnings: list[EngineWarning] = []
    for status in sources:
        refs = (status.source.value, status.target) if status.target else (status.source.value,)
        name = f"{status.source.value} {status.target}".strip()
        if status.state == SourceState.SKIPPED:
            warnings.append(EngineWarning(code=WarningCode.LIVE_DATA_SKIPPED, message=f"{name} 자료를 받지 않았습니다: {status.reason}", ref_ids=refs))
        elif status.state == SourceState.FAILED:
            warnings.append(EngineWarning(code=WarningCode.LIVE_DATA_FAILED, message=f"{name} 자료를 받지 못했습니다: {status.reason}", ref_ids=refs))
        warnings.extend(status.issues)
    return warnings


def _sorted_warnings(warnings: Iterable[EngineWarning]) -> tuple[EngineWarning, ...]:
    """경고를 (코드, 첫 번째 ref_id) 순으로 늘어놓는다(§3.5). 같은 경고가 두 번 오면 하나만 남긴다."""
    unique = list(dict.fromkeys(warnings))
    return tuple(sorted(unique, key=lambda warning: (warning.code.value, warning.ref_ids[0] if warning.ref_ids else "")))


@dataclass(frozen=True, eq=False)
class EngineDetail:
    """`run_engine` 의 결과와 그 계산에 쓴 탐색 문맥, 후보 여정(여정 ID → Journey). 붙이기에 실패하면 문맥은 None (§4.13.2)."""

    output: EngineOutput
    context: "SearchContext | None"
    journeys: dict[str, "Journey"]


def run_engine(scenario: Scenario, query: Query, config: EngineConfig, sources: Sequence[ApiSourceStatus] = ()) -> EngineOutput:
    """엔진 절차 1 ~ 8 (§2). 계산은 `run_engine_detail` 과 같고 그 결과만 돌려준다."""
    return run_engine_detail(scenario, query, config, sources).output


def run_engine_detail(
    scenario: Scenario, query: Query, config: EngineConfig, sources: Sequence[ApiSourceStatus] = ()
) -> EngineDetail:
    """엔진 절차 1 ~ 8 (§2): 붙이기, 가지치기, 차량 시각, 탐색, 후보와 계획, 후보마다 평가, 순위·대표·비교 패널·대여소 상태, 경고.

    검증된 입력에 대해 예외를 던지지 않는다(§3.5). 붙이기에 실패하면 SNAP_FAILED, $D$ 에 닿지 못하면 NO_ROUTE 다.
    """
    unverified_nodes = sorted(node.id for node in scenario.nodes if not node.verified)
    unverified_stations = sorted(station.id for station in scenario.bike_stations if not station.verified)
    unverified = tuple(sorted(unverified_nodes + unverified_stations))
    warnings: list[EngineWarning] = []
    if unverified:
        warnings.append(
            EngineWarning(
                code=WarningCode.UNVERIFIED_COORDINATES,
                message=f"좌표를 확인하지 않은 노드 {len(unverified_nodes)}개와 대여소 {len(unverified_stations)}개가 있습니다",
                ref_ids=unverified,
            )
        )
    warnings.extend(_source_warnings(sources))
    common = {
        "scenario_id": scenario.id,
        "query": query,
        "config": config,
        "sources": tuple(sources),
        "unverified_node_ids": unverified,
        "data_mode": scenario.data_mode,
        "clock_s": scenario.clock_s,
        "day_type": scenario.day_type,
    }
    context, failure = build_search_context(scenario, query, config)
    if context is None:
        warnings.append(failure)
        return EngineDetail(output=EngineOutput(
            status=EngineStatus.SNAP_FAILED,
            origin_node_id=None,
            destination_node_id=None,
            pruning=None,
            pruning_records=(),
            line_times=(),
            search=_empty_summary(),
            itineraries=(),
            ranking=(),
            pruned_ids=(),
            best_id=None,
            comparison=comparison_panel((), None, None),
            stations=(),
            warnings=_sorted_warnings(warnings),
            **common,
        ), context=None, journeys={})
    warnings.extend(context.warnings)
    journeys, summary = search_candidates(context, config)
    status = EngineStatus.OK
    if not journeys:
        status = EngineStatus.NO_ROUTE
        warnings.append(EngineWarning(code=WarningCode.NO_ROUTE, message="경로 없음, γ 확대 필요", ref_ids=()))
    results = [assess_itinerary(journey, plan_schedule(journey, context, config), context, config) for journey in journeys]
    capped = sorted({signal_id for result in results for signal_id in result.arrival.capped_signal_ids})
    if capped:
        warnings.append(
            EngineWarning(
                code=WarningCode.QMC_DIMENSIONS_CAPPED,
                message=f"표본 신호가 준난수 차원보다 많아 {len(capped)}개 신호의 대기를 평균 대기로 두었습니다",
                ref_ids=tuple(capped),
            )
        )
    for result in results:
        for code in fare_warnings(result.fare, config):
            message = (
                "환승 인정 시간을 넘겨 기본요금을 다시 냅니다"
                if code == WarningCode.TRANSFER_WINDOW_EXCEEDED
                else "광역버스가 있어 기후동행카드 단기권을 적용하지 않았습니다"
            )
            warnings.append(EngineWarning(code=code, message=message, ref_ids=(result.itinerary_id,)))
    if config.rank_criterion == RankCriterion.ON_TIME and query.deadline_s is None:
        warnings.append(
            EngineWarning(code=WarningCode.DEADLINE_MISSING, message="마감 시각이 없어 평균 도착으로 정렬했습니다", ref_ids=())
        )
    ranked, ranking, pruned, best = rank_itineraries(results, query, config)
    naive_trace = next((trace for trace in summary.runs if trace.run == SearchRun.NAIVE), None)
    naive_best = naive_trace.itinerary_ids[0] if naive_trace is not None and naive_trace.itinerary_ids else None
    output = EngineOutput(
        status=status,
        origin_node_id=context.origin_id,
        destination_node_id=context.destination_id,
        pruning=context.pruning,
        pruning_records=context.pruning_records,
        line_times=tuple(line_times(route.trips) for route in context.routes.values()),
        search=summary,
        itineraries=ranked,
        ranking=ranking,
        pruned_ids=pruned,
        best_id=best,
        comparison=comparison_panel(ranked, best, naive_best),
        stations=_station_statuses(context, config),
        warnings=_sorted_warnings(warnings),
        **common,
    )
    return EngineDetail(output=output, context=context, journeys={journey.itinerary_id: journey for journey in journeys})


# --- S6 (5단계). 시계 이동과 출발 늦추기 (§4.6) ---


def advance_clock(scenario: Scenario, dt_s: float, config: EngineConfig) -> Scenario:
    """시나리오의 값을 Δt 뒤로 옮긴 새 시나리오(§4.6). 원본은 바꾸지 않는다. Δt = 0 이면 그대로 돌려준다.

    시계 (+Δt mod 86,400), 개방 신호의 위상 θ' = (θ + Δt) mod C, 버스 예측 `eta_s` − Δt (음수가 된 NORMAL 항목은 없앤다)와
    `prediction_age_s` + Δt (None 이면 그대로), 열차 시각 − Δt (모든 시각이 음수인 열차는 없애고, 열차가 남지 않은 패턴도 없앤다),
    `bike_obs_age_s` + Δt. 요일 종류, 배차 간격, 막차 시각, 자전거 수는 그대로다. 질의는 옮기지 않는다(`shift_origin`).
    `config` 는 계약의 인자이고 지금 규칙에서는 쓰지 않는다.
    """
    del config
    dt = float(dt_s)
    if dt < 0:
        raise ValueError(f"advance_clock 은 Δt ≥ 0 만 받습니다(지금 {dt:g})")
    if dt == 0:
        return scenario
    signals = tuple(
        phase.model_copy(update={"offset_s": (phase.offset_s + dt) % phase.cycle_s}) if is_open_signal(phase) else phase
        for phase in scenario.signals
    )
    lines = []
    for line in scenario.bus_lines:
        predictions = tuple(
            tuple(
                item if item.kind != PredictionKind.NORMAL else item.model_copy(update={"eta_s": item.eta_s - dt})
                for item in items
                if item.kind != PredictionKind.NORMAL or item.eta_s - dt >= 0
            )
            for items in line.predictions
        )
        age = None if line.prediction_age_s is None else line.prediction_age_s + dt
        lines.append(line.model_copy(update={"predictions": predictions, "prediction_age_s": age}))
    patterns = []
    for pattern in scenario.subway_patterns:
        trips = tuple(
            trip.model_copy(update={"arr_s": tuple(v - dt for v in trip.arr_s), "dep_s": tuple(v - dt for v in trip.dep_s)})
            for trip in pattern.trips
            if any(v - dt >= 0 for v in (*trip.arr_s, *trip.dep_s))
        )
        if trips:
            patterns.append(pattern.model_copy(update={"trips": trips}))
    query = scenario.default_query
    if query is not None and query.origin.kind == OriginKind.ON_TRAIN:
        kept = {pattern.id: {trip.id for trip in pattern.trips} for pattern in patterns}
        if query.origin.trip_id not in kept.get(query.origin.pattern_id, set()):
            query = None
    return scenario.model_copy(
        update={
            "clock_s": (scenario.clock_s + dt) % SECONDS_PER_DAY,
            "signals": signals,
            "bus_lines": tuple(lines),
            "subway_patterns": tuple(patterns),
            "default_query": query,
            "bike_obs_age_s": scenario.bike_obs_age_s + dt,
        }
    )


def _origin_trips(scenario: Scenario, origin: OriginState, config: EngineConfig) -> TripSet | None:
    """차량 안 출발이 탄 노선(버스는 `build_bus_trips` 로 만든 차량, 합성 차량 포함)이나 정차 패턴의 차량 배열."""
    if origin.kind == OriginKind.ON_BUS:
        line = next((line for line in scenario.bus_lines if line.id == origin.line_id), None)
        return None if line is None else build_bus_trips(line, scenario.clock_s, config)
    pattern = next((pattern for pattern in scenario.subway_patterns if pattern.id == origin.pattern_id), None)
    return None if pattern is None else pattern_trips(pattern, config)


def shift_origin(base: Scenario, shifted: Scenario, query: Query, dt_s: float, config: EngineConfig) -> Query | None:
    """출발 늦추기의 차량 안 출발(§4.6): 원래 차량이 순번 $j_0$ 에 닿는 시각 $a_0$ (옮기기 전 시나리오의 $t$)에 대해,
    옮긴 시나리오의 같은 노선·패턴 차량 가운데 $j_0$ 에 $a_0$ 이상의 시각에 닿는 첫 차량을 탄 질의. 없으면 None.

    옮긴 시나리오의 $t$ 는 이미 Δt 만큼 늦은 기준이므로 `dt_s` 는 따로 더하지 않는다(계약의 인자). 지점 출발은 그대로다.
    """
    del dt_s
    origin = query.origin
    if origin.kind in (OriginKind.AT_NODE, OriginKind.AT_POINT):
        return query
    before = _origin_trips(base, origin, config)
    after = _origin_trips(shifted, origin, config)
    if before is None or after is None:
        return None
    row = before.row_of(origin.trip_id)
    index = origin.next_index
    if row is None or index >= before.n_stops or index >= after.n_stops:
        return None
    a0 = float(before.arr[row, index])
    if math.isnan(a0):
        return None
    candidates = [
        (float(after.arr[other, index]), other)
        for other in range(after.n_trips)
        if not math.isnan(after.arr[other, index]) and after.arr[other, index] >= a0
    ]
    if not candidates:
        return None
    chosen = min(candidates)[1]
    return query.model_copy(update={"origin": origin.model_copy(update={"trip_id": after.trip_ids[chosen]})})


# ===== S7. 시나리오, 생성기, 지하철 시각표 (§4, §1.7.2, §4.9, §4.10) =====

# --- 지하철 시각표: 응답 읽기, CSV 쓰기와 읽기, 받기 (§4.10) ---

TIMETABLE_COLUMNS: tuple[str, ...] = (
    "line", "station", "direction", "day_type", "train_no", "arrive", "depart", "destination", "express",
)
DISTANCE_COLUMNS: tuple[str, ...] = ("line", "from_station_key", "to_station_key", "distance_km")
TIMETABLE_SKIPPED = "건너뜀"  # parse_timetable_payload 의 사유 (§4.10)
TIMETABLE_EXPRESS_UNKNOWN = "급행 미확인"
NO_TIMETABLE_REASON = "OA-101 에 이 역의 시각표가 없습니다(INFO-200)"
_WEEK_TAGS: MappingProxyType = MappingProxyType({1: DayType.WEEKDAY, 2: DayType.SATURDAY, 3: DayType.HOLIDAY})
_DAY_ORDER: MappingProxyType = MappingProxyType({DayType.WEEKDAY: 0, DayType.SATURDAY: 1, DayType.HOLIDAY: 2})
_HMS_RE = re.compile(r"(\d{2}):(\d{2}):(\d{2})")
_EXPRESS_CODES: MappingProxyType = MappingProxyType({"D": True, "G": False, "": False})
_NO_TIME = "00:00:00"  # OA-101 의 "없음" (시발역 도착, 종착역 출발)
_PREVIOUS_DAY = "@전날"


def _hms_value(text: str) -> float:
    """"HH:MM:SS" (두 자리씩, 시 0 ~ 47, 분과 초 0 ~ 59) → 운행일 0시부터의 초. 형식이 틀리면 ValueError."""
    match = _HMS_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"시각 {text!r} 는 HH:MM:SS 형식이 아닙니다")
    hours, minutes, seconds = (int(part) for part in match.groups())
    if hours >= 48:
        raise ValueError(f"시각 {text}: 시가 48 이상입니다")
    if minutes >= 60 or seconds >= 60:
        raise ValueError(f"시각 {text}: 분이나 초가 60 이상입니다")
    return float(hours * 3600 + minutes * 60 + seconds)


def _hms_text(seconds: float) -> str:
    """초 → "HH:MM:SS". 24시 이상도 그대로 적는다(자정을 넘긴 운행, §4.10)."""
    total = int(round(seconds))
    return f"{total // 3600:02d}:{total % 3600 // 60:02d}:{total % 60:02d}"


def _clock_label(seconds: float) -> str:
    """시계 시각(초, 하루를 넘으면 접는다) → 화면용 "HH:MM:SS"."""
    return _hms_text(seconds % SECONDS_PER_DAY)


def _line_and_direction(line_num: str, inout_tag: int) -> tuple[str, str]:
    """`LINE_NUM` ("02호선")과 방향 값 → ("2호선", "내선") (§4.10 응답 읽기의 5). 숫자가 없으면 문구 그대로 둔다."""
    digits = re.sub(r"\D", "", line_num)
    if not digits:
        return line_num.strip(), "상행" if inout_tag == 1 else "하행"
    number = int(digits)
    if number == 2:
        return "2호선", "내선" if inout_tag == 1 else "외선"
    return f"{number}호선", "상행" if inout_tag == 1 else "하행"


def _timetable_row_key(row: TimetableRow) -> tuple:
    """시각표 행의 순서 (요일 종류, 방향, 시각, 열차 번호). 시각은 도착, 없으면 출발이다(§4.10)."""
    first = row.arrive_s if row.arrive_s is not None else row.depart_s
    return (_DAY_ORDER[row.day_type], row.direction, first, row.train_no, row.depart_s if row.depart_s is not None else -1.0)


def _timetable_identity(row: TimetableRow) -> tuple:
    """같은 행을 가리는 키 (요일 종류, 방향, 열차 번호, 도착, 출발) (§4.10)."""
    return (row.day_type, row.direction, row.train_no, row.arrive_s, row.depart_s)


def _validation_reason(exc: ValueError) -> str:
    """pydantic 검증 오류는 첫 오류 문장만, 아니면 예외 문장 그대로."""
    if isinstance(exc, ValidationError):
        errors = exc.errors()
        if errors:
            return str(errors[0].get("msg", exc)).removeprefix("Value error, ")
    return str(exc)


def parse_timetable_payload(
    payload: dict, week_tag: int | str, inout_tag: int | str, config: EngineConfig
) -> tuple[list[TimetableRow], dict[str, int]]:
    """OA-101 응답 하나(요일 값과 방향 값으로 요청한 묶음) → (행 목록(응답 순서), 사유별 수) (§4.10 응답 읽기).

    사유는 "건너뜀" (열차 번호 없음, 시각 형식 틀림, 도착과 출발 모두 없음)과 "급행 미확인" (`EXPRESS_YN` 이 D, G, 빈 값이
    아님) 두 가지다. 같은 (요일 종류, 방향, 열차 번호, 도착, 출발) 행이 다시 오면 하나만 남기고 세지 않는다.
    """
    week = int(week_tag)
    inout = int(inout_tag)
    if week not in _WEEK_TAGS:
        raise ValueError(f"요일 값 {week_tag} 는 1, 2, 3 가운데 하나여야 합니다")
    if inout not in (1, 2):
        raise ValueError(f"방향 값 {inout_tag} 는 1, 2 가운데 하나여야 합니다")
    day_type = _WEEK_TAGS[week]
    spec = API_SPECS["subway_timetable"]
    fields = spec.fields
    counts = {TIMETABLE_SKIPPED: 0, TIMETABLE_EXPRESS_UNKNOWN: 0}
    rows: list[TimetableRow] = []
    seen: set[tuple] = set()

    def read_time(value: Any) -> float | None:
        text = _text(value)
        if text is None or text == _NO_TIME:
            return None
        seconds = _hms_value(text)
        return seconds + SECONDS_PER_DAY if seconds < config.timetable_day_start_s else seconds

    for item in _items(payload, spec.items_path):
        train_no = _text(item.get(fields["train_no"]))
        try:
            arrive = read_time(item.get(fields["arrive"]))
            depart = read_time(item.get(fields["depart"]))
        except ValueError:
            counts[TIMETABLE_SKIPPED] += 1
            continue
        if not train_no or (arrive is None and depart is None):
            counts[TIMETABLE_SKIPPED] += 1
            continue
        line, direction = _line_and_direction(_text(item.get(fields["line"])) or "", inout)
        code = (_text(item.get(fields["express"])) or "").upper()
        try:
            row = TimetableRow(
                line=line,
                station=_text(item.get(fields["station_nm"])) or "",
                direction=direction,
                day_type=day_type,
                train_no=train_no,
                arrive_s=arrive,
                depart_s=depart,
                destination=_text(item.get(fields["destination"])) or "",
                express=_EXPRESS_CODES.get(code, False),
            )
        except ValueError:
            counts[TIMETABLE_SKIPPED] += 1
            continue
        identity = _timetable_identity(row)
        if identity in seen:
            continue
        seen.add(identity)
        if code not in _EXPRESS_CODES:
            counts[TIMETABLE_EXPRESS_UNKNOWN] += 1
        rows.append(row)
    return rows, counts


@dataclass(frozen=True)
class TimetableFetch:
    """`fetch_timetable` 의 자세한 결과: 시각표(못 만들면 None), 호출 결과, 사유별 수, 못 만든 이유."""

    timetable: Timetable | None
    results: tuple[ApiCallResult, ...]
    counts: dict[str, int]
    reason: str


def _fetch_timetable(station_cd: str, config: EngineConfig, client: httpx.Client | None) -> TimetableFetch:
    """요일 3 × 방향 2 = 6 묶음을 (1, 1), (1, 2), …, (3, 2) 순으로 받는다(§4.10). 실패하거나 키가 없으면 거기서 멈춘다."""
    results: list[ApiCallResult] = []
    counts = {TIMETABLE_SKIPPED: 0, TIMETABLE_EXPRESS_UNKNOWN: 0}
    rows: list[TimetableRow] = []
    seen: set[tuple] = set()
    for week in sorted(_WEEK_TAGS):
        for inout in (1, 2):
            _, calls = fetch_pages(client, "subway_timetable", {"station_cd": station_cd, "week_tag": week, "inout_tag": inout}, config)
            results.extend(calls)
            failed = next((call for call in calls if call.state != SourceState.SUCCESS), None)
            if failed is not None:
                reason = "키 없음" if failed.state == SourceState.SKIPPED else f"요청 실패: {failed.reason}"
                return TimetableFetch(None, tuple(results), counts, reason)
            for call in calls:
                if call.no_data or call.payload is None:
                    continue
                page_rows, page_counts = parse_timetable_payload(call.payload, week, inout, config)
                for name, count in page_counts.items():
                    counts[name] += count
                for row in page_rows:
                    identity = _timetable_identity(row)
                    if identity not in seen:
                        seen.add(identity)
                        rows.append(row)
    if not rows:
        reason = NO_TIMETABLE_REASON if all(call.no_data for call in results) else "받은 행이 없습니다"
        return TimetableFetch(None, tuple(results), counts, reason)
    today = _kst(time.time()).date().isoformat()
    timetable = Timetable(
        station_key=station_cd,
        rows=tuple(sorted(rows, key=_timetable_row_key)),
        source=f"OA-101 응답 ({today})",
    )
    return TimetableFetch(timetable, tuple(results), counts, "")


def fetch_timetable(
    station_cd: str, config: EngineConfig, client: httpx.Client | None = None
) -> tuple[Timetable | None, tuple[ApiCallResult, ...]]:
    """역 하나의 시각표를 받는다(§4.10). 키가 없으면 요청하지 않고(SKIPPED), 실패한 요청이 있거나 행이 없으면 None 이다."""
    fetched = _fetch_timetable(station_cd, config, client)
    return fetched.timetable, fetched.results


def write_timetable_csv(timetable: Timetable, path: str | os.PathLike) -> None:
    """시각표를 CSV 로 쓴다(§4.10 의 형식, UTF-8, 머리글 한 줄, (요일 종류, 방향, 시각, 열차 번호) 순)."""
    target = pathlib.Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    with target.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.writer(handle, lineterminator="\n")
        writer.writerow(TIMETABLE_COLUMNS)
        for row in sorted(timetable.rows, key=_timetable_row_key):
            writer.writerow(
                (
                    row.line,
                    row.station,
                    row.direction,
                    row.day_type.value,
                    row.train_no,
                    "" if row.arrive_s is None else _hms_text(row.arrive_s),
                    "" if row.depart_s is None else _hms_text(row.depart_s),
                    row.destination,
                    "1" if row.express else "0",
                )
            )


def _csv_rows(path: pathlib.Path, columns: tuple[str, ...]) -> Iterator[tuple[int, dict[str, str]]]:
    """머리글을 확인하고 (줄 번호, {열: 값}) 을 차례로 준다. 빈 줄은 건너뛴다. 틀리면 ValueError (줄 번호 포함)."""
    with path.open(encoding="utf-8-sig", newline="") as handle:
        reader = csv.reader(handle)
        header = next(reader, None)
        if header is None or tuple(cell.strip() for cell in header) != columns:
            raise ValueError(f"{path.name} 1번째 줄: 머리글은 {','.join(columns)} 이어야 합니다")
        for record in reader:
            number = reader.line_num
            if not any(cell.strip() for cell in record):
                continue
            if len(record) != len(columns):
                raise ValueError(f"{path.name} {number}번째 줄: 칸이 {len(record)}개입니다({len(columns)}개여야 합니다)")
            yield number, {name: cell.strip() for name, cell in zip(columns, record)}


def load_timetable(path: str | os.PathLike) -> Timetable:
    """시각표 CSV 를 읽는다(§4.10). 열 이름, 시각 형식, 빈 필수 칸, 두 시각 모두 빔, 같은 행이 있으면 ValueError (줄 번호와 이유)."""
    source = pathlib.Path(path)
    rows: list[TimetableRow] = []
    seen: dict[tuple, int] = {}
    for number, values in _csv_rows(source, TIMETABLE_COLUMNS):
        where = f"{source.name} {number}번째 줄"
        for name in ("line", "direction", "day_type", "train_no", "express"):
            if not values[name]:
                raise ValueError(f"{where}: {name} 칸이 비었습니다")
        try:
            day_type = DayType(values["day_type"])
        except ValueError:
            raise ValueError(f"{where}: 요일 종류 {values['day_type']!r} 를 모릅니다(WEEKDAY, SATURDAY, HOLIDAY)") from None
        times: dict[str, float | None] = {}
        for name in ("arrive", "depart"):
            try:
                times[name] = _hms_value(values[name]) if values[name] else None
            except ValueError as exc:
                raise ValueError(f"{where}: {name} {exc}") from None
        if times["arrive"] is None and times["depart"] is None:
            raise ValueError(f"{where}: 도착과 출발이 모두 비었습니다")
        if values["express"] not in ("0", "1"):
            raise ValueError(f"{where}: express 는 0 이나 1 이어야 합니다(지금 {values['express']!r})")
        try:
            row = TimetableRow(
                line=values["line"],
                station=values["station"],
                direction=values["direction"],
                day_type=day_type,
                train_no=values["train_no"],
                arrive_s=times["arrive"],
                depart_s=times["depart"],
                destination=values["destination"],
                express=values["express"] == "1",
            )
        except ValueError as exc:
            raise ValueError(f"{where}: {_validation_reason(exc)}") from None
        identity = _timetable_identity(row)
        if identity in seen:
            raise ValueError(f"{where}: {seen[identity]}번째 줄과 같은 행입니다")
        seen[identity] = number
        rows.append(row)
    if not rows:
        raise ValueError(f"{source.name}: 행이 없습니다")
    modified = _kst(source.stat().st_mtime).date().isoformat()
    return Timetable(
        station_key=source.stem,
        rows=tuple(sorted(rows, key=_timetable_row_key)),
        source=f"{source.name} (수정 {modified})",
    )


def timetable_summary(timetable: Timetable) -> list[str]:
    """`--fetch-timetable`, `--check-timetable` 의 요약 줄: 요일 종류·방향별 열차 수, 첫·마지막 시각(§3.7)."""
    groups: dict[tuple[DayType, str], set[str]] = {}
    for row in timetable.rows:
        groups.setdefault((row.day_type, row.direction), set()).add(row.train_no)
    firsts = [min(value for value in (row.arrive_s, row.depart_s) if value is not None) for row in timetable.rows]
    lasts = [max(value for value in (row.arrive_s, row.depart_s) if value is not None) for row in timetable.rows]
    lines = [
        f"{day_type.value} {direction} {len(trains):,}대"
        for (day_type, direction), trains in sorted(groups.items(), key=lambda item: (_DAY_ORDER[item[0][0]], item[0][1]))
    ]
    lines.append(f"첫 시각 {_hms_text(min(firsts))}, 마지막 시각 {_hms_text(max(lasts))}")
    return lines


# --- 지하철 역간 거리표와 정차 패턴 (§4.10, §1.7.2) ---


def load_subway_distances(path: str | os.PathLike) -> dict[tuple[str, str, str], float]:
    """역간 거리표 CSV → {(호선, 앞 역 키, 뒤 역 키): 거리 km} (파일의 값 그대로, §4.10).

    방향과 상관없이 같은 거리로 보므로 같은 호선의 같은 두 역(순서 무관)이 두 번 나오면 ValueError 다.
    """
    source = pathlib.Path(path)
    table: dict[tuple[str, str, str], float] = {}
    pairs: dict[tuple[str, frozenset[str]], int] = {}
    for number, values in _csv_rows(source, DISTANCE_COLUMNS):
        where = f"{source.name} {number}번째 줄"
        for name in DISTANCE_COLUMNS:
            if not values[name]:
                raise ValueError(f"{where}: {name} 칸이 비었습니다")
        if values["from_station_key"] == values["to_station_key"]:
            raise ValueError(f"{where}: 앞 역과 뒤 역이 같습니다")
        try:
            km = float(values["distance_km"])
        except ValueError:
            raise ValueError(f"{where}: distance_km {values['distance_km']!r} 는 수가 아닙니다") from None
        if not math.isfinite(km) or km <= 0:
            raise ValueError(f"{where}: distance_km 는 0 보다 커야 합니다")
        pair = (values["line"], frozenset((values["from_station_key"], values["to_station_key"])))
        if pair in pairs:
            raise ValueError(f"{where}: {pairs[pair]}번째 줄과 같은 구간입니다(방향과 상관없이 하나만 둡니다)")
        pairs[pair] = number
        table[(values["line"], values["from_station_key"], values["to_station_key"])] = km
    return table


def _line_distance_km(distances: dict[tuple[str, str, str], float], line: str, a: str, b: str) -> float | None:
    """그 호선의 거리표 행을 방향 없는 그래프로 보고 두 역 사이의 최단 합(km). 이어지지 않으면 None (§1.7.2 의 7)."""
    graph: dict[str, list[tuple[str, float]]] = {}
    for (row_line, start, end), km in sorted(distances.items()):
        if row_line != line:
            continue
        graph.setdefault(start, []).append((end, km))
        graph.setdefault(end, []).append((start, km))
    if a not in graph or b not in graph:
        return None
    best = {a: 0.0}
    heap = [(0.0, a)]
    while heap:
        km, node = heapq.heappop(heap)
        if node == b:
            return km
        if km > best.get(node, math.inf):
            continue
        for neighbor, step in graph[node]:
            candidate = km + step
            if candidate < best.get(neighbor, math.inf):
                best[neighbor] = candidate
                heapq.heappush(heap, (candidate, neighbor))
    return None


def _timetable_station_index(scenario: Scenario) -> dict[tuple[str, str], tuple[str, str]]:
    """(시각표 역 키, 호선) → (시나리오 역 키, 승강장 노드 ID). 역 키는 `SubwayStation.key` 이거나, 환승역처럼 그 호선의
    역코드가 다르면 `line_keys` 에 적은 역코드다(§1.7.2 의 1)."""
    index: dict[tuple[str, str], tuple[str, str]] = {}
    for station in scenario.subway_stations:
        for line, platform_id in station.platforms:
            index[(station.line_key(line), line)] = (station.key, platform_id)
    return index


@dataclass
class _TrainRows:
    """한 열차로 묶을 시각표 행들: (시나리오 역 키, 승강장, arr t, dep t) 와 열차 정보."""

    line: str
    direction: str
    previous_day: bool
    train_no: str
    service_day: DayType
    express: bool
    destination: str
    stops: list[tuple[str, str, float, float]]


def build_subway_patterns(
    timetables: Sequence[Timetable],
    scenario: Scenario,
    distances: dict[tuple[str, str, str], float],
    clock_s: float,
    day_type: DayType,
    prev_day_type: DayType,
    config: EngineConfig,
) -> tuple[tuple[SubwayPattern, ...], tuple[EngineWarning, ...]]:
    """시각표로 정차 패턴과 열차를 만든다(§1.7.2 의 1 ~ 7). 역과 승강장 좌표는 `scenario` 에서 읽는다.

    경고는 역 거르기(`TIMETABLE_STATION_UNUSED`, (역 키, 호선) 순), 그다음 패턴 ID 순으로 패턴마다 추월 고침
    (`TIMETABLE_OVERTAKE`)과 직선거리 구간(`UNVERIFIED_DISTANCE`)이다.
    """
    station_index = _timetable_station_index(scenario)
    nodes = _node_index(scenario)
    warnings: list[EngineWarning] = []
    unused: set[tuple[str, str]] = set()
    groups: dict[tuple[str, str, bool, str], _TrainRows] = {}
    for timetable in sorted(timetables, key=lambda item: item.station_key):
        for row in timetable.rows:
            found = station_index.get((timetable.station_key, row.line))
            if found is None:
                unused.add((timetable.station_key, row.line))
                continue
            station_key, platform_id = found
            choices: list[tuple[bool, float]] = []
            if row.day_type == day_type:
                choices.append((False, 0.0))
            if row.day_type == prev_day_type and any(
                value is not None and value >= SECONDS_PER_DAY for value in (row.arrive_s, row.depart_s)
            ):
                choices.append((True, -SECONDS_PER_DAY))
            for previous_day, shift in choices:
                arrive = row.arrive_s if row.arrive_s is not None else row.depart_s
                depart = row.depart_s if row.depart_s is not None else row.arrive_s
                key = (row.line, row.direction, previous_day, row.train_no)
                group = groups.get(key)
                if group is None:
                    group = groups[key] = _TrainRows(
                        line=row.line,
                        direction=row.direction,
                        previous_day=previous_day,
                        train_no=row.train_no,
                        service_day=prev_day_type if previous_day else day_type,
                        express=row.express,
                        destination=row.destination,
                        stops=[],
                    )
                group.express = group.express or row.express
                group.stops.append((station_key, platform_id, arrive + shift - clock_s, depart + shift - clock_s))
    for station_key, line in sorted(unused):
        warnings.append(
            EngineWarning(
                code=WarningCode.TIMETABLE_STATION_UNUSED,
                message=f"시각표의 역 {station_key} ({line}) 이 시나리오의 역에 없어 쓰지 않았습니다",
                ref_ids=(station_key, line),
            )
        )
    # 2 ~ 4: 묶음을 (호선, 방향, 운행일, 열차 번호) 순으로 처리하고, 같은 역이 다시 나오면 나눈다. 범위 밖 열차는 버린다.
    trains: list[tuple[str, str, tuple[str, ...], tuple[str, ...], SubwayTrip]] = []
    for key in sorted(groups, key=lambda item: (item[0], item[1], not item[2], item[3])):
        group = groups[key]
        stops = sorted(group.stops, key=lambda stop: (stop[2], stop[3]))
        pieces: list[list[tuple[str, str, float, float]]] = [[]]
        for stop in stops:
            if any(stop[0] == earlier[0] for earlier in pieces[-1]):
                pieces.append([])
            pieces[-1].append(stop)
        base_id = group.train_no + (_PREVIOUS_DAY if group.previous_day else "")
        for number, piece in enumerate(pieces, start=1):
            if len(piece) < 2:
                continue  # 한 역만 남은 조각은 탈 수도 내릴 수도 없다
            values = [value for stop in piece for value in (stop[2], stop[3])]
            if max(values) < 0 or min(values) > config.horizon_s:
                continue
            trip = SubwayTrip(
                id=base_id if number == 1 else f"{base_id}~{number}",
                train_no=group.train_no,
                service_day=group.service_day,
                arr_s=tuple(stop[2] for stop in piece),
                dep_s=tuple(stop[3] for stop in piece),
                express=group.express,
                destination=group.destination,
            )
            trains.append((group.line, group.direction, tuple(stop[0] for stop in piece), tuple(stop[1] for stop in piece), trip))
    # 5: (호선, 방향, 역 키 튜플)로 패턴을 묶고 ID 를 정한다. 같은 ID 는 역 키 튜플의 사전순으로 #2, #3.
    patterns_by_key: dict[tuple[str, str, tuple[str, ...]], tuple[tuple[str, ...], list[SubwayTrip]]] = {}
    for line, direction, keys, platforms, trip in trains:
        entry = patterns_by_key.setdefault((line, direction, keys), (platforms, []))
        entry[1].append(trip)
    base_ids: dict[str, list[tuple[str, str, tuple[str, ...]]]] = {}
    for line, direction, keys in patterns_by_key:
        base_ids.setdefault(f"{line}:{direction}:{keys[0]}-{keys[-1]}:{len(keys)}", []).append((line, direction, keys))
    named: list[tuple[str, tuple[str, str, tuple[str, ...]]]] = []
    for base_id, members in base_ids.items():
        for rank, member in enumerate(sorted(members, key=lambda item: item[2]), start=1):
            named.append((base_id if rank == 1 else f"{base_id}#{rank}", member))
    patterns: list[SubwayPattern] = []
    for pattern_id, (line, direction, keys) in sorted(named):
        platforms, pattern_trips_list = patterns_by_key[(line, direction, keys)]
        ordered, overtakes = _remove_timetable_overtakes(pattern_id, pattern_trips_list)
        warnings.extend(overtakes)
        lengths: list[float] = []
        verified: list[bool] = []
        for a, b, pa, pb in zip(keys, keys[1:], platforms, platforms[1:]):
            km = _line_distance_km(distances, line, a, b)
            if km is not None:
                lengths.append(round(km * 1000.0, 3))
                verified.append(True)
                continue
            straight = haversine_m(_latlon(nodes[pa]), _latlon(nodes[pb]), config.earth_radius_m)
            lengths.append(round(max(straight, 1.0), 3))
            verified.append(False)
            warnings.append(
                EngineWarning(
                    code=WarningCode.UNVERIFIED_DISTANCE,
                    message=f"패턴 {pattern_id} 의 {a} → {b} 구간이 역간 거리표에 없어 승강장 직선거리 {straight:,.1f} m 로 둡니다",
                    ref_ids=(pattern_id, a, b),
                )
            )
        patterns.append(
            SubwayPattern(
                id=pattern_id,
                line=line,
                direction=direction,
                station_keys=keys,
                platform_ids=platforms,
                segment_dist_m=tuple(lengths),
                distance_verified=tuple(verified),
                trips=tuple(ordered),
            )
        )
    return tuple(patterns), tuple(warnings)


def _remove_timetable_overtakes(pattern_id: str, trips: Sequence[SubwayTrip]) -> tuple[list[SubwayTrip], list[EngineWarning]]:
    """패턴 안의 열차를 (첫 순번 dep, 열차 ID) 순으로 두고, 뒤 열차의 dep·arr 가 바로 앞 열차의 같은 순번 값보다 작으면
    앞 열차의 값으로 올린다(§1.7.2 의 6). 고친 열차마다 `TIMETABLE_OVERTAKE` (패턴, 열차)를 남기고 문장에 고친 순번 수를 적는다."""
    ordered = sorted(trips, key=lambda trip: (trip.dep_s[0], trip.id))
    fixed: list[SubwayTrip] = []
    warnings: list[EngineWarning] = []
    for trip in ordered:
        if not fixed:
            fixed.append(trip)
            continue
        previous = fixed[-1]
        arr = list(trip.arr_s)
        dep = list(trip.dep_s)
        changed = 0
        for index in range(len(arr)):
            raised = False
            if arr[index] < previous.arr_s[index]:
                arr[index] = previous.arr_s[index]
                raised = True
            if dep[index] < previous.dep_s[index]:
                dep[index] = previous.dep_s[index]
                raised = True
            changed += raised
        if changed:
            trip = trip.model_copy(update={"arr_s": tuple(arr), "dep_s": tuple(dep)})
            warnings.append(
                EngineWarning(
                    code=WarningCode.TIMETABLE_OVERTAKE,
                    message=f"패턴 {pattern_id} 열차 {trip.id}: 앞 열차보다 이른 {changed}개 순번을 앞 열차 시각으로 올렸습니다",
                    ref_ids=(pattern_id, trip.id),
                )
            )
        fixed.append(trip)
    return fixed, warnings


def train_candidates(scenario: Scenario, station_key: str, config: EngineConfig) -> tuple[TrainChoice, ...]:
    """"지금 탄 열차" 후보(§4.10): 그 역(다음에 설 역)을 지나는 패턴의 열차 가운데 그 역 도착이 0 이상
    `train_lookahead_s` 이하인 열차를 (도착 시각, 방향, 열차 번호) 순으로."""
    choices: list[TrainChoice] = []
    for pattern in scenario.subway_patterns:
        for index, key in enumerate(pattern.station_keys):
            if key != station_key:
                continue
            for trip in pattern.trips:
                arrive = float(trip.arr_s[index])
                if not 0.0 <= arrive <= config.train_lookahead_s:
                    continue
                choices.append(
                    TrainChoice(
                        station_key=station_key,
                        pattern_id=pattern.id,
                        trip_id=trip.id,
                        index=index,
                        train_no=trip.train_no,
                        line=pattern.line,
                        direction=pattern.direction,
                        destination=trip.destination,
                        express=trip.express,
                        arrive_s=arrive,
                        clock_label=_clock_label(scenario.clock_s + arrive),
                    )
                )
    choices.sort(key=lambda choice: (choice.arrive_s, choice.direction, choice.train_no, choice.pattern_id, choice.trip_id))
    return tuple(choices)


# --- 시나리오 JSON 저장과 읽기 (§4.9) ---


def save_scenario_json(scenario: Scenario, path: str | os.PathLike) -> None:
    """시나리오를 JSON 으로 저장한다(UTF-8, 들여쓰기 2). 폴더가 없으면 만든다."""
    target = pathlib.Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(scenario.model_dump_json(indent=2), encoding="utf-8")


def load_scenario_json(path: str | os.PathLike) -> Scenario:
    """시나리오 JSON 을 읽어 검증한다. 검증에 실패하면 pydantic 의 ValidationError (ValueError)."""
    return Scenario.model_validate_json(pathlib.Path(path).read_text(encoding="utf-8"))


# --- 시나리오 생성기 (§4.9) ---

_OSM_HIGHWAYS = frozenset({"footway", "pedestrian", "path", "steps", "living_street", "residential", "service",
                           "unclassified", "tertiary", "secondary", "primary", "cycleway", "track"})
_OSM_ROADS = frozenset({"residential", "living_street", "service", "unclassified", "tertiary", "secondary", "primary"})
_OSM_WALKWAYS = frozenset({"footway", "pedestrian", "path"})
_OSM_ALLEYS = frozenset({"residential", "living_street", "service"})
_SPEC_SOURCE = "생성 명세"
_STATION_GUESS = "역 좌표로 둠"


@dataclass
class _OsmWay:
    way_id: str
    refs: list[str]
    tags: dict[str, str]


@dataclass
class ScenarioBuildReport:
    """생성기의 결과와 생성 보고(§4.9 의 10). `scenario` 가 None 이면 `error` 가 저장하지 않은 이유다."""

    scenario: Scenario | None = None
    error: str = ""
    unconnected: list[tuple[str, float | None]] = field(default_factory=list)
    missing_timetables: list[str] = field(default_factory=list)
    skipped_routes: list[str] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)
    warnings: tuple[EngineWarning, ...] = ()
    elapsed_s: float = 0.0

    def lines(self) -> list[str]:
        out: list[str] = []
        scenario = self.scenario
        if scenario is not None:
            kinds = Counter(node.node_type for node in scenario.nodes)
            osm = sum(1 for node in scenario.nodes if node.source.startswith("OpenStreetMap"))
            inside = kinds[NodeType.SUBWAY_PLATFORM] + kinds[NodeType.STATION_HALL] + kinds[NodeType.STATION_EXIT]
            out.append(f"시나리오 {scenario.id} ({scenario.title})")
            out.append(
                f"  노드 {len(scenario.nodes):,} (OSM {osm:,}, 정류장 {kinds[NodeType.BUS_STOP]:,}, 승강장·대합실·출구 {inside:,}, "
                f"장소 {kinds[NodeType.PLACE]:,}), 엣지 {len(scenario.edges):,}, 신호 {len(scenario.signals):,}, "
                f"정류장 {kinds[NodeType.BUS_STOP]:,}, 버스 노선 {len(scenario.bus_lines):,}, 역 {len(scenario.subway_stations):,}, "
                f"정차 패턴 {len(scenario.subway_patterns):,}, 대여소 {len(scenario.bike_stations):,}"
            )
        if self.unconnected:
            items = ", ".join(f"({item_id}, {'-' if distance is None else f'{distance:,.2f} m'})" for item_id, distance in self.unconnected)
            out.append(f"  연결하지 못한 항목: {items}")
        else:
            out.append("  연결하지 못한 항목: 없음")
        if self.missing_timetables:
            out.append("  시각표 없는 역: " + ", ".join(f"{code}: 시각표 없음" for code in self.missing_timetables))
        if self.skipped_routes:
            out.append("  넣지 않은 노선: " + "; ".join(self.skipped_routes))
        for note in self.notes:
            out.append(f"  {note}")
        if self.warnings:
            counts = Counter(warning.code.value for warning in self.warnings)
            out.append("  패턴 경고: " + ", ".join(f"{code} {count}건" for code, count in sorted(counts.items())))
        out.append(f"  걸린 시간 {self.elapsed_s:.2f}초")
        return out


def _osm_id_key(value: str) -> tuple[int, int | str]:
    try:
        return (0, int(value))
    except ValueError:
        return (1, value)


def _read_osm(path: pathlib.Path) -> tuple[dict[str, tuple[float, float, dict[str, str]]], list[_OsmWay]]:
    """OSM XML → (노드 {ID: (위도, 경도, 태그)}, 길 목록). 지운 표시(`action="delete"`, `visible="false"`)는 건너뛴다."""
    nodes: dict[str, tuple[float, float, dict[str, str]]] = {}
    ways: list[_OsmWay] = []
    try:
        for _, element in ET.iterparse(path, events=("end",)):
            if element.tag not in ("node", "way"):
                continue
            deleted = element.get("action") == "delete" or element.get("visible") == "false"
            element_id = element.get("id")
            tags = {tag.get("k"): tag.get("v") or "" for tag in element.findall("tag") if tag.get("k")}
            if not deleted and element_id:
                if element.tag == "node":
                    try:
                        nodes[element_id] = (float(element.get("lat")), float(element.get("lon")), tags)
                    except (TypeError, ValueError):
                        raise ValueError(f"{path.name}: OSM 노드 {element_id} 의 좌표를 읽을 수 없습니다") from None
                else:
                    ways.append(_OsmWay(element_id, [nd.get("ref") for nd in element.findall("nd") if nd.get("ref")], tags))
            element.clear()
    except ET.ParseError as exc:
        raise ValueError(f"{path.name}: OSM XML 을 읽을 수 없습니다: {exc}") from None
    return nodes, sorted(ways, key=lambda way: _osm_id_key(way.way_id))


def _osm_modes(tags: dict[str, str]) -> tuple[Mode, ...]:
    """길의 통행 수단 (WALK, BIKE) 순(§4.9 의 6). 쓰지 않는 길은 빈 튜플."""
    highway = tags.get("highway")
    if highway not in _OSM_HIGHWAYS or tags.get("access") in ("private", "no"):
        return ()
    walk = tags.get("foot") != "no"
    bicycle = tags.get("bicycle")
    if highway == "steps" or bicycle == "no":
        bike = False
    elif bicycle in ("yes", "designated"):
        bike = True
    else:
        bike = highway in ("cycleway", "track", "path") or highway in _OSM_ROADS
    return tuple(mode for mode, ok in ((Mode.WALK, walk), (Mode.BIKE, bike)) if ok)


def _osm_edge_kind(tags: dict[str, str]) -> EdgeKind:
    highway = tags.get("highway")
    if highway == "steps":
        return EdgeKind.STAIRS
    if tags.get("footway") == "crossing" or "crossing" in tags:
        return EdgeKind.CROSSWALK
    if highway in _OSM_WALKWAYS and tags.get("tunnel") == "yes":
        return EdgeKind.UNDERPASS
    if highway in _OSM_WALKWAYS and tags.get("bridge") == "yes":
        return EdgeKind.OVERPASS
    if highway == "cycleway":
        return EdgeKind.BIKE_LANE
    if highway in _OSM_ALLEYS:
        return EdgeKind.ALLEY
    return EdgeKind.SIDEWALK


def _osm_is_signal(tags: dict[str, str]) -> bool:
    return (tags.get("highway") == "traffic_signals" or tags.get("crossing") == "traffic_signals"
            or tags.get("crossing:signals") == "yes")


def _in_bbox(spec: ScenarioBuildSpec, lat: float | None, lon: float | None) -> bool:
    south, west, north, east = spec.bbox
    return lat is not None and lon is not None and south <= lat <= north and west <= lon <= east


def _osm_network(
    spec: ScenarioBuildSpec, osm_path: pathlib.Path
) -> tuple[list[Node], list[Edge], list[SignalPhase]]:
    """§4.9 의 1, 6, 7: 범위 안 OSM 노드로 보행망·자전거망 노드와 엣지, 설계 신호를 만든다."""
    osm_nodes, ways = _read_osm(osm_path)
    source = f"OpenStreetMap ({osm_path.name})"

    def inside(ref: str) -> bool:
        node = osm_nodes.get(ref)
        return node is not None and _in_bbox(spec, node[0], node[1])

    used: list[tuple[_OsmWay, tuple[Mode, ...], EdgeKind, list[list[str]]]] = []
    uses: Counter[str] = Counter()
    ends: set[str] = set()
    for way in ways:
        modes = _osm_modes(way.tags)
        if not modes:
            continue
        pieces: list[list[str]] = []
        current: list[str] = []
        for ref in way.refs:
            if inside(ref):
                current.append(ref)
                continue
            if len(current) >= 2:
                pieces.append(current)
            current = []
        if len(current) >= 2:
            pieces.append(current)
        if not pieces:
            continue
        for piece in pieces:
            uses.update(piece)
            ends.update((piece[0], piece[-1]))
        used.append((way, modes, _osm_edge_kind(way.tags), pieces))
    kept = {ref for ref in uses if uses[ref] >= 2 or ref in ends or osm_nodes[ref][2]}
    edges: list[Edge] = []
    for way, modes, kind, pieces in used:
        number = 0
        for piece in pieces:
            start = piece[0]
            via: list[tuple[float, float]] = []
            for ref in piece[1:]:
                if ref not in kept:
                    via.append((osm_nodes[ref][0], osm_nodes[ref][1]))
                    continue
                if ref != start:  # 같은 노드로 돌아오는 고리는 길이 있는 이동이 아니다
                    number += 1
                    edges.append(Edge(id=f"w{way.way_id}-{number}", source=f"o{start}", target=f"o{ref}", modes=modes,
                                      kind=kind, via=tuple(via)))
                start = ref
                via = []
    endpoints = {node_id[1:] for edge in edges for node_id in (edge.source, edge.target)}
    nodes: list[Node] = []
    signal_nodes: set[str] = set()
    for ref in sorted(endpoints, key=_osm_id_key):
        lat, lon, tags = osm_nodes[ref]
        is_signal = _osm_is_signal(tags)
        if is_signal:
            signal_nodes.add(f"o{ref}")
        nodes.append(Node(id=f"o{ref}", name=tags.get("name") or f"OSM {ref}",
                          node_type=NodeType.INTERSECTION if is_signal else NodeType.WAYPOINT,
                          lat=lat, lon=lon, verified=True, source=source))
    mapping = {str(osm_id): (official, direction) for osm_id, official, direction in spec.signal_map}
    signals: list[SignalPhase] = []
    for index, edge in enumerate(edges):
        if edge.kind != EdgeKind.CROSSWALK:
            continue
        crossing = sorted(node_id for node_id in (edge.source, edge.target) if node_id in signal_nodes)
        if not crossing:
            continue
        official, direction = mapping.get(crossing[0][1:], (None, ""))
        phase = SignalPhase(id=f"sg-{edge.id}", intersection_id=crossing[0], direction=direction,
                            green_s=spec.design_green_s, red_s=spec.design_cycle_s - spec.design_green_s, offset_s=None,
                            realtime_open=False, official_id=official, source=SignalSource.DESIGN)
        signals.append(phase)
        edges[index] = Edge(**{**dict(edge), "signal_id": phase.id})
    return nodes, edges, signals


@dataclass(frozen=True)
class _RouteStop:
    seq: int
    st_id: str
    ars_id: str | None
    name: str
    lat: float
    lon: float


def _generated_bus_lines(
    spec: ScenarioBuildSpec, config: EngineConfig, client: httpx.Client | None, now: float, date_text: str,
    report: ScenarioBuildReport,
) -> tuple[list[Node], list[BusLine]]:
    """§4.9 의 2: 노선마다 정류장 목록과 도착 응답으로 범위 안 구간의 `BusLine` 과 정류장 노드를 만든다."""
    stops: dict[str, Node] = {}
    lines: list[BusLine] = []
    listing_spec = API_SPECS["route_stations"]
    arrival_spec = API_SPECS["bus_arrival_all"]
    for route_id in spec.route_ids:
        listing = api_call(client, "route_stations", {"busRouteId": route_id}, config)
        if listing.state != SourceState.SUCCESS:
            report.skipped_routes.append(f"노선 정보를 얻지 못함 ({route_id}): 정류장 목록 {listing.reason}")
            continue
        names = listing_spec.fields
        entries: list[_RouteStop] = []
        for item in [] if listing.no_data else _items(listing.payload, listing_spec.items_path):
            seq = _int(item.get(names["seq"]))
            st_id = _text(item.get(names["st_id"]))
            lat = _num(item.get(names["lat"]))
            lon = _num(item.get(names["lon"]))
            if seq is None or st_id is None or lat is None or lon is None:
                continue
            entries.append(_RouteStop(seq, st_id, _text(item.get(names["ars_id"])), _text(item.get(names["name"])) or st_id, lat, lon))
        arrival = api_call(client, "bus_arrival_all", {"busRouteId": route_id}, config)
        if arrival.state != SourceState.SUCCESS:
            report.skipped_routes.append(f"노선 정보를 얻지 못함 ({route_id}): 버스 도착 {arrival.reason}")
            continue
        rows = [] if arrival.no_data else _items(arrival.payload, arrival_spec.items_path)
        fields = arrival_spec.fields
        name = next((text for row in rows if (text := _text(row.get(fields["route_name"])))), None)
        code = next((text for row in rows if (text := _text(row.get(fields["route_type"])))), None)
        if name is None:
            report.skipped_routes.append(f"노선 정보를 얻지 못함 ({route_id}): 도착 응답에 노선 이름(rtNm)이 없습니다")
            continue
        if name.startswith(NIGHT_ROUTE_PREFIX):
            route_type = BusRouteType.NIGHT
        elif code in ROUTE_TYPE_CODES:
            route_type = ROUTE_TYPE_CODES[code]
        else:
            report.skipped_routes.append(f"범위 밖 노선 종류 ({route_id}, {code})")
            continue
        observations, _ = parse_arrival_payload(arrival.payload or {}) if not arrival.no_data else ([], 0)
        runs: list[list[_RouteStop]] = []
        current: list[_RouteStop] = []
        for entry in sorted(entries, key=lambda item: item.seq):
            if not _in_bbox(spec, entry.lat, entry.lon):
                current = []
                continue
            if current and entry.seq == current[-1].seq + 1:
                current.append(entry)
            else:
                current = [entry]
                runs.append(current)
        for run in (run for run in runs if len(run) >= 2):
            for entry in run:
                stops.setdefault(f"bs{entry.st_id}", Node(
                    id=f"bs{entry.st_id}", name=entry.name, node_type=NodeType.BUS_STOP, lat=entry.lat, lon=entry.lon,
                    verified=True, source=f"노선 정류장 목록 API ({date_text})", official_id=entry.ars_id,
                    official_st_id=entry.st_id))
            stop_ids = tuple(f"bs{entry.st_id}" for entry in run)
            draft = BusLine(
                id=f"{name}:{run[0].seq}", name=name, route_type=route_type, real_route=True, official_route_id=route_id,
                stop_ids=stop_ids, stop_ords=tuple(entry.seq for entry in run),
                segment_dist_m=tuple(max(haversine_m((a.lat, a.lon), (b.lat, b.lon), config.earth_radius_m), 1.0)
                                     for a, b in zip(run, run[1:])),
                predictions=tuple(() for _ in run),
            )
            predictions, headway, age = predictions_from_observations(
                draft, tuple(stops[stop_id] for stop_id in stop_ids), observations, now, now)
            lines.append(BusLine(**{**dict(draft), "predictions": predictions, "headway_s": headway, "prediction_age_s": age}))
    return list(stops.values()), lines


def _generated_stations(spec: ScenarioBuildSpec, config: EngineConfig) -> tuple[list[Node], list[Edge], list[SubwayStation]]:
    """§4.9 의 3: 역마다 승강장·대합실·출구 노드와 역 안 엣지. 적은 길이가 양 끝 직선거리보다 짧으면 ValueError."""
    nodes: list[Node] = []
    edges: list[Edge] = []
    stations: list[SubwayStation] = []
    for station in spec.stations:
        key = station.key
        first = station.lines[0]
        hall = Node(id=f"{key}-H", name=f"{station.name} 대합실", node_type=NodeType.STATION_HALL, lat=first.lat,
                    lon=first.lon, verified=False, source=_STATION_GUESS)
        platforms = {
            item.line: Node(id=f"{key}-P-{item.line}", name=f"{station.name} {item.line} 승강장",
                            node_type=NodeType.SUBWAY_PLATFORM, lat=item.lat, lon=item.lon, verified=False, source=_STATION_GUESS)
            for item in station.lines
        }
        exits = [Node(id=f"{key}-X{number}", name=item.name, node_type=NodeType.STATION_EXIT, lat=item.lat, lon=item.lon,
                      verified=True, source=_SPEC_SOURCE) for number, item in enumerate(station.exits, start=1)]
        nodes.extend([*platforms.values(), hall, *exits])

        def inner(edge_id: str, a: Node, b: Node, kind: EdgeKind, length: float) -> None:
            straight = haversine_m(_latlon(a), _latlon(b), config.earth_radius_m)
            if length < straight:
                raise ValueError(f"역 {key}: {edge_id} 의 길이 {length:g} m 가 양 끝 직선거리 {straight:.2f} m 보다 짧습니다")
            edges.append(Edge(id=edge_id, source=a.id, target=b.id, modes=(Mode.WALK,), kind=kind, distance_m=length))

        for item in station.lines:
            inner(f"{key}-S-{item.line}", platforms[item.line], hall, EdgeKind.STAIRS, item.stairs_m)
        for number, (item, exit_node) in enumerate(zip(station.exits, exits), start=1):
            inner(f"{key}-E{number}", hall, exit_node, EdgeKind.STATION_PASSAGE, item.passage_m)
        for transfer in station.transfers:
            a, b = transfer.lines
            inner(f"{key}-T-{a}-{b}", platforms[a], platforms[b], EdgeKind.STATION_PASSAGE, transfer.passage_m)
        stations.append(SubwayStation(
            key=key, name=station.name, platforms=tuple((item.line, platforms[item.line].id) for item in station.lines),
            hall_ids=(hall.id,), exit_ids=tuple(node.id for node in exits),
            line_keys=tuple((item.line, item.key) for item in station.lines if item.key and item.key != key)))
    return nodes, edges, stations


def _nearest_walk_node(
    point: tuple[float, float], candidates: Sequence[Node], config: EngineConfig
) -> tuple[str, float] | None:
    """가장 가까운 후보 노드(거리가 같으면 ID 순)와 거리."""
    best: tuple[float, str] | None = None
    for node in candidates:
        distance = haversine_m(point, _latlon(node), config.earth_radius_m)
        if best is None or (distance, node.id) < best:
            best = (distance, node.id)
    return None if best is None else (best[1], best[0])


def _walk_component(start: str, edges: Iterable[Edge]) -> set[str]:
    neighbors: dict[str, list[str]] = {}
    for edge in edges:
        if Mode.WALK not in edge.modes:
            continue
        neighbors.setdefault(edge.source, []).append(edge.target)
        if edge.bidirectional:
            neighbors.setdefault(edge.target, []).append(edge.source)
    seen = {start}
    stack = [start]
    while stack:
        for nxt in neighbors.get(stack.pop(), ()):
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    return seen


def _build_scenario(
    spec_path: str | os.PathLike, config: EngineConfig, client: httpx.Client | None = None, now: float | None = None
) -> ScenarioBuildReport:
    """§4.9 의 1 ~ 9. 저장은 하지 않는다(명령줄이 한다). 고칠 수 없는 문제는 `error` 에 담는다."""
    started = time.perf_counter()
    report = ScenarioBuildReport()
    try:
        source_path = pathlib.Path(spec_path)
        try:
            spec = ScenarioBuildSpec.model_validate_json(source_path.read_text(encoding="utf-8"))
        except ValidationError as exc:
            raise ValueError(f"{source_path.name}: 생성 명세가 틀렸습니다: {_validation_reason(exc)}") from None
        now_unix = time.time() if now is None else float(now)
        moment = _kst(now_unix)
        date_text = moment.date().isoformat()
        data_dir = _data_dir(config)
        osm_path = pathlib.Path(spec.osm_file)
        if not osm_path.is_absolute():
            osm_path = data_dir / osm_path
        if not osm_path.exists():
            raise ValueError(f"OSM 파일이 없습니다: {osm_path}")
        osm_nodes, edges, signals = _osm_network(spec, osm_path)
        stop_nodes, bus_lines = _generated_bus_lines(spec, config, client, now_unix, date_text, report)
        station_nodes, station_edges, stations = _generated_stations(spec, config)
        walk_ids = {node_id for edge in edges if Mode.WALK in edge.modes for node_id in (edge.source, edge.target)}
        walk_nodes = [node for node in osm_nodes if node.id in walk_ids]
        place_nodes = [Node(id=f"place{number}", name=item.name, node_type=NodeType.PLACE, lat=item.lat, lon=item.lon,
                            verified=True, source=_SPEC_SOURCE) for number, item in enumerate(spec.places, start=1)]
        connections: list[Edge] = []

        def connect(node: Node, radius: float, modes: tuple[Mode, ...]) -> bool:
            found = _nearest_walk_node(_latlon(node), walk_nodes, config)
            if found is None or found[1] > radius:
                report.unconnected.append((node.official_id if node.node_type == NodeType.BIKE_STATION else node.id,
                                           None if found is None else found[1]))
                return False
            connections.append(Edge(id=f"c-{node.id}", source=node.id, target=found[0], modes=modes, kind=EdgeKind.SIDEWALK))
            return True

        exits = [node for node in station_nodes if node.node_type == NodeType.STATION_EXIT]
        for node in [*stop_nodes, *exits, *place_nodes]:
            connect(node, config.stop_match_radius_m, (Mode.WALK,))
        bikes: list[BikeStation] = []
        rows, results = fetch_pages(client, "bike_list", {}, config)
        failed = next((result for result in results if result.state != SourceState.SUCCESS), None)
        if failed is not None:
            report.notes.append(f"따릉이 목록을 얻지 못함: {failed.reason}")
        else:
            observations, _ = _parse_bike_rows(rows)
            seen: set[str] = set()
            for obs in sorted(observations, key=lambda item: item.station_id):
                if obs.station_id in seen or not _in_bbox(spec, obs.lat, obs.lon):
                    continue
                seen.add(obs.station_id)
                station = BikeStation(
                    id=f"k{obs.station_id}", name=obs.station_name or obs.station_id, node_type=NodeType.BIKE_STATION,
                    lat=obs.lat, lon=obs.lon, verified=True, source=f"따릉이 실시간 대여정보 ({date_text})",
                    official_id=obs.station_id, bikes_available=obs.bikes, rack_total=obs.racks, rental_rate_per_hour=None)
                if connect(station, config.bike_match_radius_m, (Mode.WALK, Mode.BIKE)):
                    bikes.append(station)
        codes: list[str] = []
        for station in spec.stations:
            for item in station.lines:
                code = item.key or station.key
                if code not in codes:
                    codes.append(code)
        timetables: list[Timetable] = []
        for code in codes:
            path = data_dir / "timetables" / f"{code}.csv"
            if path.exists():
                timetables.append(load_timetable(path))
            else:
                report.missing_timetables.append(code)
        distances_path = data_dir / "subway_distances.csv"
        distances = load_subway_distances(distances_path) if distances_path.exists() else {}
        south, west, north, east = spec.bbox
        sources = [f"OpenStreetMap ({osm_path.name})", f"{_SPEC_SOURCE} ({source_path.name})"]
        if bus_lines:
            sources += [f"노선 정류장 목록 API ({date_text})", f"버스 도착 API ({moment.strftime('%Y-%m-%d %H:%M:%S')})",
                        "버스 구간 거리: 이웃 정류장의 직선거리(하한값)"]
        if bikes:
            sources.append(f"따릉이 실시간 대여정보 ({date_text})")
        sources += [timetable.source for timetable in timetables]
        try:
            scenario = Scenario(
                id=spec.id, title=spec.title, description=spec.description,
                nodes=tuple([*osm_nodes, *stop_nodes, *station_nodes, *place_nodes]), bike_stations=tuple(bikes),
                edges=tuple([*edges, *station_edges, *connections]), signals=tuple(signals), bus_lines=tuple(bus_lines),
                subway_stations=tuple(stations), subway_patterns=(),
                places=tuple(Place(name=node.name, node_id=node.id) for node in place_nodes),
                default_query=Query(origin=OriginState(kind=OriginKind.AT_NODE, node_id=place_nodes[0].id),
                                    destination_node_id=place_nodes[1].id),
                map_center=((south + north) / 2.0, (west + east) / 2.0), map_zoom=spec.map_zoom, sources=tuple(sources),
                simulated_time_note=(f"생성 명세의 기준 시각 {spec.clock} ({spec.day_type.value}). 버스 예측과 자전거 수는 "
                                     f"{moment.strftime('%Y-%m-%d %H:%M:%S')} 에 받은 값"),
                data_mode=DataMode.SIMULATION, clock_s=spec.clock_s, day_type=spec.day_type, bike_obs_age_s=0.0,
            )
            patterns, warnings = build_subway_patterns(timetables, scenario, distances, spec.clock_s, spec.day_type,
                                                       spec.day_type, config)
            scenario = Scenario(**{**dict(scenario), "subway_patterns": patterns})
        except ValidationError as exc:
            raise ValueError(f"시나리오 검증 실패: {_validation_reason(exc)}") from None
        report.warnings = warnings
        reach = _walk_component(place_nodes[0].id, scenario.edges)
        apart = [node for node in place_nodes[1:] if node.id not in reach]
        if apart:
            names = ", ".join(f"{node.name} ({node.id})" for node in apart)
            raise ValueError(f"첫 장소 {place_nodes[0].name} 와 보행망으로 이어지지 않는 장소가 있습니다: {names}")
        report.scenario = scenario
    except (OSError, ValueError) as exc:
        report.error = str(exc)
    report.elapsed_s = time.perf_counter() - started
    return report


def build_scenario_from_spec(
    spec_path: str | os.PathLike, config: EngineConfig, client: httpx.Client | None = None, now: float | None = None
) -> Scenario:
    """생성 명세로 시나리오를 만든다(§4.9). 만들 수 없으면 이유를 담은 ValueError. 저장은 `save_scenario_json` 이 한다."""
    report = _build_scenario(spec_path, config, client, now)
    if report.scenario is None:
        raise ValueError(report.error)
    return report.scenario


# --- 시나리오 A, B (§4.1 ~ §4.5) ---
#
# 좌표는 설계용 지역 좌표(기준점에서 큰길을 따라 s m, 가로질러 q m, 동쪽이 +)로 적고 위도·경도로 바꾼다.
# 확인한 좌표는 역 좌표 네 개(삼성, 봉은사, 강남, 신논현)뿐이고 승강장·대합실에만 "역 좌표로 둠"으로 쓴다.
# 나머지 노드는 모두 verified=False 이고 source 가 "미검증:" 으로 시작한다(§4.1). 조사 결과가 오면 표의
# 좌표와 출처만 바꾸고 동적 값을 다시 맞춘다(§10.7 절차 3).

_DEG_M = 111_194.93  # 위도 1도의 길이 (m), 지구 반지름 6,371 km


class _Frame:
    """설계용 지역 좌표. 기준점(위도, 경도)에서 큰길 북쪽 방향 단위 벡터 u 를 따라 s, 그 오른쪽(동쪽) p 를 따라 q."""

    def __init__(self, lat0: float, lon0: float, u: tuple[float, float]) -> None:
        norm = math.hypot(*u)
        self.lat0, self.lon0 = lat0, lon0
        self.u = (u[0] / norm, u[1] / norm)
        self.p = (self.u[1], -self.u[0])
        self.m_per_deg_lon = _DEG_M * math.cos(math.radians(lat0))

    def xy(self, s: float, q: float) -> tuple[float, float]:
        return (s * self.u[0] + q * self.p[0], s * self.u[1] + q * self.p[1])

    def latlon_xy(self, x: float, y: float) -> tuple[float, float]:
        return (round(self.lat0 + y / _DEG_M, 6), round(self.lon0 + x / self.m_per_deg_lon, 6))

    def latlon(self, s: float, q: float) -> tuple[float, float]:
        return self.latlon_xy(*self.xy(s, q))

    def sq_of(self, lat: float, lon: float) -> tuple[float, float]:
        x = (lon - self.lon0) * self.m_per_deg_lon
        y = (lat - self.lat0) * _DEG_M
        return (x * self.u[0] + y * self.u[1], x * self.p[0] + y * self.p[1])


_W = (Mode.WALK,)
_WB = (Mode.WALK, Mode.BIKE)
_STATION_COORD = "역 좌표로 둠"


def _nodes_from(frame: _Frame, rows: Sequence[tuple]) -> tuple[Node, ...]:
    """(ID, 이름, 종류, 위치, 출처, 공식 ID) 표를 노드로. 위치는 (s, q) 또는 ("ll", 위도, 경도)."""
    nodes = []
    for node_id, name, node_type, where, source, official in rows:
        lat, lon = (where[1], where[2]) if where[0] == "ll" else frame.latlon(*where)
        nodes.append(Node(id=node_id, name=name, node_type=node_type, lat=lat, lon=lon, verified=False, source=source, official_id=official))
    return tuple(nodes)


def _bike_from(frame: _Frame, rows: Sequence[tuple]) -> tuple[BikeStation, ...]:
    """(ID, 이름, (s, q), 자전거 수, 거치대 수, 시간당 대여, 출처) 표를 대여소로."""
    out = []
    for station_id, name, where, bikes, racks, rate, source in rows:
        lat, lon = frame.latlon(*where)
        out.append(
            BikeStation(
                id=station_id, name=name, node_type=NodeType.BIKE_STATION, lat=lat, lon=lon, verified=False, source=source,
                bikes_available=bikes, rack_total=racks, rental_rate_per_hour=rate,
            )
        )
    return tuple(out)


def _edges_from(rows: Sequence[tuple]) -> tuple[Edge, ...]:
    """(ID, 시작, 끝, 종류, 수단, 신호, 직접 길이) 표를 엣지로. 직접 길이는 역 안·지하도·육교·계단만(§4.1)."""
    return tuple(
        Edge(id=edge_id, source=a, target=b, modes=modes, kind=kind, signal_id=signal, distance_m=length)
        for edge_id, a, b, kind, modes, signal, length in rows
    )


def _prediction(item: tuple) -> StopPrediction:
    """(순위, 차량 ID, eta_s[, 막차]) → 예측 칸. eta_s 가 None 이면 "정보 없음"(NO_INFO), "ENDED" 면 "운행종료" 칸이다."""
    rank, vehicle, eta = item[0], item[1], item[2]
    if eta is None:
        return StopPrediction(rank=rank, vehicle_id=vehicle, kind=PredictionKind.NO_INFO, eta_s=None)
    if eta == "ENDED":
        return StopPrediction(rank=rank, vehicle_id=vehicle, kind=PredictionKind.ENDED, eta_s=None)
    return StopPrediction(rank=rank, vehicle_id=vehicle, kind=PredictionKind.NORMAL, eta_s=float(eta), is_last=len(item) > 3 and bool(item[3]))


def _predictions(rows: Sequence[Sequence[tuple]]) -> tuple[tuple[StopPrediction, ...], ...]:
    """순번마다 (순위, 차량 ID, eta_s[, 막차]) 표를 예측으로."""
    return tuple(tuple(_prediction(item) for item in row) for row in rows)


def _headway_trips(
    prefix: str, first_no: int, step_no: int, first_dep_s: float, headway_s: float, runs_s: Sequence[float], dwells_s: Sequence[float],
    destination: str, horizon_s: float, day: DayType = DayType.WEEKDAY,
) -> tuple[SubwayTrip, ...]:
    """배차대로 만든 열차(§4.1). 첫 역 출발이 [first_dep_s, horizon_s) 인 열차와, 그 앞에 이미 떠나 아직 달리는 열차.

    runs_s[i] 는 i → i+1 운행, dwells_s[i] 는 사이 역 i+1 의 정차. 첫 역은 도착 = 출발 − 30 s, 끝 역은 출발 = 도착 + 30 s 로
    적는다(시발·종착이 아니라 지나가는 역이라 시각이 둘 다 있다).
    """
    trips = []
    total = sum(runs_s) + sum(dwells_s)
    k = 0
    while first_dep_s - k * headway_s + total >= 0:  # 뒤로: 끝 역 도착이 0 이상인 열차까지
        k += 1
    start = first_dep_s - (k - 1) * headway_s
    n = 0
    while start + n * headway_s < horizon_s:
        dep0 = start + n * headway_s
        arr, dep = [dep0 - 30.0], [dep0]
        t = dep0
        for i, run in enumerate(runs_s):
            t += run
            arr.append(t)
            if i < len(dwells_s):
                t += dwells_s[i]
            else:
                t += 30.0
            dep.append(t)
        number = str(first_no + step_no * (n - (k - 1)))
        trips.append(SubwayTrip(id=f"{prefix}{number}", train_no=f"{prefix}{number}", service_day=day, arr_s=tuple(arr), dep_s=tuple(dep), destination=destination))
        n += 1
    return tuple(trips)


def _open_signal(signal_id: str, at: str, direction: str, green: float, cycle: float, offset: float) -> SignalPhase:
    """실시간 개방 고정 신호(§1.2). `offset` 은 $t = 0$ 의 위상 $\\theta$ 다."""
    return SignalPhase(id=signal_id, intersection_id=at, direction=direction, green_s=green, red_s=cycle - green, offset_s=offset, realtime_open=True)


def _sampled_signal(signal_id: str, at: str, direction: str, green: float, cycle: float) -> SignalPhase:
    """미개방 고정 신호(위상을 모름, §1.2 (2))."""
    return SignalPhase(id=signal_id, intersection_id=at, direction=direction, green_s=green, red_s=cycle - green, offset_s=None, realtime_open=False)


def _actuated_signal(signal_id: str, at: str, direction: str, green: float, samples: Sequence[float]) -> SignalPhase:
    """감응 신호(주기 표본, §1.2 (3)). 적색 시간 칸은 표본 중앙값 주기로 적는다(표시용)."""
    ordered = tuple(sorted(float(value) for value in samples))
    return SignalPhase(
        id=signal_id, intersection_id=at, direction=direction, green_s=green, red_s=statistics.median(ordered) - green,
        offset_s=None, realtime_open=False, actuated=True, gap_samples_s=ordered,
    )


