def scenario_a_query() -> Query:
    """A 의 기본 질의: 2호선 외선 열차 "2209" 안, 다음 역 삼성($j_0$ = 1), 이미 탄 거리 3.3 km → 청담역·경기고교 정류장 근처."""
    return Query(
        origin=OriginState(kind=OriginKind.ON_TRAIN, pattern_id=_A_PATTERN_2, trip_id="2209", next_index=1, prior_distance_m=3_300.0),
        destination_node_id="D",
    )


