_B_GANGNAM = ("ll", 37.4979278, 127.0275833)
_B_SINNONHYEON = ("ll", 37.50444, 127.024417)
_B_SINSA = ("ll", 37.516334, 127.020114)
_B_GYODAE = ("ll", 37.493415, 127.01408)
_B_EXPRESS = ("ll", 37.50481, 127.004943)
_B_JAMWON = ("ll", 37.512759, 127.01122)
_B_SAPYEONG = ("ll", 37.504206, 127.015259)
_B_YEOKSAM = ("ll", 37.500622, 127.036456)
# 중앙선이 꺾이는 점 (s, q): 신논현역(확인), 논현역 추정 좌표 37.511093, 127.021415, 신사역 추정 좌표
_B_BENDS = ((776.1, 0.0), (1561.7, 19.1), (2146.7, 121.8))
