def golden_query() -> Query:
    """골든의 기본 질의: 지점 출발 AT_NODE S → D, 마감 없음(§9.2)."""
    return Query(origin=OriginState(kind=OriginKind.AT_NODE, node_id="S"), destination_node_id="D")


def golden_bus_query() -> Query:
    """골든의 버스 질의: ON_BUS, 노선 G1, 차량 "G1:g1a", j0 = 1 (다음 정류장 B2), 이미 탄 거리 0 → D (§9.2)."""
    return Query(
        origin=OriginState(kind=OriginKind.ON_BUS, line_id="G1", trip_id="G1:g1a", next_index=1, prior_distance_m=0.0),
        destination_node_id="D",
    )


def golden_train_query() -> Query:
    """골든의 열차 질의: ON_TRAIN, 패턴 "가상선:하행:M1-M3:3", 열차 "1000", j0 = 1 (다음 역 M2) → D (§9.2)."""
    return Query(
        origin=OriginState(kind=OriginKind.ON_TRAIN, pattern_id=GOLDEN_PATTERN_ID, trip_id="1000", next_index=1),
        destination_node_id="D",
    )


def golden_last_vehicle_scenario() -> Scenario:
    """골든의 막차 변형: G2 의 g2a 예측 두 개(B4, B5)에 is_last = True 를 준다(§9.2)."""
    data = golden_scenario().model_dump()
    for line in data["bus_lines"]:
        if line["id"] == "G2":
            for items in line["predictions"]:
                for item in items:
                    if item["vehicle_id"] == "g2a":
                        item["is_last"] = True
    return Scenario.model_validate(data)


# --- 검사 틀 (§9.0) ---


def _short(value: Any, limit: int = 160) -> str:
    """검사 출력에 보일 값. 길면 앞부분만 보인다."""
    text = repr(value)
    return text if len(text) <= limit else f"{text[:limit]}… ({len(text):,}자)"


def _rounded(value: Any) -> Any:
    """검사 출력에 보일 값: 중첩된 튜플·리스트 안의 실수를 소수 여섯째 자리까지 줄이고, 열거형은 값으로 보인다."""
    if isinstance(value, (list, tuple)):
        return tuple(_rounded(item) for item in value)
    if isinstance(value, enum.Enum):
        return value.value
    if isinstance(value, (float, np.floating)):
        return round(float(value), 6)
    return value


def _approx_equal(expected: Any, actual: Any, tol: float) -> bool:
    """기대값과 실제값을 비교한다(§9.0). 기대값의 실수는 오차 tol 안, 정수·문자열·열거형·None 은 정확히 같아야 한다.

    튜플과 리스트는 길이가 같고 항목마다 같아야 한다. 정수 기대값(개수, 라운드 번호)은 실수 실제값과도 정확히 비교한다.
    """
    if isinstance(expected, (list, tuple)):
        if not isinstance(actual, (list, tuple)) or len(actual) != len(expected):
            return False
        return all(_approx_equal(item, other, tol) for item, other in zip(expected, actual))
    if isinstance(expected, float):
        if actual is None or isinstance(actual, (bool, str, enum.Enum)):
            return False
        try:
            return abs(float(actual) - expected) <= tol
        except (TypeError, ValueError):
            return False
    return expected == actual


class _Probe:
    """한 검사 항목 안의 비교들을 모은다. 첫 실패가 FAIL 줄의 사유가 된다."""

    def __init__(self) -> None:
        self.items: list[tuple[str, str, bool]] = []

    def check(self, label: str, ok: bool, detail: str) -> bool:
        self.items.append((label, detail, bool(ok)))
        return bool(ok)

    def eq(self, label: str, expected: Any, actual: Any) -> bool:
        return self.check(label, expected == actual, f"기대 {_short(expected)}, 실제 {_short(actual)}")

    def close(self, label: str, expected: float, actual: float | None, tol: float) -> bool:
        ok = actual is not None and abs(actual - expected) <= tol
        return self.check(label, ok, f"기대 {expected}, 실제 {actual} (오차 {tol:g})")

    def approx(self, label: str, expected: Any, actual: Any, tol: float = 0.01) -> bool:
        """중첩된 값을 비교한다. 실수는 tol 안(기본은 시간 0.01 s), 나머지는 정확히 같아야 한다."""
        ok = _approx_equal(expected, actual, tol)
        return self.check(label, ok, f"기대 {_short(_rounded(expected), 400)}, 실제 {_short(_rounded(actual), 400)}")

    def true(self, label: str, cond: bool, detail: str = "") -> bool:
        return self.check(label, cond, detail or ("참" if cond else "거짓"))

    def rejects(self, label: str, factory: Callable[[], Any]) -> bool:
        try:
            factory()
        except ValidationError as exc:
            first = exc.errors()[0]
            return self.check(label, True, f"거부됨 ({first.get('msg', '')})")
        except Exception as exc:  # noqa: BLE001 - 다른 예외도 실패 사유로 보인다
            return self.check(label, False, f"ValidationError 가 아닌 {type(exc).__name__}: {exc}")
        return self.check(label, False, "거부되지 않음")

    def accepts(self, label: str, factory: Callable[[], Any]) -> bool:
        try:
            factory()
        except ValidationError as exc:
            first = exc.errors()[0]
            return self.check(label, False, f"거부됨: {first.get('msg', '')}")
        return self.check(label, True, "허용됨")

    def raises(self, label: str, exc_type: type[BaseException], factory: Callable[[], Any]) -> bool:
        try:
            factory()
        except exc_type as exc:
            return self.check(label, True, f"{exc_type.__name__} ({_short(str(exc), 120)})")
        except Exception as exc:  # noqa: BLE001 - 다른 예외도 실패 사유로 보인다
            return self.check(label, False, f"{exc_type.__name__} 가 아닌 {type(exc).__name__}: {exc}")
        return self.check(label, False, f"{exc_type.__name__} 가 나지 않음")

    def first_failure(self) -> str | None:
        for label, detail, ok in self.items:
            if not ok:
                return f"{label}: {detail}"
        return None


@dataclass(frozen=True)
class _Check:
    code: str
    title: str
    func: Callable[[_Probe], None]


@dataclass
class _Outcome:
    code: str
    title: str
    ok: bool
    message: str
    items: list[tuple[str, str, bool]] = field(default_factory=list)


def _module_dir() -> pathlib.Path:
    return pathlib.Path(__file__).resolve().parent


def _validate(model: type, data: dict) -> Any:
    """딕셔너리를 다시 검증한다(한 곳씩 고친 객체의 검사, §9.3)."""
    return model.model_validate(data)


# --- M1 의존 규칙 (§3.1) ---

_THIRD_PARTY_ALLOWED: dict[str, frozenset[str]] = {
    "models_and_config.py": frozenset({"pydantic"}),
    "core_engine.py": frozenset({"pydantic", "httpx", "numpy", "models_and_config"}),
}
_CORE_FORBIDDEN = frozenset({"streamlit", "folium", "streamlit_folium", "pandas", "altair", "app"})


def _top_level_imports(path: pathlib.Path) -> list[str]:
    tree = ast.parse(path.read_text(encoding="utf-8"), filename=str(path))
    names: list[str] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            names.extend(alias.name.split(".")[0] for alias in node.names)
        elif isinstance(node, ast.ImportFrom):
            names.append("." if node.level else (node.module or "").split(".")[0])
    return names


def _m1(p: _Probe) -> None:
    stdlib = set(sys.stdlib_module_names)
    for file_name, allowed in _THIRD_PARTY_ALLOWED.items():
        path = _module_dir() / file_name
        if not path.exists():
            p.true(f"{file_name} 없음, 건너뜀", True)
            continue
        names = _top_level_imports(path)
        bad = sorted({name for name in names if name not in stdlib and name not in allowed})
        p.eq(f"{file_name} 의 허용되지 않은 임포트", [], bad)
        if file_name == "core_engine.py":
            p.eq("core_engine.py 의 금지 임포트", [], sorted(set(names) & _CORE_FORBIDDEN))
    app = _module_dir() / "app.py"
    if app.exists():
        p.true("app.py 는 무엇이든 임포트할 수 있다", True, "검사 대상 아님")
    else:
        p.true("app.py 없음, 건너뜀", True)


