def _m2(p: _Probe) -> None:
    config = EngineConfig()
    fields = set(EngineConfig.model_fields)
    p.eq("§0.3, §3.3 에 없는 필드", [], sorted(fields - set(_EXPECTED_DEFAULTS)))
    p.eq("빠진 필드", [], sorted(set(_EXPECTED_DEFAULTS) - fields))
    for name, expected in _EXPECTED_DEFAULTS.items():
        actual = getattr(config, name, None)
        if name == "bus_design_speed_mps":
            p.close(name, expected, actual, 1e-4)
        else:
            p.eq(name, expected, actual)
    p.close("m_slow", 0.846214, config.m_slow, 5e-7)
    weights = config.normalized_weights
    for label, expected, actual in zip(("w_t", "w_c", "w_r"), (0.5, 0.2, 0.3), weights):
        p.close(f"normalized_weights {label}", expected, actual, 1e-12)


