def _m11(p: _Probe) -> None:
    scenario = golden_scenario()
    p.eq("검증 왕복", scenario, _validate(Scenario, scenario.model_dump()))
    p.eq("노드 수", 24, len(scenario.nodes))
    p.eq("대여소 수", 5, len(scenario.bike_stations))
    p.eq("엣지 수", 29, len(scenario.edges))
    p.eq("신호 수", 4, len(scenario.signals))
    p.eq("개방 신호", 2, sum(1 for s in scenario.signals if s.realtime_open and not s.actuated))
    p.eq("미개방 고정 신호", 1, sum(1 for s in scenario.signals if not s.realtime_open and not s.actuated))
    p.eq("감응 신호", 1, sum(1 for s in scenario.signals if s.actuated))
    p.eq("버스 노선 수", 2, len(scenario.bus_lines))
    p.eq("예측 항목 수", 8, sum(len(items) for line in scenario.bus_lines for items in line.predictions))
    p.eq("역 수", 3, len(scenario.subway_stations))
    p.eq("패턴 수", 1, len(scenario.subway_patterns))
    p.eq("열차 수", 30, sum(len(pattern.trips) for pattern in scenario.subway_patterns))
    p.eq("장소 수", 2, len(scenario.places))
    edges = {edge.id: edge for edge in scenario.edges}
    p.eq("e09 의 distance_m", 120.0, edges["e09"].distance_m)
    signals = {signal.id: signal for signal in scenario.signals}
    p.eq("SG3 의 offset_s", 85.0, signals["SG3"].offset_s)
    trips = {trip.id: trip for trip in scenario.subway_patterns[0].trips}
    p.eq("열차 1029 의 dep_s[2]", 7270.0, trips["1029"].dep_s[2])
    p.eq("열차 1000 의 arr_s", (40.0, 170.0, 290.0), trips["1000"].arr_s)
    p.eq("data_mode", DataMode.SIMULATION, scenario.data_mode)
    p.eq("clock_s", 28_800.0, scenario.clock_s)
    p.eq("day_type", DayType.WEEKDAY, scenario.day_type)
    points = [*scenario.nodes, *scenario.bike_stations]
    p.eq("좌표 표의 ID", sorted(_GOLDEN_TABLE_LATLON), sorted(point.id for point in points))
    for point in points:
        lat, lon = _GOLDEN_TABLE_LATLON.get(point.id, (float("nan"), float("nan")))
        p.close(f"{point.id} 위도", lat, point.lat, 1e-9)
        p.close(f"{point.id} 경도", lon, point.lon, 1e-9)
    p.eq("미검증 노드·대여소", 29, sum(1 for point in points if not point.verified and point.source == _GOLDEN_SOURCE))
    query = golden_query()
    p.eq("golden_query() == default_query", scenario.default_query, query)
    p.eq("기본 질의 출발", (OriginKind.AT_NODE, "S"), (query.origin.kind, query.origin.node_id))
    p.eq("기본 질의 목적지", "D", query.destination_node_id)
    p.eq("두 번 부른 golden_scenario()", scenario, golden_scenario())
    p.eq("두 번 부른 golden_query()", query, golden_query())


# --- M12 직렬화 왕복 (§3.6) ---


def _roundtrip(p: _Probe, label: str, obj: Any) -> None:
    text = obj.model_dump_json()
    back = type(obj).model_validate_json(text)
    p.true(f"{label} 왕복", back == obj, f"JSON {len(text):,}자, 다시 읽은 객체가 {'같음' if back == obj else '다름'}")
    p.true(f"{label} JSON 이 결정적", text == obj.model_dump_json() == back.model_dump_json())


def _m12(p: _Probe) -> None:
    """5단계부터 EngineOutput 은 골든의 실제 run_engine 결과(기본 질의, 막차 변형, 버스 질의, Δt 300)로 검사한다(§9.3)."""
    for name in ("골든 기본", "V12e 막차 변형", "V12f 버스 질의", "V12g Δt 300"):
        _roundtrip(p, f"EngineOutput ({name} 의 run_engine 결과)", _run(name))
