def _primes_up_to(limit: int) -> tuple[int, ...]:
    return tuple(n for n in range(2, limit + 1) if all(n % d for d in range(2, int(n**0.5) + 1)))


def _m13(p: _Probe) -> None:
    config = EngineConfig()
    for name, (low, high, step) in PARAM_RANGES.items():
        if name in EngineConfig.model_fields:
            value = getattr(config, name)
        else:
            value = 0.0  # 출발 늦추기와 이미 탄 거리의 기본값
        ticks = (value - low) / step
        on_grid = abs(ticks - round(ticks)) <= 1e-9
        p.true(f"PARAM_RANGES {name} 기본값 {value} 이 [{low}, {high}] 안이고 간격 {step} 에 맞음", low <= value <= high and on_grid)
    p.eq("출발 늦추기 범위", (0.0, 1800.0, 60.0), tuple(float(v) for v in PARAM_RANGES["depart_offset_s"]))
    p.eq("출발 늦추기 최대 = depart_offset_max_s", config.depart_offset_max_s, float(PARAM_RANGES["depart_offset_s"][1]))
    p.eq("WALK_SPEED_PRESETS 보통 = v_walk_mps", config.v_walk_mps, WALK_SPEED_PRESETS["보통"])
    for name, weights in WEIGHT_PRESETS.items():
        p.close(f"WEIGHT_PRESETS {name} 합", 1.0, sum(weights), 1e-9)
    p.eq("WEIGHT_PRESETS 균형 = 기본 가중치", (config.w_time, config.w_cost, config.w_risk), WEIGHT_PRESETS["균형"])
    p.eq(
        "ROUTE_TYPE_CODES",
        {"2": BusRouteType.VILLAGE, "3": BusRouteType.TRUNK, "4": BusRouteType.BRANCH, "5": BusRouteType.CIRCULAR, "6": BusRouteType.WIDE_AREA},
        dict(ROUTE_TYPE_CODES),
    )
    p.true("FARE_NOTES 가 비어 있지 않음", len(FARE_NOTES) > 0)
    for number in ("1,550", "1550", "1,500"):
        p.eq(f"FARE_NOTES 원문에 {number} 없음", [], [i for i, note in enumerate(FARE_NOTES) if number in note])
    used = sorted({name for note in FARE_NOTES for _, name, _, _ in string.Formatter().parse(note) if name})
    p.eq("FARE_NOTES 자리 표시가 FARE_NOTE_FIELDS 안", [], [name for name in used if name not in FARE_NOTE_FIELDS])
    sample = {name: 1 for name in FARE_NOTE_FIELDS}
    try:
        filled = [note.format(**sample) for note in FARE_NOTES]
        p.true("FARE_NOTES 를 값으로 채울 수 있음", all(filled))
    except (KeyError, ValueError, IndexError) as exc:
        p.true("FARE_NOTES 를 값으로 채울 수 있음", False, f"{type(exc).__name__}: {exc}")
    for name, spec in API_SPECS.items():
        p.eq(f"API_SPECS {name} 이름", name, spec.api)
        p.true(f"API_SPECS {name} 에 verified 와 근거", isinstance(spec.verified, bool) and bool(spec.evidence.strip()))
    for name in _UNCONFIRMED_APIS:
        spec = API_SPECS.get(name)
        ok = spec is not None and (not spec.verified or "실제 응답 표본" in spec.evidence)
        p.true(f"{name} 은 verified=False 이거나 근거에 실제 응답 표본", ok, f"verified={getattr(spec, 'verified', None)}")
    p.eq("HALTON_PRIMES", _primes_up_to(61), HALTON_PRIMES)
    p.eq("HALTON_PRIMES 개수", 18, len(HALTON_PRIMES))
    p.eq("DEFAULT_TARGETS_JSON = §5.3 예시", _EXPECTED_TARGETS, json.loads(DEFAULT_TARGETS_JSON))
    p.accepts("DEFAULT_TARGETS_JSON 검증", _example_targets)
    p.eq("SIGNAL_FIELD_ROLES", _EXPECTED_SIGNAL_ROLES, SIGNAL_FIELD_ROLES)

    def spec_mod(base: str, **update: Any) -> Callable[[], Any]:
        return lambda: _validate(ApiSpec, {**API_SPECS[base].model_dump(), **update})

    signal = API_SPECS["signal"]
    p.rejects("ApiSpec 거부: RANGE 인데 page_size 없음", spec_mod("bike_list", page_size=None))
    p.rejects("ApiSpec 거부: expected_pages 3 에 max_pages 2", spec_mod("bike_list", expected_pages=3, max_pages=2))
    p.rejects(
        "ApiSpec 거부: PAGE_NO 인데 params 에 pageNo 없음",
        spec_mod("signal", params=tuple(name for name in signal.params if name != "pageNo")),
    )
    p.rejects(
        "ApiSpec 거부: fixed_params 에 params 에 없는 이름",
        spec_mod("signal", fixed_params={**signal.fixed_params, "resultType": "json"}),
    )
    p.rejects("ApiSpec 거부: no_data_values 만 있고 error_paths 없음", spec_mod("kakao_walk", no_data_values=("NONE",)))


