_EXPECTED_INDEXES = ("ix_arr", "ix_bike", "ix_polls", "ix_sig")


def _m14(p: _Probe) -> None:
    connection = sqlite3.connect(":memory:")
    try:
        try:
            connection.executescript(RECORD_SCHEMA_SQL)
            connection.executescript(RECORD_SCHEMA_SQL)
            p.true("RECORD_SCHEMA_SQL 을 두 번 실행", True, "오류 없음")
        except sqlite3.Error as exc:
            p.true("RECORD_SCHEMA_SQL 을 두 번 실행", False, f"{type(exc).__name__}: {exc}")
            return
        tables = sorted(
            row[0]
            for row in connection.execute("SELECT name FROM sqlite_master WHERE type = 'table'")
            if not row[0].startswith("sqlite_")
        )
        p.eq("표 6개", sorted(_EXPECTED_TABLES), tables)
        for table, columns in _EXPECTED_TABLES.items():
            actual = tuple(row[1] for row in connection.execute(f"PRAGMA table_info({table})"))
            p.eq(f"{table} 의 열", columns, actual)
        indexes = tuple(
            sorted(row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type = 'index'") if row[0].startswith("ix_"))
        )
        p.eq("색인 4개", _EXPECTED_INDEXES, indexes)
    finally:
        connection.close()


# --- M15 수집 대상 스키마 ---


def _m15(p: _Probe) -> None:
    p.accepts("§5.3 예시 JSON", _example_targets)

    def mod(change: Callable[[dict[str, Any]], None]) -> Callable[[], Any]:
        def factory() -> Any:
            data = json.loads(DEFAULT_TARGETS_JSON)
            change(data)
            return _validate(CollectTargets, data)

        return factory

    def window(**update: Any) -> Callable[[dict[str, Any]], None]:
        return lambda data: data.__setitem__("windows", [{**data["windows"][0], **update}, *data["windows"][1:]])

    rejected = (
        ("poll_s 5", lambda data: data.__setitem__("poll_s", 5)),
        ("휴일 2026-13-01", lambda data: data.__setitem__("holidays", ["2026-13-01"])),
        ("시간대 start 25:00", window(start="25:00")),
        ("start 09:00 · end 07:30", window(start="09:00", end="07:30")),
        ("day_types 가 빔", window(day_types=[])),
        ("windows 가 빔", lambda data: data.__setitem__("windows", [])),
        ("daily_call_limits 의 값 0", lambda data: data["daily_call_limits"].__setitem__("bus_arrival_all", 0)),
        ("station_match OTHER", lambda data: data["bike_history"].__setitem__("station_match", "OTHER")),
        ("bike_history.columns 의 모르는 역할 rent_date", lambda data: data["bike_history"]["columns"].__setitem__("rent_date", "대여일")),
        ("signal_api.field_map 의 모르는 역할 sigId", lambda data: data["signal_api"]["field_map"].__setitem__("sigId", "crsrdId")),
    )
    for label, change in rejected:
        p.rejects(f"거부 {label}", mod(change))


