@contextlib.contextmanager
def _env(values: dict[str, str | None]) -> Iterator[None]:
    """환경변수를 잠시 바꾸고 되돌린다(이 프로세스 안에서만). None 은 지운다."""
    saved = {name: os.environ.get(name) for name in values}
    try:
        for name, value in values.items():
            if value is None:
                os.environ.pop(name, None)
            else:
                os.environ[name] = value
        yield
    finally:
        for name, value in saved.items():
            if value is None:
                os.environ.pop(name, None)
            else:
                os.environ[name] = value


def _fake_keys() -> contextlib.AbstractContextManager:
    return _env(dict(_FAKE_KEYS))


def _no_keys() -> contextlib.AbstractContextManager:
    return _env({name: None for name, _ in _FAKE_KEYS})


class _ListHandler(logging.Handler):
    def __init__(self) -> None:
        super().__init__(logging.DEBUG)
        self.lines: list[str] = []

    def emit(self, record: logging.LogRecord) -> None:
        try:
            self.lines.append(record.getMessage())
        except Exception:  # noqa: BLE001
            self.lines.append(str(record.msg))


@contextlib.contextmanager
def _capture_logs() -> Iterator[_ListHandler]:
    """뿌리 로거에서 모든 로그(mobility_router, httpx 포함)를 잡는다."""
    handler = _ListHandler()
    root = logging.getLogger()
    previous = root.level
    root.addHandler(handler)
    root.setLevel(logging.DEBUG)
    try:
        yield handler
    finally:
        root.removeHandler(handler)
        root.setLevel(previous)


def _run_main(argv: list[str]) -> tuple[int, str]:
    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        code = main(argv)
    return code, out.getvalue()


