def _p1(p: _Probe) -> None:
    observations, skipped = parse_bike_payload(_sample_bike())
    p.eq("관측 수와 건너뛴 수", (1, 1), (len(observations), skipped))
    if observations:
        obs = observations[0]
        p.eq("ST-T1 (ID, 자전거, 거치대)", ("ST-T1", 4, 10), (obs.station_id, obs.bikes, obs.racks))
        p.close("ST-T1 위도", 37.4997, obs.lat, 1e-9)
        p.close("ST-T1 경도", 127.0004, obs.lon, 1e-9)
    empty = _sample_bike()
    empty["rentBikeStatus"]["row"] = []
    p.eq("row 가 빈 목록이면 (관측, 건너뛴 수)", ([], 0), parse_bike_payload(empty))


def _p2(p: _Probe) -> None:
    observations, skipped = parse_arrival_payload(_sample_arrival())
    p.eq("관측 6건, 건너뛴 행 0", (6, 0), (len(observations), skipped))
    by_slot = {(obs.sta_ord, obs.slot): obs for obs in observations}
    p.eq(
        "정류장 11 의 1번 칸",
        (11, "TESTST11", "00011", 1, "NORMAL", "T101", 10, 125.0, None, None, _T_SAMPLE, 0, 0, 0, "2분5초후[1번째 전]", 10.0, "3"),
        _arrival_view(by_slot[(11, 1)]),
    )
    p.eq("정류장 12 의 1번 칸 kals", 370.0, by_slot[(12, 1)].kals)
    p.eq("정류장 11·12 의 2번 칸 만차", (1, 1), (by_slot[(11, 2)].full_flag, by_slot[(12, 2)].full_flag))
    p.eq("정류장 13 의 2번 칸", ("WAITING", "0"), (by_slot[(13, 2)].kind.value, by_slot[(13, 2)].veh_id))

    def slot13(**values: str) -> Callable[[list[dict[str, Any]]], None]:
        return lambda items: items[2].update(values)

    def kinds(payload: dict[str, Any]) -> tuple[int, str]:
        found, _ = parse_arrival_payload(payload)
        return len(found), next(obs.kind.value for obs in found if (obs.sta_ord, obs.slot) == (13, 2))

    p.eq("arrmsg2 \"운행 종료\" → ENDED", (6, "ENDED"), kinds(_arrival_variant(slot13(arrmsg2="운행 종료"))))
    blank = {"vehId2": "", "exps2": "", "kals2": "", "neus2": "", "arrmsg2": ""}
    p.eq("칸이 모두 빈 문자열 → NO_INFO, 관측 6건", (6, "NO_INFO"), kinds(_arrival_variant(slot13(**blank))))
    p.eq("vehId2 \"T103\", 세 예측이 빔 → NO_INFO", (6, "NO_INFO"),
         kinds(_arrival_variant(slot13(**{**blank, "vehId2": "T103"}))))
    last = parse_arrival_payload(_arrival_variant(lambda items: items[1].update(isLast1="1")))[0]
    p.eq("정류장 12 의 isLast1 \"1\" → 막차 1", 1, next(obs.is_last for obs in last if (obs.sta_ord, obs.slot) == (12, 1)))

    def drop_last(items: list[dict[str, Any]]) -> None:
        for item in items:
            item.pop("isLast1", None)
            item.pop("isLast2", None)

    no_last = parse_arrival_payload(_arrival_variant(drop_last))[0]
    p.eq("isLast 필드를 지우면 막차 모두 0", [0] * 6, [obs.is_last for obs in no_last])
    extra = _arrival_variant(lambda items: items.append({**items[0], "staOrd": ""}))
    p.eq("staOrd 가 빈 넷째 항목 → (관측, 건너뛴 행)", (6, 1), tuple(len(x) if isinstance(x, list) else x for x in parse_arrival_payload(extra)))
    single = _sample_arrival()
    single["ServiceResult"]["msgBody"]["itemList"] = single["ServiceResult"]["msgBody"]["itemList"][0]
    p.eq("itemList 가 dict 하나 → 관측 2건", 2, len(parse_arrival_payload(single)[0]))

    def mk_values(change: Callable[[list[dict[str, Any]]], Any]) -> set:
        return {obs.mk_unix for obs in parse_arrival_payload(_arrival_variant(change))[0]}

    p.eq("mkTm \"20261117080005\" → 같은 mk_unix", {_T_SAMPLE},
         mk_values(lambda items: [item.update(mkTm="20261117080005") for item in items]))
    p.eq("mkTm 을 지우면 mk_unix None", {None}, mk_values(lambda items: [item.pop("mkTm") for item in items]))


def _p3(p: _Probe) -> None:
    expected = parse_arrival_payload(_sample_arrival())
    document = _xml_document(_sample_arrival())
    converted = xml_to_dict(document)
    p.eq("XML → dict → 파싱이 P2 와 같다", expected, parse_arrival_payload(converted))
    renamed = document.replace("ServiceResult>", "OtherRoot>")
    p.eq("루트 이름이 달라도 msgBody 를 찾는다", expected, parse_arrival_payload(xml_to_dict(renamed)))
    p.eq("itemList 세 개는 list", 3, len(converted["ServiceResult"]["msgBody"]["itemList"]))
    p.eq("형제가 여럿이면 list, 하나면 dict, 자식이 없으면 글자",
         {"a": {"b": ["1", "2"], "c": {"d": ""}, "e": "x"}}, xml_to_dict("<a><b>1</b><b>2</b><c><d/></c><e> x </e></a>"))


def _golden_g1_inputs() -> tuple[BusLine, tuple[Node, ...]]:
    scenario = golden_scenario()
    line = next(item for item in scenario.bus_lines if item.id == "G1")
    nodes = {node.id: node for node in scenario.nodes}
    return line, tuple(nodes[stop] for stop in line.stop_ids)


def _prediction_view(predictions: tuple[tuple[StopPrediction, ...], ...]) -> tuple:
    return tuple(
        tuple((item.rank, item.vehicle_id, item.kind.value, item.eta_s, item.is_full, item.sect_ord) for item in items)
        for items in predictions
    )


def _p4(p: _Probe) -> None:
    line, stops = _golden_g1_inputs()
    with_ords = line.model_copy(update={"stop_ords": (11, 12, 13)})
    observations = parse_arrival_payload(_sample_arrival())[0]
    t = _T_REQUEST
    predictions, headway, age = predictions_from_observations(with_ords, stops, observations, t, t)
    first = (
        ((1, "T101", "NORMAL", 120.0, False, 10), (2, "T102", "NORMAL", 605.0, True, 8)),
        ((1, "T101", "NORMAL", 360.0, False, 10), (2, "T102", "NORMAL", 845.0, True, 8)),
        ((1, "T101", "NORMAL", 780.0, False, 10), (2, "0", "WAITING", None, False, 0)),
    )
    p.eq("08:00:10 의 순번별 예측", first, _prediction_view(predictions))
    p.eq("배차 간격과 관측 경과", (600.0, 5.0), (headway, age))
    data = with_ords.model_dump()
    data.update(predictions=[[item.model_dump() for item in items] for items in predictions], headway_s=headway,
                prediction_age_s=age)
    p.accepts("결과로 만든 BusLine 이 검증을 통과", lambda: BusLine.model_validate(data))
    at_0210 = _prediction_view(predictions_from_observations(with_ords, stops, observations, t, t + 120)[0])
    p.eq("t0 08:02:10 의 B1 (T101, T102)", (0.0, 485.0), tuple(item[3] for item in at_0210[0]))
    at_0211 = _prediction_view(predictions_from_observations(with_ords, stops, observations, t, t + 121)[0])
    p.eq("t0 08:02:11 의 B1", ((2, "T102", "NORMAL", 484.0, True, 8),), at_0211[0])
    p.eq("t0 08:02:11 의 B2, B3", ((239.0, 724.0), (659.0, None)),
         (tuple(item[3] for item in at_0211[1]), tuple(item[3] for item in at_0211[2])))
    p.eq("t0 08:02:11 의 B3 둘째 칸", "WAITING", at_0211[2][1][2])
    no_mk = parse_arrival_payload(_arrival_variant(lambda items: [item.pop("mkTm") for item in items]))[0]
    view, _, age_no_mk = predictions_from_observations(with_ords, stops, no_mk, t, t)
    p.eq("mkTm 이 없으면 판단 시각 = 요청 시각", ((125.0, 610.0), (365.0, 850.0), (785.0, None)),
         tuple(tuple(item[3] for item in items) for items in _prediction_view(view)))
    p.eq("mkTm 이 없을 때 관측 경과", 0.0, age_no_mk)
    no_exps = parse_arrival_payload(_arrival_variant(lambda items: items[1].update(exps1="")))[0]
    p.eq("정류장 12 의 exps1 이 비면 kals 370", 365.0,
         _prediction_view(predictions_from_observations(with_ords, stops, no_exps, t, t)[0])[1][0][3])
    no_term = parse_arrival_payload(_arrival_variant(lambda items: [item.pop("term") for item in items]))[0]
    p.eq("term 을 모두 지우면 배차 간격 None", None, predictions_from_observations(with_ords, stops, no_term, t, t)[1])
    plain = line.model_copy(update={"stop_ords": None})
    by_ars = tuple(node.model_copy(update={"official_id": f"000{11 + index}"}) for index, node in enumerate(stops))
    p.eq("stop_ords 없이 official_id 로", (first, 600.0, 5.0),
         (lambda r: (_prediction_view(r[0]), r[1], r[2]))(predictions_from_observations(plain, by_ars, observations, t, t)))
    by_st = tuple(node.model_copy(update={"official_id": None, "official_st_id": f"TESTST{11 + index}"})
                  for index, node in enumerate(stops))
    p.eq("official_st_id 만으로", first, _prediction_view(predictions_from_observations(plain, by_st, observations, t, t)[0]))
    bare = tuple(node.model_copy(update={"official_id": None, "official_st_id": None}) for node in stops)
    p.eq("맞는 행이 없으면 빈 예측, None, None", (((), (), ()), None, None),
         predictions_from_observations(plain, bare, observations, t, t))


def _p5(p: _Probe) -> None:
    field_map = _example_field_map()
    observations, skipped = parse_signal_payload(_sample_signal(), field_map)
    view = [(obs.signal_src_id, obs.state.value, round(obs.remaining_s, 9), obs.obs_unix) for obs in observations]
    p.eq("관측 3건 (순서대로)",
         [("C1:nt", "RED", 45.6, _T_SIGNAL), ("C1:et", "GREEN", 12.3, _T_SIGNAL), ("C2:st", "RED", 30.0, _T_SIGNAL)], view)
    p.eq("건너뛴 수 (C2 의 nt 점멸, et 36001)", 2, skipped)
    unscaled = parse_signal_payload(_sample_signal(), {**field_map, "remaining_scale": ""})[0]
    p.eq("remaining_scale 을 비우면 C1:nt", 456.0, unscaled[0].remaining_s if unscaled else None)
    p.eq("교차로 목록", [("C1", 37.5001, 127.0001), ("C2", 37.51, 127.01)],
         parse_signal_intersections(_sample_intersections(), field_map))
    without_remaining = {role: name for role, name in field_map.items() if role != "remaining"}
    p.raises("remaining 역할을 뺀 표는 ValueError", ValueError, lambda: parse_signal_payload(_sample_signal(), without_remaining))
    p.raises("directions 를 비운 채 {dir} 은 ValueError", ValueError,
             lambda: parse_signal_payload(_sample_signal(), {**field_map, "directions": ""}))


def _p6(p: _Probe) -> None:
    config = EngineConfig()
    params = {"busRouteId": "TESTROUTE"}

    def call(maker: ResponseMaker, spec_name: str = "bus_arrival_all", call_params: dict | None = None) -> tuple[ApiCallResult | None, _Router, str]:
        router = _Router(bus=maker, bike=maker, signal=maker, intersections=maker)
        try:
            with router.client() as client:
                return api_call(client, spec_name, call_params or params, config), router, ""
        except Exception as exc:  # noqa: BLE001 - 예외가 밖으로 나오면 실패로 센다
            return None, router, f"{type(exc).__name__}: {exc}"

    with _fake_keys():
        result, router, error = call(_json_body(_sample_arrival()))
        p.eq("① 200 → (SUCCESS, 시도 1)", ("SUCCESS", 1), (result.state.value, result.attempts) if result else error)
        request = router.requests[0][1] if router.requests else None
        p.eq("① 클라이언트 타임아웃 = api_timeout_s", {"connect": 5.0, "read": 5.0, "write": 5.0, "pool": 5.0},
             request.extensions.get("timeout") if request else None)
        raw_query = dict(part.split("=", 1) for part in request.url.query.decode().split("&")) if request else {}
        p.eq("① serviceKey 를 한 번 디코딩하면 가짜 키", "TESTKEY-DATA", urllib.parse.unquote(raw_query.get("serviceKey", "")))
        result, router, error = call(_sequence(_status_only(500), _status_only(500), _json_body(_sample_arrival())))
        p.eq("② 500 두 번 뒤 200 → (SUCCESS, 시도 3)", ("SUCCESS", 3), (result.state.value, result.attempts) if result else error)
        result, router, error = call(_connect_error)
        p.eq("③ 연결 오류가 계속되면 (FAILED, 시도 3)", ("FAILED", 3), (result.state.value, result.attempts) if result else error)
        result, router, error = call(_status_only(401))
        p.eq("④ 401 → (FAILED, 시도 1, 요청 1회)", ("FAILED", 1, 1),
             (result.state.value, result.attempts, len(router.requests)) if result else error)
        result, router, error = call(_raw_body("{\"msgBody\": ", "application/json"))
        p.eq("⑤ 깨진 JSON → (FAILED, 시도 1)", ("FAILED", 1), (result.state.value, result.attempts) if result else error)
        document = _xml_document(_sample_arrival())
        for content_type in ("text/xml", "application/json"):
            result, router, error = call(_raw_body(document, content_type))
            p.eq(f"⑥ XML 본문 ({content_type}) → dict", ("SUCCESS", xml_to_dict(document)),
                 (result.state.value, result.payload) if result else error)
        result, router, error = call(lambda request: (_ for _ in ()).throw(RuntimeError(f"처리기 오류 {request.url}")))
        p.eq("처리기가 다른 예외를 던져도 FAILED", "FAILED", result.state.value if result else error)
    special = "ab+c/d=e==Key"
    with _env({ENV_DATA_GO_KR_KEY: special, ENV_SEOUL_KEY: None, ENV_KAKAO_KEY: None}):
        result, router, error = call(_json_body(_sample_arrival()))
        request = router.requests[0][1] if router.requests else None
        raw_query = dict(part.split("=", 1) for part in request.url.query.decode().split("&")) if request else {}
        p.eq("+, /, = 가 든 키도 한 번만 인코딩", special, urllib.parse.unquote(raw_query.get("serviceKey", "")))


