def _v6(p: _Probe) -> None:
    config = EngineConfig()
    signals = {"A": _v_signal("A", 45, 75, offset=30), "B": _v_signal("B", 30, 60, offset=0)}
    steps = (
        travel_step(100),
        signal_step("A"),
        travel_step(20),
        travel_step(150),
        signal_step("B"),
        travel_step(30),
    )
    end, events = propagate_steps(steps, 0.0, signals, config)
    p.eq("신호 이벤트 수", 2, len(events))
    for event, (t_arr, tau, state, wait) in zip(events, ((80, 110, SignalState.RED, 10), (226, 46, SignalState.RED, 44))):
        p.close(f"{event.signal_id}: t_arr", t_arr, event.t_arr_s, 0.01)
        p.close(f"{event.signal_id}: τ", tau, event.tau_s, 0.01)
        p.eq(f"{event.signal_id}: 상태", state, event.state)
        p.close(f"{event.signal_id}: W", wait, event.wait_s, 0.01)
    p.close("도착", 294.0, end, 0.01)
    separate = deterministic_wait(signals["B"], 216.0)
    p.true("A 의 대기를 빼고 B 를 따로 계산하면 W 54 로 다르다", abs(separate.wait_s - 54.0) < 0.01 and abs(events[1].wait_s - separate.wait_s) > 1)
    walk_only, _ = propagate_steps(compact_steps(steps), 0.0, signals, config)
    p.close("이어진 TRAVEL 을 합쳐도 같다", end, walk_only, 0.01)


def _v7(p: _Probe) -> None:
    config = EngineConfig()
    p.close("80 + 25 + 200 + 20 + 15 + 40", 380.0, bike_plan_time_s(100, 800, 50, 20, config), 0.01)
    steps = (travel_step(100), fixed_step(config.t_unlock_s), travel_step(800, Mode.BIKE), fixed_step(20), fixed_step(config.t_dock_s), travel_step(50))
    end, _ = propagate_steps(steps, 0.0, {}, config)
    p.close("같은 다섯 단계를 프로필로 지나도 380", 380.0, end, 0.01)


def _v8(p: _Probe) -> None:
    config = EngineConfig()

    def walk_only(dep: float, walk: float, buffer: float, cfg: EngineConfig = config) -> EventProbability:
        return arrival_probability((_walk_s(walk, cfg),), dep - buffer, {}, cfg)

    worst = 0.0
    for dep, walk, buffer, expected, grade in (
        (290, 240, 30, 0.739247, Grade.RISKY),
        (300, 240, 30, 0.822758, Grade.SAFE),
        (180, 200, 30, 0.002737, Grade.GHOST),
        (420, 380, 30, 0.584600, Grade.RISKY),
        (300, 240, 0, 0.952210, Grade.SAFE),
        (100, 70, 30, 0.500000, Grade.RISKY),
    ):
        result = walk_only(dep, walk, buffer)
        label = f"({dep}, 도보 {walk}, {buffer})"
        p.close(f"{label} 확률", expected, result.probability, 1e-5)
        p.eq(f"{label} (등급, 방법)", (grade, ProbMethod.EXACT), (grade_of(result.probability, config), result.method))
        m_star = walk / (dep - buffer)
        closed = 0.5 * math.erfc((m_star - 1.0) / (config.k_move * math.sqrt(2.0)))
        worst = max(worst, abs(closed - result.probability))
    p.true("닫힌 식과 1e-6 안에서 같다", worst <= 1e-6, f"최대 차이 {worst:.2e}")
    p.close("(100, 70, 30) 의 m*", 1.0, float(walk_only(100, 70, 30).thresholds[0]), 1e-5)
    normal = statistics.NormalDist(240, config.k_move * 240).cdf(260)
    p.close("도착 시각의 정규 근사는 0.7563 으로 틀린다", 0.7563, normal, 1e-4)
    flat = EngineConfig(k_move=0)
    for walk, expected in ((70, 1.0), (71, 0.0)):
        result = walk_only(100, walk, 30, flat)
        p.eq(f"k_move 0: (100, {walk}, 30) (확률, 방법)", (expected, ProbMethod.DEGENERATE), (result.probability, result.method))
    dense_flat = EngineConfig(k_move=0, n_qmc=131_072)
    for dep, w1, green, red, w2, buffer, count, dense_expected in (
        (150, 50, 30, 90, 50, 30, 1708, 0.416687),
        (130, 40, 40, 60, 40, 30, 2456, 0.599983),
        (65, 50, 20, 80, 10, 0, 1024, None),
    ):
        signals = {"K": _v_signal("K", green, red)}
        steps = (_walk_s(w1, flat), signal_step("K"), _walk_s(w2, flat))
        result = arrival_probability(steps, dep - buffer, signals, flat)
        label = f"k_move 0, 미개방 신호 ({dep}, [도보 {w1}, 녹색 {green} · 적색 {red}, 도보 {w2}], {buffer})"
        p.eq(f"{label}: (점 수, 방법, 표본 신호의 차원)", (count, 4096, ProbMethod.DEGENERATE, {"K": 1}), (round(result.probability * result.n_points), result.n_points, result.method, result.dims))
        p.close(f"{label}: 확률 {count}/4096", count / 4096, result.probability, 1e-9)
        slack = dep - buffer - w1 - w2
        closed = (green + min(slack, red)) / (green + red) if slack >= 0 else 0.0
        p.close(f"{label}: 닫힌 식 (T_g + min(s, T_r)) / C = {closed:.6f} 와 1e-3 안", closed, result.probability, 1e-3)
        if dense_expected is not None:
            p.close(f"{label}: 점 131,072개", dense_expected, arrival_probability(steps, dep - buffer, signals, dense_flat).probability, 1e-5)

    signals = {"K": _v_signal("K", 30, 130, offset=111)}
    steps = (_walk_s(240, config), signal_step("K"), _walk_s(80, config))
    result = arrival_probability(steps, 360 - 30, signals, config)
    p.close("개방 신호 확률", 0.486093, result.probability, 1e-5)
    p.eq("개방 신호 (등급, 방법)", (Grade.RISKY, ProbMethod.EXACT), (grade_of(result.probability, config), result.method))
    end, events = propagate_steps(steps, 0.0, signals, config)
    p.eq(
        "개방 신호 계획: K 도착, τ, 상태, 대기, 정류장",
        (240.0, 31.0, SignalState.RED, 129.0, 449.0),
        (round(events[0].t_arr_s, 4), round(events[0].tau_s, 4), events[0].state, round(events[0].wait_s, 4), round(end, 4)),
    )
    p.close("개방 신호 m*", 1.004184, float(result.thresholds[0]), 1e-5)
    grid = (0.97, 0.99, 1.0, 1.003, 1.005, 1.01, 1.05)
    expected_times = (451.4742, 449.8081, 449.0, 448.7607, 318.4080, 316.8317, 304.7619)
    for m, expected, actual in zip(grid, expected_times, move_times(steps, np.array(grid), {}, signals, config)):
        p.close(f"개방 신호 T_move({m})", expected, float(actual), 0.01)
    p.close("같은 거리에 신호가 없으면", 0.599682, arrival_probability((_walk_s(320, config),), 330, {}, config).probability, 1e-5)
    approx = statistics.NormalDist(449, config.k_move * 320).cdf(330)
    p.close("계획 도착 449 를 평균으로 둔 정규 근사는 0.0010 으로 틀린다", 0.0010, approx, 1e-4)

    signals = {"Q": _v_signal("Q", 40, 80)}
    steps = (_walk_s(120, config), signal_step("Q"), _walk_s(120, config))
    result = arrival_probability(steps, 300 - 30, signals, config)
    p.close("미개방 신호 확률", 0.526797, result.probability, 1e-5)
    p.eq(
        "미개방 신호 (방법, 표본 신호, 점, 차원)",
        (ProbMethod.QMC, 1, 4096, 2),
        (result.method, len(result.dims), result.n_points, result.n_dims),
    )
    dense = arrival_probability(steps, 300 - 30, signals, EngineConfig(n_qmc=131_072))
    p.close("미개방 신호, 점 131,072개", 0.526883, dense.probability, 1e-5)
    p.close("점 4,096개와 131,072개의 차이", 8.6e-5, abs(dense.probability - result.probability), 5e-6)

    for k_pm, expected in ((0.12, 0.775647), (0.20, 0.699184), (0.0, 0.972765)):
        cfg = EngineConfig(k_pm=k_pm)
        steps = (_walk_s(60, cfg), fixed_step(25), _bike_s(200, cfg), fixed_step(15), _walk_s(40, cfg))
        result = arrival_probability(steps, 400 - 30, {}, cfg)
        p.close(f"따릉이 프로필 k_pm {k_pm:g}", expected, result.probability, 1e-5)
        p.eq(f"따릉이 프로필 k_pm {k_pm:g} 방법", ProbMethod.EXACT, result.method)
        times = move_times(steps, np.array([0.9, 1.0, 1.1]), {}, {}, cfg)
        expected_times = {0.12: (373.3333, 340.0, 312.7273), 0.20: (391.1111, 340.0, 302.3377), 0.0: (351.1111, 340.0, 330.9091)}[k_pm]
        for m, want, got in zip((0.9, 1.0, 1.1), expected_times, times):
            p.close(f"따릉이 프로필 k_pm {k_pm:g}: T_move({m})", want, float(got), 0.01)

    for value, grade in ((0.75, Grade.SAFE), (0.7499, Grade.RISKY), (0.40, Grade.RISKY), (0.3999, Grade.GHOST)):
        p.eq(f"등급 {value}", grade, grade_of(value, config))


_FARE_KINDS: MappingProxyType = MappingProxyType(
    {
        "간선": BusRouteType.TRUNK,
        "지선": BusRouteType.BRANCH,
        "순환": BusRouteType.CIRCULAR,
        "광역": BusRouteType.WIDE_AREA,
        "심야": BusRouteType.NIGHT,
        "마을": BusRouteType.VILLAGE,
    }
)


def _fare_rides(items: tuple[tuple[str, float, str, bool], ...], gaps: tuple[float, ...] = ()) -> list[FareRide]:
    """§9.1 V9 의 탑승 목록: (종류, 거리 m, 같은 노선 글자, 역 안). 첫 승차 t = 0, 탑승마다 600 s, 다음 승차까지 300 s."""
    rides: list[FareRide] = []
    t = 0.0
    for number, (kind, distance_m, letter, in_station) in enumerate(items, start=1):
        if number > 1:
            t += gaps[number - 2] if number - 2 < len(gaps) else 300.0
        subway = kind == "지하철"
        rides.append(
            FareRide(
                mode=TravelMode.SUBWAY if subway else TravelMode.BUS,
                route_type=None if subway else _FARE_KINDS[kind],
                route_id=letter or f"{kind}{number}",
                board_s=t,
                alight_s=t + 600.0,
                distance_m=distance_m,
                in_station=in_station,
            )
        )
        t += 600.0
    return rides


def _fr(kind: str, km: float, letter: str = "", in_station: bool = False) -> tuple[str, float, str, bool]:
    return (kind, km * 1000.0, letter, in_station)


def _fare_view(breakdown: FareBreakdown) -> tuple:
    """(합계, 묶음마다 (탑승 번호, 기본, 거리 km, 추가, 끊긴 이유))."""
    return (
        breakdown.total_krw,
        tuple(
            (chain.ride_indexes, chain.base_krw, round(chain.distance_m / 1000.0, 6), chain.distance_extra_krw, chain.break_reason)
            for chain in breakdown.chains
        ),
    )


