def _v10(p: _Probe) -> None:
    routes = (("R1", 900.0, 2650.0, 0.86), ("R2", 1320.0, 1650.0, 0.97), ("R3", 2400.0, 1550.0, 1.0))

    def scores(weights: tuple[float, float, float], costs: tuple[float, ...]) -> dict[str, UtilityTerms]:
        t_max = max(route[1] for route in routes)
        cost_max = max(costs)
        return {name: utility_terms(mean, cost, p_star, t_max, cost_max, weights) for (name, mean, _, p_star), cost in zip(routes, costs)}

    costs = tuple(route[2] for route in routes)
    weights = EngineConfig().normalized_weights
    result = scores(weights, costs)
    p.eq("(T_max, Cost_max)", (2400.0, 2650.0), (result["R1"].t_max_s, result["R1"].cost_max_krw))
    for name, terms in (("R1", (0.1875, 0.2000, 0.0420, 0.4295)), ("R2", (0.2750, 0.1245, 0.0090, 0.4085)), ("R3", (0.5000, 0.1170, 0.0, 0.6170))):
        actual = result[name]
        for label, want, got in zip(("시간 항", "요금 항", "위험 항", "J"), terms, (actual.time_term, actual.cost_term, actual.risk_term, actual.total)):
            p.close(f"{name} {label}", want, got, 1e-4)
    p.eq("최적", "R2", min(result, key=lambda name: result[name].total))
    free = scores(weights, (0.0, 0.0, 0.0))
    for name, want in (("R1", 0.2295), ("R2", 0.2840), ("R3", 0.5000)):
        p.close(f"요금이 모두 0: {name} J", want, free[name].total, 1e-4)
    p.eq("요금이 모두 0: 요금 항", (0.0, 0.0, 0.0), tuple(free[name].cost_term for name in ("R1", "R2", "R3")))
    p.eq("요금이 모두 0: 최적", "R1", min(free, key=lambda name: free[name].total))
    raw = scores((3.0, 5.0, 2.0), costs)
    normalized = EngineConfig(w_time=3, w_cost=5, w_risk=2).normalized_weights
    p.eq("가중치 (3, 5, 2) 의 정규화", (0.3, 0.5, 0.2), tuple(round(w, 10) for w in normalized))
    for name, want in (("R1", 0.6405), ("R2", 0.4823), ("R3", 0.5925)):
        p.close(f"가중치 (3, 5, 2): {name} J", want, raw[name].total, 1e-4)
    p.eq("가중치 (3, 5, 2): 최적", "R2", min(raw, key=lambda name: raw[name].total))


def _v13(p: _Probe) -> None:
    p.eq(
        "radical_inverse_int 밑 2, n 1 ~ 8",
        [(1, 2), (1, 4), (3, 4), (1, 8), (5, 8), (3, 8), (7, 8), (1, 16)],
        [radical_inverse_int(n, 2) for n in range(1, 9)],
    )
    column = halton_column(3, 6)
    for i, want in enumerate((1 / 3, 2 / 3, 1 / 9, 4 / 9, 7 / 9, 2 / 9)):
        p.close(f"halton_column 밑 3 의 {i + 1}번째", want, float(column[i]), 1e-6)
    p.true("준난수 열은 읽기 전용", not column.flags.writeable)
    for i, (want, got) in enumerate(zip((1.0, 0.919061, 1.080939, 0.861958, 1.038237, 0.961763, 1.138042, 0.815906), halton_m(8, 0.12))):
        p.close(f"속도 배수 m_{i + 1}", want, float(got), 1e-5)
    for z, want, got in zip(("0", "1.959964", "-1", "+inf"), (0.5, 0.025, 0.841345, 0.0), upper_normal_tail([0.0, 1.959964, -1.0, math.inf])):
        p.close(f"upper_normal_tail({z})", want, float(got), 1e-5)
    signals = {
        "S1": _v_signal("S1", 40, 80),
        "S2": _v_signal("S2", 30, 110, gaps=(100, 120, 140, 160, 180)),
        "S3": _v_signal("S3", 30, 60, offset=5),
    }
    dims, capped = assign_halton_dims(("S1", "S2", "S1", "S3"), signals, EngineConfig())
    p.eq("차원 배정 (같은 신호는 같은 차원, 개방 신호는 차원 없음)", ({"S1": 1, "S2": 2}, ()), (dims, capped))
    draws = signal_draws(dims, signals, 8)
    p.true("차원 1 은 밑 3", np.allclose(draws["S1"][0] / draws["S1"][1], halton_column(3, 8)))
    many = {f"Q{i}": _v_signal(f"Q{i}", 40, 80) for i in range(18)}
    order = tuple(f"Q{i}" for i in range(18))
    dims, capped = assign_halton_dims(order, many, EngineConfig())
    p.eq("미개방 신호 18개: Q0 ~ Q16 에 차원 1 ~ 17", {f"Q{i}": i + 1 for i in range(17)}, dims)
    p.eq("미개방 신호 18개: 넘친 신호", ("Q17",), capped)
    steps: list[ProfileStep] = []
    for signal_id in order:
        steps += [travel_step(20), signal_step(signal_id)]
    result = arrival_probability(tuple(steps), 3000, many, EngineConfig())
    p.eq(
        "넘친 신호는 기대 대기로 다루고 경고를 남긴다 (넘친 신호, 경고, 차원 수)",
        (("Q17",), (WarningCode.QMC_DIMENSIONS_CAPPED,), 18),
        (result.capped, result.warnings, result.n_dims),
    )


def _v14(p: _Probe) -> None:
    config = EngineConfig()
    signals = {"G": _v_signal("G", 30, 120, offset=55)}
    steps = (_walk_s(144, config), signal_step("G"), _walk_s(16, config), _walk_s(80, config))
    cases = (
        (0.05, math.inf),
        (0.06, 4095.0),
        (0.5, 587.0),
        (0.8, 365.0),
        (1.0, 341.0),
        (1.15, 328.4783),
        (1.152, 328.3333),
        (1.153, 208.1526),
        (1.2, 200.0),
        (1.5, 160.0),
        (2.0, 143.0),
        (20.0, 99.8),
    )
    times = move_times(steps, np.array([m for m, _ in cases]), {}, signals, config)
    for (m, want), got in zip(cases, times):
        if math.isinf(want):
            p.eq(f"T_move({m}) 는 +∞ (m ≤ m_min)", math.inf, float(got))
        else:
            p.close(f"T_move({m})", want, float(got), 0.01)
    grid = np.linspace(0.051, 20.0, 20_000)
    values = move_times(steps, grid, {}, signals, config)
    p.true("0.051 ~ 20 의 20,000점에서 늘어나지 않는다", bool(np.all(np.diff(values) <= 1e-9)))
    merged = compact_steps(steps)
    p.eq("이어진 도보를 합친 단계 수", 3, len(merged))
    p.close("합쳐도 T_move(1.0) 은 같다", 341.0, float(move_times(merged, np.array([1.0]), {}, signals, config)[0]), 0.01)
    for y, m_star, probability in ((300, 1.152, 0.102637), (330, 1.129412, 0.140421), (250, 1.152, 0.102637), (200, 1.2, 0.047790), (11, math.inf, 0.0)):
        result = arrival_probability(steps, y, signals, config)
        threshold = float(result.thresholds[0])
        if math.isinf(m_star):
            p.eq(f"y {y}: m* = +∞", math.inf, threshold)
        else:
            p.close(f"y {y}: m*", m_star, threshold, 1e-5)
        p.close(f"y {y}: 확률", probability, result.probability, 1e-5)


