def _fixed_signal_obs(t0: float, t1: float, cycle: float = 150.0, green: float = 30.0, theta: float = 55.0, step: float = 30.0) -> list[tuple[float, SignalState, float]]:
    """V16 의 고정 신호 관측: 위상 τ = (θ + t) mod C 가 녹색 미만이면 (GREEN, 녹색 − τ), 아니면 (RED, C − τ)."""
    rows = []
    t = t0
    while t <= t1:
        tau = (theta + t) % cycle
        rows.append((t, SignalState.GREEN, green - tau) if tau < green else (t, SignalState.RED, cycle - tau))
        t += step
    return rows


def _actuated_signal_obs(t0: float, t1: float, step: float = 30.0) -> list[tuple[float, SignalState, float]]:
    """V16 (c): 07:00:10 에 녹색 시작, 녹색 30초, 주기 100, 120, 140, 160, 180 을 되풀이한다."""
    cycles = (100.0, 120.0, 140.0, 160.0, 180.0)
    starts = [25_210.0]
    while starts[-1] <= t1 + 200:
        starts.append(starts[-1] + cycles[(len(starts) - 1) % len(cycles)])
    rows = []
    t = t0
    while t <= t1:
        if t < starts[0]:
            rows.append((t, SignalState.RED, starts[0] - t))
        else:
            k = max(i for i, start in enumerate(starts) if start <= t)
            if t - starts[k] < 30.0:
                rows.append((t, SignalState.GREEN, starts[k] + 30.0 - t))
            else:
                rows.append((t, SignalState.RED, starts[k + 1] - t))
        t += step
    return rows


def _fit_view(fit: SignalSlotFit) -> tuple:
    return (fit.learned, fit.cycle_s, fit.green_s, fit.red_s, fit.iqr_s, fit.actuated, fit.n_gaps, fit.n_greens)


def _v16(p: _Probe) -> None:
    config = EngineConfig()
    base = _fixed_signal_obs(25_200, 32_400)
    p.eq("(a) 관측 수와 처음 여섯 개", (241, [(25_200, "RED", 95), (25_230, "RED", 65), (25_260, "RED", 35), (25_290, "RED", 5), (25_320, "GREEN", 5), (25_350, "RED", 95)]),
         (len(base), [(int(t), s.value, round(r, 6)) for t, s, r in base[:6]]))
    day = signal_day_samples(base, 30.0, config)
    p.eq("(a) 녹색 시작, 녹색 끝, 버린 간격", (49, 48, 0), (len(day.green_starts), len(day.green_ends), day.dropped_gaps))
    fits = fit_signal_slots([day], config)
    for slot in (7, 8):
        p.eq(f"(a) {slot}시 (학습, C, 녹색, 적색, IQR, 감응, 주기 표본, 녹색 표본)", (True, 150.0, 30.0, 120.0, 0.0, False, 24, 24), _fit_view(fits[slot]))
    noise = (-1.0, 0.0, 1.0, 0.0, 1.0, -1.0, 0.0)
    noisy = [(t, s, r + noise[i % len(noise)]) for i, (t, s, r) in enumerate(base)]
    fits = fit_signal_slots([signal_day_samples(noisy, 30.0, config)], config)
    for slot in (7, 8):
        fit = fits[slot]
        p.eq(f"(b) {slot}시 (C, 녹색, 적색, IQR, 감응)", (149.5, 30.0, 119.5, 1.0, False), (fit.cycle_s, fit.green_s, fit.red_s, fit.iqr_s, fit.actuated))
    actuated = fit_signal_slots([signal_day_samples(_actuated_signal_obs(25_200, 32_400), 30.0, config)], config)
    for slot in (7, 8):
        fit = actuated[slot]
        p.eq(
            f"(c) {slot}시 (C, 녹색, 적색, IQR, 감응, 주기 표본 수, 주기 값)",
            (140.0, 30.0, 110.0, 40.0, True, 26, [100.0, 120.0, 140.0, 160.0, 180.0]),
            (fit.cycle_s, fit.green_s, fit.red_s, fit.iqr_s, fit.actuated, len(fit.gap_samples_s), sorted(set(fit.gap_samples_s))),
        )
    gap_rows = [row for row in base if not 27_000 <= row[0] < 27_300]
    gap_day = signal_day_samples(gap_rows, 30.0, config)
    p.eq("(d) 관측 공백과 버린 간격", (((26_970.0, 27_300.0),), 1), (gap_day.outages, gap_day.dropped_gaps))
    gap_fits = fit_signal_slots([gap_day], config)
    p.eq("(d) 7시 (주기 표본, 녹색 표본, C)", (21, 22, 150.0), (gap_fits[7].n_gaps, gap_fits[7].n_greens, gap_fits[7].cycle_s))
    p.eq("(d) 8시는 (a)와 같다", (True, 150.0, 30.0, 120.0, 0.0, False, 24, 24), _fit_view(gap_fits[8]))
    early = fit_signal_slots([signal_day_samples(_fixed_signal_obs(24_300, 28_800), 30.0, config)], config)
    p.eq("(e) 6시 (학습, 주기 표본, 합친 시간대)", (True, 30, (6, 7)), (early[6].learned, early[6].n_gaps, early[6].merged_slots))
    p.eq("(e) 7시 (주기 표본, 합친 시간대)", (24, (7,)), (early[7].n_gaps, early[7].merged_slots))
    short = fit_signal_slots([signal_day_samples(_fixed_signal_obs(25_200, 26_400), 30.0, config)], config)
    p.eq("(f) 7시 (학습, 주기 표본, 합친 시간대)", (False, 8, (7,)), (short[7].learned, short[7].n_gaps, short[7].merged_slots))
    p.eq("전환 묶기: 첫 값과 2초 이하면 한 묶음", [101.0, 110.0], group_switches([100.0, 101.0, 102.0, 110.0], 2.0))
    p.eq("관측 공백: 조회 주기 30초의 1.5배를 넘는 간격", [(60.0, 120.0)], observation_outages([0.0, 30.0, 60.0, 120.0, 150.0], 30.0, 1.5))


def _v17(p: _Probe) -> None:
    values = (5.0, 1.0, 3.0, 3.0, 9.0)
    weights = (0.1, 0.2, 0.3, 0.1, 0.3)
    for q, want in ((0.1, 1.0), (0.2, 1.0), (0.5, 3.0), (0.6, 3.0), (0.65, 5.0), (0.7, 5.0), (0.9, 9.0), (1.0, 9.0)):
        p.eq(f"가중 분위수 q {q}", want, weighted_quantile(values, weights, q))
    flat = tuple(float(i) for i in range(1, 11))
    for q, want in ((0.1, 1.0), (0.5, 5.0), (0.9, 9.0), (0.95, 10.0)):
        p.eq(f"같은 무게 1 ~ 10, q {q}", want, weighted_quantile(flat, (1.0,) * 10, q))
    margins = [-12.0] + [float(v) for v in range(20, 220)] + [500.0] + [math.inf] * 3
    hist = margin_histogram(margins, None, 30.0, 5.0)
    p.eq("막대그래프 1: (점, 칸 수, 첫 칸, 끝 칸)", (205, 40, (20.0, 5), (215.0, 5)), (hist.n_points, len(hist.bins), hist.bins[0], hist.bins[-1]))
    p.eq("막대그래프 1: 칸마다 5점, 합 200", (True, 200), (all(count == 5 for _, count in hist.bins), sum(count for _, count in hist.bins)))
    p.eq("막대그래프 1: (아래, 위, 무한)", (1, 1, 3), (hist.n_under, hist.n_over, hist.n_infinite))
    p.close("막대그래프 1: 성공 질량 191/205", 191 / 205, hist.success_mass, 1e-6)
    hist = margin_histogram([31.0, 33.5, 34.9, 35.0, 47.2, math.inf], None, 30.0, 5.0)
    p.eq("막대그래프 2: 칸", ((30.0, 3), (35.0, 1), (40.0, 0), (45.0, 1)), hist.bins)
    p.eq("막대그래프 2: 점 수", 6, hist.n_points)
    p.close("막대그래프 2: 성공 질량 5/6", 5 / 6, hist.success_mass, 1e-6)
    hist = margin_histogram([40.0] * 7, None, 30.0, 5.0)
    p.eq("막대그래프 3: 칸 하나, 성공 질량 1", (((40.0, 7),), 1.0), (hist.bins, hist.success_mass))
    hist = margin_histogram([math.inf] * 4, None, 30.0, 5.0)
    p.eq("막대그래프 4: (칸, 점, 무한, 성공 질량)", ((), 4, 4, 0.0), (hist.bins, hist.n_points, hist.n_infinite, hist.success_mass))


def _v18(p: _Probe) -> None:
    config = EngineConfig()
    cycles = (100.0, 120.0, 140.0, 160.0, 180.0)
    phase = _v_signal("A", 30, 110, gaps=cycles)
    mean, var = stochastic_wait(phase)
    p.close("E[W] (주기 길이로 가중)", 46.0714, mean, 0.01)
    p.close("Var", 1675.0425, var, 0.01)
    fixed_mean, fixed_var = stochastic_wait(_v_signal("F", 30, 110))
    p.close("주기 140 고정 신호로 보면 E[W]", 43.2143, fixed_mean, 0.01)
    p.close("주기 140 고정 신호로 보면 Var", 1301.5731, fixed_var, 0.01)
    naive = sum(max(0.0, c - 30) ** 2 / (2 * c) for c in cycles) / len(cycles)
    p.close("같은 무게로 평균하면 43.3554 (틀린 값)", 43.3554, naive, 0.01)
    p.true("엔진의 E[W] 는 같은 무게 평균과 다르다", abs(mean - naive) > 1)
    theta, cycle = sample_signal_phase(phase, halton_column(3, 8))
    for i, (want_theta, want_cycle) in enumerate(
        zip((13.3333, 106.6667, 77.7778, 91.1111, 24.4444, 55.5556, 28.8889, 102.2222), (140, 160, 100, 140, 180, 120, 160, 180))
    ):
        p.close(f"표본 {i + 1}: θ", want_theta, float(theta[i]), 0.01)
        p.eq(f"표본 {i + 1}: 주기", float(want_cycle), float(cycle[i]))
    steps = (_walk_s(100, config), signal_step("A"), _walk_s(60, config))
    dense_config = EngineConfig(n_qmc=131_072)
    for dep, want, want_dense, want_fixed in ((300, 0.888449, 0.888459, 0.934906), (250, 0.620499, 0.620229, 0.624352)):
        result = arrival_probability(steps, dep - 30, {"A": phase}, config)
        p.close(f"dep {dep}: 확률", want, result.probability, 1e-5)
        p.eq(f"dep {dep}: 방법", ProbMethod.QMC, result.method)
        p.close(f"dep {dep}: 점 131,072개", want_dense, arrival_probability(steps, dep - 30, {"A": phase}, dense_config).probability, 1e-5)
        fixed = arrival_probability(steps, dep - 30, {"A": _v_signal("A", 30, 110)}, config)
        p.close(f"dep {dep}: 고정 신호로 다루면 (틀린 값)", want_fixed, fixed.probability, 1e-5)
    p.close("최악 대기: 감응 A (180 − 30)", 150.0, worst_wait(phase), 0.01)
    p.close("최악 대기: 미개방 고정 40 / 80", 80.0, worst_wait(_v_signal("U", 40, 80)), 0.01)
    p.close("WORST 규칙의 신호 이벤트", 150.0, signal_event(phase, 0.0, WaitRule.WORST).wait_s, 0.01)


# --- 4단계 검사의 공통 자료 (§9.5, §9.2 V11, §9.6) ---

_SRC_P, _SRC_E, _SRC_H = TimeSource.PREDICTED, TimeSource.EXTENDED, TimeSource.HEADWAY
_RT_P, _RT_D = RunTimeSource.PREDICTION, RunTimeSource.DESIGN
_ALL_RUNS = tuple(SearchRun)


def _warning_view(warnings: Iterable[EngineWarning]) -> tuple[tuple[WarningCode, tuple[str, ...]], ...]:
    """경고의 (코드, ref_ids) 목록."""
    return tuple((warning.code, warning.ref_ids) for warning in warnings)


def _round_view(rounds: Iterable[SearchRoundTrace]) -> tuple[tuple[int, int, int, int, float | None], ...]:
    """라운드 기록의 (k, 새 걷기 라벨 수, 표시된 정류장 수, 훑은 노선 수, 최선 D 도착) (§1.10.5)."""
    return tuple((r.round, r.new_labels, r.marked_stops, r.routes_scanned, r.best_d_s) for r in rounds)


def _labels_view(result: RunResult) -> tuple[tuple[float, int, int, str], ...]:
    """실행 결과의 D 파레토 라벨과 되짚은 여정: (도착, 탑승 수, b, 여정 ID)."""
    return tuple((t, rides, b, journey.itinerary_id) for (t, rides, b, _k, _f), journey in zip(result.d_labels, result.journeys))


def _trace_view(trace: SearchRunTrace) -> tuple[tuple, tuple[str, ...]]:
    """탐색 기록의 ((도착, 탑승 수, b) 라벨들, 여정 ID 들)."""
    return trace.d_labels, trace.itinerary_ids


def _trip_label(trips: TripSet, row: int | None) -> str | None:
    return None if row is None else trips.trip_ids[row]


# --- TR1 ~ TR12 버스 차량 시각, 탈 수 있는 차량, 노선 묶음 (§9.5.1) ---


def _tr_item(
    rank: int,
    vehicle: str = "",
    eta: float | None = None,
    *,
    kind: PredictionKind = PredictionKind.NORMAL,
    last: bool = False,
    full: bool = False,
    sect: int | None = None,
) -> StopPrediction:
    """TR 표의 예측 항목: (순위, 차량, eta_s) 와 표시."""
    return StopPrediction(
        rank=rank, vehicle_id=vehicle, kind=kind, eta_s=None if eta is None else float(eta), is_last=last, is_full=full, sect_ord=sect
    )


def _tr_line(rows: Sequence[Sequence[StopPrediction]], *, headway: float | None = 600.0, last_departure: float | None = None) -> BusLine:
    """TR 의 노선: ID "L", 정류장 s0, s1, …, 구간 500.004 m (설계 운행시간 120 s), 배차 간격 600 s (§9.5.1)."""
    n = len(rows)
    return BusLine(
        id="L",
        name="L",
        route_type=BusRouteType.BRANCH,
        real_route=False,
        stop_ids=tuple(f"s{index}" for index in range(n)),
        segment_dist_m=tuple([500.004] * (n - 1)),
        headway_s=headway,
        last_departure_clock_s=last_departure,
        predictions=tuple(tuple(row) for row in rows),
    )


def _tr_inputs() -> dict[str, tuple[BusLine, float]]:
    """TR1 ~ TR9, TR11 의 입력 (노선, 기준 시각 c0). I6 도 같은 입력을 쓴다."""
    i, c0 = _tr_item, 28_800.0
    same_three = [[], [i(1, "a", 100)], [i(1, "a", 220)]]
    return {
        "TR1": (
            _tr_line([[i(1, "b", 400)], [i(1, "a", 30), i(2, "b", 500)], [i(1, "a", 130), i(2, "b", 610)], [i(1, "a", 260)], [i(1, "a", 380)]]),
            c0,
        ),
        "TR2 (가)": (_tr_line([[i(1, "a", 100), i(2, "a", 95)], [i(1, "a", 90)], [i(1, "a", 200)]]), c0),
        "TR2 (나)": (_tr_line([[i(1, "a", 100)], [], [i(1, "a", 150)]]), c0),
        "TR3 (가)": (
            _tr_line(
                [
                    [i(1, "y", 50, sect=5), i(2, "x", 80, sect=7)],
                    [i(1, "x", 200, sect=7), i(2, "y", 230, sect=6)],
                    [i(1, "y", 300, sect=6), i(2, "x", 320, sect=8)],
                ]
            ),
            c0,
        ),
        "TR3 (나)": (_tr_line([[i(1, "p", 100), i(2, "q", 60)], [i(1, "q", 150), i(2, "p", 210)]]), c0),
        "TR4": (_tr_line([[i(1, "a", 100), i(2, kind=PredictionKind.ENDED)], [i(1, "a", 230)], []]), c0),
        "TR5": (_tr_line([[i(1, "a", 100, last=True), i(2, "b", 700)], [i(1, "a", 250, last=True), i(2, "b", 850)]]), c0),
        "TR6 (가)": (_tr_line(same_three, last_departure=80_400.0), 79_000.0),
        "TR6 (나)": (_tr_line(same_three, last_departure=87_000.0), 85_000.0),
        "TR7": (_tr_line([[i(1, "a", 100)], [i(1, "a", 220)]], headway=None), c0),
        "TR8": (_tr_line([[i(1, "0", kind=PredictionKind.WAITING), i(2, kind=PredictionKind.NO_INFO)], [i(1, kind=PredictionKind.ENDED)]]), c0),
        "TR9": (_tr_line([[i(1, "a", 100, full=True), i(2, "b", 700)], [i(1, "a", 220), i(2, "b", 820, full=True)]]), c0),
        "TR11": (_tr_line([[i(1, "a", 100), i(2, "b", 700, full=True)], [i(1, "a", 220, full=True), i(2, "b", 820)], [], []]), c0),
    }


def _tr_trips(case: str, config: EngineConfig | None = None) -> TripSet:
    line, clock = _tr_inputs()[case]
    return build_bus_trips(line, clock, config if config is not None else EngineConfig())


def _tr_vehicle(p: _Probe, case: str, trips: TripSet, trip_id: str, times: tuple, sources: tuple | None = None) -> None:
    """차량 하나의 순번별 시각(없으면 None)과 출처를 비교한다."""
    row = trips.row_of(trip_id)
    if not p.true(f"{case}: {trip_id} 가 있다", row is not None, f"차량 {trips.trip_ids}"):
        return
    p.approx(f"{case}: {trip_id} 시각", times, trips.times(row))
    if sources is not None:
        p.eq(f"{case}: {trip_id} 출처", sources, trips.sources[row])


def _tr_ids(*known: str, synthetic: int = 0) -> tuple[str, ...]:
    return tuple(f"L:{vehicle}" for vehicle in known) + tuple(f"L:+{k}" for k in range(1, synthetic + 1))


def _tr1(p: _Probe) -> None:
    trips = _tr_trips("TR1")
    p.approx("r", (100.0, 100.0, 130.0, 120.0), trips.run_s)
    p.eq("r 의 출처", (_RT_P,) * 4, trips.run_sources)
    p.eq("차량 13대 (a 가 b 보다 앞)", _tr_ids("a", "b", synthetic=11), trips.trip_ids)
    _tr_vehicle(p, "TR1", trips, "L:a", (None, 30.0, 130.0, 260.0, 380.0), (None, _SRC_P, _SRC_P, _SRC_P, _SRC_P))
    _tr_vehicle(p, "TR1", trips, "L:b", (400.0, 500.0, 610.0, 740.0, 860.0), (_SRC_P, _SRC_P, _SRC_P, _SRC_E, _SRC_E))
    _tr_vehicle(p, "TR1", trips, "L:+1", (1000.0, 1100.0, 1210.0, 1340.0, 1460.0), (_SRC_H,) * 5)
    _tr_vehicle(p, "TR1", trips, "L:+11", (7000.0, 7100.0, 7210.0, 7340.0, 7460.0), (_SRC_H,) * 5)
    p.eq("L:+12 는 만들지 않는다 (s0 7,600 > horizon_s)", None, trips.row_of("L:+12"))
    p.eq("경고 없음, 쓸 수 있음", ((), True), (trips.warnings, trips.usable))
    p.approx(
        "s3 에서 본 차량 순서 (앞 3대)",
        (("L:a", 260.0, _SRC_P), ("L:b", 740.0, _SRC_E), ("L:+1", 1340.0, _SRC_H)),
        stop_vehicle_order(trips, 3)[:3],
    )


def _tr2(p: _Probe) -> None:
    trips = _tr_trips("TR2 (가)")
    p.eq("(가) 경고 (코드, ref_ids)", ((WarningCode.PREDICTION_NOT_MONOTONE, ("L", "a")),), _warning_view(trips.warnings))
    p.true("(가) 경고의 고친 순번 1개", bool(trips.warnings) and "1개 순번" in trips.warnings[0].message, trips.warnings[0].message if trips.warnings else "")
    _tr_vehicle(p, "(가)", trips, "L:a", (95.0, 95.0, 200.0), (_SRC_P, _SRC_P, _SRC_P))
    p.approx("(가) r", (0.0, 105.0), trips.run_s)
    p.eq("(가) r 의 출처", (_RT_P, _RT_P), trips.run_sources)
    _tr_vehicle(p, "(가)", trips, "L:+1", (695.0, 695.0, 800.0))
    _tr_vehicle(p, "(가)", trips, "L:+11", (6695.0, 6695.0, 6800.0))
    p.eq("(가) 차량 12대", _tr_ids("a", synthetic=11), trips.trip_ids)
    trips = _tr_trips("TR2 (나)")
    _tr_vehicle(p, "(나)", trips, "L:a", (100.0, 220.0, 220.0), (_SRC_P, _SRC_E, _SRC_P))
    p.approx("(나) r", (120.0, 120.0), trips.run_s)
    p.eq("(나) r 의 출처 (함께 관측된 차량이 없다)", (_RT_D, _RT_D), trips.run_sources)
    p.eq("(나) 경고 없음 (관측을 연장 시각으로 올린 것은 경고하지 않는다)", (), trips.warnings)
    p.eq("(나) 차량 12대", 12, trips.n_trips)


