# --- I1 ~ I6 불변식 (§9.6, 4단계) ---


def _i_grid_phases() -> list[SignalPhase]:
    """I1, I2 의 개방 고정 신호 격자: (녹색, 적색) ∈ {25, 30, 45} × {0, 60, 120}, 오프셋 0 부터 주기까지 7 s 간격."""
    phases: list[SignalPhase] = []
    for green in (25.0, 30.0, 45.0):
        for red in (0.0, 60.0, 120.0):
            cycle = green + red
            for step in range(int(math.ceil(cycle / 7.0))):
                phases.append(
                    SignalPhase(
                        id=f"G{green:g}R{red:g}T{7 * step}", intersection_id="N", green_s=green, red_s=red, offset_s=7.0 * step, realtime_open=True
                    )
                )
    return phases


def _i_times(cycle: float) -> list[float]:
    """0 부터 주기의 2배까지 3.5 s 간격."""
    return [3.5 * j for j in range(int(2 * cycle / 3.5) + 1)]


def _i_sampled_phases() -> list[SignalPhase]:
    """위상을 모르는 신호: 미개방 고정 격자와 골든 SG2 의 주기 표본 세 가지."""
    sg2 = next(phase for phase in golden_scenario().signals if phase.id == "SG2")
    phases = [
        SignalPhase(id=f"F{green:g}R{red:g}", intersection_id="N", green_s=green, red_s=red, realtime_open=False)
        for green in (25.0, 30.0, 45.0)
        for red in (0.0, 60.0, 120.0)
    ]
    phases += [sg2.model_copy(update={"id": f"SG2-{len(gaps)}", "gap_samples_s": gaps}) for gaps in ((60.0,), (60.0, 90.0), (90.0, 120.0, 150.0, 180.0))]
    return phases + [sg2]


def _i1(p: _Probe) -> None:
    count, bad = 0, []
    for phase in _i_grid_phases():
        for t in _i_times(phase.cycle_s):
            event = deterministic_wait(phase, t)
            count += 1
            if not (0.0 <= event.wait_s <= phase.red_s and event.tau_s is not None and 0.0 <= event.tau_s < phase.cycle_s):
                bad.append(f"{phase.id} t {t:g}: 대기 {event.wait_s}, τ {event.tau_s}")
    p.true(f"개방 고정 신호: 0 ≤ W_det ≤ T_red, 0 ≤ τ < C ({count:,}점)", not bad, bad[0] if bad else "모두 맞음")
    for phase in _i_sampled_phases():
        mean, _var = stochastic_wait(phase)
        p.true(f"{phase.id}: E[W] ≤ 최악 대기", mean <= worst_wait(phase) + 1e-12, f"E[W] {mean:.4f}, 최악 {worst_wait(phase):.4f}")


def _i2(p: _Probe) -> None:
    golden = golden_scenario()
    phases = _i_grid_phases() + _i_sampled_phases() + list(golden.signals)
    for rule in WaitRule:
        bad = []
        for phase in phases:
            previous = -math.inf
            for t in _i_times(phase.cycle_s):
                leave = t + signal_event(phase, t, rule).wait_s
                if leave < previous - 1e-9:
                    bad.append(f"{phase.id} t {t:g}: {leave} < {previous}")
                    break
                previous = leave
        p.true(f"{rule.value}: t + w(t) 가 줄지 않는다 (신호 {len(phases)}개)", not bad, bad[0] if bad else "모두 맞음")
    config = EngineConfig()
    graph = _sr_context(golden, config, golden_query()).graph
    hops = {hop.signal_id: hop for table in graph.adjacency.values() for hops_ in table.values() for hop in hops_ if hop.signal_id}
    mismatch = []
    for signal_id, hop in sorted(hops.items()):
        phase = graph.signals[signal_id]
        for rule in WaitRule:
            for t in _i_times(phase.cycle_s):
                if abs(graph.hop_wait(hop, t, rule) - signal_event(phase, t, rule).wait_s) > 1e-9:
                    mismatch.append(f"{signal_id} {rule.value} t {t:g}")
    p.true("탐색의 엣지 대기와 신호 이벤트의 대기가 같다 (골든 신호 4개, 대기 규칙 3가지)", len(hops) == 4 and not mismatch, mismatch[0] if mismatch else f"신호 {sorted(hops)}")


_PRUNING_GAMMAS = (1.0, 1.05, 1.1, 1.3, 1.6, 2.0)


def _pruning_steps(scenario: Scenario, origin: str, destination: str, base: EngineConfig) -> list[tuple[float, float | None, list[str], list[str], int]]:
    """I3: γ 를 차례로 키우며 가지치기한 결과. 단계마다 (γ, 앞 단계의 γ, 빠진 승하차·역 안 노드, 앞 단계에서 남았는데 빠진 노드, 유지 수).
    설정은 base 에서 γ 만 바꾼다."""
    always = {
        node.id for node in scenario.nodes if node.node_type in (NodeType.BUS_STOP, NodeType.SUBWAY_PLATFORM, NodeType.STATION_HALL)
    }
    steps: list[tuple[float, float | None, list[str], list[str], int]] = []
    previous: tuple[float, frozenset[str]] | None = None
    for gamma in _PRUNING_GAMMAS:
        config = EngineConfig.model_validate({**base.model_dump(), "gamma": gamma})
        _summary, _records, kept = prune_by_ellipse(scenario, origin, destination, config)
        lost = sorted(previous[1] - kept) if previous is not None else []
        steps.append((gamma, previous[0] if previous is not None else None, sorted(always - kept), lost, len(kept)))
        previous = (gamma, kept)
    return steps


def _i3(p: _Probe) -> None:
    golden = golden_scenario()
    cases = [(name, golden, origin, "D") for name, origin in (("기본 질의", "S"), ("버스 질의", "B2"), ("열차 질의", "P2"))]
    for scenario_id, scenario in build_scenarios().items():
        query = scenario.default_query
        cases.append((f"{scenario_id} 기본 질의", scenario, _query_origin_node(scenario, query), query.destination_node_id))
    for name, scenario, origin, destination in cases:
        for gamma, before, missing, lost, kept in _pruning_steps(scenario, origin, destination, EngineConfig()):
            p.true(f"{name} γ {gamma:g}: 승하차·역 안 노드가 모두 남는다", not missing, f"빠짐 {missing}" if missing else f"유지 {kept}")
            if before is not None:
                p.true(f"{name}: γ {before:g} 에서 남은 노드는 γ {gamma:g} 에서도 남는다", not lost, f"빠짐 {lost}" if lost else "포함")


def _simple_paths(adjacency: dict[str, tuple[Hop, ...]], src: str, dst: str) -> list[tuple[Hop, ...]]:
    """src 에서 dst 까지 노드가 겹치지 않는 모든 경로(같은 두 노드 사이의 엣지는 따로 센다)."""
    paths: list[tuple[Hop, ...]] = []
    trail: list[Hop] = []
    visited = {src}

    def extend(node: str) -> None:
        if node == dst:
            paths.append(tuple(trail))
            return
        for hop in adjacency.get(node, ()):
            if hop.to_id in visited:
                continue
            visited.add(hop.to_id)
            trail.append(hop)
            extend(hop.to_id)
            trail.pop()
            visited.discard(hop.to_id)

    extend(src)
    return paths


def _path_arrival(signals: dict[str, SignalPhase], hops: Sequence[Hop], t0: float, speed: float, rule: WaitRule) -> float:
    """경로를 차례로 지나 도착 시각을 구한다(신호 대기는 signal_event 로 따로 계산)."""
    t = t0
    for hop in hops:
        if hop.signal_id is not None:
            t += signal_event(signals[hop.signal_id], t, rule).wait_s
        t += hop.length_m / speed
    return t


def _i4(p: _Probe) -> None:
    config = EngineConfig()
    graph = _sr_context(golden_scenario(), config, golden_query()).graph
    cases = ((Mode.WALK, "S", ("B1", "B2", "B4", "P1", "D"), config.v_walk_mps), (Mode.BIKE, "K1", ("K2",), config.v_pm_mps))
    for mode, src, targets, speed in cases:
        paths = {target: _simple_paths(graph.adjacency[mode], src, target) for target in targets}
        for rule in WaitRule:
            worst, fifo, previous = 0.0, [], dict.fromkeys(targets, -math.inf)
            for step in range(86):
                t0 = 7.0 * step
                labels = td_dijkstra(graph, [(src, t0)], mode, speed, rule)
                for target in targets:
                    best = min(_path_arrival(graph.signals, path, t0, speed, rule) for path in paths[target])
                    got = labels.times.get(target, math.inf)
                    worst = max(worst, abs(got - best))
                    if got < previous[target] - 1e-9:
                        fifo.append(f"{target} t0 {t0:g}")
                    previous[target] = got
            count = sum(len(items) for items in paths.values())
            p.true(
                f"{mode.value} {src} → {', '.join(targets)} {rule.value}: 열거한 최소 도착과 같다 (단순 경로 {count}개, 출발 86개)",
                worst <= 0.01,
                f"최대 차이 {worst:.2e} s",
            )
            p.true(f"{mode.value} {src} {rule.value}: 출발이 늦으면 도착도 늦거나 같다", not fifo, fifo[0] if fifo else "FIFO")


def _journey_time_under(context: SearchContext, journey: Journey, conditions: RunConditions, config: EngineConfig) -> float | None:
    """여정을 실행 조건(속도 배수, 대기 규칙, 승차 여유, NAIVE 의 기존 방식 시각 모형)으로 다시 지나 도착 시각을 구한다."""
    signals = context.graph.signals
    walk_speed = conditions.m * config.v_walk_mps
    bike_factor = 1.0 + config.k_pm / config.k_move * (conditions.m - 1.0) if config.k_move > 0 else 1.0
    bike_speed = bike_factor * config.v_pm_mps
    virtual_from = 1 if conditions.naive and config.naive_transfer_wait == NaiveTransferWait.ZERO else len(journey.rides)
    if journey.in_vehicle:
        first = journey.rides[0]
        t = float(context.routes[first.route_id].trips.arr[context.origin_row, first.alight_index])
    else:
        t = 0.0
    for number, move in enumerate(journey.moves):
        if move.has_bike:
            t = _path_arrival(signals, move.walk_in, t, walk_speed, conditions.rule) + config.t_unlock_s
            t = _path_arrival(signals, move.ride, t, bike_speed, conditions.rule) + config.t_dock_s
            t = _path_arrival(signals, move.walk_out, t, walk_speed, conditions.rule)
        else:
            t = _path_arrival(signals, move.walk or (), t, walk_speed, conditions.rule)
        ride_number = number + (1 if journey.in_vehicle else 0)
        if ride_number >= len(journey.rides):
            continue
        ride = journey.rides[ride_number]
        route = context.routes[ride.route_id]
        if ride_number >= virtual_from:
            t = t + route.pi_arr[ride.alight_index] - route.pi_dep[ride.board_index]
        else:
            row = route.board.first_row(ride.board_index, t + conditions.buffer_s)
            if row is None:
                return None
            t = float(route.trips.arr[row, ride.alight_index])
    return t


def _label_problems(context: SearchContext, config: EngineConfig) -> tuple[int, float, list[str]]:
    """I5: 실행마다 D 의 라벨을 되짚은 여정을 그 실행의 조건으로 다시 계산해 라벨 시각, (탑승 수, 따릉이 수), 여정 모양을 본다.
    (라벨 수, 라벨과 다시 계산한 시각의 최대 차이, 문제)를 돌려준다."""
    count, worst, problems = 0, 0.0, []
    for run in SearchRun:
        result = search_run(context, run, config)
        for (t, rides, b, _k, _f), journey in zip(result.d_labels, result.journeys):
            count += 1
            again = _journey_time_under(context, journey, result.conditions, config)
            bikes = sum(1 for move in journey.moves if move.has_bike)
            if again is None or abs(again - t) > 0.01:
                problems.append(f"{run.value} {journey.itinerary_id}: 라벨 {t:.4f}, 다시 계산 {again}")
                continue
            worst = max(worst, abs(again - t))
            if (rides, b) != (len(journey.rides), bikes):
                problems.append(f"{run.value} {journey.itinerary_id}: 라벨 (탑승 {rides}, b {b}) ≠ 여정 ({len(journey.rides)}, {bikes})")
            problems.extend(f"{run.value} {journey.itinerary_id}: {item}" for item in _journey_shape_problems(context, journey))
    return count, worst, problems


def _i5(p: _Probe) -> None:
    for name, context, config in _invariant_search_targets():
        count, worst, problems = _label_problems(context, config)
        p.true(
            f"{name}: D 라벨 {count}개를 실행 조건으로 다시 계산",
            (count > 0) != (name == "γ 1.0") and not problems,
            problems[0] if problems else f"최대 차이 {worst:.2e} s",
        )


def _trip_set_problems(trips: TripSet, headway_s: float | None, horizon_s: float) -> list[str]:
    """I6: 추월 없음, 알려진 차량 시각이 순번을 따라 줄지 않음, 합성 차량의 간격·출처·기점 시각."""
    problems: list[str] = []
    dep = trips.dep
    for row in range(trips.n_trips - 1):
        for index in range(trips.n_stops):
            for array in (trips.dep, trips.arr):
                ahead, behind = array[row, index], array[row + 1, index]
                if not (math.isnan(ahead) or math.isnan(behind)) and ahead > behind:
                    problems.append(f"{trips.trip_ids[row + 1]} 가 순번 {index} 에서 앞 차량을 추월한다")
    for row in range(trips.n_known):
        values = [value for value in dep[row] if not math.isnan(value)]
        if any(a > b for a, b in zip(values, values[1:])):
            problems.append(f"{trips.trip_ids[row]} 의 시각이 순번을 따라 줄어든다")
    if trips.n_synthetic:
        rear = trips.n_known - 1
        first = next(index for index in range(trips.n_stops) if not math.isnan(dep[rear, index]))
        for k in range(1, trips.n_synthetic + 1):
            row = rear + k
            if any(source != TimeSource.HEADWAY for source in trips.sources[row]):
                problems.append(f"{trips.trip_ids[row]} 의 출처가 HEADWAY 가 아니다")
            if dep[row, 0] > horizon_s:
                problems.append(f"{trips.trip_ids[row]} 의 첫 순번 시각 {dep[row, 0]:g} > horizon_s")
            gaps = [dep[row, index] - dep[rear, index] - k * (headway_s or 0.0) for index in range(first, trips.n_stops)]
            if headway_s is None or any(abs(gap) > 1e-6 for gap in gaps):
                problems.append(f"{trips.trip_ids[row]} 가 맨 뒤 차량과 {k}H 떨어지지 않았다")
    return problems


def _board_problems(board: BoardIndex) -> list[str]:
    return [f"{board.route_id} 순번 {index} 의 출발 배열이 오름차순이 아니다" for index, deps in enumerate(board.deps) if np.any(np.diff(deps) < 0)]


def _sequence_problems(context: SearchContext, bundles: Iterable[tuple[tuple[str, int | None, int], ...]]) -> list[str]:
    """I6: 묶음마다 유효 차량열(§1.7.4)의 출발과 도착이 함께 줄지 않는다(둘 다 오름차순)."""
    problems: list[str] = []
    for bundle in bundles:
        sequence = ride_vehicles(context, bundle)
        if bool(np.any(np.diff(sequence.deps) < 0)) or bool(np.any(np.diff(sequence.arrs) < 0)):
            problems.append(f"묶음 {bundle} 의 유효 차량열이 오름차순이 아니다")
    return problems


def _route_problems(context: SearchContext, scenario: Scenario, config: EngineConfig) -> list[str]:
    """I6: 탐색 준비가 만든 노선마다 차량 시각 배열(추월, 순번 순서, 합성 차량)과 승차 색인의 출발 배열."""
    headways = {line.id: line.headway_s for line in scenario.bus_lines}
    problems: list[str] = []
    for route in context.routes.values():
        problems += _trip_set_problems(route.trips, headways.get(route.route_id), config.horizon_s)
        problems += _board_problems(route.board)
    return problems


def _i6(p: _Probe) -> None:
    for case, (line, clock) in _tr_inputs().items():
        problems: list[str] = []
        for policy in FullVehiclePolicy:
            config = EngineConfig(full_vehicle_policy=policy)
            trips = build_bus_trips(line, clock, config)
            problems += _trip_set_problems(trips, line.headway_s, config.horizon_s)
            problems += _board_problems(board_index(trips, line.stop_ids, frozenset(line.stop_ids), config))
        p.true(f"{case} 의 입력", not problems, problems[0] if problems else "맞음")
    for name, context in _tr12_contexts().items():
        bundles = sorted(
            {
                bundle
                for rides in _TR12_RIDES[name]
                for bundle in ride_bundles(context, rides)
                if all(board is not None for _line, board, _alight in bundle)
            }
        )
        problems = _sequence_problems(context, bundles)
        p.true(f"TR12 {name}: 묶음 {len(bundles)}개의 유효 차량열", not problems, problems[0] if problems else "맞음")
    full = golden_scenario().bus_lines[0]
    full_first = tuple(item.model_copy(update={"is_full": item.vehicle_id == "g1a"}) for item in full.predictions[0])
    last_rows = tuple(
        (StopPrediction(rank=1, vehicle_id="g2a", kind=PredictionKind.NORMAL, eta_s=eta, is_last=True),) for eta in (300.0, 480.0)
    )
    query = golden_query()
    scenarios = [
        ("골든", golden_scenario(), EngineConfig(), query),
        ("골든 막차 변형", golden_last_vehicle_scenario(), EngineConfig(), query),
        ("골든 만차 변형 (SKIP)", _sr_golden_variant("G1", (full_first,) + full.predictions[1:]), EngineConfig(full_vehicle_policy=FullVehiclePolicy.SKIP), query),
        ("골든 막차 하나 (SR9)", _sr_golden_variant("G2", last_rows), EngineConfig(), query),
    ]
    scenarios += [(scenario_id, scenario, EngineConfig(), scenario.default_query) for scenario_id, scenario in build_scenarios().items()]
    for name, scenario, config, case_query in scenarios:
        context = _sr_context(scenario, config, case_query)
        problems = _route_problems(context, scenario, config)
        p.true(f"{name}: 노선 {len(context.routes)}개", not problems, problems[0] if problems else "맞음")
        journeys, _summary = search_candidates(context, config)
        bundles = sorted({ride.lines for journey in journeys for ride in journey.rides if ride.board_index is not None})
        problems = _sequence_problems(context, bundles)
        p.true(f"{name}: 후보 여정의 탑승 {len(bundles)}가지의 유효 차량열", not problems, problems[0] if problems else "맞음")


# --- 5단계 검사의 공통 자료 (§9.5.3, §9.2 V12, §9.6) ---

_TOLERANCES = {"t": 0.01, "d": 0.05, "p": 1e-5, "m": 1e-5, "j": 1e-4, "=": 0.0}


def _fields(p: _Probe, label: str, expected: Sequence[Any], actual: Sequence[Any] | None, kinds: str) -> bool:
    """항목마다 허용 오차가 다른 비교(§9.0). kinds 의 글자는 t 시간, d 거리, p 확률, m 속도 배수, j 효용, = 정확히."""
    ok = (
        actual is not None
        and len(expected) == len(kinds) == len(actual)
        and all(_approx_equal(want, got, _TOLERANCES[kind]) for want, got, kind in zip(expected, actual, kinds))
    )
    return p.check(label, ok, f"기대 {_short(_rounded(expected), 400)}, 실제 {_short(_rounded(actual), 400)}")


def _ev_line(
    line_id: str,
    name: str,
    route_type: BusRouteType,
    stops: tuple[str, str],
    segment_m: float,
    headway_s: float,
    rows: tuple[tuple[tuple[int, str, float], ...], ...],
    *,
    last: bool = False,
) -> BusLine:
    """평가 검사의 작은 시나리오 노선(§9.5.3): 예측은 순번마다 (순위, 차량, eta_s), 모두 NORMAL. last 면 예측이 모두 막차다."""
    return BusLine(
        id=line_id,
        name=name,
        route_type=route_type,
        real_route=False,
        stop_ids=stops,
        segment_dist_m=(float(segment_m),),
        headway_s=float(headway_s),
        predictions=tuple(
            tuple(
                StopPrediction(rank=rank, vehicle_id=vehicle, kind=PredictionKind.NORMAL, eta_s=float(eta), is_last=last)
                for rank, vehicle, eta in row
            )
            for row in rows
        ),
    )


