def _ev_signals18() -> Scenario:
    """신호 18개: 50 m 마다 미개방 고정 신호(녹색 30, 적색 30)가 있는 직선 길(EV8). q(i+1) 의 신호 Qi 는 Xi 교차로다."""
    names = ["S", *(f"X{i:02d}" for i in range(1, 19)), "D"]
    nodes = [_sr_node("S", 0, 0, NodeType.PLACE), *(_sr_node(f"X{i:02d}", 50 * i, 0) for i in range(1, 19)), _sr_node("D", 950, 0, NodeType.PLACE)]
    edges = []
    for k in range(19):
        signal = f"Q{k:02d}" if k >= 1 else None
        edges.append(
            Edge(
                id=f"q{k + 1:02d}",
                source=names[k],
                target=names[k + 1],
                modes=_WALK,
                kind=EdgeKind.CROSSWALK if signal else EdgeKind.SIDEWALK,
                signal_id=signal,
                distance_m=50.0,
            )
        )
    signals = tuple(
        SignalPhase(id=f"Q{i:02d}", intersection_id=f"X{i:02d}", green_s=30.0, red_s=30.0, realtime_open=False) for i in range(1, 19)
    )
    return _sr_scenario("신호 18개", nodes, edges, signals=signals)


def _ev_last(eta_a: float) -> Scenario:
    """막차: 노선 U 의 차량이 막차 u1 하나다(EV9). (가) A 에 150, (나) A 에 80. A 와 Bz 를 잇는 걷는 길은 없다."""
    place, stop = NodeType.PLACE, NodeType.BUS_STOP
    line = _ev_line("U", "가상6", BusRouteType.VILLAGE, ("A", "Bz"), 300, 600, (((1, "u1", eta_a),), ((1, "u1", eta_a + 300),)), last=True)
    return _sr_scenario(
        "막차",
        (_sr_node("S", 0, 0, place), _sr_node("A", 100, 0, stop), _sr_node("Bz", 100, 300, stop), _sr_node("D", 140, 300, place)),
        (_sr_edge("u1", "S", "A", 100), _sr_edge("u2", "Bz", "D", 50)),
        lines=(line,),
    )


