_AC_Y = "가상Y선:하행:Y1-Y2:2"


def _ac_pattern(
    pattern_id: str, line: str, keys: tuple[str, str], platforms: tuple[str, str], segment_m: float, prefix: str, count: int, first_s: float, second_s: float, step_s: float
) -> SubwayPattern:
    """사례 검사의 두 역 정차 패턴(§9.5.4): 열차 {prefix}{k:02d} 는 첫 역에 first + k·step, 둘째 역에 second + k·step 에 닿고 바로 떠난다."""
    trips = tuple(
        SubwayTrip(
            id=f"{prefix}{k:02d}",
            train_no=f"{prefix}{k:02d}",
            service_day=DayType.WEEKDAY,
            arr_s=(first_s + step_s * k, second_s + step_s * k),
            dep_s=(first_s + step_s * k, second_s + step_s * k),
        )
        for k in range(count)
    )
    return SubwayPattern(
        id=pattern_id,
        line=line,
        direction="하행",
        station_keys=keys,
        platform_ids=platforms,
        segment_dist_m=(float(segment_m),),
        distance_verified=(True,),
        trips=trips,
    )


