def _same_as_v12a(p: _Probe, name: str, output: EngineOutput, ids: Sequence[str]) -> None:
    """후보 ID 와 값이 V12a 판정표와 같은지(상태와 순위 밖의 값)."""
    results = _by_id(output)
    p.eq(f"{name}: 후보 (ID 순)", tuple(sorted(ids)), tuple(results))
    for jid in ids:
        _fields(p, f"{name}: {jid} 의 값은 V12a 와 같다", _V12A_ROWS[jid], _result_row(results.get(jid)), _ROW_KINDS)


def _ranking_view(output: EngineOutput) -> tuple:
    """(대표 순위, 대표마다 아래 여정)."""
    results = _by_id(output)
    return output.ranking, tuple((jid, results[jid].variant_ids) for jid in output.ranking if results[jid].variant_ids)


def _step_view(step: ProfileStep) -> tuple:
    """프로필 단계를 §9.5.3 의 표기처럼 보인다: TRAVEL(수단, 거리), SIGNAL(신호), BOARD(번호), BIKE_GATE(번호), FIXED(초)."""
    if step.kind == StepKind.TRAVEL:
        return ("TRAVEL", step.mode.value, step.distance_m)
    if step.kind == StepKind.SIGNAL:
        return ("SIGNAL", step.signal_id)
    if step.kind in (StepKind.BOARD, StepKind.BIKE_GATE):
        return (step.kind.value, step.index)
    return (step.kind.value, step.seconds)


def _steps_view(steps: Sequence[ProfileStep] | None) -> tuple | None:
    return None if steps is None else tuple(_step_view(step) for step in steps)


def _walk_steps(*parts: Any) -> tuple:
    """기대 단계 표를 짧게 적는다: 숫자는 TRAVEL(WALK), 문자열은 SIGNAL, ("BOARD", l) 같은 튜플은 그대로."""
    out = []
    for part in parts:
        if isinstance(part, (int, float)):
            out.append(("TRAVEL", "WALK", float(part)))
        elif isinstance(part, str):
            out.append(("SIGNAL", part))
        else:
            out.append(part)
    return tuple(out)


def _trip_ids_of(evaluation: "_Evaluation", number: int, positions: np.ndarray) -> tuple[str | None, ...]:
    """실현의 탄 차량(유효 차량열 위치, −1 은 타지 못함)을 차량 ID 로 바꾼다."""
    ids = evaluation.vehicles(number).trip_ids
    return tuple(ids[int(position)] if position >= 0 else None for position in positions)


def _guided_fraction(evaluation: "_Evaluation") -> tuple[float, float]:
    """모든 $\\beta_b = 1$ 조합의 Halton 점 가운데 모든 탑승에서 안내 차량이나 더 이른 차량을 탄 비율과 $Q_L(g_L)$ (§1.4.5 (6))."""
    guides = evaluation.guide()
    if not guides:
        return 1.0, 1.0
    real = next(real for beta, _weight, real in evaluation.realizations() if beta == evaluation.ones)
    ok = np.ones(real.arrival.size, dtype=bool)
    for number, (ride, guide) in enumerate(zip(evaluation.journey.rides, guides)):
        if ride.board_index is None:
            continue
        limit = guide.position if guide.position is not None else -1
        taken = real.vehicles[number]
        ok &= (taken >= 0) & (taken <= limit)
    return float(np.mean(ok)), guides[-1].q_joint


def _histogram_problems(histogram: MarginHistogram, buffer: float) -> list[str]:
    """§1.4.7 의 막대그래프 모양: 점 수 합, 칸 경계가 $t_{buf} + 5j$ 꼴, 빈틈없이 이어짐."""
    problems = []
    total = sum(count for _left, count in histogram.bins) + histogram.n_under + histogram.n_over + histogram.n_infinite
    if total != histogram.n_points:
        problems.append(f"점 수 합 {total} ≠ n_points {histogram.n_points}")
    lefts = [left for left, _count in histogram.bins]
    for left in lefts:
        steps = (left - buffer) / histogram.bin_width_s
        if abs(steps - round(steps)) > 1e-9:
            problems.append(f"칸 경계 {left} 가 t_buf + 5j 꼴이 아니다")
            break
    if any(abs(b - a - histogram.bin_width_s) > 1e-9 for a, b in zip(lefts, lefts[1:])):
        problems.append("칸이 빈틈없이 이어지지 않는다")
    return problems


# --- EV1 ~ EV14 평가 (§9.5.3) ---


def _ev1(p: _Probe) -> None:
    config = EngineConfig()
    context = _sr_context(golden_scenario(), config, golden_query())
    journeys = {journey.itinerary_id: journey for journey in search_candidates(context, config)[0]}
    board1, board2 = ("BOARD", 1), ("BOARD", 2)
    fallback_p1 = _walk_steps(170, "SG2", 530, "SG4", 800)
    cases = (
        ("I469424fb69", _walk_steps(300, "SG2", 200, board1, 230), (fallback_p1,), (), {"SG2": 1}),
        ("I3a248c7d10", _walk_steps(560, board1, 230), (fallback_p1,), (), {"SG2": 1}),
        (
            "Ic5c1b22780",
            _walk_steps(50, ("BIKE_GATE", 1), ("FIXED", 25.0), ("TRAVEL", "BIKE", 850.0), "SG4", ("TRAVEL", "BIKE", 790.0), ("FIXED", 15.0), 70),
            (),
            (_walk_steps(850, "SG4", 800),),
            {},
        ),
        (
            "Ifbf4ec4c04",
            _walk_steps(170, board1, 20, "SG1", 40, board2, 20, "SG3", 60),
            (_walk_steps(670, "SG4", 800), _walk_steps(20, "SG1", 20, "SG4", 800)),
            (),
            {"SG1": 1},
        ),
    )
    for jid, steps, ride_fallbacks, bike_fallbacks, dims in cases:
        journey = journeys.get(jid)
        if journey is None:
            p.true(f"{jid}: 후보에 있다", False, "없음")
            continue
        profile = build_profile(journey, context, config)
        p.approx(f"{jid}: 본 프로필", steps, _steps_view(profile.steps))
        p.approx(f"{jid}: 탑승의 대체 보행", ride_fallbacks, tuple(_steps_view(steps) for steps in profile.ride_fallbacks))
        p.approx(f"{jid}: 따릉이 구간의 대체 보행", bike_fallbacks, tuple(_steps_view(steps) for steps in profile.bike_fallbacks))
        p.eq(f"{jid}: 표본 신호의 차원과 K", (dims, len(dims), ()), (profile.dims, len(profile.dims), profile.capped))


def _ev2(p: _Probe) -> None:
    config = EngineConfig()
    context = _sr_context(golden_scenario(), config, golden_query())
    journeys = {journey.itinerary_id: journey for journey in search_candidates(context, config)[0]}
    profile = build_profile(journeys["Ifbf4ec4c04"], context, config)
    m = np.array([0.8, 1.0, 1.25])
    table = {
        0.1: (12.0, ((170.0, 410.0, ("G1:g1a", "G2:g2b"), 1325.0), (136.0, 398.0, ("G1:g1a", "G2:g2b"), 1313.0), (108.8, 388.4, ("G1:g1a", "G2:g2a"), 673.4))),
        0.5: (60.0, ((170.0, 460.0, ("G1:g1a", "G2:g2b"), 1325.0), (136.0, 452.0, ("G1:g1a", "G2:g2b"), 1313.0), (108.8, 445.6, ("G1:g1a", "G2:g2b"), 1251.2))),
        0.9: (108.0, ((170.0, 412.0, ("G1:g1a", "G2:g2b"), 1325.0), (136.0, 404.0, ("G1:g1a", "G2:g2b"), 1313.0), (108.8, 397.6, ("G1:g1a", "G2:g2b"), 1251.2))),
    }
    evaluation = _Evaluation(journeys["Ifbf4ec4c04"], plan_schedule(journeys["Ifbf4ec4c04"], context, config), context, config)
    for u, (theta, rows) in table.items():
        real = realize(profile, m, {"SG1": (np.full(3, theta), np.full(3, 120.0))}, (), context)
        got = tuple(
            (float(real.stops[0][k]), float(real.stops[1][k]), (_trip_ids_of(evaluation, 0, real.vehicles[0])[k], _trip_ids_of(evaluation, 1, real.vehicles[1])[k]), float(real.arrival[k]))
            for k in range(3)
        )
        p.approx(f"Ifbf4ec4c04, SG1 u {u} (θ {theta:g}), m 0.8 / 1.0 / 1.25: (B1 도착, B4 도착, 탄 차량, T)", rows, got)
    profile = build_profile(journeys["I469424fb69"], context, config)
    evaluation = _Evaluation(journeys["I469424fb69"], plan_schedule(journeys["I469424fb69"], context, config), context, config)
    m = np.array([0.9, 1.0])
    table2 = {
        0.05: ((35.0, 100.0), ((444.4444, "1002", 974.4444), (425.0, "1002", 954.0))),
        0.5: ((130.0, 140.0), ((467.7778, "1002", 974.4444), (450.0, "1002", 954.0))),
        0.95: ((145.0, 180.0), ((572.7778, "1003", 1214.4444), (400.0, "1002", 954.0))),
    }
    for u, ((theta, cycle), rows) in table2.items():
        real = realize(profile, m, {"SG2": (np.full(2, theta), np.full(2, cycle))}, (), context)
        trips = _trip_ids_of(evaluation, 0, real.vehicles[0])
        got = tuple((float(real.stops[0][k]), trips[k], float(real.arrival[k])) for k in range(2))
        p.approx(f"I469424fb69, SG2 u {u} (θ {theta:g}, C {cycle:g}), m 0.9 / 1.0: (P1 도착, 탄 열차, T)", rows, got)


def _ev3(p: _Probe) -> None:
    config = EngineConfig()
    context = _sr_context(golden_scenario(), config, golden_query())
    journeys = {journey.itinerary_id: journey for journey in search_candidates(context, config)[0]}
    cases = (
        ("Idddde0a626", 136.0, (("G1:g1a", 200.0, 0.8, 0.952210), ("G1:g1b", 800.0, 0.176623, 1.0))),
        (
            "I3a248c7d10",
            448.0,
            (("1000", 60.0, 14.933333, 0.0), ("1001", 300.0, 1.659259, 1.97e-8), ("1002", 540.0, 0.878431, 0.844487), ("1003", 780.0, 0.597333, 0.999604)),
        ),
    )
    for jid, walk_s, vehicles in cases:
        journey = journeys[jid]
        evaluation = _Evaluation(journey, plan_schedule(journey, context, config), context, config)
        sequence = evaluation.vehicles(0)
        for trip_id, dep, m_star, chance in vehicles:
            closed = walk_s / (dep - config.safety_buffer_s)
            p.close(f"{jid} · {trip_id}: 닫힌 식 m* = {walk_s:g} / ({dep:g} − t_buf)", m_star, closed, 1e-5)
            values = evaluation.threshold(evaluation.ones, 0, sequence.position_of(trip_id))
            p.close(f"{jid} · {trip_id}: 이분법의 m*", m_star, float(values[0]), 1e-5)
            p.true(f"{jid} · {trip_id}: 모든 점의 m* 가 같다(승차 전 신호 없음)", float(np.ptp(values)) <= 1e-12, f"범위 {float(np.ptp(values)):g}")
            got = evaluation.chance(values)
            p.close(f"{jid} · {trip_id}: Pr[m ≥ m*]", chance, got, 1e-5)
            if 0 < chance < 1e-6:
                p.true(f"{jid} · {trip_id}: Pr[m ≥ m*] ≈ {chance:g} (상대 1%)", abs(got - chance) <= 0.01 * chance, f"{got:.4g}")
        if jid == "Idddde0a626":
            hi = float(evaluation.threshold(evaluation.ones, 0, sequence.position_of("G1:g1a"))[0])
            p.true("Idddde0a626 · G1:g1a: 이분법의 hi 는 0.8 보다 크고 2e-8 안", 0.8 < hi <= 0.8 + 2e-8, f"hi = {hi!r}")


def _ev4(p: _Probe) -> None:
    output = _run("EV4 긴 줄")
    results = _by_id(output)
    p.eq("여정 2개", ("I06ab726384", "I207f592df0"), tuple(results))
    bus = results.get("I06ab726384")
    if bus is None:
        return
    p.eq("I06ab726384: 이름과 구조 키", ("가상4번", '[[["H",0,1]],[null,null],[["w1"],["w2"]]]'), (bus.label, bus.structure_key))
    ride = bus.rides[0]
    p.approx("I06ab726384: 계획 (A 도착, 차량, 출발, Bz 하차, T_plan)", (960.0, "H:+15", 990.0, 1290.0, 1330.0), (ride.plan_stop_arrival_s, ride.plan_trip_id, ride.plan_dep_s, ride.plan_arr_s, bus.plan_arrival_s))
    stats = bus.arrival
    _fields(p, "I06ab726384: (평균, 10%, 50%, 90%, P*, 등급, 상태, 방법)", (1375.1683, 1204.6705, 1330.0, 1517.2750, 0.5, "RISKY", "RANKED", "EXACT"), (stats.mean_s, stats.p10_s, stats.p50_s, stats.p90_s, bus.p_star, bus.grade, bus.status, stats.method), "ttttp===")
    boarding = bus.boardings[0]
    _fields(p, "I06ab726384: 안내 차량 (m* = 960/960 = 1 이라 Q = 0.5)", ("H:+15", True, 0.5, 0.5), (boarding.guided_trip_id, boarding.guided_found, boarding.q_joint, boarding.p_conditional), "==pp")
    expected = (("H:+11", 750.0, 1050.0), ("H:+12", 810.0, 1110.0), ("H:+13", 870.0, 1170.0), ("H:+14", 930.0, 1230.0), ("H:+15", 990.0, 1290.0), ("H:+16", 1050.0, 1350.0))
    p.approx("I06ab726384: 차량 목록 (H:h2 ~ H:+16 의 17대 가운데 뒤 6대)", expected, tuple((v.trip_id, v.dep_s, v.alight_arr_s) for v in boarding.vehicles))
    p.approx("I06ab726384: 차량 목록의 p_catch", (0.002737, 0.027235, 0.116930, 0.289257, 0.5, 0.688002), tuple(v.p_catch for v in boarding.vehicles), 1e-5)
    evaluation = _evaluations("EV4 긴 줄")["I06ab726384"]
    guide = evaluation.guide()[0]
    first = evaluation.vehicles(0).trip_ids[guide.start] if guide.position is not None else None
    count = guide.position + 2 - guide.start if guide.position is not None else None
    p.eq("m_max 에서 탈 수 있는 첫 차는 H:h2 (안내 다음 차 H:+16 까지 17대)", ("H:h2", 17), (first, count))
    _fields(p, "I06ab726384: 기존 방식 차량 (차량, 정류장 도착, 여유, p_catch, 유령), T_naive", ("H:+15", 960.0, 30.0, 0.5, False, 1330.0), (boarding.naive_trip_id, boarding.naive_stop_arrival_s, boarding.naive_margin_s, boarding.p_catch_naive, boarding.ghost, bus.naive_promised_s), "=ttp=t")
    distribution = boarding.trip_distribution
    p.eq("탄 차량 분포: 18대 H:+11 ~ H:+28", (18, "H:+11", "H:+28"), (len(distribution), distribution[0][0], distribution[-1][0]) if distribution else None)
    top = tuple(sorted(distribution, key=lambda item: -item[1])[:4])
    p.approx("탄 차량 분포의 큰 넷", (("H:+15", 0.210938), ("H:+16", 0.187988), ("H:+14", 0.172363), ("H:+17", 0.134766)), top, 1e-5)
    walk = results.get("I207f592df0")
    p.approx("I207f592df0 도보 (T_plan, 평균)", ("도보", 3400.0, 3451.6560), (walk.label, walk.plan_arrival_s, walk.arrival.mean_s) if walk else None)


_EV5_TARGETS = (
    ("골든 기본", "I3a248c7d10", 0.844482, 0.844487),
    ("골든 기본", "I469424fb69", 0.812744, 0.816372),
    ("골든 기본", "Ic5c1b22780", 1.0, 1.0),
    ("골든 기본", "Idddde0a626", 0.952148, 0.952210),
    ("골든 기본", "If1e99436b8", 1.0, 1.0),
    ("골든 기본", "Ifbf4ec4c04", 0.952148, 0.952210),
    ("EV4 긴 줄", None, None, None),
    ("EV7 두 번 빌리기", None, None, None),
    ("EV9 막차 (가)", None, None, None),
)


def _ev5(p: _Probe) -> None:
    for name, jid, fraction, q_last in _EV5_TARGETS:
        evaluations = _evaluations(name)
        ids = (jid,) if jid is not None else tuple(evaluations)
        for itinerary_id in ids:
            got_fraction, got_q = _guided_fraction(evaluations[itinerary_id])
            if fraction is not None:
                p.approx(f"{name} {itinerary_id}: (점 비율, Q_L)", (fraction, q_last), (got_fraction, got_q), 1e-5)
            p.true(f"{name} {itinerary_id}: |점 비율 − Q_L| ≤ 0.01", abs(got_fraction - got_q) <= 0.01, f"{got_fraction:.6f} / {got_q:.6f}")


def _ev6(p: _Probe) -> None:
    names = ("골든 기본", "EV4 긴 줄", "EV7 두 번 빌리기", "EV9 막차 (가)")
    for name in names:
        output = _run(name)
        buffer = output.config.safety_buffer_s
        for result in output.itineraries:
            for boarding in result.boardings:
                histogram = boarding.histogram
                if histogram is None:
                    continue
                where = f"{name} {result.itinerary_id} · {boarding.ride_index}"
                problems = _histogram_problems(histogram, buffer)
                p.true(f"{where}: 막대그래프 모양", not problems, "; ".join(problems) or "점 수 합, 칸 경계, 이어짐 맞음")
                gap = abs(histogram.success_mass - boarding.p_conditional)
                p.true(f"{where}: |성공 질량 − 조건부 확률| ≤ 0.01", gap <= 0.01, f"{histogram.success_mass:.6f} / {boarding.p_conditional:.6f}")


