def _ev_result(
    template: ItineraryResult, jid: str, mean: float | None, p_star: float, fare: int, walk: float, ride_key: str, *,
    status: RouteStatus = RouteStatus.RANKED, p_on_time: float | None = None,
) -> ItineraryResult:
    """EV10, EV11 의 손으로 고친 결과: 분위수는 평균과 같게 둔다."""
    arrival = template.arrival.model_copy(update={"mean_s": mean, "p10_s": mean, "p50_s": mean, "p90_s": mean, "p_on_time": p_on_time})
    return template.model_copy(
        update={
            "itinerary_id": jid,
            "arrival": arrival,
            "p_star": p_star,
            "fare": template.fare.model_copy(update={"total_krw": fare}),
            "walk_distance_m": walk,
            "ride_key": ride_key,
            "status": status,
            "reasons": () if status == RouteStatus.RANKED else (ReasonCode.LOW_PLAN_PROBABILITY,),
        }
    )


def _ev10_results(on_time: tuple[float, ...] | None = None, same_ab: bool = False) -> list[ItineraryResult]:
    golden = _by_id(_run("골든 기본"))
    one, two = golden["Idddde0a626"], golden["Ifbf4ec4c04"]
    rows = (
        ("Ia", 1000.0000004, 0.90, 1500, one, 300.0, "r2" if same_ab else "r1"),
        ("Ib", 1000.0000001, 0.95, 1500, one, 300.0, "r2"),
        ("Ic", 1000.0000002, 0.95, 1400, two, 500.0, "r3"),
        ("Id", 999.9999996, 0.95, 1400, two, 400.0, "r4"),
        ("Ie", 999.9999996, 0.95, 1400, two, 400.0, "r5"),
    )
    return [
        _ev_result(template, jid, mean, p_star, fare, walk, key, p_on_time=on_time[k] if on_time else None)
        for k, (jid, mean, p_star, fare, template, walk, key) in enumerate(rows)
    ]


def _ev10(p: _Probe) -> None:
    query = golden_query()
    results = list(reversed(_ev10_results()))
    for criterion in (RankCriterion.MEAN_ARRIVAL, RankCriterion.P90_ARRIVAL):
        _updated, ranking, _pruned, best = rank_itineraries(results, query, EngineConfig(rank_criterion=criterion))
        p.eq(f"{criterion.value}: 순위 (모두 1,000.000000 이라 동점 규칙)", (("Id", "Ie", "Ic", "Ib", "Ia"), "Id"), (ranking, best))
    timed = list(reversed(_ev10_results(on_time=(0.8, 0.8, 0.9, 0.8, 0.8))))
    _updated, ranking, _pruned, best = rank_itineraries(timed, query.model_copy(update={"deadline_s": 1000.0}), EngineConfig(rank_criterion=RankCriterion.ON_TIME))
    p.eq("ON_TIME (p_on_time 0.8, 0.8, 0.9, 0.8, 0.8): 순위", (("Ic", "Id", "Ie", "Ib", "Ia"), "Ic"), (ranking, best))


def _ev11(p: _Probe) -> None:
    results = _ev10_results(same_ab=True)
    template = results[0]
    results.append(_ev_result(template, "Ix", 1200.0, 0.2, 1500, 300.0, "r6", status=RouteStatus.GHOST_PRUNED))
    results.append(_ev_result(template, "Iy", None, 0.0, 1500, 300.0, "r7", status=RouteStatus.GHOST_PRUNED))
    updated, ranking, pruned, best = rank_itineraries(list(reversed(results)), golden_query(), EngineConfig())
    p.eq("대표 순위와 최선", (("Id", "Ie", "Ic", "Ib"), "Id"), (ranking, best))
    view = {r.itinerary_id: (r.rank, r.representative_id, r.variant_ids) for r in updated}
    p.eq(
        "순위 번호, 대표, 아래 여정",
        {"Id": (1, None, ()), "Ie": (2, None, ()), "Ic": (3, None, ()), "Ib": (4, None, ("Ia",)), "Ia": (None, "Ib", ()), "Ix": (None, None, ()), "Iy": (None, None, ())},
        view,
    )
    p.eq("pruned_ids (평균 순, 평균이 없으면 맨 뒤)", ("Ix", "Iy"), pruned)
    p.eq("돌려준 결과는 들어온 순서", tuple(r.itinerary_id for r in reversed(results)), tuple(r.itinerary_id for r in updated))


def _ev12(p: _Probe) -> None:
    config = EngineConfig()
    context = _sr_context(golden_scenario(), config, golden_query())
    journeys = {journey.itinerary_id: journey for journey in search_candidates(context, config)[0]}
    real = naive_timeline(journeys["Ifbf4ec4c04"], context, config, NaiveTransferWait.REAL)
    p.approx(
        "Ifbf4ec4c04: 기존 방식 차량 (정류장 도착, ν, 여유)은 대기 설정과 상관없이 실제 차량으로 정한다",
        ((136.0, 398.0), ("G1:g1a", "G2:g2a"), (64.0, 22.0)),
        (real.stop_arrivals, real.trip_ids, real.margins),
    )
    hops = context.shortest("B2", "B4")
    p.approx("B2 → B4 최단거리 (e07, e08, e10), 60 m", (("e07", "e08", "e10"), 60.0), (tuple(hop.edge_id for hop in hops), sum(hop.length_m for hop in hops)) if hops else None, 0.05)
    zero = naive_timeline(journeys["Ifbf4ec4c04"], context, config, NaiveTransferWait.ZERO)
    p.approx("Ifbf4ec4c04 ZERO: 398 + 180 = 578 에 B5, 80 m 를 64 초 → 약속 도착 642", ((136.0, 398.0), 642.0), (zero.stop_arrivals, zero.promised_s))
    p.approx("Ifbf4ec4c04 REAL: g2a 를 타 600 에 B5 → 약속 도착 664", 664.0, real.promised_s)
    subway = naive_timeline(journeys["I3a248c7d10"], context, config, NaiveTransferWait.ZERO)
    p.approx("I3a248c7d10: S → P1 최단거리 500 m 로 400, ν = 1002 (여유 140), 약속 954", ((400.0,), ("1002",), (140.0,), 954.0), (subway.stop_arrivals, subway.trip_ids, subway.margins, subway.promised_s))
    bike = naive_timeline(journeys["Ic5c1b22780"], context, config, NaiveTransferWait.ZERO)
    p.approx("Ic5c1b22780: 40 + 25 + 1,640/4 + 15 + 56 = 546", 546.0, bike.promised_s)
    results = _by_id(_run("골든 기본"))
    boardings = results["Ifbf4ec4c04"].boardings
    p.approx("Ifbf4ec4c04: 기존 방식 차량의 p_catch", (0.952210, 0.012551), tuple(b.p_catch_naive for b in boardings), 1e-5)
    p.eq("Ifbf4ec4c04: 유령 (0.012551 < 0.4)", (False, True), tuple(b.ghost for b in boardings))
    p.approx("REAL 설정의 Ifbf4ec4c04 T_naive", 664.0, _by_id(_run("V12h REAL"))["Ifbf4ec4c04"].naive_promised_s)


def _ev13(p: _Probe) -> None:
    template = _by_id(_run("골든 기본"))["Idddde0a626"]

    def result(jid: str, mean: float, p90: float, unreachable: float, on_time: float, key: str) -> ItineraryResult:
        base = _ev_result(template, jid, mean, 0.9, 1500, 300.0, key, p_on_time=on_time)
        return base.model_copy(update={"arrival": base.arrival.model_copy(update={"p90_s": p90, "p_unreachable": unreachable})})

    ia = result("Ia", 300.0, 350.0, 0.1, 0.85, "r1")
    ib = result("Ib", 320.0, 360.0, 0.0, 0.80, "r2")
    query = golden_query()
    for criterion in (RankCriterion.MEAN_ARRIVAL, RankCriterion.P90_ARRIVAL, RankCriterion.UTILITY):
        for order in ((ia, ib), (ib, ia)):
            _updated, ranking, _pruned, best = rank_itineraries(order, query, EngineConfig(rank_criterion=criterion))
            p.eq(f"{criterion.value} (입력 {order[0].itinerary_id} 먼저): 도착하지 못하는 점이 적은 Ib 가 앞", (("Ib", "Ia"), "Ib"), (ranking, best))
    timed = query.model_copy(update={"deadline_s": 600.0})
    for order in ((ia, ib), (ib, ia)):
        _updated, ranking, _pruned, best = rank_itineraries(order, timed, EngineConfig(rank_criterion=RankCriterion.ON_TIME))
        p.eq(f"ON_TIME (마감 600, p_on_time 0.85, 0.80, 입력 {order[0].itinerary_id} 먼저): Ia 가 앞", (("Ia", "Ib"), "Ia"), (ranking, best))
    tiny = result("Ia", 300.0, 350.0, 4e-7, 0.85, "r1")
    for order in ((tiny, ib), (ib, tiny)):
        _updated, ranking, _pruned, best = rank_itineraries(order, query, EngineConfig(rank_criterion=RankCriterion.MEAN_ARRIVAL))
        p.eq(
            f"Ia 의 p_unreachable 4e-7 은 0 으로 반올림 (입력 {order[0].itinerary_id} 먼저): MEAN_ARRIVAL 은 Ia, Ib",
            (("Ia", "Ib"), "Ia"),
            (ranking, best),
        )


def _ev14_variant(context: SearchContext, journey: Journey, line: tuple[str, int, int]) -> Journey:
    """EV14: 같은 여정에서 탑승의 묶음을 노선 하나로 줄인 여정. 구조 키, 여정 ID, 이름을 다시 만든다(§1.10.5)."""
    route_id, board, alight = line
    rides = (dataclasses.replace(journey.rides[0], route_id=route_id, board_index=board, alight_index=alight, search_trip_id=None, bundle=()),)
    ride_part = [[route_id, board, alight]]
    bike_part = [[move.pick_id, move.drop_id] if move.has_bike else None for move in journey.moves]
    path_part = [[hop.edge_id for hop in move.hops] for move in journey.moves]
    key = _json_key([ride_part, bike_part, path_part])
    return dataclasses.replace(
        journey,
        itinerary_id="I" + hashlib.sha1(key.encode("utf-8")).hexdigest()[:10],
        structure_key=key,
        ride_key=_json_key([ride_part, bike_part]),
        label=_journey_label(context, rides, journey.moves, journey.in_vehicle),
        rides=rides,
    )


def _ev14(p: _Probe) -> None:
    output = _run("EV14 묶음 세계")
    results = _by_id(output)
    p.eq("여정 하나", ("I9b74478fdb",), tuple(results))
    result = results.get("I9b74478fdb")
    if result is None:
        return
    runs = (SearchRun.FULL, SearchRun.NO_BIKE, SearchRun.BUS_ONLY, SearchRun.SLOW, SearchRun.NAIVE)
    p.eq(
        "이름, 구조 키, 찾은 실행 (Z 는 요금 종류가 달라 묶음에서 빠진다)",
        ("가상7·가상8번", '[[[["X",0,1],["Y",0,1]]],[null,null],[["v1"],["v2"]]]', runs),
        (result.label, result.structure_key, result.found_by),
    )
    ride = result.rides[0]
    _fields(
        p,
        "계획 (P 도착, 차량, 출발, 기다림, Q 하차, T_plan)",
        (240.0, "Y:y1", 330.0, 90.0, 540.0, 580.0),
        (ride.plan_stop_arrival_s, ride.plan_trip_id, ride.plan_dep_s, ride.plan_wait_s, ride.plan_arr_s, result.plan_arrival_s),
        "t=tttt",
    )
    stats = result.arrival
    _fields(p, "(평균, 10%, 50%, 90%, 방법)", (593.0491, 574.6705, 580.0, 587.2750, "EXACT"), (stats.mean_s, stats.p10_s, stats.p50_s, stats.p90_s, stats.method), "tttt=")
    boarding = result.boardings[0]
    _fields(
        p,
        "(안내 차량, 찾음, Q, P*, 등급, 상태)",
        ("Y:y1", True, 0.952210, 0.952210, "SAFE", "RANKED"),
        (boarding.guided_trip_id, boarding.guided_found, boarding.q_joint, result.p_star, result.grade, result.status),
        "==pp==",
    )
    evaluation = _evaluations("EV14 묶음 세계")["I9b74478fdb"]
    sequence = evaluation.vehicles(0)
    position = sequence.position_of("Y:y1")
    m_star = float(evaluation.threshold(evaluation.ones, 0, position)[0]) if position is not None else None
    p.close("안내 차량 Y:y1 의 m* = 240 / (330 − 30)", 0.8, m_star, 1e-5)
    p.approx(
        "차량 목록 (노선, 차량, 몇 번째 차, 출발, 하차, p_catch)",
        (("Y", "Y:y1", 1, 330.0, 540.0, 0.952210), ("X", "X:x2", 2, 500.0, 800.0, 0.999977)),
        tuple((v.route_id, v.trip_id, v.ordinal, v.dep_s, v.alight_arr_s, v.p_catch) for v in boarding.vehicles),
        1e-5,
    )
    p.approx("탄 차량 분포", (("Y:y1", 0.952148), ("X:x2", 0.047852)), boarding.trip_distribution, 1e-5)
    _fields(
        p,
        "기존 방식 차량 (차량, 정류장 도착, 여유, p_catch, 유령), T_naive",
        ("Y:y1", 240.0, 90.0, 0.952210, False, 580.0),
        (boarding.naive_trip_id, boarding.naive_stop_arrival_s, boarding.naive_margin_s, boarding.p_catch_naive, boarding.ghost, result.naive_promised_s),
        "=ttp=t",
    )
    p.eq(
        "Ride (노선, 이름, 종류, 승차 순번, 하차 순번, 계획 차량, 묶음, 묶음 이름)",
        ("Y", "가상8", BusRouteType.TRUNK, 0, 1, "Y:y1", (("X", "가상7", 0, 1), ("Y", "가상8", 0, 1)), "가상7·가상8번"),
        (
            ride.route_id,
            ride.route_name,
            ride.bus_type,
            ride.board_index,
            ride.alight_index,
            ride.plan_trip_id,
            tuple((line.route_id, line.route_name, line.board_index, line.alight_index) for line in ride.bundle),
            ride.bundle_name,
        ),
    )
    p.close("Ride 거리", 1200.0, ride.distance_m, 0.05)
    comparison = output.comparison
    p.eq(
        "(요금, 최선, 기존 방식 1위, app_misled)",
        (1500, "I9b74478fdb", "I9b74478fdb", False),
        (result.fare.total_krw, output.best_id, comparison.naive_best_id, comparison.app_misled),
    )
    context, config, journey = evaluation.context, evaluation.config, evaluation.journey
    e40 = float(np.mean(40.0 / halton_m(config.n_qmc, config.k_move)))
    p.close("E[40/m] (Q → D 50 m 를 걷는 평균 시간)", 40.6077, e40, 1e-4)
    means = [stats.mean_s]
    singles = (
        (("Y", 0, 1), "Ice862a27d9", 598.3128, (("Y:y1", 0.952148), ("Y:y2", 0.047852))),
        (("X", 0, 1), "I98fc012418", 676.0569, (("X:x1", 0.822754), ("X:x2", 0.177246))),
    )
    for line, jid, mean, distribution in singles:
        variant = _ev14_variant(context, journey, line)
        single = assess_itinerary(variant, plan_schedule(variant, context, config), context, config)
        p.eq(f"{line[0]} 하나로 줄인 여정의 ID", jid, variant.itinerary_id)
        p.close(f"{jid}: 평균", mean, single.arrival.mean_s, 0.01)
        p.approx(f"{jid}: 탄 차량 분포", distribution, single.boardings[0].trip_distribution, 1e-5)
        means.append(single.arrival.mean_s)
    p.approx(
        "하차 정류장 평균 (평균 − E[40/m]): 묶음, Y 하나, X 하나 (§1.7.4 의 예)",
        (552.4414, 557.7051, 635.4492),
        tuple(None if mean is None else mean - e40 for mean in means),
    )


# --- AC1 ~ AC6 사례 검사 (§9.5.4) ---


def _ac_check(
    p: _Probe,
    name: str,
    itineraries: tuple,
    ranking: tuple[str, ...],
    naive_best: str,
    misled: bool,
    panel: tuple[float, float, float, float] | None,
    traces: dict[str, tuple],
) -> EngineOutput:
    """사례 검사 하나의 공통 비교(§9.5.4). `k_move` 0 이라 모든 점이 m = 1 이고 평균과 분위수가 T_plan, P* 1, SAFE, DEGENERATE 다.

    itineraries 는 여정마다 (ID, 이름, 구조 키, 찾은 실행, T_plan, 요금, T_naive, 유령 수, 탑승들)이고, 탑승은
    (계획 (정류장 도착, 차량, 출발, 기다림, 하차) 또는 None, 안내 차량, 차량 목록, 기존 방식 (차량, 정류장 도착, 여유, p_catch, 유령))이다.
    traces 는 실행 이름마다 (D 라벨들, 여정 ID 들)이다.
    """
    output = _run(name)
    results = _by_id(output)
    p.eq(f"여정 {len(itineraries)}개", tuple(sorted(item[0] for item in itineraries)), tuple(results))
    for jid, label, key, runs, t_plan, fare, t_naive, ghosts, rides in itineraries:
        result = results.get(jid)
        if result is None:
            continue
        p.eq(f"{jid}: (이름, 구조 키, 찾은 실행)", (label, key, tuple(SearchRun(run) for run in runs)), (result.label, result.structure_key, result.found_by))
        stats = result.arrival
        p.approx(
            f"{jid}: (T_plan, 평균, 10%, 50%, 90%, P*, 등급, 상태, 방법, T_naive, 유령 수, 요금)",
            (t_plan, t_plan, t_plan, t_plan, t_plan, 1.0, Grade.SAFE, RouteStatus.RANKED, ProbMethod.DEGENERATE, t_naive, ghosts, fare),
            (
                result.plan_arrival_s,
                stats.mean_s,
                stats.p10_s,
                stats.p50_s,
                stats.p90_s,
                result.p_star,
                result.grade,
                result.status,
                stats.method,
                result.naive_promised_s,
                result.ghost_count,
                result.fare.total_krw,
            ),
            1e-5,
        )
        p.eq(f"{jid}: 탑승 수", len(rides), len(result.rides))
        for number, ((plan, guide, vehicles, naive), ride, boarding) in enumerate(zip(rides, result.rides, result.boardings), start=1):
            where = f"{jid} 탑승 {number}"
            if plan is not None:
                p.approx(
                    f"{where}: 계획 (정류장 도착, 차량, 출발, 기다림, 하차)",
                    plan,
                    (ride.plan_stop_arrival_s, ride.plan_trip_id, ride.plan_dep_s, ride.plan_wait_s, ride.plan_arr_s),
                    1e-5,
                )
            p.approx(f"{where}: (안내 차량, Q)", (guide, 1.0), (boarding.guided_trip_id, boarding.q_joint), 1e-5)
            p.approx(
                f"{where}: 차량 목록 (차량, 몇 번째 차, 출발, 하차, p_catch)",
                vehicles,
                tuple((v.trip_id, v.ordinal, v.dep_s, v.alight_arr_s, v.p_catch) for v in boarding.vehicles),
                1e-5,
            )
            p.approx(
                f"{where}: 기존 방식 차량 (차량, 정류장 도착, 여유, p_catch, 유령)",
                naive,
                (boarding.naive_trip_id, boarding.naive_stop_arrival_s, boarding.naive_margin_s, boarding.p_catch_naive, boarding.ghost),
                1e-5,
            )
    comparison = output.comparison
    p.eq(
        "(순위, 최선, 기존 방식 1위, app_misled, 걸러진 여정)",
        (ranking, ranking[0], naive_best, misled, ()),
        (output.ranking, output.best_id, comparison.naive_best_id, comparison.app_misled, output.pruned_ids),
    )
    if panel is not None:
        p.approx(
            "비교 패널 (약속 도착, 평균, 약속보다 늦는 시간, 줄이는 시간)",
            panel,
            (comparison.naive_promised_s, comparison.naive_mean_s, comparison.late_vs_promise_s, comparison.saving_s),
            1e-5,
        )
    by_run = {trace.run: trace for trace in output.search.runs}
    for run, view in traces.items():
        p.approx(f"{run} 의 D 라벨과 여정", view, _trace_view(by_run[SearchRun(run)]), 1e-5)
    p.eq("SLOW 와 AVERSE 는 건너뛴다 (k_move 0, 표본 신호 없음)", (True, True), (by_run[SearchRun.SLOW].skipped, by_run[SearchRun.AVERSE].skipped))
    return output


