def _ac6(p: _Probe) -> None:
    racks = tuple((station.id, station.rack_total, station.bikes_available) for station in _ac_full_racks().bike_stations if station.id in ("Kb", "Kd"))
    p.eq("반납소 Kb, Kd 의 (거치대, 자전거)", (("Kb", 0, 0), ("Kd", 0, 0)), racks)
    base = _run("EV7 두 번 빌리기").model_dump_json()
    full = _run("AC6 반납소 가득").model_dump_json()
    same = base == full
    at = len(os.path.commonprefix([base, full]))
    p.true("EV7 과 모든 값이 같다 (엔진 출력 JSON 전체)", same, "같음" if same else f"{at}번째 글자부터 다름: {_short(full[max(0, at - 60): at + 60])}")


