def _sorted_pairs(mapping: dict) -> tuple:
    """사전을 키 순 (키, 값) 튜플로 바꿔 항목마다 오차 비교를 한다."""
    return tuple(sorted(mapping.items()))


def _plan_events(result: ItineraryResult) -> tuple:
    """계획이 지난 경로의 신호 이벤트를 지난 순서대로 (신호, 도착, τ, 상태, 대기)."""
    events = []
    for move in result.moves:
        paths = (move.walk,) if move.walk is not None else ((move.bike.walk_in, move.bike.ride, move.bike.walk_out) if move.bike else ())
        for path in paths:
            if path is not None:
                events.extend((e.signal_id, e.t_arr_s, e.tau_s, e.state, e.wait_s) for e in path.events)
    return tuple(events)


def _plan_view(result: ItineraryResult) -> tuple:
    legs = tuple((leg.kind, leg.start_s, leg.end_s) for leg in result.legs)
    rides = tuple((r.plan_stop_arrival_s, r.plan_trip_id, r.plan_dep_s, r.plan_arr_s, r.plan_wait_s) for r in result.rides)
    return legs, rides, _plan_events(result)


def _boarding_check(p: _Probe, where: str, boarding: BoardingAssessment | None, expected: tuple) -> None:
    head, vehicles, catches, distribution, naive = expected
    if boarding is None:
        p.true(f"{where}: 탑승 평가가 있다", False, "없음")
        return
    _fields(p, f"{where}: (안내 차량, Q, 조건부)", head, (boarding.guided_trip_id, boarding.q_joint, boarding.p_conditional), "=pp")
    p.approx(f"{where}: 차량 목록 (차량, 몇 번째, 출처, 출발, 하차)", vehicles, tuple((v.trip_id, v.ordinal, v.time_source, v.dep_s, v.alight_arr_s) for v in boarding.vehicles))
    p.approx(f"{where}: 차량 목록의 p_catch", catches, tuple(v.p_catch for v in boarding.vehicles), 1e-5)
    p.approx(f"{where}: 탄 차량 분포", distribution, boarding.trip_distribution, 1e-5)
    _fields(
        p,
        f"{where}: 기존 방식 차량 (차량, 정류장 도착, 여유, p_catch, 유령)",
        naive,
        (boarding.naive_trip_id, boarding.naive_stop_arrival_s, boarding.naive_margin_s, boarding.p_catch_naive, boarding.ghost),
        "=ttp=",
    )


def _histogram_view(histogram: MarginHistogram | None) -> tuple | None:
    if histogram is None:
        return None
    bins = histogram.bins
    return (
        histogram.n_points,
        bins[0] if bins else None,
        bins[-1] if bins else None,
        len(bins),
        histogram.n_under,
        histogram.n_over,
        histogram.n_infinite,
        histogram.success_mass,
    )


def _fare_rows(fare: FareBreakdown) -> tuple:
    chains = tuple((c.ride_indexes, c.base_krw, c.distance_m, c.distance_extra_krw) for c in fare.chains)
    return chains, fare.transit_krw, fare.bike_krw, fare.total_krw


def _v12a(p: _Probe) -> None:
    start = time.perf_counter()
    output = run_engine(golden_scenario(), golden_query(), EngineConfig())
    elapsed = time.perf_counter() - start
    _ENGINE_RUNS.setdefault("골든 기본", output)
    p.true("골든 run_engine 1회 실행 시간 2초 이내 (§10.6)", elapsed <= 2.0, f"{elapsed:.3f}초")
    results = _by_id(output)
    p.eq("후보 6개", _GOLDEN_CANDIDATES, tuple(results))
    for jid, row in _V12A_ROWS.items():
        _fields(p, f"판정표 {jid} (이름, T_plan, 걷는 거리, 평균, 10%, 50%, 90%, P*, 등급, 상태, 방법, 표본 신호, T_naive, 유령, 요금)", row, _result_row(results.get(jid)), _ROW_KINDS)
    for jid, (legs, rides, events) in _V12A_PLANS.items():
        result = results.get(jid)
        view = _plan_view(result) if result else (None, None, None)
        p.approx(f"계획 {jid}: 시간 막대 (칸, 시작, 끝)", legs, view[0])
        p.approx(f"계획 {jid}: 탑승 (정류장 도착, 계획 차량, 출발, 하차, 대기)", rides, view[1])
        p.approx(f"계획 {jid}: 신호 (신호, 도착, τ, 상태, 대기)", events, view[2])
    for (jid, ride), expected in _V12A_BOARDINGS.items():
        result = results.get(jid)
        boarding = result.boardings[ride - 1] if result and len(result.boardings) >= ride else None
        _boarding_check(p, f"탑승 평가 {jid} · {ride}", boarding, expected)
    flags = [(v.is_full, v.is_last) for r in output.itineraries for b in r.boardings for v in b.vehicles]
    p.true("차량 목록의 만차·막차 표시는 모두 거짓", not any(full or last for full, last in flags), f"{len(flags)}대")
    for (jid, ride), expected in _V12A_HISTOGRAMS.items():
        result = results.get(jid)
        histogram = result.boardings[ride - 1].histogram if result and len(result.boardings) >= ride else None
        _fields(p, f"막대그래프 {jid} · {ride} (점, 첫 칸, 마지막 칸, 칸 수, under, over, infinite, success_mass)", expected, _histogram_view(histogram), "=tt====p")
    bike = results.get("Ic5c1b22780")
    if bike is not None:
        segment = bike.moves[0].bike
        _fields(
            p,
            "따릉이 Ic5c1b22780 (a, g, P_bike, bike_fallback_mass, 대체 보행 K1 → D 거리)",
            (40.0, 0.0, 0.875173, (0.124827,), 1650.0),
            (segment.arrival_at_pick_s, segment.obs_age_s, segment.p_bike, bike.arrival.bike_fallback_mass, segment.fallback.distance_m if segment.fallback else None)
            if segment
            else None,
            "ttppd",
        )
    for jid, expected in _V12A_FARES.items():
        result = results.get(jid)
        p.approx(f"요금 {jid} (묶음, 대중교통, 따릉이, 합계)", expected, _fare_rows(result.fare) if result else None, 0.05)
    p.eq("결과 전체 (status, 경고, pruned_ids)", (EngineStatus.OK, (WarningCode.UNVERIFIED_COORDINATES,), ()), (output.status, tuple(w.code for w in output.warnings), output.pruned_ids))
    p.eq(
        "모든 여정의 (p_unreachable, 넘친 신호, 점 수)",
        {jid: (0.0, (), 4096) for jid in _GOLDEN_CANDIDATES},
        {r.itinerary_id: (r.arrival.p_unreachable, r.arrival.capped_signal_ids, r.arrival.n_points) for r in output.itineraries},
    )


