def _criterion_run(criterion: RankCriterion, deadline: float | None, **updates: Any) -> EngineOutput:
    """골든 기본 질의를 순위 기준·마감·요금 선택만 바꿔 돌린 결과(V12b, V12c, I12, I16 이 나누어 쓴다)."""
    if criterion == RankCriterion.MEAN_ARRIVAL and deadline is None and not updates:
        return _run("골든 기본")
    key = f"골든 {criterion.value} 마감 {deadline} {sorted(updates.items())}"
    if key not in _ENGINE_RUNS:
        query = golden_query() if deadline is None else golden_query().model_copy(update={"deadline_s": deadline})
        _ENGINE_RUNS[key] = run_engine(golden_scenario(), query, EngineConfig(rank_criterion=criterion, **updates))
    return _ENGINE_RUNS[key]


def _v12b(p: _Probe) -> None:
    for criterion, deadline, ranking, variant, kind, extra_warnings in _V12B:
        name = f"{criterion.value}" + (f", 마감 {deadline:g}" if deadline is not None else (", 마감 없음" if criterion == RankCriterion.ON_TIME else ""))
        output = _criterion_run(criterion, deadline)
        results = _by_id(output)
        p.eq(f"{name}: 대표 순위", tuple(jid for jid, _value in ranking), output.ranking)
        for jid, value in ranking:
            result = results.get(jid)
            _fields(p, f"{name}: {jid} 의 (순위, 기준 값)", (ranking.index((jid, value)) + 1, value), (result.rank, result.criterion_value) if result else None, "=" + kind)
        vid, value, head = variant
        result = results.get(vid)
        _fields(p, f"{name}: 아래 여정 {vid} (순위, 기준 값, 대표)", (None, value, head), (result.rank, result.criterion_value, result.representative_id) if result else None, "=" + kind + "=")
        p.eq(f"{name}: 대표 {head} 의 아래 여정", (vid,), results[head].variant_ids if head in results else None)
        p.eq(f"{name}: 경고", tuple(sorted((*extra_warnings, WarningCode.UNVERIFIED_COORDINATES), key=lambda code: code.value)), tuple(w.code for w in output.warnings))
        if criterion == RankCriterion.ON_TIME:
            expected = dict(ranking)
            expected[vid] = value
            if deadline is None:
                expected = {jid: None for jid in expected}
            p.approx(f"{name}: 모든 여정의 p_on_time", _sorted_pairs(expected), _sorted_pairs({jid: r.arrival.p_on_time for jid, r in results.items()}), 1e-5)
        if criterion == RankCriterion.UTILITY:
            for jid, terms in _V12B_UTILITY_TERMS.items():
                utility = results[jid].utility if jid in results else None
                _fields(
                    p,
                    f"UTILITY {jid}: (시간, 요금, 위험, J), T_max, Cost_max",
                    (*terms, 1319.8554, 1550.0),
                    (utility.time_term, utility.cost_term, utility.risk_term, utility.total, utility.t_max_s, utility.cost_max_krw) if utility else None,
                    "jjjjt=",
                )
    panel = _run("골든 기본").comparison
    _fields(
        p,
        "비교 패널 (기존 방식 1위, 최선, same, 약속, 평균, 90%, P*, 상태, 사유, 최선 평균, 최선 90%, 늦음, 줄임, app_misled)",
        ("Ifbf4ec4c04", "Ic5c1b22780", False, 642.0, 1318.2926, 1321.73, 0.952210, "RANKED", (), 673.8259, 1301.0603, 676.2926, 644.4667, True),
        (
            panel.naive_best_id,
            panel.best_id,
            panel.same,
            panel.naive_promised_s,
            panel.naive_mean_s,
            panel.naive_p90_s,
            panel.naive_p_star,
            panel.naive_status,
            panel.naive_reasons,
            panel.best_mean_s,
            panel.best_p90_s,
            panel.late_vs_promise_s,
            panel.saving_s,
            panel.app_misled,
        ),
        "===tttp==tttt=",
    )
    results = _by_id(_run("골든 기본"))
    naive, best = results["Ifbf4ec4c04"], results["Ic5c1b22780"]
    ghosts = tuple((b.ride_index, b.naive_trip_id, b.guided_trip_id) for b in naive.boardings if b.ghost)
    p.eq("기존 방식 1위의 유령 환승 (탑승, 기존 방식 차량, 대신 안내한 차량)", (1, ((2, "G2:g2a", "G2:g2b"),)), (naive.ghost_count, ghosts))
    p.close("최선의 P*", 0.875173, best.p_star, 1e-5)


