def _v12c(p: _Probe) -> None:
    for name, updates, fares, cost_max, ranking, utility in _V12C_CASES:
        output = _criterion_run(RankCriterion.UTILITY, None, **updates)
        results = _by_id(output)
        p.eq(f"{name}: 요금 ({', '.join(_V12C_ORDER)})", fares, tuple(results[jid].fare.total_krw if jid in results else None for jid in _V12C_ORDER))
        maxima = {results[jid].utility.cost_max_krw for jid in output.ranking if results[jid].utility}
        p.approx(f"{name}: Cost_max", (cost_max,), tuple(maxima))
        p.eq(f"{name}: 순위", ranking, output.ranking)
        p.approx(f"{name}: J", _sorted_pairs(utility), _sorted_pairs({jid: r.criterion_value for jid, r in results.items()}), 1e-4)
    output = _run("골든 기본")
    expected = (
        ("K1", 1, 40.0, 0.875173, "AVAILABLE"),
        ("K2", 2, 1272.0, 0.374499, "LOW_P_BIKE"),
        ("K3", 0, 696.0, 0.0, "NO_BIKE"),
        ("K4", 1, 264.0, 0.012277, "LOW_P_BIKE"),
        ("K5", 3, 338.0714, 1.0, "AVAILABLE"),
    )
    p.eq("대여소 상태의 대여소", tuple(row[0] for row in expected), tuple(s.station_id for s in output.stations))
    for row, status in zip(expected, output.stations):
        _fields(p, f"대여소 {row[0]} (n0, a, P_bike, use)", row, (status.station_id, status.bikes_available, status.arrival_s, status.p_bike, status.use), "==tp=")


