def _eta_rows(line: BusLine) -> tuple:
    return tuple(tuple((item.rank, item.vehicle_id, item.eta_s) for item in row) for row in line.predictions)


def _v12g(p: _Probe) -> None:
    config = EngineConfig()
    golden = golden_scenario()
    shifted = advance_clock(golden, 300.0, config)
    signals = {s.id: s.offset_s for s in shifted.signals}
    p.approx("바뀐 시나리오 (clock_s, bike_obs_age_s, SG1, SG2, SG3, SG4 의 θ)", (29100.0, 300.0, None, None, 25.0, 60.0), (shifted.clock_s, shifted.bike_obs_age_s, signals.get("SG1"), signals.get("SG2"), signals.get("SG3"), signals.get("SG4")))
    lines = {line.id: line for line in shifted.bus_lines}
    p.approx("G1 예측 (B1, B2, B3)", (((2, "g1b", 500.0),), ((1, "g1a", 50.0), (2, "g1b", 650.0)), ()), _eta_rows(lines["G1"]))
    p.approx("G2 예측 (B4, B5)", (((1, "g2a", 120.0), (2, "g2b", 720.0)), ((1, "g2a", 300.0), (2, "g2b", 900.0))), _eta_rows(lines["G2"]))
    pattern = shifted.subway_patterns[0]
    first = pattern.trips[0]
    p.approx("열차 30개 모두 남고 \"1000\" 은 도착 (−260, −130, −10), 출발 (−240, −110, 10)", (30, "1000", (-260.0, -130.0, -10.0), (-240.0, -110.0, 10.0)), (len(pattern.trips), first.id, first.arr_s, first.dep_s))
    twice = advance_clock(advance_clock(golden, 100.0, config), 200.0, config)
    p.true("100 을 늦춘 뒤 200 을 더 늦춘 시나리오는 한 번에 300 을 늦춘 시나리오와 같다", twice.model_dump() == shifted.model_dump())
    context = _sr_context(shifted, config, golden_query())

    def vehicles(route_id: str) -> tuple:
        trips = context.routes[route_id].trips
        return tuple((trips.trip_ids[row], tuple(None if math.isnan(x) else float(x) for x in trips.arr[row])) for row in range(min(3, trips.n_trips)))

    p.approx("G1 차량", (("G1:g1a", (None, 50.0, 217.9987)), ("G1:g1b", (500.0, 650.0, 817.9987)), ("G1:+1", (1100.0, 1250.0, 1417.9987))), vehicles("G1"))
    p.approx("G2 차량", (("G2:g2a", (120.0, 300.0)), ("G2:g2b", (720.0, 900.0)), ("G2:+1", (1320.0, 1500.0))), vehicles("G2"))
    output = _run("V12g Δt 300")
    results = _by_id(output)
    p.eq("기본 질의: 후보 3개 (따릉이 여정 없음)", ("I3a248c7d10", "I469424fb69", "If1e99436b8"), tuple(results))
    k1 = next((s for s in output.stations if s.station_id == "K1"), None)
    p.close("K1 의 P_bike = e^(−12 · 340/3600) < 0.5", 0.321958, k1.p_bike if k1 else None, 1e-5)
    rows = {
        "I3a248c7d10": ((SearchRun.AVERSE,), 894.0, 1013.7486, 869.4842, 894.0, 1167.4649, 0.514772, "RISKY", "RANKED", "QMC", 1, 894.0, 1550),
        "I469424fb69": ((SearchRun.FULL, SearchRun.NO_BIKE, SearchRun.SUBWAY_ONLY, SearchRun.SLOW, SearchRun.NAIVE), 894.0, 1012.0494, 870.1391, 909.9245, 1167.4649, 0.519749, "RISKY", "RANKED", "QMC", 1, 894.0, 1550),
        "If1e99436b8": (tuple(SearchRun), 1300.0, 1319.8688, 1109.4552, 1300.0, 1536.3996, 1.0, "SAFE", "RANKED", "EXACT", 0, 1280.0, 0),
    }
    for jid, row in rows.items():
        r = results.get(jid)
        stats = r.arrival if r else None
        _fields(
            p,
            f"{jid}: (찾은 실행, T_plan, 평균, 10%, 50%, 90%, P*, 등급, 상태, 방법, 표본 신호, T_naive, 요금)",
            row,
            (r.found_by, r.plan_arrival_s, stats.mean_s, stats.p10_s, stats.p50_s, stats.p90_s, r.p_star, r.grade, r.status, stats.method, stats.n_sampled_signals, r.naive_promised_s, r.fare.total_krw) if r else None,
            "=tttttp====t=",
        )
    plans = {
        "I3a248c7d10": ((448.0, "1003", 480.0, 710.0, 32.0),),
        "I469424fb69": ((446.0714, "1003", 480.0, 710.0, 33.9286),),
    }
    for jid, expected in plans.items():
        p.approx(f"{jid}: 계획 탑승 (P1 도착, 차량, 출발, 하차, 대기)", expected, _plan_view(results[jid])[1] if jid in results else None)
    if "If1e99436b8" in results:
        p.approx("If1e99436b8: SG4 에 640 에 닿아 τ 100, RED, 대기 20", (("SG4", 640.0, 100.0, "RED", 20.0),), _plan_events(results["If1e99436b8"]))
    _boarding_check(
        p,
        "I3a248c7d10 · 1",
        results["I3a248c7d10"].boardings[0] if "I3a248c7d10" in results else None,
        (
            ("1003", 0.514772, 0.514772),
            (("1002", 2, "TIMETABLE", 240.0, 470.0), ("1003", 3, "TIMETABLE", 480.0, 710.0), ("1004", 4, "TIMETABLE", 720.0, 950.0)),
            (0.0, 0.514772, 0.998265),
            (("1003", 0.514648), ("1004", 0.483398), ("1005", 0.001953)),
            ("1003", 400.0, 80.0, 0.514772, False),
        ),
    )
    boarding = results["I469424fb69"].boardings[0] if "I469424fb69" in results else None
    p.approx("I469424fb69 · 1: p_catch (1002, 1003, 1004)", (("1002", 0.0), ("1003", 0.519749), ("1004", 0.998343)), tuple((v.trip_id, v.p_catch) for v in boarding.vehicles) if boarding else None, 1e-5)
    p.approx("I469424fb69 · 1: 탄 차량 분포", (("1003", 0.520996), ("1004", 0.477783), ("1005", 0.001221)), boarding.trip_distribution if boarding else None, 1e-5)
    p.eq("순위와 대표 아래 여정, (최선, 기존 방식 1위)", (("I469424fb69", "If1e99436b8"), (("I469424fb69", ("I3a248c7d10",)),), ("I469424fb69", "I469424fb69")), (*_ranking_view(output), (output.best_id, output.comparison.naive_best_id)))
    bus, train = golden_bus_query(), golden_train_query()

    def shifted_origin(query: Query, dt: float) -> tuple | None:
        moved = advance_clock(golden, dt, config)
        new = shift_origin(golden, moved, query, dt, config)
        if new is None:
            return None
        origin = new.origin
        ctx = _sr_context(moved, config, new)
        trips = ctx.routes[origin.line_id or origin.pattern_id].trips
        return origin.trip_id, float(trips.arr[trips.row_of(origin.trip_id), origin.next_index])

    p.approx("shift_origin 버스 질의 300: G1:g1b (B2 650)", ("G1:g1b", 650.0), shifted_origin(bus, 300.0))
    p.approx("shift_origin 열차 질의 300: \"1002\" (P2 350)", ("1002", 350.0), shifted_origin(train, 300.0))
    p.approx("shift_origin 버스 질의 600: G1:g1b (350)", ("G1:g1b", 350.0), shifted_origin(bus, 600.0))
    p.approx("shift_origin 버스 질의 900: G1:+1 (650)", ("G1:+1", 650.0), shifted_origin(bus, 900.0))
    p.eq("shift_origin 버스 질의 1,200: None (G1 의 예측이 모두 지나감)", None, shift_origin(golden, advance_clock(golden, 1200.0, config), bus, 1200.0, config))
    output = _run("V12g 바꾼 버스 질의")
    results = _by_id(output)
    rows = {
        "I577e75eb8b": (1306.0, 1315.9666, 1218.5958, 1306.0, 1425.3096, 1.0, "EXACT", 1306.0),
        "I370e4c69aa": (1564.0, 1557.6481, 1555.4728, 1564.0, 1575.6400, 1.0, "QMC", 942.0),
    }
    for jid, row in rows.items():
        r = results.get(jid)
        _fields(p, f"바꾼 버스 질의 {jid}: (T_plan, 평균, 10%, 50%, 90%, P*, 방법, T_naive)", row, (r.plan_arrival_s, r.arrival.mean_s, r.arrival.p10_s, r.arrival.p50_s, r.arrival.p90_s, r.p_star, r.arrival.method, r.naive_promised_s) if r else None, "tttttp=t")
    p.eq("바꾼 버스 질의: 순위", ("I577e75eb8b", "I370e4c69aa"), output.ranking)
    output = _run("V12g 바꾼 열차 질의")
    r = _by_id(output).get("I52672ef644")
    _fields(p, "바꾼 열차 질의 I52672ef644: (T_plan, 평균, 10%, 50%, 90%, P*, 방법)", (654.0, 656.7955, 629.4842, 654.0, 687.4649, 1.0, "EXACT"), (r.plan_arrival_s, r.arrival.mean_s, r.arrival.p10_s, r.arrival.p50_s, r.arrival.p90_s, r.p_star, r.arrival.method) if r else None, "tttttp=")


