# --- SR7 ~ SR11 의 5단계 값 (§9.5.2: 4단계 검사에 평가 값을 더한다) ---


def _sr7_engine(p: _Probe, scenario: Scenario) -> None:
    query = golden_query()
    ignore = run_engine(scenario, query, EngineConfig())
    _same_as_v12a(p, "IGNORE 엔진", ignore, _GOLDEN_CANDIDATES)
    skip = run_engine(scenario, query, EngineConfig(full_vehicle_policy=FullVehiclePolicy.SKIP))
    _same_as_v12a(p, "SKIP 엔진", skip, ("I3a248c7d10", "I469424fb69", "Ic5c1b22780", "If1e99436b8"))
    p.eq("SKIP 엔진: 순위와 대표 아래 여정", (("Ic5c1b22780", "I3a248c7d10", "If1e99436b8"), (("I3a248c7d10", ("I469424fb69",)),)), _ranking_view(skip))
    p.eq("SKIP 엔진: 기존 방식 1위", "I469424fb69", skip.comparison.naive_best_id)


def _sr8_engine(p: _Probe, base: Scenario, near: Query, far: Query) -> None:
    output = run_engine(base, near, EngineConfig())
    rows = {r.itinerary_id: (r.plan_arrival_s, r.arrival.mean_s, r.p_star) for r in output.itineraries}
    expected = {
        "I310c5f7ad3": (1006.0, 1085.5467, 0.884098),
        "I7560ba5da7": (1289.6072, 1329.5366, 1.0),
        "I94948474c3": (954.0, 1010.8189, 0.776414),
        "I9c66ebe1b3": (954.0, 1004.0221, 0.804026),
        "Iab8eef7e72": (1313.0, 1356.0457, 0.884098),
        "Idf8d0f03cb": (555.6072, 709.7261, 0.847591),
    }
    p.eq("(가) 엔진 후보", tuple(expected), tuple(rows))
    for jid, want in expected.items():
        _fields(p, f"(가) {jid}: (T_plan, 평균, P*)", want, rows.get(jid), "ttp")
    p.eq(
        "(가) 순위와 대표 아래 여정",
        (("Idf8d0f03cb", "I9c66ebe1b3", "I310c5f7ad3", "I7560ba5da7", "Iab8eef7e72"), (("I9c66ebe1b3", ("I94948474c3",)),)),
        _ranking_view(output),
    )
    unverified = next((w for w in output.warnings if w.code == WarningCode.UNVERIFIED_COORDINATES), None)
    p.eq("(가) 경고의 미검증 수 29 (POINT 는 세지 않는다)", 29, len(unverified.ref_ids) if unverified else None)
    failed = run_engine(base, far, EngineConfig())
    snap = next((w for w in failed.warnings if w.code == WarningCode.SNAP_FAILED), None)
    p.eq("(다) run_engine: (status, 후보, SNAP_FAILED 경고)", (EngineStatus.SNAP_FAILED, (), True), (failed.status, failed.itineraries, snap is not None))
    p.true("(다) run_engine 경고 문구에 155.67 m", snap is not None and "155.67 m" in snap.message, snap.message if snap else "")


def _sr9_engine(p: _Probe, scenario: Scenario) -> None:
    output = run_engine(scenario, golden_query(), EngineConfig())
    _same_as_v12a(p, "엔진", output, tuple(jid for jid in _GOLDEN_CANDIDATES if jid != "Ifbf4ec4c04"))
    p.eq("엔진: 기존 방식 1위", "I469424fb69", output.comparison.naive_best_id)
    p.eq(
        "엔진: 순위와 대표 아래 여정",
        (("Ic5c1b22780", "I3a248c7d10", "Idddde0a626", "If1e99436b8"), (("I3a248c7d10", ("I469424fb69",)),)),
        _ranking_view(output),
    )


def _sr11_engine(p: _Probe) -> None:
    output = run_engine(golden_scenario(), golden_query(), EngineConfig(max_rides=1))
    p.eq(
        "기본 질의 엔진: (후보 5개, 기존 방식 1위)",
        (tuple(jid for jid in _GOLDEN_CANDIDATES if jid != "Ifbf4ec4c04"), "I469424fb69"),
        (tuple(_by_id(output)), output.comparison.naive_best_id),
    )


