    """표본 7 (§9.8.1): 노선 정류장 목록, busRouteId "TESTROUTE"."""
    rows = ((10, "126.99500", "37.49500"), (11, "127.00100", "37.49980"), (12, "127.00390", "37.49980"),
            (13, "127.00200", "37.51000"), (14, "127.00200", "37.50010"))
