_N_NOW = 1_794_870_010.0


def _n_build(
    folder: pathlib.Path,
    *,
    osm: str = _SAMPLE6_OSM,
    spec: dict[str, Any] | None = None,
    bus: ResponseMaker | None = None,
) -> tuple[ScenarioBuildReport, _Router]:
    """임시 폴더(데이터 폴더)에 명세와 OSM 을 두고 `_build_scenario` 를 가짜 응답으로 부른다."""
    (folder / "test.osm").write_text(osm, encoding="utf-8")
    (folder / "timetables").mkdir(exist_ok=True)
    spec_path = folder / "TESTGEN.spec.json"
    spec_path.write_text(json.dumps(spec or _n_spec(), ensure_ascii=False), encoding="utf-8")
    router = _Router(route_stations=_json_body(_sample_route_stations()), bus=bus or _json_body(_sample_arrival()),
                     bike=_json_body(_n_bike_payload()))
    config = EngineConfig(data_dir=str(folder))
    with _fake_keys(), router.client() as client:
        report = _build_scenario(spec_path, config, client, now=_N_NOW)
    return report, router


def _n_scenario(p: _Probe, **kwargs: Any) -> Scenario | None:
    with _temp_dir() as tmp:
        report, _ = _n_build(pathlib.Path(tmp), **kwargs)
    p.true("생성됨", report.scenario is not None, report.error or "만들어짐")
    return report.scenario


def _edge_map(scenario: Scenario) -> dict[str, Edge]:
    return {edge.id: edge for edge in scenario.edges}


def _n1(p: _Probe) -> None:
    scenario = _n_scenario(p)
    if scenario is None:
        return
    ways = sorted({int(edge.id[1:].split("-")[0]) for edge in scenario.edges if edge.id.startswith("w")})
    p.eq("쓰인 길", [101, 102, 103, 104, 105, 106, 107, 110], ways)
    ids = {node.id for node in scenario.nodes}
    p.eq("OSM 노드 9, 10 없음", (False, False), ("o9" in ids, "o10" in ids))


def _n2(p: _Probe) -> None:
    scenario = _n_scenario(p)
    if scenario is None:
        return
    walk, both = ("WALK",), ("WALK", "BIKE")
    expected = {"w101-1": ("SIDEWALK", walk), "w102-1": ("SIDEWALK", both), "w103-1": ("CROSSWALK", both),
                "w104-1": ("SIDEWALK", both), "w105-1": ("STAIRS", walk), "w106-1": ("ALLEY", both),
                "w107-1": ("BIKE_LANE", both), "w110-1": ("UNDERPASS", walk)}
    edges = _edge_map(scenario)
    p.eq("엣지 종류와 수단", expected,
         {edge_id: (edges[edge_id].kind.value, tuple(mode.value for mode in edges[edge_id].modes)) if edge_id in edges else None
          for edge_id in expected})
    variants = (
        ("106 에 foot=no → 자전거만", '<way id="106"><nd ref="7"/><nd ref="8"/><tag k="highway" v="residential"/>',
         '<way id="106"><nd ref="7"/><nd ref="8"/><tag k="highway" v="residential"/><tag k="foot" v="no"/>',
         "w106-1", ("ALLEY", ("BIKE",))),
        ("101 을 path, bicycle=no 로 → 도보만", '<way id="101"><nd ref="1"/><nd ref="2"/><tag k="highway" v="footway"/>',
         '<way id="101"><nd ref="1"/><nd ref="2"/><tag k="highway" v="path"/><tag k="bicycle" v="no"/>',
         "w101-1", ("SIDEWALK", walk)),
        ("101 에 bridge=yes → OVERPASS", '<way id="101"><nd ref="1"/><nd ref="2"/><tag k="highway" v="footway"/>',
         '<way id="101"><nd ref="1"/><nd ref="2"/><tag k="highway" v="footway"/><tag k="bridge" v="yes"/>',
         "w101-1", ("OVERPASS", walk)),
    )
    for label, old, new, edge_id, want in variants:
        changed = _n_scenario(p, osm=_SAMPLE6_OSM.replace(old, new))
        edge = None if changed is None else _edge_map(changed).get(edge_id)
        p.eq(label, want, None if edge is None else (edge.kind.value, tuple(mode.value for mode in edge.modes)))


