    config = EngineConfig()
    expected = {"w101-1": 88.2169, "w102-1": 44.1084, "w103-1": 17.6434, "w104-1": 202.8988, "w105-1": 66.7170,
                "w106-1": 264.6485, "w107-1": 66.7170, "w110-1": 110.6043}
    p.approx("길이", sorted(expected.items()),
             sorted((edge_id, edge_length_m(edges[edge_id], index, config)) for edge_id in expected if edge_id in edges), tol=1e-4)
    p.eq("distance_m 은 None", {None}, {edges[edge_id].distance_m for edge_id in expected})


