def _timetable_payload(rows: Sequence[dict[str, str]], line_num: str = "02호선") -> dict[str, Any]:
    """OA-101 응답 모양. 공통 필드(LINE_NUM, STATION_CD, STATION_NM, WEEK_TAG, INOUT_TAG)를 모든 행에 넣는다."""
    common = {"LINE_NUM": line_num, "STATION_CD": "0222", "STATION_NM": "강남", "WEEK_TAG": "1", "INOUT_TAG": "1"}
    return {"SearchSTNTimeTableByIDService": {
        "list_total_count": len(rows),
        "RESULT": {"CODE": "INFO-000", "MESSAGE": "정상 처리되었습니다."},
        "row": [{**common, **row} for row in rows]}}


def _sample_timetable_payload(line_num: str = "02호선") -> dict[str, Any]:
    """표본 8 (§9.8.1): 강남 0222, 요일 1, 방향 1."""
    return _timetable_payload([dict(zip(_SAMPLE8_NAMES, row)) for row in _SAMPLE8_ROWS], line_num)


def _timetable_no_data() -> dict[str, Any]:
    return {"RESULT": {"CODE": "INFO-200", "MESSAGE": "해당하는 데이터가 없습니다."}}


def _timetable_view(row: TimetableRow) -> tuple:
    return (row.line, row.station, row.direction, row.day_type.value, row.train_no, row.arrive_s, row.depart_s,
            row.destination, row.express)


@contextlib.contextmanager
def _main_client(client: httpx.Client) -> Iterator[None]:
    """검사 안에서만 `main` 의 호출이 이 전송을 쓰게 한다."""
    _CLI_CLIENTS.append(client)
    try:
        yield
    finally:
        _CLI_CLIENTS.pop()


def _t1(p: _Probe) -> None:
    config = EngineConfig()
    rows, counts = parse_timetable_payload(_sample_timetable_payload(), 1, 1, config)
    p.eq("행 6개를 응답 순서로", [
        ("2호선", "강남", "내선", "WEEKDAY", "2153", 29_670.0, 29_700.0, "성수", False),
        ("2호선", "강남", "내선", "WEEKDAY", "2001", None, 19_860.0, "성수", False),
        ("2호선", "강남", "내선", "WEEKDAY", "2399", 89_640.0, None, "강남", False),
        ("2호선", "강남", "내선", "WEEKDAY", "2391", 87_150.0, 87_180.0, "성수", False),
        ("2호선", "강남", "내선", "WEEKDAY", "2161", 30_000.0, 30_030.0, "성수", True),
        ("2호선", "강남", "내선", "WEEKDAY", "2163", 30_240.0, 30_270.0, "성수", False),
    ], [_timetable_view(row) for row in rows])
    p.eq("사유별 수", {"건너뜀": 3, "급행 미확인": 1}, counts)
    outer, _ = parse_timetable_payload(_sample_timetable_payload(), 1, 2, config)
    p.eq("방향 2 → 외선", {"외선"}, {row.direction for row in outer})
    holiday, _ = parse_timetable_payload(_sample_timetable_payload(), 3, 1, config)
    p.eq("요일 3 → HOLIDAY", {DayType.HOLIDAY}, {row.day_type for row in holiday})
    up, _ = parse_timetable_payload(_sample_timetable_payload("09호선"), 1, 1, config)
    down, _ = parse_timetable_payload(_sample_timetable_payload("09호선"), 1, 2, config)
    p.eq("09호선 → (9호선, 상행), (9호선, 하행)", ({("9호선", "상행")}, {("9호선", "하행")}),
         ({(row.line, row.direction) for row in up}, {(row.line, row.direction) for row in down}))


def _t2(p: _Probe) -> None:
    config = EngineConfig()
    rows, _ = parse_timetable_payload(_sample_timetable_payload(), 1, 1, config)
    table = Timetable(station_key="0222", rows=tuple(rows), source="표본 8")
    with _temp_dir() as tmp:
        folder = pathlib.Path(tmp)
        path = folder / "0222.csv"
        write_timetable_csv(table, path)
        lines = path.read_text(encoding="utf-8").splitlines()
        p.eq("첫 줄", "line,station,direction,day_type,train_no,arrive,depart,destination,express", lines[0])
        p.eq("행 순서", ["2001", "2153", "2161", "2163", "2391", "2399"], [line.split(",")[4] for line in lines[1:]])
        cells = {line.split(",")[4]: line.split(",") for line in lines[1:]}
        p.eq("2391, 2399 의 시각", (("24:12:30", "24:13:00"), ("24:54:00", "")),
             (tuple(cells["2391"][5:7]), tuple(cells["2399"][5:7])))
        loaded = load_timetable(path)
        p.eq("읽은 행", [_timetable_view(row) for row in sorted(rows, key=_timetable_row_key)],
             [_timetable_view(row) for row in loaded.rows])
        modified = _kst(path.stat().st_mtime).date().isoformat()
        p.eq("station_key 와 source", ("0222", f"0222.csv (수정 {modified})"), (loaded.station_key, loaded.source))

        def broken(label: str, text_lines: list[str], expected: tuple[str, ...]) -> None:
            bad = folder / "고장.csv"
            bad.write_text("\n".join(text_lines) + "\n", encoding="utf-8")
            try:
                load_timetable(bad)
            except ValueError as exc:
                message = str(exc)
                p.true(f"{label}: 메시지에 {', '.join(expected)}", all(part in message for part in expected), message)
            else:
                p.true(f"{label}: ValueError", False, "오류가 나지 않음")

        def third(column: int, value: str) -> list[str]:
            changed = list(lines)
            parts = changed[2].split(",")
            parts[column] = value
            changed[2] = ",".join(parts)
            return changed

        broken("도착 08:60:00", third(5, "08:60:00"), ("3번째 줄",))
        broken("시 48", third(5, "48:00:00"), ("3번째 줄", "48"))
        both = third(5, "")
        both[2] = ",".join(both[2].split(",")[:6] + [""] + both[2].split(",")[7:])
        broken("도착과 출발 모두 빔", both, ("3번째 줄", "모두 비었"))
        broken("열차 번호 빔", third(4, ""), ("3번째 줄", "train_no"))
        broken("같은 행", lines + [lines[2]], ("8번째 줄", "3번째 줄과 같은 행"))
        broken("머리글", [lines[0].replace("train_no", "train")] + lines[1:], ("1번째 줄", "머리글"))
        code, out = _run_main(["--check-timetable", str(path)])
        p.eq("--check-timetable 종료 코드", 0, code)
        p.true("요약: WEEKDAY 내선 6, 첫 05:31:00, 마지막 24:54:00",
               all(part in out for part in ("WEEKDAY 내선 6", "05:31:00", "24:54:00")), out)
        bad = folder / "고장.csv"
        bad.write_text("\n".join(third(5, "08:60:00")) + "\n", encoding="utf-8")
        code, out = _run_main(["--check-timetable", str(bad)])
        p.eq("고장 난 파일의 종료 코드", 1, code)
        p.true("줄 번호와 이유", "3번째 줄" in out and "08:60:00" in out, out)


def _t3(p: _Probe) -> None:
    config = EngineConfig()
    sample = _sample_timetable_payload()

    def group(request: httpx.Request) -> tuple[str, ...]:
        return tuple(request.url.path.split("SearchSTNTimeTableByIDService/", 1)[1].strip("/").split("/"))

    def only_first(request: httpx.Request) -> httpx.Response:
        return httpx.Response(200, json=sample if group(request)[3:] == ("1", "1") else _timetable_no_data())

    router = _Router(timetable=only_first)
    with _fake_keys(), router.client() as client:
        table, results = fetch_timetable("0222", config, client)
    p.eq("요청 6회의 경로 (시작/끝/역코드/요일/방향)",
         [("1", "1000", "0222", str(week), str(inout)) for week in (1, 2, 3) for inout in (1, 2)],
         [group(request) for _, request in router.requests])
    p.eq("행 6개의 Timetable", 6, None if table is None else len(table.rows))
    p.eq("호출 결과 6개, 모두 SUCCESS", [SourceState.SUCCESS] * 6, [result.state for result in results])

    names = ("TRAIN_NO", "ARRIVETIME", "LEFTTIME", "SUBWAYENAME", "EXPRESS_YN")
    full_page = _timetable_payload([dict(zip(names, (f"{3000 + k}", _hms_text(21_600 + 10 * k), "", "성수", "G")))
                                    for k in range(1000)])

    def long_first(request: httpx.Request) -> httpx.Response:
        parts = group(request)
        if parts[3:] == ("1", "1") and parts[0] == "1":
            return httpx.Response(200, json=full_page)
        return httpx.Response(200, json=_timetable_no_data())

    router = _Router(timetable=long_first)
    with _fake_keys(), router.client() as client:
        table, _ = fetch_timetable("0222", config, client)
    paths = [group(request) for _, request in router.requests]
    p.eq("1,000행이면 같은 묶음의 1001/2000 을 이어 부른다", ("1001", "2000", "0222", "1", "1"), paths[1] if len(paths) > 1 else None)
    p.eq("요청 7회, 행 1,000개", (7, 1000), (len(paths), None if table is None else len(table.rows)))

    def fail_second(request: httpx.Request) -> httpx.Response:
        if group(request)[3:] == ("1", "2"):
            return httpx.Response(500, text="status 500")
        return only_first(request)

    router = _Router(timetable=fail_second)
    with _fake_keys(), router.client() as client:
        table, results = fetch_timetable("0222", config, client)
    p.eq("HTTP 500 이면 None 이고 FAILED 가 있다", (None, True),
         (table, any(result.state == SourceState.FAILED for result in results)))

    with _temp_dir() as tmp:
        folder = pathlib.Path(tmp)
        router = _Router(timetable=_json_body(_timetable_no_data()))
        with _fake_keys(), router.client() as client:
            table, _ = fetch_timetable("0222", config, client)
            with _main_client(client):
                code, out = _run_main(["--fetch-timetable", "0222", "--out", str(folder)])
        p.eq("모두 INFO-200 → None", None, table)
        p.eq("모두 INFO-200 → 종료 코드 1, 파일 없음", (1, False), (code, (folder / "0222.csv").exists()))
        p.true("이유 문구", NO_TIMETABLE_REASON in out, out)

        router = _Router(timetable=only_first)
        with _fake_keys(), router.client() as client, _main_client(client):
            code, out = _run_main(["--fetch-timetable", "0222", "--out", str(folder)])
        p.eq("정상 → 종료 코드 0, 0222.csv", (0, True), (code, (folder / "0222.csv").exists()))
        p.true("요약과 건너뛴 행 수 3",
               all(part in out for part in ("WEEKDAY 내선 6", "05:31:00", "24:54:00", "건너뛴 행 3개")), out)
        p.eq("저장한 파일을 다시 읽으면 행 6개", 6, len(load_timetable(folder / "0222.csv").rows))

        router = _Router(timetable=only_first)
        with _no_keys(), router.client() as client:
            table, results = fetch_timetable("0222", config, client)
            with _main_client(client):
                code, out = _run_main(["--fetch-timetable", "0222", "--out", str(folder / "키없음")])
        p.eq("키 없음 → None, SKIPPED, 요청 0회", (None, SourceState.SKIPPED, 0),
             (table, results[0].state if results else None, len(router.requests)))
        p.eq("키 없음 → 종료 코드 1", 1, code)
        p.true("키 값이 출력에 없다", all(value not in out for _, value in _FAKE_KEYS), out)


