def _t_station_scenario(**changes: Any) -> Scenario:
    golden = golden_scenario()
    platforms = tuple(
        Node(id=node_id, name=name, node_type=NodeType.SUBWAY_PLATFORM, lat=_golden_lat(y), lon=_golden_lon(x),
             verified=False, source=_GOLDEN_SOURCE)
        for node_id, name, x, y in _T_EXTRA_PLATFORMS
    )
    stations = golden.subway_stations + (
        SubwayStation(key="M4", name="역4", platforms=(("가상선", "P4"),)),
        SubwayStation(key="L1", name="순환1", platforms=(("순환선", "PL1"),)),
        SubwayStation(key="L2", name="순환2", platforms=(("순환선", "PL2"),)),
        SubwayStation(key="L3", name="순환3", platforms=(("순환선", "PL3"),)),
    )
    return Scenario(**{**dict(golden), "nodes": golden.nodes + platforms, "subway_stations": stations, **changes})


def _t_timetables(
    trains: Iterable[tuple[DayType, str, bool, tuple[tuple[str, str | None, str | None], ...]]],
    line: str = "가상선",
    direction: str = "하행",
    destination: str = "역4",
) -> list[Timetable]:
    """(요일 종류, 열차, 급행, 정차) 표 → 역마다 `Timetable`."""
    by_station: dict[str, list[TimetableRow]] = {}
    for day_type, train_no, express, stops in trains:
        for station, arrive, depart in stops:
            by_station.setdefault(station, []).append(TimetableRow(
                line=line, station=station, direction=direction, day_type=day_type, train_no=train_no,
                arrive_s=None if arrive is None else _hms_value(arrive), depart_s=None if depart is None else _hms_value(depart),
                destination=destination, express=express))
    return [Timetable(station_key=station, rows=tuple(sorted(rows, key=_timetable_row_key)), source="T 검사")
            for station, rows in sorted(by_station.items())]


def _t_day_timetables() -> list[Timetable]:
    trains = [(DayType.WEEKDAY, train_no, express, stops) for train_no, express, stops in _T_DAY_TRAINS]
    trains += [(day_type, train_no, False, stops) for day_type, train_no, stops in _T_OTHER_DAYS]
    return _t_timetables(trains)


def _t_distances(folder: pathlib.Path) -> dict[tuple[str, str, str], float]:
    path = folder / "subway_distances.csv"
    path.write_text("\n".join([",".join(DISTANCE_COLUMNS)] + [",".join(row) for row in _T_DISTANCE_ROWS]) + "\n", encoding="utf-8")
    return load_subway_distances(path)


def _t_day_patterns(config: EngineConfig) -> tuple[tuple[SubwayPattern, ...], tuple[EngineWarning, ...]]:
    with _temp_dir() as tmp:
        distances = _t_distances(pathlib.Path(tmp))
    return build_subway_patterns(_t_day_timetables(), _t_station_scenario(), distances, 28_800.0, DayType.WEEKDAY,
                                 DayType.HOLIDAY, config)


def _t_midnight_patterns(config: EngineConfig) -> tuple[tuple[SubwayPattern, ...], tuple[EngineWarning, ...]]:
    trains = [(DayType.WEEKDAY, train_no, False, stops) for train_no, stops in _T_MIDNIGHT_TRAINS]
    with _temp_dir() as tmp:
        distances = _t_distances(pathlib.Path(tmp))
    return build_subway_patterns(_t_timetables(trains, destination="역3"), _t_station_scenario(), distances, 1_200.0,
                                 DayType.WEEKDAY, DayType.WEEKDAY, config)


def _pattern_view(pattern: SubwayPattern) -> tuple:
    return (pattern.id, pattern.station_keys, pattern.platform_ids, pattern.segment_dist_m, pattern.distance_verified,
            tuple((trip.id, trip.train_no, trip.arr_s, trip.dep_s, trip.express) for trip in pattern.trips))


def _t4(p: _Probe) -> None:
    config = EngineConfig()
    with _temp_dir() as tmp:
        distances = _t_distances(pathlib.Path(tmp))
    p.eq("거리표 읽기", {(line, a, b): float(km) for line, a, b, km in _T_DISTANCE_ROWS}, distances)
    patterns, warnings = _t_day_patterns(config)
    base = "가상선:하행:M1-M4"
    p.approx("패턴 3개", [
        (f"{base}:3", ("M1", "M2", "M4"), ("P1", "P2", "P4"), (710.0, 1400.93), (True, False),
         (("E203", "E203", (420.0, 510.0, 660.0), (420.0, 540.0, 660.0), True),)),
        (f"{base}:3#2", ("M1", "M3", "M4"), ("P1", "P3", "P4"), (1370.0, 750.04), (True, False),
         (("E201", "E201", (180.0, 390.0, 540.0), (180.0, 420.0, 540.0), True),)),
        (f"{base}:4", ("M1", "M2", "M3", "M4"), ("P1", "P2", "P3", "P4"), (710.0, 660.0, 750.04), (True, True, False), (
            ("099", "099", (-300.0, -180.0, -30.0, 120.0), (-300.0, -150.0, 0.0, 120.0), False),
            ("101", "101", (60.0, 180.0, 330.0, 480.0), (60.0, 210.0, 360.0, 480.0), False),
            ("103", "103", (300.0, 420.0, 570.0, 960.0), (300.0, 450.0, 600.0, 960.0), False),
            ("105", "105", (540.0, 660.0, 780.0, 960.0), (540.0, 690.0, 810.0, 960.0), False))),
    ], [_pattern_view(pattern) for pattern in patterns], tol=0.005)
    p.eq("운행일과 행선지", {(DayType.WEEKDAY, "역4")},
         {(trip.service_day, trip.destination) for pattern in patterns for trip in pattern.trips})
    p.eq("경고", sorted([
        ("TIMETABLE_OVERTAKE", (f"{base}:4", "105")),
        ("TIMETABLE_STATION_UNUSED", ("M9", "가상선")),
        ("UNVERIFIED_DISTANCE", (f"{base}:3", "M2", "M4")),
        ("UNVERIFIED_DISTANCE", (f"{base}:3#2", "M3", "M4")),
        ("UNVERIFIED_DISTANCE", (f"{base}:4", "M3", "M4")),
    ]), sorted((warning.code.value, warning.ref_ids) for warning in warnings))
    overtake = next((warning for warning in warnings if warning.code == WarningCode.TIMETABLE_OVERTAKE), None)
    p.true("추월 경고의 고친 순번 1", overtake is not None and "1개 순번" in overtake.message,
           "" if overtake is None else overtake.message)


