def _t6(p: _Probe) -> None:
    config = EngineConfig()
    patterns, _ = _t_day_patterns(config)
    scenario = _t_station_scenario(subway_patterns=patterns)
    base = "가상선:하행:M1-M4"
    p.approx("M3", [
        (330.0, "101", f"{base}:4", 2, "08:05:30", False),
        (390.0, "E201", f"{base}:3#2", 1, "08:06:30", True),
        (570.0, "103", f"{base}:4", 2, "08:09:30", False),
        (780.0, "105", f"{base}:4", 2, "08:13:00", False),
    ], [_candidate_view(choice) for choice in train_candidates(scenario, "M3", config)])
    p.approx("M4", [(120.0, "099"), (480.0, "101"), (540.0, "E201"), (660.0, "E203"), (960.0, "103"), (960.0, "105")],
             [(choice.arrive_s, choice.trip_id) for choice in train_candidates(scenario, "M4", config)])
    p.approx("M1", [(60.0, "101"), (180.0, "E201"), (300.0, "103"), (420.0, "E203"), (540.0, "105")],
             [(choice.arrive_s, choice.trip_id) for choice in train_candidates(scenario, "M1", config)])
    choices = train_candidates(scenario, "M3", config)
    p.eq("후보의 호선, 방향, 행선지, 열차 번호", {("가상선", "하행", "역4")},
         {(choice.line, choice.direction, choice.destination) for choice in choices})
    p.eq("열차 번호와 역", [("101", "M3"), ("E201", "M3"), ("103", "M3"), ("105", "M3")],
         [(choice.train_no, choice.station_key) for choice in choices])
    golden = train_candidates(golden_scenario(), "M2", config)
    p.approx("골든 M2: 1000 ~ 1006, j0 = 1", [(f"{1000 + k}", 170.0 + 240.0 * k, 1) for k in range(7)],
             [(choice.trip_id, choice.arrive_s, choice.index) for choice in golden])
    midnight, _ = _t_midnight_patterns(config)
    scenario = _t_station_scenario(subway_patterns=midnight, clock_s=1_200.0)
    p.approx("자정 M3", [("175@전날", "175", 30.0, "00:20:30"), ("171@전날", "171", 570.0, "00:29:30")],
             [(choice.trip_id, choice.train_no, choice.arrive_s, choice.clock_label)
              for choice in train_candidates(scenario, "M3", config)])




# --- RP1 ~ RP6 (§9.7.5): 재생, 실시간 덮어쓰기, 학습. 합성 기록은 임시 폴더에 한 번 만들어 함께 쓴다 ---

_SYNTHETIC: dict[str, Any] = {}


def _synthetic_world() -> tuple[SyntheticTruth, EngineConfig]:
    """RP 와 K4 가 함께 쓰는 합성 기록과 설정(`data_dir` = 그 폴더, 휴일 없음). `run_selftest` 가 끝에 지운다."""
    if "truth" not in _SYNTHETIC:
        folder = _temp_dir()
        _SYNTHETIC["dir"] = folder
        _SYNTHETIC["truth"] = make_synthetic_records(pathlib.Path(folder.name) / "synthetic")
    truth: SyntheticTruth = _SYNTHETIC["truth"]
    return truth, EngineConfig(data_dir=str(truth.data_dir))


def _drop_synthetic_world() -> None:
    folder = _SYNTHETIC.pop("dir", None)
    _SYNTHETIC.clear()
    if folder is not None:
        folder.cleanup()


def _syn_scenario(truth: SyntheticTruth) -> Scenario:
    return load_scenario_json(truth.scenario_path)


def _replay_at(truth: SyntheticTruth, config: EngineConfig, at: float, models: Models | None = None) -> tuple[Scenario, tuple[ApiSourceStatus, ...]]:
    with RecordStore(truth.store_path, read_only=True) as store:
        return replay_scenario(_syn_scenario(truth), store, models, at, config)


def _run_default(scenario: Scenario, config: EngineConfig, sources: Sequence[ApiSourceStatus] = ()) -> EngineOutput:
    return run_engine(scenario, scenario.default_query, config, sources)


def _rp_same(p: _Probe, label: str, expected: EngineOutput, actual: EngineOutput) -> None:
    """"요약 같음"(§9.7.5): 후보 ID 집합, 후보마다 T_plan, P*, 평균, 90% 도착, T_naive, 등급, 상태, 순위, 최선, 기존 방식 1위."""

    def parts(output: EngineOutput) -> tuple:
        items = sorted(output.itineraries, key=lambda result: result.itinerary_id)
        return (
            tuple(result.itinerary_id for result in items),
            tuple((r.plan_arrival_s, r.arrival.mean_s, r.arrival.p90_s, r.naive_promised_s) for r in items),
            tuple(r.p_star for r in items),
            tuple((r.grade.value, r.status.value) for r in items),
            (output.ranking, output.best_id, output.comparison.naive_best_id),
        )

    want, got = parts(expected), parts(actual)
    p.eq(f"{label}: 후보 ID", want[0], got[0])
    p.approx(f"{label}: 후보마다 (T_plan, 평균, 90%, T_naive)", want[1], got[1], 0.01)
    p.approx(f"{label}: 후보마다 P*", want[2], got[2], 1e-5)
    p.eq(f"{label}: 후보마다 (등급, 상태)", want[3], got[3])
    p.eq(f"{label}: (순위, 최선, 기존 방식 1위)", want[4], got[4])


def _rp_expect(
    p: _Probe,
    label: str,
    output: EngineOutput,
    rows: Sequence[tuple[str, str | None, float, float, str]],
    ranking: tuple[str, ...],
    best: str | None,
    naive: str | None,
) -> None:
    """§9.7.5 표의 후보 값 (ID, 이름, T_plan, P*, 등급)과 순위, 최선, 기존 방식 1위를 비교한다(시간 0.01 s, 확률 1e-5)."""
    by_id = {result.itinerary_id: result for result in output.itineraries}
    p.eq(f"{label}: 후보 ID", tuple(sorted(row[0] for row in rows)), tuple(sorted(by_id)))
    for itinerary_id, name, t_plan, p_star, grade in rows:
        result = by_id.get(itinerary_id)
        if result is None:
            continue
        if name is not None:
            p.eq(f"{label}: {itinerary_id} 이름", name, result.label)
        p.approx(f"{label}: {itinerary_id} T_plan", t_plan, result.plan_arrival_s, 0.01)
        p.approx(f"{label}: {itinerary_id} P*", p_star, result.p_star, 1e-5)
        p.eq(f"{label}: {itinerary_id} 등급", grade, result.grade.value)
    p.eq(f"{label}: (순위, 최선, 기존 방식 1위)", (ranking, best, naive),
         (output.ranking, output.best_id, output.comparison.naive_best_id))


def _status_view(status: ApiSourceStatus) -> tuple:
    return (status.source.value, status.target, status.state.value, status.observed_at)


def _eta_view(line: BusLine) -> tuple:
    return tuple(tuple((item.vehicle_id, item.eta_s) for item in items) for items in line.predictions)


def _table_rows(store: RecordStore) -> dict[str, list[tuple]]:
    """저장소의 모든 표의 행(rowid 순). 두 번 만든 저장소를 행 단위로 비교한다."""
    tables = ("meta", "polls", "arr_obs", "bike_obs", "sig_obs", "api_log")
    return {table: store.execute(f"SELECT * FROM {table} ORDER BY rowid").fetchall() for table in tables}


def _rp1(p: _Probe) -> None:
    truth, _ = _synthetic_world()
    p.eq("SyntheticTruth: 날짜, 조회 간격, 실패 목록",
         (("2026-11-02", "2026-11-03", "2026-11-04"), 30.0,
          (("2026-11-03", "BUS_ARRIVAL", "SYN-G1", "08:12:00"), ("2026-11-03", "BUS_ARRIVAL", "SYN-G2", "08:20:00"),
           ("2026-11-03", "BUS_ARRIVAL", "SYN-G2", "08:20:30"))),
         (truth.dates, truth.poll_s, truth.failed_polls))
    p.eq("SyntheticTruth: 신호 참값", {"SYN-SG3": (90.0, 40.0, 85.0), "SYN-SG4": (120.0, 50.0, 0.0)}, dict(truth.signal_truth))
    p.eq("SyntheticTruth: 공식 ID 표",
         {"G1": "SYN-G1", "G2": "SYN-G2", "K1": "SYN-K1", "K2": "SYN-K2", "K3": "SYN-K3", "K4": "SYN-K4", "K5": "SYN-K5",
          "SG3": "SYN-SG3", "SG4": "SYN-SG4"}, dict(truth.official_ids))
    folder = truth.data_dir
    p.eq("만든 파일",
         ("collect_targets.json", "records.sqlite", "scenarios/SYN.json", "subway_distances.csv", "timetables/M1.csv",
          "timetables/M2.csv", "timetables/M3.csv"),
         tuple(sorted(path.relative_to(folder).as_posix() for path in folder.rglob("*") if path.is_file()
                      and not path.name.endswith(("-wal", "-shm")))))
    p.eq("SyntheticTruth 의 경로",
         (folder / "scenarios" / "SYN.json", (folder / "timetables" / "M1.csv", folder / "timetables" / "M2.csv",
          folder / "timetables" / "M3.csv"), folder / "subway_distances.csv", folder / "collect_targets.json",
          folder / "records.sqlite"),
         (truth.scenario_path, truth.timetable_paths, truth.distances_path, truth.targets_path, truth.store_path))
    targets = CollectTargets.model_validate_json(truth.targets_path.read_bytes())
    example = CollectTargets.model_validate_json(DEFAULT_TARGETS_JSON)
    p.eq("수집 대상: poll_s, 노선, 지역, 시간대, 휴일",
         (30.0, (("SYN-G1", "가상1"), ("SYN-G2", "가상2")), (("합성", 37.5, 127.0, 2500.0),), (("합성", 37.5, 127.0, 2500.0),),
          (("평일 아침", ("WEEKDAY",), "07:30", "09:00"),), ()),
         (targets.poll_s, tuple((r.route_id, r.name) for r in targets.routes),
          tuple((a.name, a.lat, a.lon, a.radius_m) for a in targets.bike_areas),
          tuple((a.name, a.lat, a.lon, a.radius_m) for a in targets.signal_areas),
          tuple((w.name, tuple(d.value for d in w.day_types), w.start, w.end) for w in targets.windows), targets.holidays))
    p.eq("수집 대상: 한도, bike_history, signal_api 는 §5.3 예시 그대로",
         (example.daily_call_limits, example.bike_history, example.signal_api),
         (targets.daily_call_limits, targets.bike_history, targets.signal_api))
    p.eq("역간 거리표", {("가상선", "M1", "M2"): 0.71, ("가상선", "M2", "M3"): 0.66}, load_subway_distances(truth.distances_path))
    first = load_timetable(truth.timetable_paths[0]).rows[0]
    p.eq("시각표 M1 의 열차 1000",
         ("가상선", "역1", "하행", "WEEKDAY", "1000", 28_840.0, 28_860.0, "역3", False),
         (first.line, first.station, first.direction, first.day_type.value, first.train_no, first.arrive_s, first.depart_s,
          first.destination, first.express))
    p.eq("시각표 행 수 (M1, M2, M3)", (30, 30, 30), tuple(len(load_timetable(path).rows) for path in truth.timetable_paths))
    t800 = _kst_unix(2026, 11, 2, 8, 0)
    with RecordStore(truth.store_path, read_only=True) as store:
        p.eq("행 수 (polls, arr_obs, bike_obs, sig_obs, api_log)", (2160, 5386, 2700, 1080, 2160),
             tuple(_count(store, table) for table in ("polls", "arr_obs", "bike_obs", "sig_obs", "api_log")))
        p.eq("원천별 (조회, 성공)", {"BUS_ARRIVAL": (1080, 1077), "BIKE": (540, 540), "SIGNAL": (540, 540)},
             {source: (n, ok) for source, n, ok in store.execute("SELECT source, COUNT(*), SUM(ok) FROM polls GROUP BY source")})
        p.eq("arr_obs 종류", {"NORMAL": 4308, "NO_INFO": 1078}, dict(store.execute("SELECT kind, COUNT(*) FROM arr_obs GROUP BY kind").fetchall()))
        p.eq("poll_id 241", (241, "BUS_ARRIVAL", "SYN-G1", "평일 아침", t800, 1, 6),
             store.execute('SELECT poll_id, source, target_id, "window", t_unix, ok, n_items FROM polls WHERE poll_id = 241').fetchone())
        rows = store.execute("SELECT sta_ord, slot, kind, veh_id, sect_ord, exps, arrmsg FROM arr_obs WHERE poll_id = 241 ORDER BY rowid").fetchall()
        p.eq("SYN-G1 08:00:00 의 행",
             [(11, 1, "NORMAL", "G1-04", 10, 200.0, "3분20초후[1번째 전]"), (11, 2, "NORMAL", "G1-05", 10, 800.0, "13분20초후[1번째 전]"),
              (12, 1, "NORMAL", "G1-04", 10, 350.0, "5분50초후[2번째 전]"), (12, 2, "NORMAL", "G1-05", 10, 950.0, "15분50초후[2번째 전]"),
              (13, 1, "NO_INFO", None, None, None, ""), (13, 2, "NO_INFO", None, None, None, "")], rows)
        p.eq("정류장 11 칸 1 의 나머지 칸 (route_id, st_id, ars_id, mk_unix, kals, neus, 만차, 막차, 도착, term, 노선 종류)",
             ("SYN-G1", "SYNST11", "90011", t800, None, None, 0, 0, 0, 10.0, "3"),
             store.execute("SELECT route_id, st_id, ars_id, mk_unix, kals, neus, full_flag, is_last, is_arrive, term_min, route_type "
                           "FROM arr_obs WHERE poll_id = 241 ORDER BY rowid LIMIT 1").fetchone())
        g2 = store.execute("SELECT a.sta_ord, a.veh_id, a.sect_ord, a.exps, a.route_type FROM arr_obs a JOIN polls p ON p.poll_id = a.poll_id "
                           "WHERE p.target_id = 'SYN-G2' AND p.t_unix = ? ORDER BY a.rowid", (t800,)).fetchall()
        p.eq("SYN-G2 08:00:00 의 행", [(21, "G2-04", 20, 420.0, "4"), (21, "G2-05", 20, 1020.0, "4"), (22, "G2-04", 20, 600.0, "4"),
                                     (22, "G2-05", 20, 1200.0, "4")], g2)

        def bikes(t: float) -> tuple:
            return tuple(row[0] for row in store.execute(
                "SELECT b.bikes FROM bike_obs b JOIN polls p ON p.poll_id = b.poll_id WHERE p.source = 'BIKE' AND p.t_unix = ? "
                "ORDER BY b.rowid", (t,)))

        def signals(t: float) -> tuple:
            return tuple(store.execute(
                "SELECT s.signal_src_id, s.state, s.remaining_s, s.obs_unix FROM sig_obs s JOIN polls p ON p.poll_id = s.poll_id "
                "WHERE p.source = 'SIGNAL' AND p.t_unix = ? ORDER BY s.rowid", (t,)).fetchall())

        p.eq("자전거 수 08:00:00, 08:00:30, 07:59:30", ((1, 2, 0, 1, 3), (2, 2, 0, 1, 3), (3, 2, 0, 1, 3)),
             (bikes(t800), bikes(t800 + 30), bikes(t800 - 30)))
        p.eq("대여소와 거치대 (08:00:00)", [("SYN-K1", 10), ("SYN-K2", 10), ("SYN-K3", 10), ("SYN-K4", 10), ("SYN-K5", 10)],
             store.execute("SELECT b.station_id, b.racks FROM bike_obs b JOIN polls p ON p.poll_id = b.poll_id "
                           "WHERE p.source = 'BIKE' AND p.t_unix = ? ORDER BY b.rowid", (t800,)).fetchall())
        p.eq("신호 08:00:00", (("SYN-SG3", "RED", 5.0, t800), ("SYN-SG4", "GREEN", 50.0, t800)), signals(t800))
        p.eq("신호 08:00:30", (("SYN-SG3", "GREEN", 15.0, t800 + 30), ("SYN-SG4", "GREEN", 20.0, t800 + 30)), signals(t800 + 30))
        t_fail = _kst_unix(2026, 11, 3, 8, 12)
        p.eq("실패 조회 (2026-11-03 08:12:00 SYN-G1)와 api_log",
             ((0, 0, 0), ("bus_arrival_all", "SYN-G1", 500, 100.0, "HTTP 500", None)),
             (store.execute("SELECT p.ok, p.n_items, (SELECT COUNT(*) FROM arr_obs a WHERE a.poll_id = p.poll_id) FROM polls p "
                            "WHERE p.target_id = 'SYN-G1' AND p.t_unix = ?", (t_fail,)).fetchone(),
              store.execute("SELECT api, target_id, http_status, latency_ms, error, sample FROM api_log WHERE api = 'bus_arrival_all' "
                            "AND target_id = 'SYN-G1' AND t_unix = ?", (t_fail,)).fetchone()))
        p.eq("api_log 의 (api, 대상, HTTP, 수)",
             [("bike_list", "쪽 1", 200, 540), ("bus_arrival_all", "SYN-G1", 200, 539), ("bus_arrival_all", "SYN-G1", 500, 1),
              ("bus_arrival_all", "SYN-G2", 200, 538), ("bus_arrival_all", "SYN-G2", 500, 2), ("signal", "쪽 1", 200, 540)],
             store.execute("SELECT api, target_id, http_status, COUNT(*) FROM api_log GROUP BY api, target_id, http_status "
                           "ORDER BY api, target_id, http_status").fetchall())
        summary = record_summary(store, targets)
        first_t, last_t = _kst_unix(2026, 11, 2, 7, 30), _kst_unix(2026, 11, 4, 8, 59, 30)
        p.approx("record_summary: 원천마다 (대상, 조회, 성공률, 첫 조회, 마지막 조회, 조회 주기)",
                 (("BUS_ARRIVAL", 2, 1080, 0.997222, first_t, last_t, 30.0), ("BIKE", 1, 540, 1.0, first_t, last_t, 30.0),
                  ("SIGNAL", 1, 540, 1.0, first_t, last_t, 30.0)),
                 tuple((s.source, s.targets, s.polls, s.success_rate, s.first_unix, s.last_unix, s.period_s) for s in summary.sources),
                 1e-6)
        p.eq("record_summary: 날짜와 요일 종류", (("2026-11-02", "WEEKDAY"), ("2026-11-03", "WEEKDAY"), ("2026-11-04", "WEEKDAY")),
             tuple((day, kind.value) for day, kind in summary.dates))
        p.approx("record_summary: 시연 시간대 기록", (("2026-11-02", "평일 아침", 720, 1.0), ("2026-11-03", "평일 아침", 720, 0.995833),
                                              ("2026-11-04", "평일 아침", 720, 1.0)),
                 tuple((w.date, w.window, w.polls, w.success_rate) for w in summary.windows), 1e-6)
        p.eq("record_summary: BUS_ARRIVAL 실패 사유", (("HTTP 500", 3),), summary.source("BUS_ARRIVAL").failure_reasons)
        check = summary.remaining_check
        p.eq("남은 시간 검산 (쌍, 중앙값, 신호별)", (447, -1.0, (("SYN-SG3", 177), ("SYN-SG4", 270))),
             (check.pairs, check.median, check.per_signal) if check else None)
        before = _table_rows(store)
    again = make_synthetic_records(folder)
    with RecordStore(again.store_path, read_only=True) as store:
        after = _table_rows(store)
    p.true("같은 폴더에 두 번 만들면 모든 표가 행 단위로 같다", before == after,
           ", ".join(f"{table} {len(before[table])}/{len(after[table])}" for table in before))
    with _temp_dir() as tmp:
        real = pathlib.Path(tmp)
        RecordStore(real / "records.sqlite").close()
        p.raises("실제 기록 저장소가 있는 폴더는 거부", ValueError, lambda: make_synthetic_records(real))
        (real / "records.sqlite").unlink()
        (real / "collect_targets.json").write_text(DEFAULT_TARGETS_JSON, encoding="utf-8")
        p.raises("내용이 다른 collect_targets.json 이 있는 폴더는 거부", ValueError, lambda: make_synthetic_records(real))
        p.eq("거부한 폴더의 collect_targets.json 은 그대로", DEFAULT_TARGETS_JSON, (real / "collect_targets.json").read_text(encoding="utf-8"))


def _rp2(p: _Probe) -> None:
    truth, config = _synthetic_world()
    base = _syn_scenario(truth)
    golden = golden_scenario()
    p.eq("SYN: ID, 이름", ("SYN", "합성 기록 시험 세계"), (base.id, base.title))
    p.eq("SYN: 노선 공식 ID 와 stop_ords", (("G1", "SYN-G1", (11, 12, 13)), ("G2", "SYN-G2", (21, 22))),
         tuple((line.id, line.official_route_id, line.stop_ords) for line in base.bus_lines))
    p.eq("SYN: 대여소와 신호의 공식 ID", (("SYN-K1", "SYN-K2", "SYN-K3", "SYN-K4", "SYN-K5"), (None, None, "SYN-SG3", "SYN-SG4")),
         (tuple(s.official_id for s in base.bike_stations), tuple(s.official_id for s in base.signals)))

    def strip(scenario: Scenario) -> dict:
        data = scenario.model_dump(mode="json")
        data.update(id="", title="")
        for line in data["bus_lines"]:
            line.update(official_route_id=None, stop_ords=None)
        for item in data["bike_stations"] + data["signals"]:
            item["official_id"] = None
        return data

    p.true("SYN 의 나머지는 골든과 같다", strip(base) == strip(golden))
    at = _kst_unix(2026, 11, 2, 8, 0)
    replayed, sources = _replay_at(truth, config, at)
    p.eq("(clock_s, day_type, data_mode, record_note)", (28_800.0, "WEEKDAY", "REPLAY", "2026-11-02(월) 08:00:00 기록 재생"),
         (replayed.clock_s, replayed.day_type.value, replayed.data_mode.value, replayed.record_note))
    observed = "2026-11-02T08:00:00+09:00"
    p.eq("원천 상태 (원천, 대상, 상태, 관측 시각)",
         (("BUS_ARRIVAL", "SYN-G1", "SUCCESS", observed), ("BUS_ARRIVAL", "SYN-G2", "SUCCESS", observed),
          ("BIKE", "합성", "SUCCESS", observed), ("SIGNAL", "합성", "SUCCESS", observed), ("SUBWAY_TIMETABLE", "", "SUCCESS")),
         tuple(_status_view(s)[:3] if s.source == SourceKind.SUBWAY_TIMETABLE else _status_view(s) for s in sources))
    p.eq("원천 상태: 재생은 시도 0, issues 없음", ((0,) * 5, ((),) * 5), (tuple(s.attempts for s in sources), tuple(s.issues for s in sources)))
    lines = {line.id: line for line in replayed.bus_lines}
    p.eq("G1 예측 (순위, 차량, 종류, eta, 구간)",
         (((1, "G1-04", "NORMAL", 200.0, 10), (2, "G1-05", "NORMAL", 800.0, 10)),
          ((1, "G1-04", "NORMAL", 350.0, 10), (2, "G1-05", "NORMAL", 950.0, 10)),
          ((1, "", "NO_INFO", None, None), (2, "", "NO_INFO", None, None))),
         tuple(tuple((i.rank, i.vehicle_id, i.kind.value, i.eta_s, i.sect_ord) for i in items) for items in lines["G1"].predictions))
    p.eq("G1 배차 간격과 관측 경과", (600.0, 0.0), (lines["G1"].headway_s, lines["G1"].prediction_age_s))
    p.eq("G2 예측 (차량, eta)과 구간", (((("G2-04", 420.0), ("G2-05", 1020.0)), (("G2-04", 600.0), ("G2-05", 1200.0))), {20}),
         (_eta_view(lines["G2"]), {i.sect_ord for items in lines["G2"].predictions for i in items}))
    p.eq("자전거 수와 bike_obs_age_s", (tuple(s.bikes_available for s in golden.bike_stations), 0.0),
         (tuple(s.bikes_available for s in replayed.bike_stations), replayed.bike_obs_age_s))
    signals = {phase.id: phase for phase in replayed.signals}
    p.eq("SG3, SG4 개방과 오프셋", ((True, 85.0), (True, 0.0)),
         ((signals["SG3"].realtime_open, signals["SG3"].offset_s), (signals["SG4"].realtime_open, signals["SG4"].offset_s)))
    p.eq("SG1, SG2 는 골든과 같다", tuple(s for s in golden.signals if s.id in ("SG1", "SG2")),
         tuple(signals[key] for key in ("SG1", "SG2")))
    patterns = replayed.subway_patterns
    p.eq("지하철 패턴", (GOLDEN_PATTERN_ID,), tuple(pattern.id for pattern in patterns))
    if patterns:
        pattern, expected = patterns[0], golden.subway_patterns[0]
        p.eq("열차 30대 (1000 ~ 1029)", tuple(str(1000 + k) for k in range(30)), tuple(trip.id for trip in pattern.trips))
        diff = max(abs(a - b) for mine, gold in zip(pattern.trips, expected.trips)
                   for a, b in zip(mine.arr_s + mine.dep_s, gold.arr_s + gold.dep_s))
        p.true("열차 시각이 골든과 1e-9 s 안에서 같다", diff <= 1e-9, f"최대 차이 {diff:g}")
        p.eq("구간 거리와 거리표 확인", ((710.0, 660.0), (True, True)), (pattern.segment_dist_m, pattern.distance_verified))
    golden_output = _run_default(golden, config)
    replay_output = _run_default(replayed, config, sources)
    _rp_same(p, "재생 08:00:00 과 골든", golden_output, replay_output)
    p.eq("run_engine 의 sources 는 원천 상태 그대로", sources, replay_output.sources)


def _rp3(p: _Probe) -> None:
    truth, config = _synthetic_world()
    replayed, sources = _replay_at(truth, config, _kst_unix(2026, 11, 2, 8, 0, 10))
    p.eq("08:00:10: 원천의 관측 시각은 08:00:00 (고른 조회의 요청 시각)", ("2026-11-02T08:00:00+09:00",) * 4,
         tuple(s.observed_at for s in sources if s.source != SourceKind.SUBWAY_TIMETABLE))
    lines = {line.id: line for line in replayed.bus_lines}
    p.eq("08:00:10: G1 B1, B2 와 관측 경과", (((("G1-04", 190.0), ("G1-05", 790.0)), (("G1-04", 340.0), ("G1-05", 940.0))), 10.0),
         (_eta_view(lines["G1"])[:2], lines["G1"].prediction_age_s))
    signals = {phase.id: phase for phase in replayed.signals}
    p.eq("08:00:10: SG3, SG4 오프셋과 bike_obs_age_s", (5.0, 10.0, 10.0), (signals["SG3"].offset_s, signals["SG4"].offset_s, replayed.bike_obs_age_s))
    p.eq("08:00:10: 열차 1000 의 역1 도착", 30.0, replayed.subway_patterns[0].trips[0].arr_s[0] if replayed.subway_patterns else None)
    output = _run_default(replayed, config, sources)
    _rp_same(p, "08:00:10 과 advance_clock(골든, 10)", _run_default(advance_clock(golden_scenario(), 10.0, config), config), output)
    _rp_expect(
        p, "08:00:10", output,
        (("Ic5c1b22780", "따릉이", 546.0, 0.846482, "SAFE"), ("I3a248c7d10", "지하철 가상선", 944.0, 0.806938, "SAFE"),
         ("I469424fb69", None, 944.0, 0.777786, "SAFE"), ("Idddde0a626", "가상1번", 996.0, 0.894350, "SAFE"),
         ("If1e99436b8", "도보", 1350.0, 1.0, "SAFE"), ("Ifbf4ec4c04", "가상1번 → 가상2번", 1303.0, 0.894350, "SAFE")),
        ("Ic5c1b22780", "I3a248c7d10", "Idddde0a626", "If1e99436b8", "Ifbf4ec4c04"), "Ic5c1b22780", "Ifbf4ec4c04",
    )
    replayed, sources = _replay_at(truth, config, _kst_unix(2026, 11, 2, 8, 0, 40))
    p.eq("08:00:40: 08:00:30 의 조회를 고른다", ("2026-11-02T08:00:30+09:00",) * 4,
         tuple(s.observed_at for s in sources if s.source != SourceKind.SUBWAY_TIMETABLE))
    signals = {phase.id: phase for phase in replayed.signals}
    lines = {line.id: line for line in replayed.bus_lines}
    p.eq("08:00:40: K1, bike_obs_age_s, SG3, SG4 오프셋", (2, 10.0, 35.0, 40.0),
         (replayed.bike_stations[0].bikes_available, replayed.bike_obs_age_s, signals["SG3"].offset_s, signals["SG4"].offset_s))
    p.eq("08:00:40: G1 B1, B2 의 도착 시각", ((160.0, 760.0), (310.0, 910.0)),
         tuple(tuple(eta for _, eta in items) for items in _eta_view(lines["G1"])[:2]))
    _rp_expect(
        p, "08:00:40", _run_default(replayed, config, sources),
        (("Ic5c1b22780", None, 588.5, 0.987562, "SAFE"), ("I3a248c7d10", None, 914.0, 0.651758, "RISKY"),
         ("I469424fb69", None, 914.0, 0.633887, "RISKY"), ("Ic9a62956f6", "가상2번", 1273.0, 0.984992, "SAFE"),
         ("If1e99436b8", None, 1320.0, 1.0, "SAFE"), ("Ifbf4ec4c04", None, 1824.0, 1.0, "SAFE")),
        ("Ic5c1b22780", "I3a248c7d10", "Ic9a62956f6", "If1e99436b8", "Ifbf4ec4c04"), "Ic5c1b22780", "Ifbf4ec4c04",
    )


def _rp4(p: _Probe) -> None:
    truth, config = _synthetic_world()
    replayed, sources = _replay_at(truth, config, _kst_unix(2026, 11, 3, 8, 12, 20))
    p.eq("11-03 08:12:20: 원천 상태",
         (("BUS_ARRIVAL", "SYN-G1", "SUCCESS", "2026-11-03T08:11:30+09:00"), ("BUS_ARRIVAL", "SYN-G2", "SUCCESS", "2026-11-03T08:12:00+09:00"),
          ("BIKE", "합성", "SUCCESS", "2026-11-03T08:12:00+09:00"), ("SIGNAL", "합성", "SUCCESS", "2026-11-03T08:12:00+09:00")),
         tuple(_status_view(s) for s in sources if s.source != SourceKind.SUBWAY_TIMETABLE))
    lines = {line.id: line for line in replayed.bus_lines}
    p.eq("08:12:20: G1 관측 경과, B1, B2", (50.0, (("G1-05", 60.0), ("G1-06", 660.0)), (("G1-05", 210.0), ("G1-06", 810.0))),
         (lines["G1"].prediction_age_s, *_eta_view(lines["G1"])[:2]))
    p.eq("08:12:20: G2 B4, B5", ((("G2-05", 280.0), ("G2-06", 880.0)), (("G2-05", 460.0), ("G2-06", 1060.0))), _eta_view(lines["G2"]))
    signals = {phase.id: phase for phase in replayed.signals}
    p.eq("08:12:20: K1, bike_obs_age_s, SG3, SG4 오프셋", (1, 20.0, 15.0, 20.0),
         (replayed.bike_stations[0].bikes_available, replayed.bike_obs_age_s, signals["SG3"].offset_s, signals["SG4"].offset_s))
    _rp_expect(
        p, "08:12:20", _run_default(replayed, config, sources),
        (("Ic5c1b22780", None, 608.5, 0.818731, "SAFE"), ("I3a248c7d10", None, 934.0, 0.762475, "SAFE"),
         ("I469424fb69", None, 934.0, 0.734291, "RISKY"), ("Ic9a62956f6", None, 1124.0, 0.921793, "SAFE"),
         ("If1e99436b8", None, 1340.0, 1.0, "SAFE")),
        ("Ic5c1b22780", "I3a248c7d10", "Ic9a62956f6", "If1e99436b8"), "Ic5c1b22780", "I469424fb69",
    )
    replayed, sources = _replay_at(truth, config, _kst_unix(2026, 11, 3, 8, 20, 40))
    by_target = {(s.source.value, s.target): s for s in sources}
    gap = by_target.get(("BUS_ARRIVAL", "SYN-G2"))
    p.eq("08:20:40: SYN-G2 는 SKIPPED 와 REPLAY_DATA_GAP", ("SKIPPED", None, ("REPLAY_DATA_GAP",)),
         (gap.state.value, gap.observed_at, tuple(w.code.value for w in gap.issues)) if gap else None)
    p.eq("08:20:40: 나머지 원천은 08:20:30", ("2026-11-03T08:20:30+09:00",) * 3,
         tuple(by_target[key].observed_at for key in (("BUS_ARRIVAL", "SYN-G1"), ("BIKE", "합성"), ("SIGNAL", "합성"))))
    lines = {line.id: line for line in replayed.bus_lines}
    p.eq("08:20:40: G2 의 예측은 모두 NO_INFO", {"NO_INFO"}, {i.kind.value for items in lines["G2"].predictions for i in items})
    output = _run_default(replayed, config, sources)
    codes = {w.code.value for w in output.warnings}
