def _run_check(check: _Check) -> _Outcome:
    probe = _Probe()
    try:
        check.func(probe)
    except Exception as exc:  # noqa: BLE001 - 예상하지 못한 예외는 그 항목의 실패로 보인다
        probe.check("예외", False, f"{type(exc).__name__}: {exc}")
    failure = probe.first_failure()
    if not probe.items:
        failure = "비교한 값이 없습니다"
    return _Outcome(check.code, check.title, failure is None, failure or "", probe.items)


def run_selftest(verbose: bool = False) -> int:
    """§9 의 검사 가운데 지금 단계까지 만든 항목을 실행하고 실패 수를 돌려준다(§9.0 의 출력 형식)."""
    start = time.perf_counter()
    failed = 0
    try:
        for check in _CHECKS:
            outcome = _run_check(check)
            status = "PASS" if outcome.ok else "FAIL"
            line = f"[{status}] {outcome.code:<5} {outcome.title}"
            if not outcome.ok:
                failed += 1
                line += f": {outcome.message}"
            print(line)
            if verbose:
                for label, detail, ok in outcome.items:
                    print(f"         {'  ' if ok else '× '}{label}: {detail}")
    finally:
        _drop_synthetic_world()  # RP 와 K4 가 함께 쓴 합성 기록 임시 폴더
    total = len(_CHECKS)
    elapsed = time.perf_counter() - start
    print(f"요약: 통과 {total - failed}/{total}, 실패 {failed}, 소요 {elapsed:.1f}초")
    return failed


# --- CLI: 수집기와 상태 (§3.7) ---


@contextlib.contextmanager
def _cli_logging() -> Iterator[None]:
    """명령을 실행하는 동안 mobility_router 로거의 INFO 줄을 표준 출력에 그대로 보인다(§3.6)."""
    handler = logging.StreamHandler(sys.stdout)
    handler.setFormatter(logging.Formatter("%(message)s"))
    previous = _LOG.level
    _LOG.addHandler(handler)
    _LOG.setLevel(logging.INFO)
    try:
        yield
    finally:
        _LOG.removeHandler(handler)
        _LOG.setLevel(previous)


def _status_lines(summary: RecordSummary) -> list[str]:
    lines = [f"기록 저장소: {summary.path} ({summary.size_bytes / 1_000_000:.1f} MB)"]
    lines.append("원천 | 대상 | 조회 | 성공률 | 첫 조회 | 마지막 조회 | 조회 주기")
    for item in summary.sources:
        lines.append(
            f"{item.source} | {item.targets} | {item.polls:,} | {item.success_rate:.1%} | {_kst_text(item.first_unix)} | "
            f"{_kst_text(item.last_unix)} | {item.period_s:g}초"
        )
    if not summary.sources:
        lines.append("조회 기록이 없습니다")
    dates = ", ".join(f"{_date_label(day)} {_DAY_TYPE_KO[kind]}" for day, kind in summary.dates)
    lines.append(f"기록이 있는 날짜: {dates or '없음'}")
    lines.append("시연 시간대 기록:")
    for window in summary.windows:
        lines.append(
            f"  {_date_label(window.date)} {window.window} {_kst(window.first_unix):%H:%M:%S} ~ "
            f"{_kst(window.last_unix):%H:%M:%S} · 조회 {window.polls:,}회 · 성공률 {window.success_rate:.1%}"
        )
    if not summary.windows:
        lines.append("  없음")
    lines.append("실패 사유 (많은 순 3개):")
    reasons = [(item.source, reason, count) for item in summary.sources for reason, count in item.failure_reasons]
    lines.extend(f"  {source}: {reason} ({count:,}회)" for source, reason, count in reasons)
    if not reasons:
        lines.append("  없음")
    check = summary.remaining_check
    if check is None:
        lines.append("남은 시간 검산: 신호 기록 없음")
    elif check.median is None:
        lines.append("남은 시간 검산: 쌍 0개 (같은 상태로 1 ~ 120초 간격인 이웃 관측이 없습니다)")
    else:
        per_signal = ", ".join(f"{signal} {count}" for signal, count in check.per_signal[:5])
        lines.append(
            f"남은 시간 검산: 쌍 {check.pairs:,}개, 중앙값 {check.median:.2f} ({per_signal}). "
            "−1 근처면 remaining_scale 이 맞고, −10 이나 −0.1 근처면 단위가 10배 틀립니다"
        )
    return lines


def _cli_status(store_path: pathlib.Path, targets_path: pathlib.Path, samples: bool, config: EngineConfig) -> int:
    if not store_path.exists():
        print(f"기록 없음: {store_path}")
        return 1
    targets, _, problem = _load_targets(targets_path)
    if targets is None:
        if targets_path.exists():
            print(f"{problem}. 휴일 없이 봅니다.")
        targets = CollectTargets.model_validate_json(DEFAULT_TARGETS_JSON).model_copy(update={"holidays": ()})
    try:
        store = RecordStore(store_path, read_only=True)
    except (OSError, sqlite3.Error) as exc:
        print(f"기록 저장소를 열 수 없습니다: {store_path} ({type(exc).__name__})")
        return 1
    with store:
        try:
            summary = record_summary(store, targets)
        except sqlite3.Error as exc:
            print(f"기록 저장소를 읽을 수 없습니다: {store_path} ({type(exc).__name__}: {_mask(str(exc), config)})")
            return 1
        latest: list[tuple[str, str]] = []
        if samples:
            for (api,) in store.execute("SELECT DISTINCT api FROM api_log WHERE sample IS NOT NULL ORDER BY api").fetchall():
                row = store.execute(
                    "SELECT sample FROM api_log WHERE api = ? AND sample IS NOT NULL ORDER BY t_unix DESC, rowid DESC LIMIT 1",
                    (api,),
                ).fetchone()
                latest.append((api, row[0]))
        exposures = _key_exposures(store, config)
    for line in _status_lines(summary):
        print(line)
    for api, sample in latest:
        print(f"[{api} 표본 앞 {_SAMPLE_CHARS:,}자]")
        print(_mask(sample, config)[:_SAMPLE_CHARS])
    if exposures:
        print(f"키 노출: {', '.join(exposures)}")
        return 1
    checked = any(present for _, present in _key_presence(config))
    print("키 노출 없음" if checked else "키 노출 없음 (환경변수에 키가 없어 비교할 값이 없습니다)")
    return 0


# --- 명령줄: 지하철 시각표 (§3.7, §4.10) ---

_CLI_CLIENTS: list[httpx.Client] = []  # 검사가 main 에 넣는 가짜 전송(§9.8). 비어 있으면 호출 함수가 스스로 만든다.


def _cli_client() -> httpx.Client | None:
    return _CLI_CLIENTS[-1] if _CLI_CLIENTS else None


def _cli_fetch_timetable(codes: Sequence[str], out_dir: pathlib.Path, samples: bool, config: EngineConfig) -> int:
    """`--fetch-timetable` (§3.7): 역코드마다 6 묶음을 받아 `{역코드}.csv` 로 저장하고 요약을 출력한다."""
    failed = 0
    for code in codes:
        fetched = _fetch_timetable(code, config, _cli_client())
        attempts = sum(result.attempts for result in fetched.results)
        if fetched.timetable is None:
            failed += 1
            print(f"역 {code}: 요청 {attempts}회, 저장하지 않음: {fetched.reason}")
        else:
            path = out_dir / f"{code}.csv"
            write_timetable_csv(fetched.timetable, path)
            print(f"역 {code}: 요청 {attempts}회, 행 {len(fetched.timetable.rows):,}개를 {path} 에 저장")
            for line in timetable_summary(fetched.timetable):
                print(f"  {line}")
        print(f"  건너뛴 행 {fetched.counts[TIMETABLE_SKIPPED]:,}개, 급행 미확인 {fetched.counts[TIMETABLE_EXPRESS_UNKNOWN]:,}개")
        if samples or fetched.timetable is None:
            first = next((result for result in fetched.results if result.body_text), None)
            if first is not None:
                print(f"  첫 응답 앞 2,000자: {_mask(first.body_text, config)[:2000]}")
    return 1 if failed else 0


_DATA_DIR_ENV = "MOBILITY_ROUTER_DATA_DIR"  # 화면과 같은 데이터 폴더 환경변수(§3.7, §8.2)


def _cli_build_scenario(spec_path: pathlib.Path, out_path: pathlib.Path | None, config: EngineConfig) -> int:
    """`--build-scenario` (§3.7, §4.9): 생성 보고를 끝에 한꺼번에 출력하고, 만들었으면 시나리오 JSON 을 저장한다."""
    report = _build_scenario(spec_path, config, _cli_client(), None)
    for line in report.lines():
        print(line)
    if report.scenario is None:
        print(f"저장하지 않음: {report.error}")
        return 1
    target = out_path or _data_dir(config) / "scenarios" / f"{report.scenario.id}.json"
    save_scenario_json(report.scenario, target)
    print(f"저장: {target}")
    return 0


def _cli_check_timetable(path: pathlib.Path) -> int:
    """`--check-timetable` (§3.7): 시각표 CSV 를 읽어 요약을 출력한다. 읽을 수 없으면 줄 번호와 이유, 종료 코드 1."""
    try:
        timetable = load_timetable(path)
    except (OSError, ValueError) as exc:
        print(f"시각표를 읽을 수 없습니다: {exc}")
        return 1
    print(f"역 {timetable.station_key} ({timetable.source}): 행 {len(timetable.rows):,}개")
    for line in timetable_summary(timetable):
        print(f"  {line}")
    return 0


# --- 시연 출력: --demo, --json (§3.7) ---

_DATA_MODE_KO: MappingProxyType = MappingProxyType(
    {DataMode.SIMULATION: "시뮬레이션", DataMode.REPLAY: "기록 재생", DataMode.LIVE: "실시간"}
)
_MODE_KO: MappingProxyType = MappingProxyType({TravelMode.BUS: "버스", TravelMode.SUBWAY: "지하철", TravelMode.BIKE: "따릉이"})


def _demo_scenarios() -> dict[str, Scenario]:
    """`--demo`, `--json` 이 고르는 시나리오: 골든, 그다음 손으로 만든 시연 시나리오(ID 순)."""
    return {GOLDEN_ID: golden_scenario(), **build_scenarios()}


def _demo_input(scenario: Scenario, offset_s: float, config: EngineConfig) -> tuple[Scenario, Query | None]:
    """출발 늦추기(§4.6)를 적용한 시나리오와 기본 질의. 차량 안 출발은 `shift_origin` 으로 바꾸고, 바꿀 차가 없으면 질의가 None."""
    query = scenario.default_query
    if query is None or offset_s == 0:
        return scenario, query
    shifted = advance_clock(scenario, offset_s, config)
    if query.origin.kind in (OriginKind.ON_TRAIN, OriginKind.ON_BUS):
        return shifted, shift_origin(scenario, shifted, query, offset_s, config)
    return shifted, query


def _text_width(text: str) -> int:
    """고정폭 글꼴에서 차지하는 칸 수(한글처럼 넓은 글자는 2칸)."""
    return sum(2 if unicodedata.east_asian_width(char) in ("W", "F") else 1 for char in text)


def _table_lines(header: Sequence[str], rows: Sequence[Sequence[str]], numeric: Sequence[bool]) -> list[str]:
    """열 너비를 맞춘 표. numeric 이 참인 열은 오른쪽에 붙인다."""
    widths = [max(_text_width(cell) for cell in column) for column in zip(header, *rows)]

    def line(cells: Sequence[str]) -> str:
        parts = []
        for cell, width, right in zip(cells, widths, numeric):
            pad = " " * (width - _text_width(cell))
            parts.append(pad + cell if right else cell + pad)
        return ("  " + "  ".join(parts)).rstrip()

    return [line(header), "  " + "  ".join("-" * width for width in widths), *(line(row) for row in rows)]


def _sec_text(value: float | None) -> str:
    return "-" if value is None else f"{value:,.1f}"


def _p_text(value: float | None) -> str:
    return "-" if value is None else f"{value:.3f}"


def _clip(text: str, limit: int) -> str:
    return text if len(text) <= limit else text[:limit] + "…"


def _codes_text(items: Iterable[enum.Enum]) -> str:
    return ", ".join(item.value for item in items)


def _demo_place_text(scenario: Scenario, node_id: str | None) -> str:
    node = _node_index(scenario).get(node_id or "")
    return f"{node.name} ({node.id})" if node is not None else str(node_id)


def _demo_origin_text(scenario: Scenario, query: Query) -> str:
    """질의의 출발 상태를 한 줄로."""
    origin = query.origin
    if origin.kind == OriginKind.AT_NODE:
        return _demo_place_text(scenario, origin.node_id)
    if origin.kind == OriginKind.AT_POINT:
        return f"좌표 ({origin.lat:.6f}, {origin.lon:.6f})"
    if origin.kind == OriginKind.ON_TRAIN:
        pattern = next(item for item in scenario.subway_patterns if item.id == origin.pattern_id)
        station = next(item for item in scenario.subway_stations if item.key == pattern.station_keys[origin.next_index])
        return f"{pattern.line} {pattern.direction} 열차 {origin.trip_id} 안, 다음 역 {station.name} (순번 {origin.next_index})"
    line = next(item for item in scenario.bus_lines if item.id == origin.line_id)
    stop = _demo_place_text(scenario, line.stop_ids[origin.next_index])
    return f"{line.name}번 버스 {origin.trip_id} 안, 다음 정류장 {stop} (순번 {origin.next_index})"


def _demo_destination_text(scenario: Scenario, query: Query) -> str:
    if query.destination_node_id is not None:
        return _demo_place_text(scenario, query.destination_node_id)
    return f"좌표 ({query.destination_lat:.6f}, {query.destination_lon:.6f})"


def _demo_line_rows(output: EngineOutput) -> list[list[str]]:
    rows = []
    for item in output.line_times:
        if item.run_source:
            runs = ", ".join(f"{run:,.1f} {source.value}" for run, source in zip(item.run_s, item.run_source))
        else:
            runs = ", ".join(f"{run:,.1f}" for run in item.run_s)
        rows.append([item.route_id, _MODE_KO[item.mode], f"{item.n_known}", f"{item.n_synthetic}", "예" if item.usable else "아니오", runs])
    return rows


def _demo_search_rows(output: EngineOutput) -> list[list[str]]:
    rows = []
    for trace in output.search.runs:
        if trace.skipped:
            rows.append([trace.run.value, f"건너뜀: {trace.skip_reason}", "", "", "", "", "", "", "", ""])
            continue
        best = min((label[0] for label in trace.d_labels), default=None)
        rows.append([
            trace.run.value,
            "/".join(_MODE_KO[mode] for mode in trace.modes),
            f"{trace.m_run:g}",
            trace.wait_rule.value,
            f"{trace.bike_limit}",
            f"{trace.buffer_s:g}",
            f"{len(trace.rounds)}",
            f"{len(trace.d_labels)}",
            _sec_text(best),
            f"{len(trace.itinerary_ids)}",
        ])
    return rows


def _demo_rank_text(result: ItineraryResult, by_id: dict[str, ItineraryResult]) -> str:
    if result.rank is not None:
        return f"{result.rank}"
    if result.status != RouteStatus.RANKED:
        return "걸러짐"
    head = by_id.get(result.representative_id or "")
    return f"{head.rank}위 아래" if head is not None and head.rank is not None else "-"


def _demo_candidate_rows(output: EngineOutput) -> tuple[list[ItineraryResult], list[list[str]]]:
    by_id = _by_id(output)
    ordered = sorted(output.itineraries, key=lambda r: (r.arrival.mean_s is None, r.arrival.mean_s or 0.0, r.itinerary_id))
    rows = [
        [
            r.itinerary_id,
            _demo_rank_text(r, by_id),
            r.label,
            _sec_text(r.plan_arrival_s),
            _sec_text(r.arrival.mean_s),
            _sec_text(r.arrival.p90_s),
            _p_text(r.p_star),
            r.grade.value,
            r.status.value,
            f"{r.ghost_count}",
            f"{r.fare.total_krw:,}",
        ]
        for r in ordered
    ]
    return ordered, rows


def _demo_ghost_lines(output: EngineOutput) -> list[str]:
    """유령 판정을 받은 탑승마다: 기존 방식 차량과 그 차를 탈 확률, 이 앱이 안내하는 차량(§1.4.6)."""
    lines = []
    for r in sorted(output.itineraries, key=lambda item: item.itinerary_id):
        for b in r.boardings:
            if not b.ghost:
                continue
            ride = r.rides[b.ride_index - 1]
            if ride.bundle:
                route = ride.bundle_name
            else:
                route = f"{ride.route_name}번" if ride.mode == TravelMode.BUS else ride.route_name
            guided = f"안내 차량 {b.guided_trip_id} (Q {b.q_joint:.3f})" if b.guided_found else "안내 차량 없음"
            lines.append(
                f"  {r.itinerary_id} {r.label} · 탑승 {b.ride_index} ({route}): 기존 방식 차량 {b.naive_trip_id} "
                f"(정류장 도착 {_sec_text(b.naive_stop_arrival_s)} s, 여유 {_sec_text(b.naive_margin_s)} s) "
                f"p_catch {_p_text(b.p_catch_naive)}, {guided}"
            )
    return lines


def _demo_comparison_lines(output: EngineOutput) -> list[str]:
    panel = output.comparison
    by_id = _by_id(output)
    clock = output.clock_s

    def at(value: float | None) -> str:
        return "-" if value is None else f"{value:,.1f} s ({_clock_label(clock + value)})"

    naive = by_id.get(panel.naive_best_id or "")
    best = by_id.get(panel.best_id or "")
    lines = []
    if naive is not None:
        reasons = f" ({_codes_text(panel.naive_reasons)})" if panel.naive_reasons else ""
        lines.append(
            f"  기존 방식 1위: {naive.itinerary_id} {naive.label}, 약속 {at(panel.naive_promised_s)}, 실제 평균 {at(panel.naive_mean_s)}, "
            f"90% {_sec_text(panel.naive_p90_s)} s, P* {_p_text(panel.naive_p_star)}, {panel.naive_status.value if panel.naive_status else '-'}{reasons}"
        )
    else:
        lines.append("  기존 방식 1위: 없음")
    if best is not None:
        lines.append(f"  이 앱의 최선: {best.itinerary_id} {best.label}, 평균 {at(panel.best_mean_s)}, 90% {_sec_text(panel.best_p90_s)} s")
    else:
        lines.append("  이 앱의 최선: 없음")
    lines.append(
        f"  같은 여정: {'예' if panel.same else '아니오'}, 약속보다 늦음 {_sec_text(panel.late_vs_promise_s)} s, "
        f"아낀 시간 {_sec_text(panel.saving_s)} s, 기존 방식이 잘못 안내함: {'예' if panel.app_misled else '아니오'}"
    )
    return lines


def _demo_lines(
    scenario_id: str, scenario: Scenario, offset_s: float, config: EngineConfig, *, sources: Sequence[ApiSourceStatus] = ()
) -> list[str]:
    """한 시나리오의 `--demo` 출력 줄(§3.7). `sources` 는 기록 재생(`--replay`)의 원천 상태로, 그대로 `run_engine` 에 넘긴다."""
    lines = [f"==== {scenario_id}: {scenario.title} ===="]
    shifted, query = _demo_input(scenario, offset_s, config)
    note = scenario.simulated_time_note if shifted.data_mode == DataMode.SIMULATION else scenario.record_note
    lines.append(
        f"시각: {_DAY_TYPE_KO[shifted.day_type]} {_clock_label(shifted.clock_s)} ({_DATA_MODE_KO[shifted.data_mode]}), "
        f"출발 늦추기 {offset_s:g} s. {note}"
    )
    if query is None:
        lines.append("차 없음: 출발 늦추기를 적용하면 같은 역(정류장)에 늦게 닿는 차가 없어 건너뜁니다." if scenario.default_query else "기본 질의 없음")
        return lines
    lines.append(f"출발: {_demo_origin_text(shifted, query)} → 목적지: {_demo_destination_text(shifted, query)}")
    start = time.perf_counter()
    output = run_engine(shifted, query, config, sources)
    elapsed = time.perf_counter() - start
    lines.append(f"상태: {output.status.value}, 가지치기 초점 {output.origin_node_id} → {output.destination_node_id}")
    if output.pruning is not None:
        prune = output.pruning
        lines.append(
            f"가지치기: d(S, D) {prune.d_sd_m:,.1f} m, 임계값 {prune.threshold_m:,.1f} m (γ {output.config.gamma:g}), "
            f"반축 a {prune.a_m:,.1f} m · b {prune.b_m:,.1f} m, 남은 노드 {prune.kept_count}/{prune.total_count}"
        )
    if output.line_times:
        lines.append("노선 (차량 수와 구간 운행시간 s, 버스는 출처):")
        lines += _table_lines(["노선", "수단", "알려진 차", "합성 차", "쓸 수 있음", "구간 운행시간"], _demo_line_rows(output),
                              [False, False, True, True, False, False])
    if output.search.runs:
        lines.append("탐색 (실행마다):")
        lines += _table_lines(["실행", "수단", "속도 배수", "대기 규칙", "따릉이", "승차 여유", "라운드", "D 라벨", "가장 이른 D", "여정"],
                              _demo_search_rows(output), [False, False, True, False, True, True, True, True, True, True])
        search = output.search
        lines.append(f"  찾은 여정 {search.found_total}, 서로 다른 여정 {search.distinct}, 평가한 여정 {search.kept}, 버린 여정 {len(search.discarded_ids)}")
    ordered, rows = _demo_candidate_rows(output)
    lines.append(f"후보 {len(ordered)}개 (평균 도착 순, 시각은 출발 t = 0 부터 초):")
    if ordered:
        lines += _table_lines(["ID", "순위", "이름", "계획 도착", "평균", "90%", "P*", "등급", "상태", "유령", "요금"], rows,
                              [False, True, False, True, True, True, True, False, False, True, True])
        lines.append("  찾은 실행:")
        lines += [f"    {r.itinerary_id}  {_codes_text(r.found_by)}" for r in ordered]
    ghosts = _demo_ghost_lines(output)
    lines.append(f"유령 환승 {len(ghosts)}개 (기존 방식 차량을 탈 확률 p_catch < p_ghost {output.config.p_ghost:g}):")
    lines += ghosts or ["  없음"]
    by_id = _by_id(output)
    lines.append(f"순위 ({output.config.rank_criterion.value}):")
    if output.ranking:
        rank_rows = [
            [f"{by_id[jid].rank}", jid, by_id[jid].label, _sec_text(by_id[jid].criterion_value), _p_text(by_id[jid].p_star),
             f"{by_id[jid].fare.total_krw:,}", ", ".join(by_id[jid].variant_ids) or "-"]
            for jid in output.ranking
        ]
        lines += _table_lines(["순위", "ID", "이름", "기준 값", "P*", "요금", "아래 여정"], rank_rows, [True, False, False, True, True, True, False])
    else:
        lines.append("  없음")
    lines.append(f"걸러진 여정 {len(output.pruned_ids)}개:")
    lines += [
        f"  {jid} {by_id[jid].label}: {by_id[jid].status.value} ({_codes_text(by_id[jid].reasons)}), 평균 {_sec_text(by_id[jid].arrival.mean_s)} s, P* {_p_text(by_id[jid].p_star)}"
        for jid in output.pruned_ids
    ] or ["  없음"]
    lines.append("비교 패널:")
    lines += _demo_comparison_lines(output)
    lines.append(f"경고 {len(output.warnings)}개:")
    lines += [f"  {warning.code.value}: {_clip(warning.message, 200)}" for warning in output.warnings] or ["  없음"]
    lines.append(f"run_engine {elapsed:.2f} s")
    return lines


def run_demo(scenario_id: str | None = None, offset_s: float = 0) -> None:
    """`--demo` (§3.7): 시나리오마다(기본은 골든, A, B 전부) 기본 질의의 결과를 표 형식 텍스트로 출력한다."""
    config = EngineConfig()
    scenarios = _demo_scenarios()
    chosen = [scenario_id] if scenario_id is not None else list(scenarios)
    for number, key in enumerate(chosen):
        if number:
            print()
        for line in _demo_lines(key, scenarios[key], float(offset_s), config):
            print(line)


def _demo_scenario_id(text: str | None, scenarios: dict[str, Scenario]) -> str | None:
    """`--scenario` 값을 시나리오 ID 로(대소문자는 가리지 않는다). 없으면 None."""
    if text is None:
        return None
    if text in scenarios:
        return text
    return next((key for key in scenarios if key.casefold() == text.casefold()), None)


def _cli_demo(scenario_text: str | None, offset_s: float, as_json: bool) -> int:
    """`--demo`, `--json` (§3.7). `--json` 은 `--scenario` 가 필요하고, 차 없음이면 이유를 표준 오류에 쓰고 종료 코드 1."""
    scenarios = _demo_scenarios()
    scenario_id = _demo_scenario_id(scenario_text, scenarios)
    if scenario_text is not None and scenario_id is None:
        print(f"시나리오 {scenario_text!r} 가 없습니다. 고를 수 있는 것: {', '.join(scenarios)}")
        return 2
    if not math.isfinite(offset_s) or offset_s < 0:
        print(f"--offset 은 0 이상의 초입니다: {offset_s:g}")
        return 2
    if not as_json:
        run_demo(scenario_id, offset_s)
        return 0
    if scenario_id is None:
        print("--json 에는 --scenario ID 가 필요합니다")
        return 2
    config = EngineConfig()
    shifted, query = _demo_input(scenarios[scenario_id], offset_s, config)
    if query is None:
        print(f"차 없음: 시나리오 {scenario_id} 에 출발 늦추기 {offset_s:g} s 를 적용하면 바꿀 차가 없습니다", file=sys.stderr)
        return 1
    text = run_engine(shifted, query, config).model_dump_json(indent=2)
    sys.stdout.flush()
    sys.stdout.buffer.write(text.encode("utf-8") + b"\n")  # JSON 은 콘솔 코드 페이지와 상관없이 UTF-8 로 낸다
    sys.stdout.buffer.flush()
    return 0


# --- 명령줄: 기록 재생과 학습 (§3.7, §4.8, §1.8.2, §1.9) ---

_SOURCE_KO: MappingProxyType = MappingProxyType(
    {SourceKind.BUS_ARRIVAL: "버스 도착", SourceKind.BIKE: "따릉이", SourceKind.SIGNAL: "신호", SourceKind.SUBWAY_TIMETABLE: "지하철 시각표"}
)
_AT_FORMATS = ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M")


def _cli_targets(targets_path: pathlib.Path, explicit: bool, config: EngineConfig) -> tuple[CollectTargets | None, EngineConfig, str, int | None]:
    """`--replay`, `--fit`, `--fit-bike` 의 수집 대상 파일(§3.7): (대상, 휴일을 넣은 설정, 알림, 종료 코드).

    기본 경로에 파일이 없으면 휴일이 없는 것으로 보고 대상은 None 이다. `--targets` 로 준 파일이 없거나 파일이 검증에 실패하면
    종료 코드 1 이다(요일 종류가 결과를 바꾸므로 짐작해서 계속하지 않는다).
    """
    targets, _, problem = _load_targets(targets_path)
    if targets is not None:
        return targets, config.model_copy(update={"holidays": tuple(targets.holidays)}), "", None
    if targets_path.exists() or explicit:
        return None, config, problem, 1
    return None, config, f"수집 대상 파일이 없어 휴일 없이 봅니다: {targets_path}", None


def _cli_at(text: str) -> float | None:
    """`--at` 의 한국 시각("YYYY-MM-DD HH:MM:SS" 나 "YYYY-MM-DD HH:MM")을 유닉스 초로. 읽지 못하면 None."""
    for fmt in _AT_FORMATS:
        try:
            moment = datetime.datetime.strptime(text.strip(), fmt)
        except ValueError:
            continue
        return moment.replace(tzinfo=_KST).timestamp()
    return None


def _observed_text(value: str | None) -> str:
    if not value:
        return "-"
    try:
        return datetime.datetime.fromisoformat(value).astimezone(_KST).strftime("%Y-%m-%d %H:%M:%S")
    except ValueError:
        return value


def _models_text(models: Models) -> str:
    """`--replay` 가 쓴 학습 모델 한 줄. 모델이 없으면 신호와 대여 속도는 시나리오 값 그대로다(§4.8)."""
    if not models.summaries:
        return "없음 (신호 현시와 대여 속도는 시나리오 값)"
    parts = []
    for summary in models.summaries:
        name = "신호" if summary.kind == "SIGNAL" else "따릉이"
        if summary.created_at:
            parts.append(f"{name} {summary.period or '기간 없음'}, 대상 {summary.targets}, 만든 시각 {summary.created_at}")
        else:
            parts.append(f"{name} {'; '.join(summary.notes) or '읽지 못함'}")
    return " / ".join(parts)


def _cli_replay(args: argparse.Namespace, targets_path: pathlib.Path, config: EngineConfig) -> int:
    """`--replay` (§3.7, §4.8): 기록 재생으로 시나리오를 만들어 맨 앞에 `record_note` 와 원천별 상태를 출력한 뒤 `--demo` 형식으로
    출력한다. 기본 저장소는 데이터 폴더의 `records.sqlite`, 모델 폴더는 데이터 폴더, 시각표 폴더는 `timetables/`."""
    if not args.scenario_json or not args.at:
        print('--replay 에는 --scenario-json PATH 와 --at "YYYY-MM-DD HH:MM:SS" 가 필요합니다')
        return 2
    at_unix = _cli_at(args.at)
    if at_unix is None:
        print(f'--at 은 한국 시각 "YYYY-MM-DD HH:MM:SS" 입니다: {args.at!r}')
        return 2
    targets, config, notice, code = _cli_targets(targets_path, args.targets is not None, config)
    if code is not None:
        print(notice)
        return code
    scenario_path = pathlib.Path(args.scenario_json)
    try:
        base = load_scenario_json(scenario_path)
    except (OSError, ValueError) as exc:
        print(f"시나리오를 읽을 수 없습니다: {scenario_path} ({_clip(str(exc), 300)})")
        return 1
    store_path = pathlib.Path(args.store) if args.store else _data_dir(config) / "records.sqlite"
    if not store_path.exists():
        print(f"기록 없음: {store_path}")
        return 1
    models_dir = pathlib.Path(args.models) if args.models else _data_dir(config)
    timetables_dir = pathlib.Path(args.timetables) if args.timetables else _data_dir(config) / "timetables"
    models = load_models(models_dir)
    try:
        with RecordStore(store_path, read_only=True) as store:
            replayed, sources = replay_scenario(base, store, models, at_unix, config, timetables_dir=timetables_dir, targets=targets)
    except (OSError, sqlite3.Error) as exc:
        print(f"기록 저장소를 읽을 수 없습니다: {store_path} ({type(exc).__name__}: {_mask(str(exc), config)})")
        return 1
    print(replayed.record_note)
    if notice:
        print(notice)
    print(f"기록 저장소: {store_path} · 시각표 폴더: {timetables_dir}")
    print(f"학습 모델 ({models_dir}): {_models_text(models)}")
    print("원천 상태:")
    rows = [
        [_SOURCE_KO[item.source], item.target or "-", item.state.value, _observed_text(item.observed_at), f"{item.fetched_count:,}",
         f"{item.matched_count:,}", f"{item.attempts}", item.reason or "-"]
        for item in sources
    ]
    if rows:
        for line in _table_lines(["원천", "대상", "상태", "관측 시각", "받은", "연결", "시도", "사유"], rows,
                                 [False, False, False, False, True, True, True, False]):
            print(line)
    else:
        print("  없음 (시나리오에 기록과 이을 노선, 대여소, 신호, 역이 없습니다)")
    print()
    for line in _demo_lines(replayed.id, replayed, 0.0, config, sources=sources):
        print(line)
    return 0


def _sweep_origin_text(scenario: Scenario, query: Query) -> str:
    """일괄 재생 머리말의 출발. 차량 안 출발은 출발마다 차량을 다시 고르므로 차량 ID 를 빼고 노선과 다음 역(정류장)만 적는다."""
    origin = query.origin
    if origin.kind == OriginKind.ON_TRAIN:
        pattern = next(item for item in scenario.subway_patterns if item.id == origin.pattern_id)
        station = next(item for item in scenario.subway_stations if item.key == pattern.station_keys[origin.next_index])
        return f"{pattern.line} {pattern.direction} 열차 안, 다음 역 {station.name} (순번 {origin.next_index})"
    if origin.kind == OriginKind.ON_BUS:
        line = next(item for item in scenario.bus_lines if item.id == origin.line_id)
        return f"{line.name}번 버스 안, 다음 정류장 {_demo_place_text(scenario, line.stop_ids[origin.next_index])} (순번 {origin.next_index})"
    return _demo_origin_text(scenario, query)


def _sweep_row_cells(row: SweepRow, vehicle: bool) -> list[str]:
    """출발 표의 한 줄(§4.11): 출발, 결과, (차량 안 출발이면 탄 차량), 최선, 최선 평균, 기존 방식 1위, 유령, 줄이는 시간, 따릉이 효과.
    평가가 아닌 줄은 탄 차량(고르지 못했으면 "-") 말고는 "-" 다."""
    when = row.at_label[5:]
    trip = [row.trip_id or "-"] if vehicle else []
    if row.outcome == SweepOutcome.EVALUATED:
        return [when, "평가", *trip, row.best_label, _sec_text(row.best_mean_s), row.naive_label, f"{row.naive_ghosts}",
                _sec_text(row.saving_s), _sec_text(row.bike_gain_s)]
    reason = {
        SweepOutcome.GAP: f"기록 공백: {', '.join(row.gaps)}",
        SweepOutcome.NO_VEHICLE: "탈 차 없음",
        SweepOutcome.NO_ROUTE: f"경로 없음: {row.note}",
    }[row.outcome]
    return [when, reason, *trip, "-", "-", "-", "-", "-", "-"]


def _sweep_summary_lines(summary: SweepSummary) -> list[str]:
    """일괄 재생 요약(§4.11 의 형식). 시간은 소수 1자리, 비율은 백분율 소수 1자리, 없는 값은 "-"."""
    s = summary
    gaps = ", ".join(f"{key} {count}" for key, count in s.gap_sources) or "없음"
    lines = [
        "요약:",
        f"  출발 {s.moments}개: 평가 {s.evaluated}, 기록 공백 {s.gap}, 탈 차 없음 {s.no_vehicle}, 경로 없음 {s.no_route}",
        f"  기록 공백 원천: {gaps}",
    ]
    if not s.evaluated:
        return [*lines, "  평가한 출발이 없습니다"]
    n = s.evaluated

    def pct(share: float | None) -> str:
        return "-" if share is None else f"{share * 100:.1f}%"

    def sec(value: float | None) -> str:
        return "-" if value is None else f"{_sec_text(value)}초"

    notable = f"{SWEEP_NOTABLE_S:g}초 이상"
    return [
        *lines,
        f"  기존 방식 1위에 유령 환승: {s.misled}/{n} ({pct(s.misled_share)})",
        f"  기존 방식 1위가 곧 최선: {s.same}/{n} ({pct(s.same_share)}), 기존 방식 1위가 걸러짐: {s.naive_pruned}",
        f"  이 앱으로 줄이는 시간: 평균 {sec(s.saving_mean_s)}, 중앙값 {sec(s.saving_median_s)}, 최대 {sec(s.saving_max_s)}, "
        f"{notable} {s.saving_notable}번, 유령 환승일 때 평균 {sec(s.saving_mean_misled_s)}",
        f"  약속보다 늦는 시간 (기존 방식 1위): 평균 {sec(s.late_mean_s)}",
        f"  따릉이: 최선에 따릉이 {s.best_bike}/{n} ({pct(s.best_bike_share)}), 따릉이를 넣어 줄인 시간 평균 {sec(s.bike_gain_mean_s)}, "
        f"중앙값 {sec(s.bike_gain_median_s)}, 최대 {sec(s.bike_gain_max_s)}, {notable} {s.bike_gain_notable}번",
    ]


def _sweep_lines(result: SweepResult, base: Scenario, context: Sequence[str]) -> list[str]:
    """`--replay-sweep` 의 출력(§4.11): 머리말, 기준 출발의 원천 상태, 알림, 출발 표, 요약."""
    vehicle = result.a0_s is not None
    lines = [
        f"기록 일괄 재생: {result.scenario_id} {result.scenario_title}, {_sweep_label(result.start_unix_s)} ~ "
        f"{_sweep_label(result.end_unix_s)} (한국 시각), 간격 {result.step_s}초, 출발 {len(result.rows)}개",
        *context,
        f"출발: {_sweep_origin_text(base, result.query)} → 목적지: {_demo_destination_text(base, result.query)}",
    ]
    if vehicle:
        lines.append(f"차량 안 출발: 출발마다 다음 역(정류장)에 {_sec_text(result.a0_s)}초 이상 뒤에 닿는 같은 노선의 첫 차량을 탄 것으로 봅니다")
    lines.append("기준 출발의 원천 상태:")
    rows = [
        [_SOURCE_KO[item.source], item.target or "-", item.state.value, _observed_text(item.observed_at), f"{item.fetched_count:,}",
         f"{item.matched_count:,}", item.reason or "-"]
        for item in result.sources
    ]
    if rows:
        lines += _table_lines(["원천", "대상", "상태", "관측 시각", "받은", "연결", "사유"], rows,
                              [False, False, False, False, True, True, False])
    else:
        lines.append("  없음")
    lines += [f"알림: {note}" for note in result.notes]
    lines.append("출발마다 (평균과 줄이는 시간은 초, 자세한 값은 CSV):")
    header = ["출발", "결과", *(["탄 차"] if vehicle else []), "최선", "최선 평균", "기존 방식 1위", "유령", "줄이는 시간", "따릉이 효과"]
    numeric = [False, False, *([False] if vehicle else []), False, True, False, True, True, True]
    lines += _table_lines(header, [_sweep_row_cells(row, vehicle) for row in result.rows], numeric)
    lines += _sweep_summary_lines(result.summary)
    return lines


def _cli_replay_sweep(args: argparse.Namespace, targets_path: pathlib.Path, config: EngineConfig) -> int:
    """`--replay-sweep` (§3.7, §4.11): 기록 일괄 재생을 출력하고 CSV 를 쓴다. 진행은 표준 오류에 쓴다."""
    if bool(args.scenario) == bool(args.scenario_json):
        print("--replay-sweep 에는 --scenario ID 와 --scenario-json PATH 가운데 하나만 줍니다")
        return 2
    if not args.sweep_from or not args.sweep_to:
        print('--replay-sweep 에는 --from 과 --to (한국 시각 "YYYY-MM-DD HH:MM:SS")가 필요합니다')
        return 2
    start, end = _cli_at(args.sweep_from), _cli_at(args.sweep_to)
    if start is None or end is None:
        print(f'--from, --to 는 한국 시각 "YYYY-MM-DD HH:MM:SS" 입니다: {args.sweep_from!r}, {args.sweep_to!r}')
        return 2
    targets, config, notice, code = _cli_targets(targets_path, args.targets is not None, config)
    if code is not None:
        print(notice)
        return code
    if args.scenario:
        scenarios = _demo_scenarios()
        scenario_id = _demo_scenario_id(args.scenario, scenarios)
        if scenario_id is None:
            print(f"시나리오 {args.scenario!r} 가 없습니다. 고를 수 있는 것: {', '.join(scenarios)}")
            return 2
        base = scenarios[scenario_id]
    else:
        scenario_path = pathlib.Path(args.scenario_json)
        try:
            base = load_scenario_json(scenario_path)
        except (OSError, ValueError) as exc:
            print(f"시나리오를 읽을 수 없습니다: {scenario_path} ({_clip(str(exc), 300)})")
            return 1
    store_path = pathlib.Path(args.store) if args.store else _data_dir(config) / "records.sqlite"
    if not store_path.exists():
        print(f"기록 없음: {store_path}")
        return 1
    models_dir = pathlib.Path(args.models) if args.models else _data_dir(config)
    timetables_dir = pathlib.Path(args.timetables) if args.timetables else _data_dir(config) / "timetables"
    models = load_models(models_dir)

    def progress(done: int, total: int) -> None:
        if done % 30 == 0 or done == total:
            print(f"진행 {done}/{total}", file=sys.stderr, flush=True)

    try:
        with RecordStore(store_path, read_only=True) as store:
            result = replay_sweep(base, store, models, round(start), round(end), args.step, config, timetables_dir=timetables_dir,
                                  targets=targets, progress=progress)
    except (OSError, sqlite3.Error) as exc:
        print(f"기록 저장소를 읽을 수 없습니다: {store_path} ({type(exc).__name__}: {_mask(str(exc), config)})")
        return 1
    except ValueError as exc:
        print(f"일괄 재생을 할 수 없습니다: {_clip(str(exc), 300)}")
        return 2
    out = pathlib.Path(args.out) if args.out else (
        _data_dir(config) / "sweeps" / f"{base.id}_{_kst(result.start_unix_s):%Y%m%d-%H%M%S}_{_kst(result.end_unix_s):%Y%m%d-%H%M%S}.csv"
    )
    context = [f"기록 저장소: {store_path} · 시각표 폴더: {timetables_dir}", f"학습 모델 ({models_dir}): {_models_text(models)}"]
    if notice:
        context.append(notice)
    for line in _sweep_lines(result, base, context):
        print(line)
    write_sweep_csv(result, out)
    print(f"CSV: {out}")
    return 0 if result.summary.evaluated else 1


def _pct(value: float | None) -> str:
    return "-" if value is None else f"{100.0 * value:.1f}%"


def _track_sec(value: float | None) -> str:
    return "-" if value is None else f"{value:,.1f}초"


def _track_summary_lines(summary: TrackSummary) -> list[str]:
    """`--track` 의 요약(§4.13.4)."""
    o = summary.outcomes
    lines = [
        "요약:",
        f"  추적 {summary.picked}개: 평가 {o['EVALUATED']}, 잘림 {o['CENSORED']}, 기록 공백 {o['GAP']}, 경로 없음 {o['NO_ROUTE']} "
        f"(대중교통 {summary.transit}, 걷기만 {summary.walk_only})",
    ]
    if summary.n == 0:
        lines.append("  평가한 대중교통 추적이 없습니다")
        return lines
    ci = "-" if summary.saving_ci_s is None else f"{_track_sec(summary.saving_ci_s[0])} ~ {_track_sec(summary.saving_ci_s[1])}"
    lines += [
        f"  실제로 줄인 시간 (대중교통 {summary.n}): 평균 {_track_sec(summary.saving_mean_s)} (95% 구간 {ci}), "
        f"중앙값 {_track_sec(summary.saving_median_s)}, 0초 넘게 줄임 {summary.saving_positive}번, 60초 이상 {summary.saving_notable}번",
        f"  정보로 본 줄이는 시간 평균 {_track_sec(summary.info_saving_mean_s)}",
        f"  기존 앱 약속을 지킨 비율 평균 {_pct(summary.kept_mean)}, 절반도 못 지킨 추적 {summary.kept_under_half}번",
        f"  이 앱 90% 약속에 든 비율 평균 {_pct(summary.p90_hit_mean)}",
        "  걷는 사람별 줄인 시간 평균: " + ", ".join(
            f"{name} {_track_sec(value)}" for (_, name, _), value in zip(TRACK_TYPES, summary.type_saving_mean_s)),
    ]
    a, b, c, d = summary.ghost_table
    lines.append(f"  유령 환승 대조 (판정 {summary.ghost_judged}): 정보 예·실제 예 {a}, 정보 예·실제 아니오 {b}, "
                 f"정보 아니오·실제 예 {c}, 정보 아니오·실제 아니오 {d}")
    cells = []
    for lo, hi, count, info, real in summary.calibration:
        right = "]" if hi == 1.0 else ")"
        values = "-" if count == 0 else f"정보 {info:.2f} 실제 {real:.2f}"
        cells.append(f"[{lo:.1f}, {hi:.1f}{right} {count}건 {values}")
    lines.append("  탈 확률 보정: " + " · ".join(cells))
    return lines


def _cli_track(args: argparse.Namespace, targets_path: pathlib.Path, config: EngineConfig) -> int:
    """`--track` (§3.7, §4.13): 추적 평가를 출력하고 CSV 두 개를 쓴다. 진행은 표준 오류에 쓴다."""
    if bool(args.scenario) == bool(args.scenario_json):
        print("--track 에는 --scenario ID 와 --scenario-json PATH 가운데 하나만 줍니다")
        return 2
    if not args.sweep_from or not args.sweep_to:
        print('--track 에는 --from 과 --to (한국 시각 "YYYY-MM-DD HH:MM:SS")가 필요합니다')
        return 2
    start, end = _cli_at(args.sweep_from), _cli_at(args.sweep_to)
    if start is None or end is None:
        print(f'--from, --to 는 한국 시각 "YYYY-MM-DD HH:MM:SS" 입니다: {args.sweep_from!r}, {args.sweep_to!r}')
        return 2
    if args.horizon is not None and not (math.isfinite(args.horizon) and args.horizon > 0):
        print(f"--horizon 은 유한한 양수입니다: {args.horizon!r}")
        return 2
    targets, config, notice, code = _cli_targets(targets_path, args.targets is not None, config)
    if code is not None:
        print(notice)
        return code
    if args.scenario:
        scenarios = _demo_scenarios()
        scenario_id = _demo_scenario_id(args.scenario, scenarios)
        if scenario_id is None:
            print(f"시나리오 {args.scenario!r} 가 없습니다. 고를 수 있는 것: {', '.join(scenarios)}")
            return 2
        base = scenarios[scenario_id]
    else:
        scenario_path = pathlib.Path(args.scenario_json)
        try:
            base = load_scenario_json(scenario_path)
        except (OSError, ValueError) as exc:
            print(f"시나리오를 읽을 수 없습니다: {scenario_path} ({_clip(str(exc), 300)})")
            return 1
    store_path = pathlib.Path(args.store) if args.store else _data_dir(config) / "records.sqlite"
    if not store_path.exists():
        print(f"기록 없음: {store_path}")
        return 1
    models_dir = pathlib.Path(args.models) if args.models else _data_dir(config)
    timetables_dir = pathlib.Path(args.timetables) if args.timetables else _data_dir(config) / "timetables"
    models = load_models(models_dir)
    n_trips = args.n if args.n is not None else TRACK_DEFAULT_TRIPS
    seed = args.seed if args.seed is not None else TRACK_SEED
    horizon = float(args.horizon) if args.horizon is not None else TRACK_HORIZON_S

    def progress(done: int, total: int) -> None:
        if done % 30 == 0 or done == total:
            print(f"진행 {done}/{total}", file=sys.stderr, flush=True)

    try:
        with RecordStore(store_path, read_only=True) as store:
            result = track_evaluate(base, store, models, round(start), round(end), config, n_trips=n_trips, seed=seed,
                                    horizon_s=horizon, timetables_dir=timetables_dir, targets=targets, progress=progress)
    except (OSError, sqlite3.Error) as exc:
        print(f"기록 저장소를 읽을 수 없습니다: {store_path} ({type(exc).__name__}: {_mask(str(exc), config)})")
        return 1
    except ValueError as exc:
        print(f"추적 평가를 할 수 없습니다: {_clip(str(exc), 300)}")
        return 2
    out = pathlib.Path(args.out) if args.out else (
        _data_dir(config) / "tracks" / f"{base.id}_{_kst(result.start_unix_s):%Y%m%d-%H%M%S}_{_kst(result.end_unix_s):%Y%m%d-%H%M%S}"
    )
    print(f"추적 평가: {base.id} {base.title}, {_kst(result.start_unix_s):%Y-%m-%d %H:%M:%S} ~ {_kst(result.end_unix_s):%Y-%m-%d %H:%M:%S} "
          f"(한국 시각), 뽑을 추적 {n_trips}개, 씨앗 {seed}, 지평 {horizon:g}초")
    print(f"기록 저장소: {store_path} · 시각표 폴더: {timetables_dir}")
    print(f"학습 모델 ({models_dir}): {_models_text(models)}")
    if notice:
        print(notice)
    print(f"후보: 지상 지점 쌍 {result.n_pairs}, 기록이 이어진 출발 시각 {result.n_moments}")
    for note in result.notes:
        print(f"알림: {note}")
    for line in _track_summary_lines(result.summary):
        print(line)
    write_track_csv(result, out / "trips.csv", out / "boardings.csv")
    print(f"CSV: {out / 'trips.csv'}, {out / 'boardings.csv'}")
    return 0 if result.summary.n else 1


def _link_area_text(link: BikeLink, targets: CollectTargets | None, config: EngineConfig) -> str:
    """대여소 표의 "기록 지역"(§4.12): 실제 대여소 좌표가 들어가는 수집 대상의 따릉이 지역 이름들, 없으면 "밖"."""
    if targets is None or link.state == BikeLinkState.NONE or link.real_lat is None:
        return "-"
    names = [area.name for area in targets.bike_areas if _within(link.real_lat, link.real_lon, area, config)]
    return ", ".join(names) or "밖"


def _link_row_cells(link: BikeLink, targets: CollectTargets | None, config: EngineConfig) -> list[str]:
    """대여소 표의 한 줄(§4.12): 시나리오 대여소 ID, 이름, 결과, 실제 대여소 ID, 실제 이름, 거리 m, 지금 자전거, 기록 지역."""
    state = {BikeLinkState.LINKED: "이음", BikeLinkState.KEPT: "원래 있음", BikeLinkState.NONE: "없음"}[link.state]
    if link.state == BikeLinkState.NONE:
        name = f"{link.real_name} (가장 가까운 남은 곳)" if link.real_name else "-"
        return [link.station_id, link.station_name, state, "-", name, _sec_text(link.distance_m), "-", "-"]
    bikes = "-" if link.bikes_now is None else f"{link.bikes_now}"
    return [link.station_id, link.station_name, state, link.official_id or "-", link.real_name or "-", _sec_text(link.distance_m), bikes,
            _link_area_text(link, targets, config)]


def _cli_link_bikes(args: argparse.Namespace, targets_path: pathlib.Path, config: EngineConfig) -> int:
    """`--link-bikes` (§3.7, §4.12): 따릉이 실시간 목록으로 대여소에 실제 ID 를 이은 시나리오 사본을 저장한다."""
    if bool(args.scenario) == bool(args.scenario_json):
        print("--link-bikes 에는 --scenario ID 와 --scenario-json PATH 가운데 하나만 줍니다")
        return 2
    within = LINK_BIKES_WITHIN_M if args.within is None else args.within
    if not math.isfinite(within) or within <= 0:
        print(f"--within 은 유한한 양수(m)입니다: {args.within!r}")
        return 2
    if args.scenario:
        scenarios = _demo_scenarios()
        scenario_id = _demo_scenario_id(args.scenario, scenarios)
        if scenario_id is None:
            print(f"시나리오 {args.scenario!r} 가 없습니다. 고를 수 있는 것: {', '.join(scenarios)}")
            return 2
        base = scenarios[scenario_id]
    else:
        scenario_path = pathlib.Path(args.scenario_json)
        try:
            base = load_scenario_json(scenario_path)
        except (OSError, ValueError) as exc:
            print(f"시나리오를 읽을 수 없습니다: {scenario_path} ({_clip(str(exc), 300)})")
            return 1
    targets, _, problem, code = _cli_targets(targets_path, args.targets is not None, config)
    if code is not None:
        print(problem)
        return code
    print(f"대여소 실제 ID 잇기: {base.id} {base.title}, 반경 {within:g} m")
    if targets is None:
        print(f'수집 대상 파일이 없어 기록 지역은 "-" 로 둡니다: {targets_path}')
    rows, results = fetch_pages(_cli_client(), "bike_list", {}, config)
    failed = next((result for result in results if result.state != SourceState.SUCCESS), None)
    if failed is not None or not results:
        print(f"따릉이 목록을 받지 못했습니다: {_mask(failed.reason if failed is not None else '응답 없음', config)}")
        return 1
    observations, skipped = _parse_bike_rows(rows)
    attempts = sum(result.attempts for result in results)
    print(f"따릉이 실시간 대여정보: 요청 {attempts}회, 대여소 {len(observations):,}곳, 건너뛴 행 {skipped:,}개")
    linked, links = link_bike_ids(base, observations, within, config)
    header = ["시나리오 대여소", "이름", "결과", "실제 대여소 ID", "실제 이름", "거리 m", "지금 자전거", "기록 지역"]
    numeric = [False, False, False, False, False, True, True, False]
    for line in _table_lines(header, [_link_row_cells(link, targets, config) for link in links], numeric):
        print(line)
    counts = Counter(link.state for link in links)
    print(f"이은 대여소 {counts[BikeLinkState.LINKED]}/{len(links)} (원래 있음 {counts[BikeLinkState.KEPT]}, "
          f"반경 안에 없음 {counts[BikeLinkState.NONE]})")
    if not counts[BikeLinkState.LINKED]:
        print("이은 대여소가 없어 저장하지 않았습니다")
        return 1
    out = pathlib.Path(args.out) if args.out else _data_dir(config) / "scenarios" / f"{linked.id}.json"
    save_scenario_json(linked, out)
    print(f"저장: {out} (시나리오 ID {linked.id})")
    print(f'일괄 재생: python core_engine.py --replay-sweep --scenario-json {out} --from "YYYY-MM-DD HH:MM:SS" --to "YYYY-MM-DD HH:MM:SS"')
    return 0


def _slot_text(slot: int, config: EngineConfig) -> str:
    """신호 학습의 시간대 번호 → 그 시간대가 시작하는 시각 "HH:MM"."""
    return _clock_label(slot * config.signal_slot_s)[:5]


def _slot_counts_text(items: Sequence[tuple[int, int]], config: EngineConfig) -> str:
    return ", ".join(f"{_slot_text(slot, config)} {count}" for slot, count in items) or "-"


def _value_text(value: float | None) -> str:
    return "-" if value is None else f"{value:g}"


def _fit_lines(model: SignalModel, config: EngineConfig) -> list[str]:
    """`--fit` 의 요약(§1.9): 날마다의 표본 수(1 ~ 4)와 요일 종류·시간대별 학습 결과(5 ~ 8)."""
    dates = ", ".join(f"{_date_label(day)} {_DAY_TYPE_KO[kind]}" for day, kind in model.dates)
    lines = [
        f"신호 학습: 관측 {model.n_observations:,}개, 신호 {len({day.signal_id for day in model.days})}개, 기간 {_period_text(model.period)}, "
        f"조회 주기 {model.poll_s:g}초 (이웃 관측 간격이 그 {config.signal_outage_factor:g}배를 넘으면 관측 공백)",
        f"날짜: {dates}",
        "날마다 (표본 수는 시간대 시작 시각별):",
    ]
    day_rows = [
        [day.signal_id, _date_label(day.date), _DAY_TYPE_KO[day.day_type], f"{day.n_obs:,}", f"{day.n_starts}", f"{day.n_ends}",
         _slot_counts_text(day.gaps_by_slot, config), _slot_counts_text(day.greens_by_slot, config), f"{day.outages}", f"{day.dropped_gaps}"]
        for day in model.days
    ]
    lines += _table_lines(["신호", "날짜", "요일", "관측", "녹색 시작", "녹색 끝", "주기 표본", "녹색 표본", "관측 공백", "버린 주기 표본"],
                          day_rows, [False, False, False, True, True, True, False, False, True, True])
    lines.append("요일 종류·시간대별 학습 결과 (초):")
    fits = list(model.slot_fits())
    fit_rows = [
        [signal_id, _DAY_TYPE_KO[kind], _slot_text(fit.slot, config), "LEARNED" if fit.learned else "NOT_LEARNED", _value_text(fit.cycle_s),
         _value_text(fit.green_s), _value_text(fit.red_s), _value_text(fit.iqr_s), ("감응" if fit.actuated else "고정") if fit.learned else "-",
         f"{fit.n_gaps}", f"{fit.n_greens}", ", ".join(_slot_text(slot, config) for slot in fit.merged_slots) or "-"]
        for signal_id, kind, fit in fits
    ]
    if fit_rows:
        lines += _table_lines(["신호", "요일", "시간대", "상태", "주기 C", "녹색", "적색", "IQR", "감응 여부", "주기 표본", "녹색 표본", "합친 시간대"],
                              fit_rows, [False, False, False, False, True, True, True, True, False, True, True, False])
    else:
        lines.append("  없음 (표본이 있는 시간대가 없습니다)")
    learned = sum(1 for _, _, fit in fits if fit.learned)
    lines.append(f"학습한 시간대 {learned}개, 학습하지 못한 시간대 {len(fits) - learned}개")
    return lines


def _cli_fit(store_path: pathlib.Path, out_dir: pathlib.Path, targets_path: pathlib.Path, explicit_targets: bool, config: EngineConfig) -> int:
    """`--fit` (§3.7, §1.9): 저장소의 `sig_obs` 로 신호 모델을 학습해 `out_dir/signal_model.json` 에 쓰고 요약을 출력한다.
    신호 기록이 없으면 그렇다고 출력하고 종료 코드 1."""
    targets, config, notice, code = _cli_targets(targets_path, explicit_targets, config)
    if notice:
        print(notice)
    if code is not None:
        return code
    if not store_path.exists():
        print(f"기록 없음: {store_path}")
        return 1
    try:
        with RecordStore(store_path, read_only=True) as store:
            model = fit_signal_model(store, config, targets=targets)
    except (OSError, sqlite3.Error) as exc:
        print(f"기록 저장소를 읽을 수 없습니다: {store_path} ({type(exc).__name__}: {_mask(str(exc), config)})")
        return 1
    if model.n_observations == 0:
        print(f"신호 기록 없음: {store_path} 의 신호 관측(sig_obs)이 비어 있어 저장하지 않습니다")
        return 1
    print(f"기록 저장소: {store_path}")
    for line in _fit_lines(model, config):
        print(line)
    path = save_signal_model(model, out_dir / _SIGNAL_MODEL_FILE)
    print(f"저장: {path}")
    return 0


def _cli_bike_stations(folder: pathlib.Path) -> tuple[list[BikeStation], int, list[str]]:
    """데이터 폴더 `scenarios/` 의 시나리오 JSON (생성 명세 `*.spec.json` 은 뺀다, 이름순)에 있는 대여소(§1.8.2).
    (대여소, 읽은 시나리오 수, 읽지 못한 파일 알림)."""
    stations: list[BikeStation] = []
    notes: list[str] = []
    count = 0
    paths = sorted(folder.glob("*.json")) if folder.is_dir() else []
    for path in paths:
        if path.name.endswith(".spec.json"):
            continue
        try:
            scenario = load_scenario_json(path)
        except (OSError, ValueError) as exc:
            notes.append(f"시나리오를 읽지 못해 건너뜀: {path.name} ({_clip(str(exc), 200)})")
            continue
        count += 1
        stations.extend(scenario.bike_stations)
    return stations, count, notes


def _fit_bike_lines(model: BikeModel, stations: Sequence[BikeStation], scenarios: int, config: EngineConfig) -> list[str]:
    """`--fit-bike` 의 요약(§1.8.2): 읽은 파일과 행, 자료 기간, 맞춘 비율과 맞추지 못한 대여소, 결과가 있으면 $\\lambda_h$ 와 주행 속도."""
    total = len(model.matched) + len(model.unmatched)
    files = ", ".join(f"{name} ({encoding}, {rows:,}행)" for name, encoding, rows in model.files)
    skipped = ", ".join(f"{reason} {count:,}" for reason, count in model.rows_skipped)
    days = ", ".join(f"{_DAY_TYPE_KO[kind]} {model.days_by_type[kind]}일" for kind in DAY_TYPE_ORDER if kind in model.days_by_type)
    lines = [
        f"따릉이 학습: 이력 폴더 {model.history_dir}, 맞추기 {model.station_match}, 맞출 대여소 {total}곳 (시나리오 {scenarios}개)",
        f"파일: {files or '없음'}",
        f"읽은 행 {model.rows_read:,}, 건너뛴 행 {model.skipped_total:,}" + (f" ({skipped})" if skipped else ""),
        f"자료 기간: {_period_text(model.period) or '없음'}" + (f" ({days})" if days else ""),
    ]
    lines += [f"문제: {problem}" for problem in model.problems]
    lines.append(f"맞춘 비율: {model.match_rate:.2f} ({len(model.matched)}/{total}, 기준 {config.bike_match_min_rate:.2f})")
    if model.unmatched:
        lines.append(f"맞추지 못한 대여소: {', '.join(model.unmatched)}")
    if not model.accepted:
        return lines
    names: dict[str, str] = {}
    for station in stations:
        names.setdefault(station.official_id or station.name, station.name)
    lines.append("대여 속도 λ_h (건/시간, 0 이 아닌 시간만):")
    for key in sorted(model.rates):
        for kind in DAY_TYPE_ORDER:
            values = model.rates[key].get(kind)
            if values is None:
                continue
            hours = ", ".join(f"{hour:02d}시 {value:.3f}" for hour, value in enumerate(values) if value)
            label = key if names.get(key, key) == key else f"{key} ({names[key]})"
            lines.append(f"  {label} {_DAY_TYPE_KO[kind]}: {hours or '모두 0'}")
    speed = model.speed
    if speed is None:
        lines.append("주행 속도 (참고값): 표본 없음")
    else:
        lines.append(
            f"주행 속도 (참고값, 대여소와 반납소가 다르고 이용 거리 300 ~ 3,000 m, 이용 시간 1 ~ 30분인 이력): 표본 {speed.n:,}, "
            f"중앙값 {speed.median_mps:.3f} m/s, 사분위 {speed.q1_mps:.3f} ~ {speed.q3_mps:.3f}, k {speed.k:.3f}. "
            "자동으로 넣지 않고 화면의 \"학습한 따릉이 속도 적용\" 버튼으로만 넣습니다"
        )
    return lines


def _cli_fit_bike(history_dir: pathlib.Path, out_dir: pathlib.Path, targets_path: pathlib.Path, explicit_targets: bool,
                  config: EngineConfig) -> int:
    """`--fit-bike` (§3.7, §1.8.2): 대여 이력으로 따릉이 모델을 배워 `out_dir/bike_model.json` 에 쓴다. 맞출 대여소는 데이터 폴더의
    생성 시나리오에서 읽는다. 맞춘 비율이 `bike_match_min_rate` 보다 낮으면 맞추지 못한 대여소를 출력하고 저장하지 않으며 종료 코드 1."""
    targets, config, notice, code = _cli_targets(targets_path, explicit_targets, config)
    if notice:
        print(notice)
    if code is not None:
        return code
    if targets is None:
        targets = CollectTargets.model_validate_json(DEFAULT_TARGETS_JSON).model_copy(update={"holidays": ()})
        print("열 이름과 대여소 맞추기는 §5.3 예시 파일의 bike_history 를 씁니다")
    if not history_dir.is_dir():
        print(f"대여 이력 폴더가 없습니다: {history_dir}. 서울 열린데이터광장의 따릉이 대여 이력 CSV 를 이 폴더에 두세요")
        return 1
    scenarios_dir = _data_dir(config) / "scenarios"
    stations, scenarios, notes = _cli_bike_stations(scenarios_dir)
    for note in notes:
        print(note)
    if not stations:
        print(f"맞출 대여소가 없습니다: {scenarios_dir} 에 대여소가 있는 시나리오 JSON 이 없습니다")
        return 1
    model = fit_bike_model(history_dir, targets, stations, config)
    for line in _fit_bike_lines(model, stations, scenarios, config):
        print(line)
    if not model.accepted:
        print(f"맞춘 비율이 기준 {config.bike_match_min_rate:.2f} 보다 낮아 저장하지 않습니다")
        return 1
    path = save_bike_model(model, out_dir / _BIKE_MODEL_FILE)
    print(f"저장: {path}")
    return 0


# --- --matrix 조합 검사 (§3.7, 10단계) ---
#
# 시나리오 3 (골든, A, B) × 출발 늦추기 {0, 300, 600} × 기후동행카드 {끔, 켬} × 순위 기준 4 × 따릉이 {켬, 끔} = 144 조합을 시뮬레이션
# 모드로 실행하고, 조합마다 §9.6 의 불변식 가운데 엔진 입력에 따라 달라지는 것(I3, I5 ~ I12, I14 ~ I16)을 검사한다. I1, I2 (신호
# 대기 함수의 격자), I4 (골든 걷기 그래프의 모든 경로 열거), I13 (골든 후보를 고정하고 t_buf, v_walk 를 쓸어 봄)은 조합과 상관없는
# 검사라 --selftest 가 본다. 조합마다 run_engine 한 번의 시간이 §3.6 의 예산(2초) 안인지도 본다.

_MATRIX_OFFSETS_S = (0.0, 300.0, 600.0)
_MATRIX_CRITERIA = (RankCriterion.MEAN_ARRIVAL, RankCriterion.P90_ARRIVAL, RankCriterion.ON_TIME, RankCriterion.UTILITY)
_MATRIX_ENGINE_BUDGET_S = 2.0
# ON_TIME 조합의 마감: 화면에서 마감을 켰을 때의 기본값(§6.3, 기본 질의에 마감이 없으면 기준 시각 + 30분을 분 단위로 내림)
_MATRIX_DEADLINE_AHEAD_S = 1800.0
# (열쇠, 이름, 검사 대상 수를 적는 꼴)
_MATRIX_CHECKS = (
    ("I3", "가지치기의 단조성", "γ 단계 {n:,}개"),
    ("I5", "라벨과 여정의 일관성", "D 라벨 {n:,}개"),
    ("I6", "차량 시각", "노선 {n:,}개"),
    ("I7", "결정성", "다시 실행 {n:,}회 (같은 입력, 튜플 순서를 뒤집은 시나리오)"),
    ("I8", "확률과 방법", "여정 {n:,}개"),
    ("I9", "분포", "여정 {n:,}개"),
    ("I10", "계획의 시간 막대", "막대 {n:,}개"),
    ("I11", "따릉이", "따릉이 구간 {n:,}개"),
    ("I12", "순위와 대표", "대표 {n:,}개"),
    ("I14", "막대그래프", "막대그래프 {n:,}개"),
    ("I15", "시계 이동", "조합 {n:,}개 (Δt 300, 600 은 옮긴 시나리오를 원래와 견줌)"),
    ("I16", "요금", "여정 {n:,}개 (기후동행카드를 켠 조합은 끈 조합의 내역과 견줌)"),
    ("설정", "조합의 설정이 결과에 반영됨", "조합 {n:,}개"),
    ("시간", "run_engine 한 번 2초 이내 (§3.6)", "조합 {n:,}개"),
)


class _MatrixCase(NamedTuple):
    """조합 하나의 결과: 조합, 엔진 결과의 요약, 검사마다 문제와 검사한 대상 수."""

    number: int
    scenario_id: str
    offset_s: float
    card: bool
    criterion: RankCriterion
    bike: bool
    deadline_s: float | None
    status: str
    candidates: int
    heads: int
    pruned: int
    best_id: str | None
    engine_s: float
    problems: dict[str, list[str]]
    counts: dict[str, int]

    @property
    def label(self) -> str:
        return (f"{self.scenario_id} · Δt {self.offset_s:,.0f} · 카드 {'켬' if self.card else '끔'} · {self.criterion.value} · "
                f"따릉이 {'켬' if self.bike else '끔'}")


def _matrix_config(card: bool, criterion: RankCriterion, bike: bool) -> EngineConfig:
    """조합의 설정: 기본 설정에서 기후동행카드, 순위 기준, 수단(따릉이를 끄면 수단에서 뺀다)만 바꾼다."""
    modes = tuple(mode for mode in EngineConfig().modes_enabled if bike or mode != TravelMode.BIKE)
    return EngineConfig(climate_card=card, rank_criterion=criterion, modes_enabled=modes)


def _matrix_deadline(scenario: Scenario, offset_s: float) -> float | None:
    """ON_TIME 조합의 마감($t$ 기준). 화면에서 마감을 켰을 때의 기본값을 시계 시각으로 두고(§6.3: 기본 질의의 마감, 없으면 기준 시각
    + 30분을 분 단위로 내림), 출발을 늦춘 만큼 남은 시간이 준다. 남은 시간이 없으면 None (마감 없이 평균 도착으로 정렬한다)."""
    query = scenario.default_query
    if query is not None and query.deadline_s is not None:
        deadline_clock = scenario.clock_s + query.deadline_s
    else:
        deadline_clock = math.floor(scenario.clock_s + _MATRIX_DEADLINE_AHEAD_S) // 60 * 60
    remaining = deadline_clock - scenario.clock_s - offset_s
    return float(remaining) if remaining > 0 else None


def _determinism_problems(scenario: Scenario, query: Query, config: EngineConfig, first: str) -> list[str]:
    """I7: 같은 입력을 다시 실행한 결과와 튜플 순서를 뒤집은 시나리오의 결과가 처음 결과(`model_dump_json()`)와 같은지."""
    problems: list[str] = []
    second = run_engine(scenario, query, config).model_dump_json()
    if second != first:
        problems.append(f"두 번 실행한 결과가 다르다: {_first_difference(first, second)}")
    flipped = run_engine(_reversed_scenario(scenario), query, config).model_dump_json()
    if flipped != first:
        problems.append(f"튜플 순서를 뒤집은 시나리오의 결과가 다르다: {_first_difference(first, flipped)}")
    return problems


def _matrix_case(number: int, scenario_id: str, scenario: Scenario, offset_s: float, card: bool, criterion: RankCriterion,
                 bike: bool, card_off: EngineOutput | None) -> tuple[_MatrixCase, EngineOutput | None]:
    """조합 하나를 실행하고 불변식을 검사한다. 기후동행카드를 켠 조합은 같은 조합에서 카드를 끈 결과(card_off)와 요금 내역을 견준다(I16)."""
    config = _matrix_config(card, criterion, bike)
    shifted, query = _demo_input(scenario, offset_s, config)
    problems: dict[str, list[str]] = {key: [] for key, _name, _unit in _MATRIX_CHECKS}
    counts: dict[str, int] = {key: 0 for key, _name, _unit in _MATRIX_CHECKS}
    deadline = _matrix_deadline(scenario, offset_s) if criterion == RankCriterion.ON_TIME else None
    if query is None:
        problems["설정"].append("출발을 늦춘 만큼 바꿀 차가 없다(shift_origin)")
        return _MatrixCase(number, scenario_id, offset_s, card, criterion, bike, deadline, "차 없음", 0, 0, 0, None, 0.0, problems, counts), None
    if deadline is not None:
        query = query.model_copy(update={"deadline_s": deadline})
    started = time.perf_counter()
    output = run_engine(shifted, query, config)
    engine_s = time.perf_counter() - started
    results = output.itineraries
    counts["시간"] = 1
    if engine_s > _MATRIX_ENGINE_BUDGET_S:
        problems["시간"].append(f"run_engine {engine_s:.2f}초")
    # I3: 출발 노드는 질의를 따른다(차량 안 출발은 출발을 늦추면 다음 정류장·승강장이 바뀐다)
    origin, destination = _query_origin_node(shifted, query), query.destination_node_id
    if origin is not None and destination is not None:
        steps = _pruning_steps(shifted, origin, destination, config)
        counts["I3"] = len(steps)
        for gamma, before, missing, lost, _kept in steps:
            if missing:
                problems["I3"].append(f"γ {gamma:g}: 승하차·역 안 노드 빠짐 {missing}")
            if lost:
                problems["I3"].append(f"γ {before:g} → {gamma:g}: 앞에서 남은 노드가 빠짐 {lost}")
    # I5, I6: 탐색 준비를 따로 만들어 실행마다 라벨과 노선의 차량 시각을 본다
    context, warning = build_search_context(shifted, query, config)
    if context is None:
        if results:
            problems["I5"].append(f"탐색 준비에 실패했는데 후보가 있다: {warning}")
    else:
        counts["I5"], _worst, label_problems = _label_problems(context, config)
        problems["I5"] += label_problems
        counts["I6"] = len(context.routes)
        problems["I6"] += _route_problems(context, shifted, config)
    counts["I7"] = 2
    problems["I7"] += _determinism_problems(shifted, query, config, output.model_dump_json())
    counts["I8"] = counts["I9"] = counts["I16"] = len(results)
    problems["I8"] += _probability_problems(output)
    if results:
        problems["I9"] += _distribution_problems(output, _build_evaluations(shifted, query, config))
    counts["I10"] = sum(len(r.legs) for r in results)
    problems["I10"] += [problem for r in results for problem in _plan_problems(r, config)]
    counts["I11"] = sum(1 for r in results for move in r.moves if move.bike is not None)
    problems["I11"] += [problem for r in results for problem in _bike_problems(r, shifted, config)]
    counts["I12"] = len(output.ranking)
    problems["I12"] += _ranking_problems(results, output.ranking, output.pruned_ids, output.best_id, output.query, output.config)
    histogram_problems, counts["I14"] = _histogram_set_problems(output)
    problems["I14"] += histogram_problems
    counts["I15"] = 1
    if offset_s:
        problems["I15"] += _shift_problems(scenario, shifted, offset_s)
    elif advance_clock(scenario, 0.0, config).model_dump() != scenario.model_dump():
        problems["I15"].append("advance_clock(s, 0) 의 model_dump() 가 원래와 다르다")
    baseline = _by_id(card_off) if card and card_off is not None else {}
    problems["I16"] += [problem for r in results for problem in _fare_problems(r, config, baseline.get(r.itinerary_id))]
    counts["설정"] = 1
    if (output.config.climate_card, output.config.rank_criterion, output.config.modes_enabled) != (card, criterion, config.modes_enabled):
        problems["설정"].append("결과의 설정이 조합과 다르다")
    if not bike and counts["I11"]:
        problems["설정"].append(f"따릉이를 끈 조합에 따릉이 구간 {counts['I11']}개")
    if deadline is not None and output.query.deadline_s != deadline:
        problems["설정"].append(f"질의의 마감 {output.query.deadline_s} (기대 {deadline})")
    case = _MatrixCase(number, scenario_id, offset_s, card, criterion, bike, deadline, output.status.value, len(results),
                       len(output.ranking), len(output.pruned_ids), output.best_id, engine_s, problems, counts)
    return case, output


def _matrix_row(case: _MatrixCase) -> list[str]:
    failed = [key for key, _name, _unit in _MATRIX_CHECKS if case.problems[key]]
    criterion = case.criterion.value
    if case.criterion == RankCriterion.ON_TIME:
        criterion += f" (마감 {case.deadline_s:,.0f})" if case.deadline_s is not None else " (마감 없음)"
    return [
        str(case.number), case.scenario_id, f"{case.offset_s:,.0f}", "켬" if case.card else "끔", criterion, "켬" if case.bike else "끔",
        case.status, str(case.candidates), str(case.heads), str(case.pruned), case.best_id or "-", f"{case.engine_s:.3f}",
        "통과" if not failed else "실패 " + ", ".join(failed),
    ]


def _cli_matrix() -> int:
    """`--matrix` (§3.7): 조합마다 한 줄의 표, 검사마다 대상 수와 실패 조합 수, 실패 내역, run_engine 시간, 요약. 실패가 있으면 종료 코드 1."""
    started = time.perf_counter()
    scenarios = _demo_scenarios()
    cases: list[_MatrixCase] = []
    for scenario_id, scenario in scenarios.items():
        for offset_s in _MATRIX_OFFSETS_S:
            card_off: dict[tuple[RankCriterion, bool], EngineOutput | None] = {}
            for card in (False, True):
                for criterion in _MATRIX_CRITERIA:
                    for bike in (True, False):
                        case, output = _matrix_case(len(cases) + 1, scenario_id, scenario, offset_s, card, criterion, bike,
                                                    card_off.get((criterion, bike)))
                        if not card:
                            card_off[(criterion, bike)] = output
                        cases.append(case)
    total_s = time.perf_counter() - started
    header = ["번호", "시나리오", "Δt", "카드", "순위 기준", "따릉이", "상태", "후보", "대표", "걸러짐", "최선", "엔진(초)", "판정"]
    numeric = [True, False, True, False, False, False, False, True, True, True, False, True, False]
    lines = [
        f"조합 검사 (시뮬레이션): 시나리오 {len(scenarios)} × 출발 늦추기 {len(_MATRIX_OFFSETS_S)} × 기후동행카드 2 × 순위 기준 "
        f"{len(_MATRIX_CRITERIA)} × 따릉이 2 = {len(cases)} 조합",
        "ON_TIME 의 마감은 화면에서 마감을 켰을 때의 기본값(기준 시각 + 30분, 분 단위 내림)이고 출발을 늦춘 만큼 남은 시간(초)이 준다.",
        "",
        *_table_lines(header, [_matrix_row(case) for case in cases], numeric),
        "",
        f"검사한 대상 ({len(cases)} 조합의 합):",
    ]
    for key, name, unit in _MATRIX_CHECKS:
        total = sum(case.counts[key] for case in cases)
        failed = sum(1 for case in cases if case.problems[key])
        lines.append(f"  {key} {name}: {unit.format(n=total)}, 실패 조합 {failed}")
    lines.append("  조합과 상관없는 I1, I2, I4, I13 은 --selftest 가 본다.")
    failures = [case for case in cases if any(case.problems.values())]
    if failures:
        lines += ["", "실패 내역:"]
        for case in failures:
            for key, _name, _unit in _MATRIX_CHECKS:
                items = case.problems[key]
                if items:
                    more = f" 외 {len(items) - 3}건" if len(items) > 3 else ""
                    lines.append(f"  {case.number} {case.label} · {key}: {'; '.join(items[:3])}{more}")
    slowest = max(cases, key=lambda case: case.engine_s)
    lines += [
        "",
        f"run_engine 시간: 최댓값 {slowest.engine_s:.3f}초 ({slowest.number} {slowest.label}), 평균 "
        f"{statistics.fmean(case.engine_s for case in cases):.3f}초, 예산 {_MATRIX_ENGINE_BUDGET_S:g}초 (§3.6)",
        f"요약: 통과 {len(cases) - len(failures)}/{len(cases)}, 실패 {len(failures)}, 소요 {total_s:.1f}초",
    ]
    print("\n".join(lines))
    return 1 if failures else 0


def main(argv: list[str] | None = None) -> int:
    """명령줄 진입점(§3.7): --selftest, --collect, --collect-once, --status, --demo, --json, --build-scenario,
    --fetch-timetable, --check-timetable, --replay, --replay-sweep, --link-bikes, --track, --fit, --fit-bike, --matrix."""
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(errors="backslashreplace")
    parser = argparse.ArgumentParser(prog="core_engine.py", description="유령 환승 필터링 라우터 코어 엔진")
    commands = parser.add_mutually_exclusive_group()
    commands.add_argument("--selftest", action="store_true", help="§9 의 검사를 실행한다")
    commands.add_argument("--collect", action="store_true", help="재생용 수집기를 실행한다(멈출 때까지, §5.3)")
    commands.add_argument("--collect-once", action="store_true", help="시간대와 상관없이 수집 한 주기만 실행한다")
    commands.add_argument("--status", action="store_true", help="기록 저장소를 읽기 전용으로 열어 요약과 키 노출 검사를 보인다")
    commands.add_argument("--demo", action="store_true", help="시나리오마다 기본 질의의 결과를 표로 보인다(기본은 GOLDEN, A, B 전부)")
    commands.add_argument("--json", action="store_true", help="--scenario 의 EngineOutput JSON 을 표준 출력으로 낸다")
    parser.add_argument("--scenario", metavar="ID", help="--demo, --json, --replay-sweep, --link-bikes: 시나리오 ID (GOLDEN, A, B)")
    parser.add_argument("--offset", type=float, default=0.0, metavar="초", help="--demo, --json: 출발 늦추기 (초, §4.6)")
    parser.add_argument("--verbose", action="store_true", help="검사마다 비교한 값을 모두 보인다")
    parser.add_argument("--dry-run", action="store_true", help="--collect: 네트워크 없이 호출 계획만 보인다")
    parser.add_argument("--samples", action="store_true", help="API 마다 응답(표본)의 앞 2,000자를 더한다(키는 ***)")
    parser.add_argument("--targets", metavar="PATH", help="수집 대상 파일 (기본 data/collect_targets.json)")
    commands.add_argument("--fetch-timetable", nargs="+", metavar="역코드", help="역마다 지하철 시각표를 받아 CSV 로 저장한다(§4.10)")
    commands.add_argument("--check-timetable", metavar="PATH", help="시각표 CSV 를 읽어 요약을 보인다")
    commands.add_argument("--build-scenario", action="store_true", help="생성 명세(--spec)로 시나리오 JSON 을 만든다(§4.9)")
    parser.add_argument("--spec", metavar="PATH", help="--build-scenario: 생성 명세 JSON")
    commands.add_argument("--replay", action="store_true", help="기록 재생으로 시나리오를 만들어 원천 상태와 --demo 형식의 결과를 보인다(§4.8)")
    commands.add_argument("--replay-sweep", action="store_true",
                          help="기록 일괄 재생: --from 부터 --to 까지 --step 초마다 재생해 유령 환승 비율, 줄이는 시간, 따릉이 효과를 보인다(§4.11)")
    parser.add_argument("--from", dest="sweep_from", metavar='"YYYY-MM-DD HH:MM:SS"', help="--replay-sweep: 첫 출발 (한국 시각)")
    parser.add_argument("--to", dest="sweep_to", metavar='"YYYY-MM-DD HH:MM:SS"', help="--replay-sweep: 마지막 출발의 상한 (한국 시각)")
    parser.add_argument("--step", type=int, default=60, metavar="초", help="--replay-sweep: 출발 간격 (정수 초, 기본 60)")
    commands.add_argument("--link-bikes", action="store_true",
                          help="따릉이 실시간 목록으로 시나리오 대여소에 실제 대여소 ID 를 이은 사본을 저장한다(§4.12)")
    commands.add_argument("--track", action="store_true",
                          help="실제 기록 추적 평가: 무작위 출발·목적지·시각에서 두 여정을 나중 기록으로 따라간다(§4.13)")
    parser.add_argument("--n", type=int, metavar="N", help="--track: 뽑을 추적 수 (기본 600)")
    parser.add_argument("--seed", type=int, metavar="S", help="--track: 뽑기 씨앗 (기본 20261122)")
    parser.add_argument("--horizon", type=float, metavar="초", help="--track: 출발 뒤 기록이 이어져야 하는 시간 (기본 2400)")
    parser.add_argument("--within", type=float, metavar="M", help="--link-bikes: 잇는 반경 m (기본 150)")
    commands.add_argument("--fit", action="store_true", help="기록 저장소의 신호 관측으로 신호 모델을 학습한다(§1.9)")
    commands.add_argument("--fit-bike", action="store_true", help="따릉이 대여 이력으로 대여 속도와 주행 속도를 배운다(§1.8.2)")
    commands.add_argument("--matrix", action="store_true",
                          help="시나리오 3 × 출발 늦추기 3 × 기후동행카드 2 × 순위 기준 4 × 따릉이 2 = 144 조합을 실행해 불변식을 검사한다(§3.7)")
    parser.add_argument("--scenario-json", metavar="PATH", help="--replay, --replay-sweep, --link-bikes: 시나리오 JSON")
    parser.add_argument("--at", metavar='"YYYY-MM-DD HH:MM:SS"', help="--replay: 재생 시각 (한국 시각)")
    parser.add_argument("--models", metavar="DIR", help="--replay, --replay-sweep: 학습 모델 폴더 (기본 data)")
    parser.add_argument("--timetables", metavar="DIR", help="--replay, --replay-sweep: 지하철 시각표 폴더 (기본 data/timetables)")
    parser.add_argument("--history", metavar="DIR", help="--fit-bike: 따릉이 대여 이력 폴더 (기본 data/bike_history)")
    parser.add_argument("--store", metavar="PATH", help="--status, --replay, --replay-sweep, --fit: 기록 저장소 (기본 data/records.sqlite)")
    parser.add_argument("--out", metavar="PATH",
                        help="--fetch-timetable: 저장 폴더 (기본 data/timetables), --build-scenario: 시나리오 JSON (기본 data/scenarios/<id>.json), "
                             "--fit, --fit-bike: 모델 폴더 (기본 data), --replay-sweep: CSV (기본 data/sweeps/<id>_<시작>_<끝>.csv), "
                             "--link-bikes: 시나리오 JSON (기본 data/scenarios/<id>-BIKE.json), --track: CSV 폴더 (기본 data/tracks/<id>_<시작>_<끝>)")
    args = parser.parse_args(argv)
    config = EngineConfig(data_dir=os.environ.get(_DATA_DIR_ENV) or "data")
    targets_path = pathlib.Path(args.targets) if args.targets else _data_dir(config) / "collect_targets.json"
    if args.selftest:
        return 1 if run_selftest(verbose=args.verbose) else 0
    if args.matrix:
        return _cli_matrix()
    if args.collect or args.collect_once:
        with _cli_logging():
            return run_collector(targets_path, config, dry_run=args.collect and args.dry_run, once=args.collect_once,
                                 samples=args.samples)
    if args.status:
        store_path = pathlib.Path(args.store) if args.store else _data_dir(config) / "records.sqlite"
        return _cli_status(store_path, targets_path, args.samples, config)
    if args.demo or args.json:
        return _cli_demo(args.scenario, args.offset, args.json)
    if args.fetch_timetable:
        out_dir = pathlib.Path(args.out) if args.out else _data_dir(config) / "timetables"
        with _cli_logging():
            return _cli_fetch_timetable(args.fetch_timetable, out_dir, args.samples, config)
    if args.check_timetable:
        return _cli_check_timetable(pathlib.Path(args.check_timetable))
    if args.build_scenario:
        if not args.spec:
            print("--build-scenario 에는 --spec PATH 가 필요합니다")
            return 2
        with _cli_logging():
            return _cli_build_scenario(pathlib.Path(args.spec), pathlib.Path(args.out) if args.out else None, config)
    if args.replay:
        return _cli_replay(args, targets_path, config)
    if args.replay_sweep:
        return _cli_replay_sweep(args, targets_path, config)
    if args.link_bikes:
        return _cli_link_bikes(args, targets_path, config)
    if args.track:
        return _cli_track(args, targets_path, config)
    if args.fit or args.fit_bike:
        out_dir = pathlib.Path(args.out) if args.out else _data_dir(config)
        if args.fit:
            store_path = pathlib.Path(args.store) if args.store else _data_dir(config) / "records.sqlite"
            return _cli_fit(store_path, out_dir, targets_path, args.targets is not None, config)
        history = pathlib.Path(args.history) if args.history else _data_dir(config) / "bike_history"
        return _cli_fit_bike(history, out_dir, targets_path, args.targets is not None, config)
    parser.print_help()
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
